static int app_cli_option_was_explicit(
    int argc,
    char *argv[],
    const char *option
)
{
    int index;

    if (argv == NULL || option == NULL) {
        return 0;
    }
    for (index = 1; index < argc; index++) {
        if (argv[index] != NULL && strcmp(argv[index], option) == 0) {
            return 1;
        }
    }
    return 0;
}

static void app_discard_hfs_pre_release_filters(AppConfig *config)
{
    if (config == NULL) {
        return;
    }
    config->mft_categories_csv = "all";
    config->mft_formats_csv = NULL;
    config->mft_dev_format = NULL;
    config->target_date_value = NULL;
    config->target_deleted_value = NULL;
    config->recover_img = 1;
    config->recover_vid = 1;
    config->recover_doc = 1;
}

/*
 * Return 1 to continue, 0 for an operator cancellation, and -1 when stdin
 * cannot provide the required answer.  The environment marker lets a crash
 * supervisor child inherit the parent's decision without prompting again.
 */
static int app_confirm_hfs_pre_release_filter_discard(
    AppConfig *config,
    int argc,
    char *argv[]
)
{
    int has_format;
    int has_date;
    int has_state;
    const char *filter_names[3];
    size_t filter_count = 0U;
    size_t filter_index;
    char answer[64];

    if (config == NULL ||
        config->filesystem_target != APP_FILESYSTEM_TARGET_HFSPLUS) {
        return 1;
    }

    has_format =
        app_cli_option_was_explicit(argc, argv, "--cat") ||
        app_cli_option_was_explicit(argc, argv, "--fmt");
    has_date = app_cli_option_was_explicit(argc, argv, "--date");
    has_state = app_cli_option_was_explicit(argc, argv, "--del");
    if (!has_format && !has_date && !has_state) {
        return 1;
    }

    if (getenv(CARV_HFS_FILTERS_DISCARDED_ENV) != NULL) {
        app_discard_hfs_pre_release_filters(config);
        return 1;
    }

    if (has_format) filter_names[filter_count++] = "Format";
    if (has_date) filter_names[filter_count++] = "date";
    if (has_state) filter_names[filter_count++] = "state";
    for (filter_index = 0U; filter_index < filter_count; filter_index++) {
        if (filter_index > 0U) {
            fputs(
                filter_index + 1U == filter_count ? " and " : ", ",
                stderr
            );
        }
        fputs(filter_names[filter_index], stderr);
    }
    fprintf(
        stderr,
        " filter%s %s not available for HFS+ in this pre-release.\n"
        "Enter Yes to discard and continue, or No to cancel: ",
        filter_count == 1U ? "" : "s",
        filter_count == 1U ? "is" : "are"
    );
    fflush(stderr);

    for (;;) {
        char *start;
        char *end;

        if (fgets(answer, (int)sizeof(answer), stdin) == NULL) {
            fputs("\nCancelled: no Yes/No answer was available.\n", stderr);
            return -1;
        }
        start = answer;
        while (*start != '\0' && isspace((unsigned char)*start)) {
            start++;
        }
        end = start + strlen(start);
        while (end > start && isspace((unsigned char)end[-1])) {
            end--;
        }
        *end = '\0';

        if (strcasecmp(start, "y") == 0 || strcasecmp(start, "yes") == 0) {
            app_discard_hfs_pre_release_filters(config);
            (void)setenv(CARV_HFS_FILTERS_DISCARDED_ENV, "1", 1);
            fputs("Continuing without the unsupported HFS+ filters.\n", stderr);
            return 1;
        }
        if (strcasecmp(start, "n") == 0 || strcasecmp(start, "no") == 0) {
            fputs("Cancelled. No recovery was started.\n", stderr);
            return 0;
        }
        fputs("Please answer Yes or No: ", stderr);
        fflush(stderr);
    }
}

