static int app_supervised_retry_context_active(void)
{
    return getenv(CRASH_RETRY_CHILD_ENV) != NULL &&
           getenv(SUPERVISOR_GENERATION_ENV) != NULL &&
           getenv(SUPERVISOR_GENERATION_PATH_ENV) != NULL &&
           app_parent_process_is_carv();
}

static int app_gui_pass_supervisor_owned_child_active(void)
{
    const char *current_pass_id = getenv(GUI_PASS_ID_ENV);
    const char *supervisor_pass_id = getenv(GUI_SUPERVISOR_PASS_ID_ENV);

    if (!has_nonempty_text(current_pass_id) ||
        !has_nonempty_text(supervisor_pass_id) ||
        strcmp(current_pass_id, supervisor_pass_id) != 0 ||
        getenv(SUPERVISOR_GENERATION_ENV) == NULL ||
        getenv(SUPERVISOR_GENERATION_PATH_ENV) == NULL ||
        !app_parent_process_is_carv()) {
        return 0;
    }

    return getenv(CRASH_RETRY_CHILD_ENV) != NULL ||
           getenv(NAME_RETRY_CHILD_ENV) != NULL;
}

static int exit_raw_all_if_stale_generation(
    Reader *reader,
    MagicTable *magic_table,
    DbHandle *db,
    int metadata_background_started,
    AppConfig *config
)
{
    if (!app_supervisor_generation_stale()) {
        return 0;
    }

    app_restore_signal_handlers();
    log_stop_working_indicator();
    log_runtime_event_info(
        "Superseded raw-all child reached a later phase, but will exit now without finalize or completion writes because a newer supervisor generation has taken over"
    );
    if (metadata_background_started) {
        fs_backend_stop_background_worker();
    }
    if (reader != NULL) {
        reader_close(reader);
    }
    if (magic_table != NULL) {
        magic_table_free(magic_table);
    }
    if (db != NULL) {
        db_close(db);
    }
    fs_backend_close();
    if (config != NULL) {
        config_free(config);
    }
    return 1;
}

static int app_parent_process_is_carv(void)
{
    pid_t parent_pid = getppid();
    char name[256];

    if (parent_pid <= 1) {
        return 0;
    }

    memset(name, 0, sizeof(name));

#ifdef __APPLE__
    {
        char command[64];
        FILE *pipe = NULL;

        snprintf(command, sizeof(command), "ps -p %ld -o comm=", (long)parent_pid);
        pipe = popen(command, "r");
        if (pipe == NULL) {
            return 0;
        }
        if (fgets(name, (int)sizeof(name), pipe) == NULL) {
            pclose(pipe);
            return 0;
        }
        pclose(pipe);
        name[strcspn(name, "\r\n")] = '\0';
    }
#elif defined(__linux__)
    {
        char path[64];
        FILE *file = NULL;

        snprintf(path, sizeof(path), "/proc/%ld/comm", (long)parent_pid);
        file = fopen(path, "r");
        if (file == NULL) {
            return 0;
        }
        if (fgets(name, (int)sizeof(name), file) == NULL) {
            fclose(file);
            return 0;
        }
        fclose(file);
        name[strcspn(name, "\r\n")] = '\0';
    }
#else
    return 0;
#endif

    if (strrchr(name, '/') != NULL) {
        const char *base = strrchr(name, '/');
        if (base != NULL && base[1] != '\0') {
            memmove(name, base + 1, strlen(base + 1) + 1U);
        }
    }

    return strcmp(name, "carv") == 0;
}

static int compare_text_ci(const void *left, const void *right)
{
    const char *const *a = (const char *const *)left;
    const char *const *b = (const char *const *)right;
    const unsigned char *pa = (const unsigned char *)*a;
    const unsigned char *pb = (const unsigned char *)*b;

    while (*pa != '\0' && *pb != '\0') {
        int ca = tolower(*pa);
        int cb = tolower(*pb);

        if (ca != cb) {
            return ca - cb;
        }
        pa++;
        pb++;
    }
    return (int)*pa - (int)*pb;
}

static void format_u64_grouped(
    uint64_t value,
    char *out,
    size_t out_size
)
{
    char reversed[64];
    size_t reversed_len = 0U;
    size_t written = 0U;
    size_t i;

    if (out == NULL || out_size == 0U) {
        return;
    }

    out[0] = '\0';

    if (value == 0U) {
        snprintf(out, out_size, "0");
        return;
    }

    while (value > 0U && reversed_len + 1U < sizeof(reversed)) {
        if (reversed_len > 0U && (reversed_len % 3U) == 0U) {
            reversed[reversed_len++] = ',';
        }
        reversed[reversed_len++] = (char)('0' + (value % 10U));
        value /= 10U;
    }

    for (i = reversed_len; i > 0U && written + 1U < out_size; i--) {
        out[written++] = reversed[i - 1U];
    }
    out[written] = '\0';
}

static void format_byte_size_human(
    uint64_t bytes,
    char *out,
    size_t out_size
)
{
    static const char *units[] = {"bytes", "KiB", "MiB", "GiB", "TiB"};
    double value = (double)bytes;
    size_t unit_index = 0U;

    if (out == NULL || out_size == 0U) {
        return;
    }

    while (value >= 1024.0 &&
           unit_index + 1U < (sizeof(units) / sizeof(units[0]))) {
        value /= 1024.0;
        unit_index++;
    }

    if (unit_index == 0U) {
        snprintf(out, out_size, "%llu bytes", (unsigned long long)bytes);
    } else {
        snprintf(out, out_size, "%.2f %s", value, units[unit_index]);
    }
}

static void copy_text_truncated_local(
    char *dest,
    size_t dest_size,
    const char *src
)
{
    size_t copy_len;

    if (dest == NULL || dest_size == 0U) {
        return;
    }

    dest[0] = '\0';
    if (src == NULL) {
        return;
    }

    copy_len = strlen(src);
    if (copy_len >= dest_size) {
        copy_len = dest_size - 1U;
    }

    memcpy(dest, src, copy_len);
    dest[copy_len] = '\0';
}

static void append_text_truncated_local(
    char *dest,
    size_t dest_size,
    const char *src
)
{
    size_t used;
    size_t copy_len;

    if (dest == NULL || dest_size == 0U || src == NULL || src[0] == '\0') {
        return;
    }

    used = strnlen(dest, dest_size);
    if (used >= dest_size - 1U) {
        dest[dest_size - 1U] = '\0';
        return;
    }

    copy_len = strlen(src);
    if (copy_len > dest_size - used - 1U) {
        copy_len = dest_size - used - 1U;
    }

    memcpy(dest + used, src, copy_len);
    dest[used + copy_len] = '\0';
}

static void format_size_summary(
    uint64_t bytes,
    char *out,
    size_t out_size
)
{
    char human[64];
    char grouped[64];

    if (out == NULL || out_size == 0U) {
        return;
    }

    format_byte_size_human(bytes, human, sizeof(human));
    format_u64_grouped(bytes, grouped, sizeof(grouped));
    copy_text_truncated_local(out, out_size, human);
    append_text_truncated_local(out, out_size, " (");
    append_text_truncated_local(out, out_size, grouped);
    append_text_truncated_local(out, out_size, " bytes)");
}

static void format_read_error_errno_summary(
    int errno_code,
    char *out,
    size_t out_size
)
{
    if (out == NULL || out_size == 0U) {
        return;
    }

    if (errno_code > 0) {
        snprintf(out, out_size, "%d (%s)", errno_code, strerror(errno_code));
        return;
    }

    snprintf(out, out_size, "%d (not captured)", errno_code);
}

static int format_text_seen(
    const char *const *items,
    size_t count,
    const char *text
)
{
    size_t i;

    if (items == NULL || text == NULL || text[0] == '\0') {
        return 0;
    }
    for (i = 0; i < count; i++) {
        if (items[i] != NULL && strcasecmp(items[i], text) == 0) {
            return 1;
        }
    }
    return 0;
}

static int print_known_formats(void)
{
    Config format_config = {0};
    const RecoveryOrder *order;
    const char *items[RECOVERY_FORMAT_MAX * FORMAT_EXTENSION_ALIAS_MAX];
    size_t item_count = 0;
    size_t i;
    size_t j;

    format_config.recovery_order = mftprobe_format_default_order();
    (void)mftprobe_format_load_common_profiles(&format_config, FORMAT_PROFILE_DB_PATH);
    order = format_config.loaded_recovery_order.count > 0
        ? &format_config.loaded_recovery_order
        : format_config.recovery_order;

    if (order == NULL || order->formats == NULL || order->count == 0) {
        return 0;
    }

    for (i = 0; i < order->count; i++) {
        const RecoveryFormat *format = &order->formats[i];

        if (format->default_extension != NULL &&
            format->default_extension[0] != '\0' &&
            !format_text_seen(items, item_count, format->default_extension) &&
            item_count < (sizeof(items) / sizeof(items[0]))) {
            items[item_count++] = format->default_extension;
        }
        for (j = 0; j < format->extension_count; j++) {
            if (format->extensions != NULL &&
                format->extensions[j] != NULL &&
                format->extensions[j][0] != '\0' &&
                !format_text_seen(items, item_count, format->extensions[j]) &&
                item_count < (sizeof(items) / sizeof(items[0]))) {
                items[item_count++] = format->extensions[j];
            }
        }
    }

    qsort(items, item_count, sizeof(items[0]), compare_text_ci);
    for (i = 0; i < item_count; i++) {
        printf("%s\n", items[i]);
    }
    return 1;
}

static void restore_terminal_on_exit(void)
{
    log_reset_terminal_mode();
}

static void lower_extension_from_path_local(
    const char *path,
    char *out,
    size_t out_size
)
{
    const char *dot;
    const char *slash;
    size_t i = 0;

    if (out == NULL || out_size == 0U) {
        return;
    }

    out[0] = '\0';
    if (path == NULL) {
        return;
    }

    dot = strrchr(path, '.');
    slash = strrchr(path, '/');
    if (dot == NULL || dot[1] == '\0' || (slash != NULL && dot < slash)) {
        return;
    }

    dot++;
    while (dot[i] != '\0' && i + 1U < out_size) {
        out[i] = (char)tolower((unsigned char)dot[i]);
        i++;
    }
    out[i] = '\0';
}

static int recovery_format_has_extension_local(
    const RecoveryFormat *format,
    const char *extension
)
{
    size_t i;

    if (format == NULL || extension == NULL || extension[0] == '\0') {
        return 0;
    }

    if (format->default_extension != NULL &&
        strcasecmp(format->default_extension, extension) == 0) {
        return 1;
    }

    for (i = 0; i < format->extension_count; i++) {
        if (format->extensions != NULL &&
            format->extensions[i] != NULL &&
            strcasecmp(format->extensions[i], extension) == 0) {
            return 1;
        }
    }

    return 0;
}

static const RecoveryFormat *recovery_order_find_format_by_extension_local(
    const RecoveryOrder *order,
    const char *extension
)
{
    size_t i;

    if (order == NULL || order->formats == NULL || extension == NULL || extension[0] == '\0') {
        return NULL;
    }

    for (i = 0; i < order->count; i++) {
        if (recovery_format_has_extension_local(&order->formats[i], extension)) {
            return &order->formats[i];
        }
    }

    return NULL;
}

static const RecoveryFormat *missed_report_recovery_format_for_path(const char *path)
{
    static Config format_config = {0};
    static int initialized = 0;
    char extension[FORMAT_EXTENSION_MAX] = {0};
    const RecoveryOrder *order;

    lower_extension_from_path_local(path, extension, sizeof(extension));
    if (extension[0] == '\0') {
        return NULL;
    }

    if (!initialized) {
        format_config.recovery_order = mftprobe_format_default_order();
        (void)mftprobe_format_load_common_profiles(&format_config, FORMAT_PROFILE_DB_PATH);
        initialized = 1;
    }

    order = format_config.loaded_recovery_order.count > 0
        ? &format_config.loaded_recovery_order
        : format_config.recovery_order;

    return recovery_order_find_format_by_extension_local(order, extension);
}

static uint64_t missed_report_available_bytes_local(const MissedReportEntry *entry)
{
    uint64_t available = 0U;
    size_t i;

    if (entry == NULL) {
        return 0U;
    }

    if (entry->resident) {
        return entry->data_size;
    }

    for (i = 0; i < entry->run_count; i++) {
        if (UINT64_MAX - available < entry->runs[i].byte_length) {
            return UINT64_MAX;
        }
        available += entry->runs[i].byte_length;
    }

    return available;
}

static int bytes_start_with_local(
    const unsigned char *data,
    size_t data_size,
    const unsigned char *signature,
    size_t signature_size
)
{
    return data != NULL &&
           signature != NULL &&
           data_size >= signature_size &&
           memcmp(data, signature, signature_size) == 0;
}

static int missed_report_bmff_brand_matches_local(
    const unsigned char *data,
    size_t data_size,
    const char *const *brands,
    size_t brand_count
)
{
    size_t i;

    if (data == NULL || data_size < 12U || brands == NULL ||
        memcmp(data + 4U, "ftyp", 4U) != 0) {
        return 0;
    }

    for (i = 0U; i < brand_count; i++) {
        if (brands[i] != NULL && memcmp(data + 8U, brands[i], 4U) == 0) {
            return 1;
        }
    }

    for (i = 16U; i + 4U <= data_size && i < 64U; i += 4U) {
        size_t j;

        for (j = 0U; j < brand_count; j++) {
            if (brands[j] != NULL && memcmp(data + i, brands[j], 4U) == 0) {
                return 1;
            }
        }
    }

    return 0;
}

static int missed_report_header_matches_path_local(
    const char *path,
    const unsigned char *data,
    size_t data_size
)
{
    char extension[FORMAT_EXTENSION_MAX] = {0};
    static const unsigned char jpeg_sig[] = {0xffU, 0xd8U};
    static const unsigned char png_sig[] = {
        0x89U, 0x50U, 0x4eU, 0x47U, 0x0dU, 0x0aU, 0x1aU, 0x0aU
    };
    static const unsigned char tiff_le_sig[] = {'I', 'I', 0x2aU, 0x00U};
    static const unsigned char tiff_be_sig[] = {'M', 'M', 0x00U, 0x2aU};
    static const unsigned char psd_sig[] = {'8', 'B', 'P', 'S'};
    static const unsigned char cfb_sig[] = {
        0xd0U, 0xcfU, 0x11U, 0xe0U, 0xa1U, 0xb1U, 0x1aU, 0xe1U
    };
    static const unsigned char seven_zip_sig[] = {
        '7', 'z', 0xbcU, 0xafU, 0x27U, 0x1cU
    };
    static const unsigned char rar_sig[] = {'R', 'a', 'r', '!', 0x1aU, 0x07U};
    static const char *const video_bmff_brands[] = {
        "isom", "iso2", "mp41", "mp42", "M4V ", "qt  ", "3gp4", "3gp5"
    };
    static const char *const image_bmff_brands[] = {
        "avif", "avis", "mif1", "msf1", "heic", "heix", "hevc", "hevx"
    };

    lower_extension_from_path_local(path, extension, sizeof(extension));
    if (extension[0] == '\0' || data == NULL || data_size == 0U) {
        return 0;
    }

    if (strcasecmp(extension, "jpg") == 0 ||
        strcasecmp(extension, "jpeg") == 0 ||
        strcasecmp(extension, "jpe") == 0) {
        return bytes_start_with_local(data, data_size, jpeg_sig, sizeof(jpeg_sig));
    }
    if (strcasecmp(extension, "png") == 0) {
        return bytes_start_with_local(data, data_size, png_sig, sizeof(png_sig));
    }
    if (strcasecmp(extension, "gif") == 0) {
        return data_size >= 6U &&
               (memcmp(data, "GIF87a", 6U) == 0 ||
                memcmp(data, "GIF89a", 6U) == 0);
    }
    if (strcasecmp(extension, "bmp") == 0 ||
        strcasecmp(extension, "dib") == 0) {
        return data_size >= 2U && data[0] == 'B' && data[1] == 'M';
    }
    if (strcasecmp(extension, "tif") == 0 ||
        strcasecmp(extension, "tiff") == 0) {
        return bytes_start_with_local(data, data_size, tiff_le_sig, sizeof(tiff_le_sig)) ||
               bytes_start_with_local(data, data_size, tiff_be_sig, sizeof(tiff_be_sig));
    }
    if (strcasecmp(extension, "jp2") == 0) {
        return data_size >= 12U &&
               memcmp(data + 4U, "jP  ", 4U) == 0;
    }
    if (strcasecmp(extension, "psd") == 0) {
        return bytes_start_with_local(data, data_size, psd_sig, sizeof(psd_sig));
    }
    if (strcasecmp(extension, "pdf") == 0) {
        return data_size >= 5U && memcmp(data, "%PDF-", 5U) == 0;
    }
    if (strcasecmp(extension, "zip") == 0 ||
        strcasecmp(extension, "docx") == 0 ||
        strcasecmp(extension, "xlsx") == 0 ||
        strcasecmp(extension, "pptx") == 0 ||
        strcasecmp(extension, "odt") == 0 ||
        strcasecmp(extension, "ods") == 0 ||
        strcasecmp(extension, "odp") == 0 ||
        strcasecmp(extension, "epub") == 0 ||
        strcasecmp(extension, "apk") == 0 ||
        strcasecmp(extension, "jar") == 0 ||
        strcasecmp(extension, "xps") == 0) {
        return data_size >= 4U &&
               data[0] == 'P' && data[1] == 'K' &&
               (data[2] == 0x03U || data[2] == 0x05U || data[2] == 0x07U) &&
               (data[3] == 0x04U || data[3] == 0x06U || data[3] == 0x08U);
    }
    if (strcasecmp(extension, "doc") == 0 ||
        strcasecmp(extension, "xls") == 0 ||
        strcasecmp(extension, "ppt") == 0) {
        return bytes_start_with_local(data, data_size, cfb_sig, sizeof(cfb_sig));
    }
    if (strcasecmp(extension, "wav") == 0 ||
        strcasecmp(extension, "avi") == 0 ||
        strcasecmp(extension, "webp") == 0) {
        const char *riff_type =
            strcasecmp(extension, "wav") == 0 ? "WAVE" :
            strcasecmp(extension, "avi") == 0 ? "AVI " : "WEBP";
        return data_size >= 12U &&
               memcmp(data, "RIFF", 4U) == 0 &&
               memcmp(data + 8U, riff_type, 4U) == 0;
    }
    if (strcasecmp(extension, "mp4") == 0 ||
        strcasecmp(extension, "m4v") == 0 ||
        strcasecmp(extension, "mov") == 0 ||
        strcasecmp(extension, "3gp") == 0 ||
        strcasecmp(extension, "3g2") == 0) {
        return missed_report_bmff_brand_matches_local(
            data,
            data_size,
            video_bmff_brands,
            sizeof(video_bmff_brands) / sizeof(video_bmff_brands[0])
        );
    }
    if (strcasecmp(extension, "heic") == 0 ||
        strcasecmp(extension, "heif") == 0 ||
        strcasecmp(extension, "avif") == 0) {
        return missed_report_bmff_brand_matches_local(
            data,
            data_size,
            image_bmff_brands,
            sizeof(image_bmff_brands) / sizeof(image_bmff_brands[0])
        );
    }
    if (strcasecmp(extension, "sqlite") == 0 ||
        strcasecmp(extension, "db") == 0 ||
        strcasecmp(extension, "lrcat") == 0) {
        return data_size >= 16U && memcmp(data, "SQLite format 3", 15U) == 0;
    }
    if (strcasecmp(extension, "7z") == 0) {
        return bytes_start_with_local(
            data,
            data_size,
            seven_zip_sig,
            sizeof(seven_zip_sig)
        );
    }
    if (strcasecmp(extension, "rar") == 0) {
        return bytes_start_with_local(data, data_size, rar_sig, sizeof(rar_sig));
    }

    return 0;
}

static int missed_report_entry_header_matches_source(
    Reader *reader,
    const MissedReportEntry *entry
)
{
    size_t sample_size;

    if (reader == NULL || entry == NULL || entry->resident ||
        entry->run_count == 0U || entry->runs[0].byte_length == 0U) {
        return 0;
    }

    if (!reader_seek_absolute(reader, entry->runs[0].abs_offset) ||
        reader_read_next(reader) == 0) {
        return 0;
    }

    sample_size = reader->bytes_in_buffer;
    if (sample_size > entry->runs[0].byte_length) {
        sample_size = (size_t)entry->runs[0].byte_length;
    }
    if (sample_size > 256U) {
        sample_size = 256U;
    }

    return missed_report_header_matches_path_local(
        entry->path,
        reader->buffer,
        sample_size
    );
}

static int append_partial_suffix_local(char *path, size_t path_size)
{
    char temp[1024];

    if (path == NULL || path_size == 0U || path[0] == '\0') {
        return 0;
    }

    if (snprintf(temp, sizeof(temp), "%s.partial", path) >= (int)sizeof(temp)) {
        return 0;
    }
    if (snprintf(path, path_size, "%s", temp) >= (int)path_size) {
        return 0;
    }

    return 1;
}

static void app_signal_handler(int signo)
{
    ssize_t ignored = 0;

    (void)signo;

    if (g_stop_signal_count == 0) {
        ignored = write(
            STDERR_FILENO,
            STOP_REQUESTED_MESSAGE,
            sizeof(STOP_REQUESTED_MESSAGE) - 1U
        );
        (void)ignored;
    }
    g_stop_requested = 1;
    if (g_stop_signal_count < 1000) {
        g_stop_signal_count++;
    }
    if (g_stop_signal_count >= 2) {
        ignored = write(
            STDERR_FILENO,
            STOP_FORCED_MESSAGE,
            sizeof(STOP_FORCED_MESSAGE) - 1U
        );
        (void)ignored;
        _exit(130);
    }
}

static int app_install_signal_handlers(void)
{
    struct sigaction action;

    memset(&action, 0, sizeof(action));
    sigemptyset(&action.sa_mask);
    action.sa_handler = app_signal_handler;

    g_stop_requested = 0;
    g_stop_signal_count = 0;
    g_stop_progress_started_at = 0.0;
    g_stop_progress_last_logged_at = 0.0;
    g_source_reconnect_requested = 0;
    g_source_reconnect_errno = 0;
    g_name_only_nonretryable_failure = 0;
    g_output_mount_guard_triggered = 0;
    pthread_mutex_lock(&g_output_mount_guard_mutex);
    output_mount_guard_reset_debounce_locked();
    pthread_mutex_unlock(&g_output_mount_guard_mutex);

    if (sigaction(SIGINT, &action, &g_previous_sigint_action) != 0) {
        return 0;
    }
    if (sigaction(SIGTERM, &action, &g_previous_sigterm_action) != 0) {
        (void)sigaction(SIGINT, &g_previous_sigint_action, NULL);
        return 0;
    }

    g_signal_handlers_installed = 1;
    return 1;
}

static void app_restore_signal_handlers(void)
{
    if (!g_signal_handlers_installed) {
        return;
    }
    (void)sigaction(SIGINT, &g_previous_sigint_action, NULL);
    (void)sigaction(SIGTERM, &g_previous_sigterm_action, NULL);
    g_signal_handlers_installed = 0;
}

int app_stop_requested(void)
{
    return g_stop_requested != 0 || app_supervisor_generation_stale();
}

int app_supervisor_generation_enabled(void)
{
    return g_supervisor_generation_enabled != 0;
}

void app_request_source_reconnect(const char *context, int errno_code)
{
    if (g_source_reconnect_requested == 0) {
        if (errno_code != 0) {
            log_runtime_event_error(
                "Source connection appears lost%s%s (%s); this pass will stop and the supervisor will try to reopen the disk and resume",
                context != NULL && context[0] != '\0' ? " during " : "",
                context != NULL && context[0] != '\0' ? context : "",
                strerror(errno_code)
            );
        } else {
            log_runtime_event_error(
                "Source connection appears lost%s%s; this pass will stop and the supervisor will try to reopen the disk and resume",
                context != NULL && context[0] != '\0' ? " during " : "",
                context != NULL && context[0] != '\0' ? context : ""
            );
        }
    }

    g_source_reconnect_requested = 1;
    if (errno_code != 0) {
        g_source_reconnect_errno = errno_code;
    }
}

int app_source_reconnect_requested(void)
{
    return g_source_reconnect_requested != 0;
}

int app_source_reconnect_errno(void)
{
    return (int)g_source_reconnect_errno;
}

static void app_clear_name_only_nonretryable_failure(void)
{
    g_name_only_nonretryable_failure = 0;
}

static void app_request_name_only_nonretryable_failure(void)
{
    g_name_only_nonretryable_failure = 1;
}

static int app_name_only_nonretryable_failure_requested(void)
{
    return g_name_only_nonretryable_failure != 0;
}

void app_note_shutdown_progress(const char *context)
{
    double now;
    double elapsed_seconds;

    if (!app_stop_requested() || app_supervisor_generation_stale()) {
        return;
    }

    now = monotonic_seconds_local();
    if (g_stop_progress_started_at <= 0.0) {
        g_stop_progress_started_at = now;
    }
    if (g_stop_progress_last_logged_at > 0.0 &&
        (now - g_stop_progress_last_logged_at) < STOP_PROGRESS_LOG_INTERVAL_SECONDS) {
        return;
    }

    g_stop_progress_last_logged_at = now;
    elapsed_seconds = now - g_stop_progress_started_at;
    if (context != NULL && context[0] != '\0') {
        log_info(
            "Clean shutdown still in progress (%s) after %.0fs; waiting for the current read/validation and cleanup to finish. Press Ctrl-C again for immediate kill.",
            context,
            elapsed_seconds
        );
    } else {
        log_info(
            "Clean shutdown still in progress after %.0fs; waiting for the current read/validation and cleanup to finish. Press Ctrl-C again for immediate kill.",
            elapsed_seconds
        );
    }
}

static int read_supervisor_generation_file(
    const char *path,
    unsigned long long *out_generation
)
{
    FILE *file;
    char line[64];
    char *end = NULL;
    unsigned long long value;

    if (out_generation != NULL) {
        *out_generation = 0ULL;
    }
    if (!has_nonempty_text(path) || out_generation == NULL) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0;
    }

    if (fgets(line, sizeof(line), file) == NULL) {
        fclose(file);
        return 0;
    }
    fclose(file);

    errno = 0;
    value = strtoull(line, &end, 10);
    if (errno != 0 || end == line) {
        return 0;
    }

    *out_generation = value;
    return 1;
}

static int write_supervisor_generation_file(
    const char *path,
    unsigned long long generation
)
{
    FILE *file;

    if (!has_nonempty_text(path)) {
        return 0;
    }

    file = fopen(path, "w");
    if (file == NULL) {
        return 0;
    }
    fprintf(file, "%llu\n", generation);
    fclose(file);
    return 1;
}

static void app_configure_supervisor_generation_from_env(void)
{
    const char *path = getenv(SUPERVISOR_GENERATION_PATH_ENV);
    const char *generation_text = getenv(SUPERVISOR_GENERATION_ENV);
    char *end = NULL;
    unsigned long long value = 0ULL;

    g_supervisor_generation_path[0] = '\0';
    g_supervisor_generation = 0ULL;
    g_supervisor_generation_enabled = 0;
    g_supervisor_generation_stale_logged = 0;
    g_supervisor_generation_last_checked_at = 0.0;
    g_supervisor_generation_last_known_stale = 0;
    g_supervisor_generation_fast_poll_countdown = 0U;

    if (!has_nonempty_text(path) || !has_nonempty_text(generation_text)) {
        return;
    }

    errno = 0;
    value = strtoull(generation_text, &end, 10);
    if (errno != 0 || end == generation_text || value == 0ULL) {
        return;
    }

    if (snprintf(
            g_supervisor_generation_path,
            sizeof(g_supervisor_generation_path),
            "%s",
            path) >= (int)sizeof(g_supervisor_generation_path)) {
        g_supervisor_generation_path[0] = '\0';
        return;
    }

    g_supervisor_generation = value;
    g_supervisor_generation_enabled = 1;
}

int app_supervisor_generation_stale(void)
{
    unsigned long long observed_generation = 0ULL;
    double now = 0.0;

    if (!g_supervisor_generation_enabled ||
        !has_nonempty_text(g_supervisor_generation_path)) {
        return 0;
    }

    if (g_supervisor_generation_last_known_stale) {
        return 1;
    }

    /*
     * Raw byte scanning can ask this question millions of times per second.
     * The real generation-file check is already time-throttled, but even the
     * monotonic clock call is expensive enough on macOS to dominate simple
     * image scans. Keep Ctrl-C responsive via g_stop_requested, and only let
     * the supervisor generation poll reach the clock after a small batch of
     * cheap calls.
     */
    if (g_supervisor_generation_fast_poll_countdown > 0U) {
        g_supervisor_generation_fast_poll_countdown--;
        return 0;
    }
    g_supervisor_generation_fast_poll_countdown =
        SUPERVISOR_GENERATION_FAST_POLL_SKIP;

    now = monotonic_seconds_local();
    if (g_supervisor_generation_last_checked_at > 0.0 &&
        (now - g_supervisor_generation_last_checked_at) <
            SUPERVISOR_GENERATION_CHECK_INTERVAL_SECONDS) {
        return 0;
    }
    g_supervisor_generation_last_checked_at = now;

    if (!read_supervisor_generation_file(
            g_supervisor_generation_path,
            &observed_generation) ||
        observed_generation == 0ULL) {
        return 0;
    }

    if (observed_generation != g_supervisor_generation &&
        !g_supervisor_generation_stale_logged) {
        log_runtime_event_error(
            "Supervised child generation %llu has been superseded by generation %llu; this stale child will stop as soon as it regains control",
            g_supervisor_generation,
            observed_generation
        );
        g_supervisor_generation_stale_logged = 1;
    }

    g_supervisor_generation_last_known_stale =
        observed_generation != g_supervisor_generation;
    return g_supervisor_generation_last_known_stale;
}

static double monotonic_seconds_local(void)
{
    struct timespec now;

    clock_gettime(CLOCK_MONOTONIC, &now);
    return (double)now.tv_sec + ((double)now.tv_nsec / 1000000000.0);
}

static void app_gui_clear_state_locked(void)
{
    free(g_gui_pass_rows);
    g_gui_pass_rows = NULL;
    g_gui_pass_count = 0U;
    g_gui_pass_capacity = 0U;

    free(g_gui_trouble_rows);
    g_gui_trouble_rows = NULL;
    g_gui_trouble_count = 0U;
    g_gui_trouble_capacity = 0U;

    free(g_gui_coverage_rows);
    g_gui_coverage_rows = NULL;
    g_gui_coverage_count = 0U;
    g_gui_coverage_capacity = 0U;

    g_gui_loaded_run_dir[0] = '\0';
    g_gui_current_pass_id[0] = '\0';
    g_gui_loaded_pid = 0;
    g_gui_last_live_gap_pass_id[0] = '\0';
    g_gui_last_live_gap_start = 0ULL;
    g_gui_last_live_gap_end = 0ULL;
    g_gui_coverage_last_flush_at = 0.0;
    g_gui_coverage_dirty_bytes = 0ULL;
    g_gui_coverage_dirty = 0;
}

static int build_state_child_path_local(
    const char *run_dir,
    const char *child_name,
    char *out,
    size_t out_size
)
{
    if (!has_nonempty_text(run_dir) ||
        !has_nonempty_text(child_name) ||
        out == NULL ||
        out_size == 0U) {
        return 0;
    }

    return snprintf(
        out,
        out_size,
        "%s/%s/%s",
        run_dir,
        APP_STATE_DIR_NAME,
        child_name) < (int)out_size;
}

static int ensure_state_dir_for_run(const char *run_dir)
{
    char state_dir[PATH_MAX_LEN];
    int ok;

    if (!has_nonempty_text(run_dir) ||
        snprintf(
            state_dir,
            sizeof(state_dir),
            "%s/%s",
            run_dir,
            APP_STATE_DIR_NAME) >= (int)sizeof(state_dir)) {
        return 0;
    }
    ok = ensure_directory_path(state_dir);
    if (ok) {
        /*
         * The GUI writes small control/ledger files here while the recovery
         * child may run as root.  Keep state/ open to the desktop user even on
         * filesystems where chown is unsupported or sudo inherited a strict
         * umask.
         */
        (void)chmod(state_dir, 0777);
    }
    return ok;
}

static void write_build_info_for_run(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 64];
    FILE *file;

    if (!build_state_child_path_local(run_dir, "build_info.txt", path, sizeof(path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp.%ld", path, (long)getpid()) >=
            (int)sizeof(temp_path) ||
        !ensure_state_dir_for_run(run_dir)) {
        return;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return;
    }
    fprintf(file, "carv_version=%s\n", CARV_VERSION);
    fprintf(file, "build_info_format=1\n");
    if (fclose(file) != 0 || rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
    }
}

static size_t split_tsv_fields_preserve_empty_local(
    char *line,
    char **fields,
    size_t max_fields
)
{
    size_t count = 0U;
    char *cursor;

    if (line == NULL || fields == NULL || max_fields == 0U) {
        return 0U;
    }

    cursor = line;
    fields[count++] = cursor;
    while (*cursor != '\0' && count < max_fields) {
        if (*cursor == '\t') {
            *cursor = '\0';
            fields[count++] = cursor + 1;
        } else if (*cursor == '\r' || *cursor == '\n') {
            *cursor = '\0';
            break;
        }
        cursor++;
    }

    while (*cursor != '\0') {
        if (*cursor == '\r' || *cursor == '\n') {
            *cursor = '\0';
            break;
        }
        cursor++;
    }

    return count;
}

static int app_gui_pass_rows_ensure_capacity_locked(size_t needed)
{
    GuiPassRow *new_rows;
    size_t new_capacity = g_gui_pass_capacity == 0U ? 16U : g_gui_pass_capacity;

    if (needed <= g_gui_pass_capacity) {
        return 1;
    }

    while (new_capacity < needed) {
        new_capacity *= 2U;
    }

    new_rows = (GuiPassRow *)realloc(
        g_gui_pass_rows,
        new_capacity * sizeof(*new_rows)
    );
    if (new_rows == NULL) {
        return 0;
    }

    g_gui_pass_rows = new_rows;
    g_gui_pass_capacity = new_capacity;
    return 1;
}

