static int app_gui_pass_kind_counts_for_raw_coverage(
    const char *mode,
    const char *kind,
    const char *range_kind
)
{
    if (!has_nonempty_text(kind)) {
        return 0;
    }

    /*
     * gui_read_coverage.tsv is a raw-byte-read coverage map.  Name salvage,
     * folders previews, and other sparse evidence passes may read useful
     * source bytes, but they must not be allowed to declare a full raw scan
     * complete or close full-scan gaps.
     */
    if (has_nonempty_text(mode) && strcmp(mode, "all") != 0) {
        return 0;
    }
    if (strcmp(kind, "scan") == 0) {
        return has_nonempty_text(range_kind) &&
               strcmp(range_kind, "full_source") == 0;
    }
    return strcmp(kind, "coverage_gap_retry") == 0 ||
           strcmp(kind, "targeted_reread") == 0;
}

static int app_gui_current_pass_counts_for_raw_coverage_locked(void)
{
    size_t i;

    if (!has_nonempty_text(g_gui_current_pass_id)) {
        return 0;
    }
    for (i = 0U; i < g_gui_pass_count; i++) {
        if (strcmp(g_gui_pass_rows[i].pass_id, g_gui_current_pass_id) == 0) {
            /*
             * Keep the visual read ledger for a deliberately selected raw
             * range too.  app_gui_pass_kind_counts_for_raw_coverage() stays
             * stricter when that ledger is later used to close whole-source
             * gaps, so a 100 GiB test can be drawn without ever claiming the
             * rest of a 300 GiB disk was scanned.
             */
            if (strcmp(g_gui_pass_rows[i].mode, "all") == 0 &&
                strcmp(g_gui_pass_rows[i].kind, "scan") == 0 &&
                strcmp(g_gui_pass_rows[i].range_kind, "selected_range") == 0) {
                return 1;
            }
            return app_gui_pass_kind_counts_for_raw_coverage(
                g_gui_pass_rows[i].mode,
                g_gui_pass_rows[i].kind,
                g_gui_pass_rows[i].range_kind
            );
        }
    }
    return 0;
}

static int load_gui_coverage_pass_filters_for_run_dir(
    const char *run_dir,
    GuiCoveragePassFilter **out_filters,
    size_t *out_filter_count,
    int *out_filter_available
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[1024];
    GuiCoveragePassFilter *filters = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    if (out_filters != NULL) {
        *out_filters = NULL;
    }
    if (out_filter_count != NULL) {
        *out_filter_count = 0U;
    }
    if (out_filter_available != NULL) {
        *out_filter_available = 0;
    }
    if (!has_nonempty_text(run_dir) ||
        out_filters == NULL ||
        out_filter_count == NULL ||
        !build_state_child_path_local(run_dir, "gui_passes.tsv", path, sizeof(path))) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }
    if (out_filter_available != NULL) {
        *out_filter_available = 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *fields[12];
        size_t field_count;
        GuiCoveragePassFilter *grown;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }
        field_count = split_tsv_fields_preserve_empty_local(
            line,
            fields,
            sizeof(fields) / sizeof(fields[0])
        );
        if (field_count < 12U || !has_nonempty_text(fields[0])) {
            continue;
        }

        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 16U : capacity * 2U;

            grown = (GuiCoveragePassFilter *)realloc(
                filters,
                next_capacity * sizeof(*filters)
            );
            if (grown == NULL) {
                fclose(file);
                free(filters);
                return 0;
            }
            filters = grown;
            capacity = next_capacity;
        }

        memset(&filters[count], 0, sizeof(filters[count]));
        snprintf(filters[count].pass_id, sizeof(filters[count].pass_id), "%s", fields[0]);
        filters[count].include_for_raw_coverage =
            app_gui_pass_kind_counts_for_raw_coverage(fields[2], fields[3], fields[5]);
        filters[count].selected_scan_range =
            strcmp(fields[2], "all") == 0 &&
            strcmp(fields[3], "scan") == 0 &&
            strcmp(fields[5], "selected_range") == 0;
        count++;
    }

    fclose(file);
    *out_filters = filters;
    *out_filter_count = count;
    return 1;
}

static int gui_coverage_pass_id_allowed(
    const char *pass_id,
    const GuiCoveragePassFilter *filters,
    size_t filter_count,
    int filter_available
)
{
    size_t i;

    if (!has_nonempty_text(pass_id)) {
        return 0;
    }
    if (!filter_available) {
        return 1;
    }
    for (i = 0U; i < filter_count; i++) {
        if (strcmp(filters[i].pass_id, pass_id) == 0) {
            return filters[i].include_for_raw_coverage ? 1 : 0;
        }
    }
    return 0;
}

static int compare_gui_coverage_rows_for_save(
    const void *lhs,
    const void *rhs
)
{
    const GuiCoverageRow *a = (const GuiCoverageRow *)lhs;
    const GuiCoverageRow *b = (const GuiCoverageRow *)rhs;
    int pass_cmp;

    pass_cmp = strcmp(a->pass_id, b->pass_id);
    if (pass_cmp != 0) {
        return pass_cmp;
    }
    if (a->start_offset < b->start_offset) {
        return -1;
    }
    if (a->start_offset > b->start_offset) {
        return 1;
    }
    if (a->end_offset < b->end_offset) {
        return -1;
    }
    if (a->end_offset > b->end_offset) {
        return 1;
    }
    return 0;
}

static int app_gui_merge_coverage_row_locked(
    const char *pass_id,
    uint64_t start_offset,
    uint64_t end_offset
)
{
    uint64_t merged_start;
    uint64_t merged_end;
    size_t i = 0U;

    if (!has_nonempty_text(pass_id) || end_offset <= start_offset) {
        return 0;
    }

    merged_start = start_offset;
    merged_end = end_offset;
    while (i < g_gui_coverage_count) {
        if (strcmp(g_gui_coverage_rows[i].pass_id, pass_id) != 0 ||
            merged_end < g_gui_coverage_rows[i].start_offset ||
            merged_start > g_gui_coverage_rows[i].end_offset) {
            i++;
            continue;
        }

        if (g_gui_coverage_rows[i].start_offset < merged_start) {
            merged_start = g_gui_coverage_rows[i].start_offset;
        }
        if (g_gui_coverage_rows[i].end_offset > merged_end) {
            merged_end = g_gui_coverage_rows[i].end_offset;
        }

        if (i + 1U < g_gui_coverage_count) {
            memmove(
                &g_gui_coverage_rows[i],
                &g_gui_coverage_rows[i + 1U],
                (g_gui_coverage_count - (i + 1U)) * sizeof(g_gui_coverage_rows[0])
            );
        }
        g_gui_coverage_count--;
    }

    if (!app_gui_coverage_rows_ensure_capacity_locked(g_gui_coverage_count + 1U)) {
        return 0;
    }

    memset(&g_gui_coverage_rows[g_gui_coverage_count], 0, sizeof(g_gui_coverage_rows[0]));
    snprintf(
        g_gui_coverage_rows[g_gui_coverage_count].pass_id,
        sizeof(g_gui_coverage_rows[g_gui_coverage_count].pass_id),
        "%s",
        pass_id
    );
    g_gui_coverage_rows[g_gui_coverage_count].start_offset = merged_start;
    g_gui_coverage_rows[g_gui_coverage_count].end_offset = merged_end;
    g_gui_coverage_count++;
    return 1;
}

static int app_gui_merge_coverage_file_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[512];
    int ok = 0;

    if (!build_state_child_path_local(run_dir, "gui_read_coverage.tsv", path, sizeof(path))) {
        return 0;
    }

    /*
     * This in-memory copy is the append/save ledger, so retain every pass.
     * Whole-source gap calculations apply their stricter pass filter later
     * in load_merged_gui_read_coverage_spans().
     */
    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *fields[3];
        size_t field_count;
        uint64_t start_offset;
        uint64_t end_offset;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }

        field_count = split_tsv_fields_preserve_empty_local(
            line,
            fields,
            sizeof(fields) / sizeof(fields[0])
        );
        if (field_count < 3U) {
            continue;
        }
        start_offset = fields[1][0] != '\0' ? strtoull(fields[1], NULL, 10) : 0ULL;
        end_offset = fields[2][0] != '\0' ? strtoull(fields[2], NULL, 10) : 0ULL;
        if (end_offset <= start_offset) {
            continue;
        }

        if (!app_gui_merge_coverage_row_locked(fields[0], start_offset, end_offset)) {
            goto cleanup;
        }
    }

    ok = 1;

cleanup:
    fclose(file);
    return ok;
}

static int app_gui_load_pass_rows_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[1024];

    if (!build_state_child_path_local(run_dir, "gui_passes.tsv", path, sizeof(path))) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *fields[12];
        size_t field_count;
        GuiPassRow row;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }

        memset(&row, 0, sizeof(row));
        field_count = split_tsv_fields_preserve_empty_local(
            line,
            fields,
            sizeof(fields) / sizeof(fields[0])
        );
        if (field_count < 12U) {
            continue;
        }

        snprintf(row.pass_id, sizeof(row.pass_id), "%s", fields[0]);
        row.pass_index = atoi(fields[1]);
        snprintf(row.mode, sizeof(row.mode), "%s", fields[2]);
        snprintf(row.kind, sizeof(row.kind), "%s", fields[3]);
        snprintf(row.label, sizeof(row.label), "%s", fields[4]);
        snprintf(row.range_kind, sizeof(row.range_kind), "%s", fields[5]);
        row.range_start_offset = fields[6][0] != '\0' ? strtoull(fields[6], NULL, 10) : 0ULL;
        row.range_end_offset = fields[7][0] != '\0' ? strtoull(fields[7], NULL, 10) : 0ULL;
        row.source_size = fields[8][0] != '\0' ? strtoull(fields[8], NULL, 10) : 0ULL;
        row.started_unix = fields[9][0] != '\0' ? (time_t)strtoull(fields[9], NULL, 10) : 0;
        row.ended_unix = fields[10][0] != '\0' ? (time_t)strtoull(fields[10], NULL, 10) : 0;
        snprintf(row.status, sizeof(row.status), "%s", fields[11]);

        if (!app_gui_pass_rows_ensure_capacity_locked(g_gui_pass_count + 1U)) {
            fclose(file);
            return 0;
        }
        g_gui_pass_rows[g_gui_pass_count++] = row;
    }

    fclose(file);
    return 1;
}

static int app_gui_load_trouble_rows_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[1024];

    if (!build_state_child_path_local(run_dir, "gui_trouble_evidence.tsv", path, sizeof(path))) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *fields[7];
        size_t field_count;
        GuiTroubleEvidenceRow row;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }

        memset(&row, 0, sizeof(row));
        field_count = split_tsv_fields_preserve_empty_local(
            line,
            fields,
            sizeof(fields) / sizeof(fields[0])
        );
        if (field_count < 7U) {
            continue;
        }

        snprintf(row.pass_id, sizeof(row.pass_id), "%s", fields[0]);
        row.start_offset = fields[1][0] != '\0' ? strtoull(fields[1], NULL, 10) : 0ULL;
        row.end_offset = fields[2][0] != '\0' ? strtoull(fields[2], NULL, 10) : 0ULL;
        snprintf(row.kind, sizeof(row.kind), "%s", fields[3]);
        row.hit_count = fields[4][0] != '\0' ? strtoull(fields[4], NULL, 10) : 0ULL;
        row.first_seen_unix = fields[5][0] != '\0' ? (time_t)strtoull(fields[5], NULL, 10) : 0;
        row.last_seen_unix = fields[6][0] != '\0' ? (time_t)strtoull(fields[6], NULL, 10) : 0;

        if (!app_gui_trouble_rows_ensure_capacity_locked(g_gui_trouble_count + 1U)) {
            fclose(file);
            return 0;
        }
        g_gui_trouble_rows[g_gui_trouble_count++] = row;
    }

    fclose(file);
    return 1;
}

static int app_gui_load_coverage_rows_locked(const char *run_dir)
{
    return app_gui_merge_coverage_file_locked(run_dir);
}

static int app_gui_save_pass_rows_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    size_t i;
    char ended_text[32];

    if (!build_state_child_path_local(run_dir, "gui_passes.tsv", path, sizeof(path)) ||
        !ensure_state_dir_for_run(run_dir)) {
        return 0;
    }

    file = fopen(path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(
        file,
        "pass_id\tpass_index\tmode\tkind\tlabel\trange_kind\trange_start_offset\trange_end_offset\tsource_size\tstarted_unix\tended_unix\tstatus\n"
    );
    for (i = 0U; i < g_gui_pass_count; i++) {
        ended_text[0] = '\0';
        if (g_gui_pass_rows[i].ended_unix > 0) {
            snprintf(
                ended_text,
                sizeof(ended_text),
                "%llu",
                (unsigned long long)g_gui_pass_rows[i].ended_unix
            );
        }
        fprintf(
            file,
            "%s\t%d\t%s\t%s\t%s\t%s\t%llu\t%llu\t%llu\t%llu\t%s\t%s\n",
            g_gui_pass_rows[i].pass_id,
            g_gui_pass_rows[i].pass_index,
            g_gui_pass_rows[i].mode,
            g_gui_pass_rows[i].kind,
            g_gui_pass_rows[i].label,
            g_gui_pass_rows[i].range_kind,
            (unsigned long long)g_gui_pass_rows[i].range_start_offset,
            (unsigned long long)g_gui_pass_rows[i].range_end_offset,
            (unsigned long long)g_gui_pass_rows[i].source_size,
            (unsigned long long)g_gui_pass_rows[i].started_unix,
            ended_text,
            g_gui_pass_rows[i].status
        );
    }

    fclose(file);
    return 1;
}

static int app_gui_save_coverage_rows_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    FILE *file;
    size_t i;

    if (!build_state_child_path_local(run_dir, "gui_read_coverage.tsv", path, sizeof(path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", path) >= (int)sizeof(temp_path) ||
        !ensure_state_dir_for_run(run_dir)) {
        return 0;
    }

    if (!app_gui_merge_coverage_file_locked(run_dir)) {
        return 0;
    }

    if (g_gui_coverage_count > 1U) {
        qsort(
            g_gui_coverage_rows,
            g_gui_coverage_count,
            sizeof(g_gui_coverage_rows[0]),
            compare_gui_coverage_rows_for_save
        );
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(file, "pass_id\tstart_offset\tend_offset\n");
    for (i = 0U; i < g_gui_coverage_count; i++) {
        fprintf(
            file,
            "%s\t%llu\t%llu\n",
            g_gui_coverage_rows[i].pass_id,
            (unsigned long long)g_gui_coverage_rows[i].start_offset,
            (unsigned long long)g_gui_coverage_rows[i].end_offset
        );
    }

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int app_gui_save_trouble_rows_locked(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 64];
    FILE *file;
    size_t i;

    if (!build_state_child_path_local(run_dir, "gui_trouble_evidence.tsv", path, sizeof(path)) ||
        snprintf(
            temp_path,
            sizeof(temp_path),
            "%s.tmp.%ld",
            path,
            (long)getpid()
        ) >= (int)sizeof(temp_path) ||
        !ensure_state_dir_for_run(run_dir)) {
        return 0;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(
        file,
        "pass_id\tstart_offset\tend_offset\tkind\thit_count\tfirst_seen_unix\tlast_seen_unix\n"
    );
    for (i = 0U; i < g_gui_trouble_count; i++) {
        fprintf(
            file,
            "%s\t%llu\t%llu\t%s\t%llu\t%llu\t%llu\n",
            g_gui_trouble_rows[i].pass_id,
            (unsigned long long)g_gui_trouble_rows[i].start_offset,
            (unsigned long long)g_gui_trouble_rows[i].end_offset,
            g_gui_trouble_rows[i].kind,
            (unsigned long long)g_gui_trouble_rows[i].hit_count,
            (unsigned long long)g_gui_trouble_rows[i].first_seen_unix,
            (unsigned long long)g_gui_trouble_rows[i].last_seen_unix
        );
    }

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int app_gui_ensure_loaded_locked(
    const char *run_dir,
    const char *current_pass_id
)
{
    const char *effective_run_dir = run_dir;
    const char *effective_pass_id = current_pass_id;
    pid_t current_pid = getpid();

    if (!has_nonempty_text(effective_run_dir)) {
        effective_run_dir = getenv(GUI_PASS_RUN_DIR_ENV);
    }
    if (!has_nonempty_text(effective_pass_id)) {
        effective_pass_id = getenv(GUI_PASS_ID_ENV);
    }
    if (!has_nonempty_text(effective_run_dir)) {
        return 0;
    }

    if (g_gui_loaded_pid != current_pid ||
        strcmp(g_gui_loaded_run_dir, effective_run_dir) != 0) {
        app_gui_clear_state_locked();
        if (!app_gui_load_pass_rows_locked(effective_run_dir) ||
            !app_gui_load_trouble_rows_locked(effective_run_dir) ||
            !app_gui_load_coverage_rows_locked(effective_run_dir)) {
            app_gui_clear_state_locked();
            return 0;
        }
        snprintf(
            g_gui_loaded_run_dir,
            sizeof(g_gui_loaded_run_dir),
            "%s",
            effective_run_dir
        );
        g_gui_loaded_pid = current_pid;
        g_gui_coverage_last_flush_at = monotonic_seconds_local();
    }

    if (has_nonempty_text(effective_pass_id)) {
        snprintf(
            g_gui_current_pass_id,
            sizeof(g_gui_current_pass_id),
            "%s",
            effective_pass_id
        );
    }

    return 1;
}

static size_t app_gui_find_pass_row_index_locked(const char *pass_id)
{
    size_t i;

    if (!has_nonempty_text(pass_id)) {
        return (size_t)-1;
    }

    for (i = 0U; i < g_gui_pass_count; i++) {
        if (strcmp(g_gui_pass_rows[i].pass_id, pass_id) == 0) {
            return i;
        }
    }

    return (size_t)-1;
}

static void app_gui_set_pass_env_locked(const char *run_dir, const char *pass_id)
{
    if (has_nonempty_text(run_dir)) {
        (void)setenv(GUI_PASS_RUN_DIR_ENV, run_dir, 1);
    }
    if (has_nonempty_text(pass_id)) {
        (void)setenv(GUI_PASS_ID_ENV, pass_id, 1);
    }
}

static int app_gui_begin_pass(
    const char *run_dir,
    const char *mode,
    const char *kind,
    const char *label,
    const char *range_kind,
    uint64_t range_start_offset,
    uint64_t range_end_offset,
    uint64_t source_size,
    char *out_pass_id,
    size_t out_pass_id_size
)
{
    GuiPassRow row;
    int next_index = 1;
    int top_level_session =
        !has_nonempty_text(getenv(GUI_PASS_ID_ENV));
    const char *supervisor_pass_id = getenv(GUI_SUPERVISOR_PASS_ID_ENV);
    int repaired_stale_pass = 0;
    size_t i;

    pthread_mutex_lock(&g_gui_evidence_mutex);

    if (!app_gui_ensure_loaded_locked(run_dir, NULL)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return 0;
    }

    if (top_level_session || has_nonempty_text(supervisor_pass_id)) {
        for (i = 0U; i < g_gui_pass_count; i++) {
            if (strcmp(g_gui_pass_rows[i].status, "running") == 0 &&
                (!has_nonempty_text(supervisor_pass_id) ||
                 strcmp(g_gui_pass_rows[i].pass_id, supervisor_pass_id) != 0)) {
                g_gui_pass_rows[i].ended_unix = time(NULL);
                snprintf(
                    g_gui_pass_rows[i].status,
                    sizeof(g_gui_pass_rows[i].status),
                    "%s",
                    "stopped"
                );
                repaired_stale_pass = 1;
            }
        }
        if (repaired_stale_pass) {
            (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);
        }
    }

    for (i = 0U; i < g_gui_pass_count; i++) {
        if (g_gui_pass_rows[i].pass_index >= next_index) {
            next_index = g_gui_pass_rows[i].pass_index + 1;
        }
    }

    memset(&row, 0, sizeof(row));
    snprintf(row.pass_id, sizeof(row.pass_id), "p%04d", next_index);
    row.pass_index = next_index;
    snprintf(row.mode, sizeof(row.mode), "%s", has_nonempty_text(mode) ? mode : "all");
    snprintf(row.kind, sizeof(row.kind), "%s", has_nonempty_text(kind) ? kind : "scan");
    snprintf(row.label, sizeof(row.label), "%s", has_nonempty_text(label) ? label : row.kind);
    snprintf(
        row.range_kind,
        sizeof(row.range_kind),
        "%s",
        has_nonempty_text(range_kind) ? range_kind : "full_source"
    );
    row.range_start_offset = range_start_offset;
    row.range_end_offset = range_end_offset;
    row.source_size = source_size;
    row.started_unix = time(NULL);
    snprintf(row.status, sizeof(row.status), "running");

    if (!app_gui_pass_rows_ensure_capacity_locked(g_gui_pass_count + 1U)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return 0;
    }
    g_gui_pass_rows[g_gui_pass_count++] = row;
    snprintf(g_gui_current_pass_id, sizeof(g_gui_current_pass_id), "%s", row.pass_id);
    app_gui_set_pass_env_locked(g_gui_loaded_run_dir, row.pass_id);
    (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);

    if (out_pass_id != NULL && out_pass_id_size > 0U) {
        snprintf(out_pass_id, out_pass_id_size, "%s", row.pass_id);
    }

    pthread_mutex_unlock(&g_gui_evidence_mutex);
    return 1;
}

static void app_gui_flush_coverage_locked(int force)
{
    double now;

    if (!g_gui_coverage_dirty || !has_nonempty_text(g_gui_loaded_run_dir)) {
        return;
    }

    now = monotonic_seconds_local();
    if (!force &&
        g_gui_coverage_dirty_bytes < GUI_READ_COVERAGE_FLUSH_BYTES &&
        g_gui_coverage_last_flush_at > 0.0 &&
        now - g_gui_coverage_last_flush_at < GUI_READ_COVERAGE_FLUSH_INTERVAL_SECONDS) {
        return;
    }

    if (app_gui_save_coverage_rows_locked(g_gui_loaded_run_dir)) {
        g_gui_coverage_dirty = 0;
        g_gui_coverage_dirty_bytes = 0ULL;
        g_gui_coverage_last_flush_at = now;
    }
}

static void app_gui_flush_current_coverage(void)
{
    pthread_mutex_lock(&g_gui_evidence_mutex);
    app_gui_flush_coverage_locked(1);
    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static void app_gui_end_current_pass(const char *status)
{
    size_t index;
    int supervisor_owned_child = app_gui_pass_supervisor_owned_child_active();
    const char *supervisor_pass_id_env = getenv(GUI_SUPERVISOR_PASS_ID_ENV);
    char supervisor_pass_id[16];

    supervisor_pass_id[0] = '\0';
    if (has_nonempty_text(supervisor_pass_id_env)) {
        snprintf(
            supervisor_pass_id,
            sizeof(supervisor_pass_id),
            "%s",
            supervisor_pass_id_env
        );
    }

    pthread_mutex_lock(&g_gui_evidence_mutex);

    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    index = app_gui_find_pass_row_index_locked(g_gui_current_pass_id);
    if (index != (size_t)-1) {
        if (supervisor_owned_child) {
            app_gui_flush_coverage_locked(1);
            pthread_mutex_unlock(&g_gui_evidence_mutex);
            return;
        }
        if (!has_nonempty_text(g_gui_pass_rows[index].status) ||
            strcmp(g_gui_pass_rows[index].status, "running") == 0) {
            g_gui_pass_rows[index].ended_unix = time(NULL);
            snprintf(
                g_gui_pass_rows[index].status,
                sizeof(g_gui_pass_rows[index].status),
                "%s",
                has_nonempty_text(status) ? status : "completed"
            );
            app_gui_flush_coverage_locked(1);
            (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);
        }
    }

    if (has_nonempty_text(supervisor_pass_id)) {
        snprintf(
            g_gui_current_pass_id,
            sizeof(g_gui_current_pass_id),
            "%s",
            supervisor_pass_id
        );
        (void)setenv(GUI_PASS_ID_ENV, supervisor_pass_id, 1);
    } else {
        g_gui_current_pass_id[0] = '\0';
        (void)unsetenv(GUI_PASS_ID_ENV);
    }
    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static void app_gui_end_pass_if_running(
    const char *run_dir,
    const char *pass_id,
    const char *status
)
{
    size_t index;
    size_t i;
    time_t ended_at;
    int changed = 0;

    pthread_mutex_lock(&g_gui_evidence_mutex);

    /*
     * A supervised raw-all child owns the live pass fields while the parent
     * waits.  Reload its on-disk row before the parent changes only status;
     * otherwise the parent's pre-fork zero-sized snapshot would overwrite
     * the child's resolved source size and selected range at completion.
     */
    app_gui_flush_coverage_locked(1);
    app_gui_clear_state_locked();
    if (!app_gui_ensure_loaded_locked(run_dir, pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    ended_at = time(NULL);
    /* A supervised child can be terminated inside a nested targeted reread.
     * There is then no child-side epilogue left to close that row.  When the
     * parent reaches a terminal state, close every orphaned nested pass while
     * keeping the named supervisor pass available for its own final status. */
    for (i = 0U; i < g_gui_pass_count; i++) {
        if (strcmp(g_gui_pass_rows[i].status, "running") == 0 &&
            (!has_nonempty_text(pass_id) ||
             strcmp(g_gui_pass_rows[i].pass_id, pass_id) != 0)) {
            g_gui_pass_rows[i].ended_unix = ended_at;
            snprintf(
                g_gui_pass_rows[i].status,
                sizeof(g_gui_pass_rows[i].status),
                "%s",
                "stopped"
            );
            changed = 1;
        }
    }

    index = app_gui_find_pass_row_index_locked(pass_id);
    if (index != (size_t)-1 &&
        (!has_nonempty_text(g_gui_pass_rows[index].status) ||
         strcmp(g_gui_pass_rows[index].status, "running") == 0)) {
        g_gui_pass_rows[index].ended_unix = ended_at;
        snprintf(
            g_gui_pass_rows[index].status,
            sizeof(g_gui_pass_rows[index].status),
            "%s",
            has_nonempty_text(status) ? status : "completed"
        );
        changed = 1;
    }
    if (changed) {
        app_gui_flush_coverage_locked(1);
        (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);
    }

    if (has_nonempty_text(pass_id) &&
        strcmp(g_gui_current_pass_id, pass_id) == 0) {
        g_gui_current_pass_id[0] = '\0';
        (void)unsetenv(GUI_PASS_ID_ENV);
    }

    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static void app_gui_set_current_pass_source_size(uint64_t source_size)
{
    size_t index;

    if (source_size == 0ULL) {
        return;
    }

    pthread_mutex_lock(&g_gui_evidence_mutex);

    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    index = app_gui_find_pass_row_index_locked(g_gui_current_pass_id);
    if (index != (size_t)-1) {
        int changed = 0;

        if (g_gui_pass_rows[index].source_size != source_size) {
            g_gui_pass_rows[index].source_size = source_size;
            changed = 1;
        }
        if (strcmp(g_gui_pass_rows[index].range_kind, "full_source") == 0 &&
            g_gui_pass_rows[index].range_end_offset != source_size) {
            g_gui_pass_rows[index].range_end_offset = source_size;
            changed = 1;
        }
        if (changed) {
            (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);
        }
    }

    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static void app_gui_set_current_pass_scope(
    uint64_t source_size,
    uint64_t range_start,
    uint64_t range_end,
    const char *range_kind)
{
    size_t index;

    if (source_size == 0ULL || range_end <= range_start) {
        return;
    }
    pthread_mutex_lock(&g_gui_evidence_mutex);
    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }
    index = app_gui_find_pass_row_index_locked(g_gui_current_pass_id);
    if (index != (size_t)-1) {
        g_gui_pass_rows[index].source_size = source_size;
        g_gui_pass_rows[index].range_start_offset = range_start;
        g_gui_pass_rows[index].range_end_offset = range_end;
        snprintf(
            g_gui_pass_rows[index].range_kind,
            sizeof(g_gui_pass_rows[index].range_kind),
            "%s",
            has_nonempty_text(range_kind) ? range_kind : "selected_range"
        );
        (void)app_gui_save_pass_rows_locked(g_gui_loaded_run_dir);
    }
    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

void app_gui_note_trouble(uint64_t start_offset, uint64_t end_offset, const char *kind)
{
    size_t i;
    time_t now;

    if (!has_nonempty_text(kind) || end_offset <= start_offset) {
        return;
    }

    pthread_mutex_lock(&g_gui_evidence_mutex);

    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    now = time(NULL);
    for (i = 0U; i < g_gui_trouble_count; i++) {
        uint64_t merged_start;
        uint64_t merged_end;

        if (strcmp(g_gui_trouble_rows[i].pass_id, g_gui_current_pass_id) != 0 ||
            strcmp(g_gui_trouble_rows[i].kind, kind) != 0) {
            continue;
        }
        if (end_offset + GUI_TROUBLE_MERGE_GAP_BYTES < g_gui_trouble_rows[i].start_offset ||
            start_offset > g_gui_trouble_rows[i].end_offset + GUI_TROUBLE_MERGE_GAP_BYTES) {
            continue;
        }

        merged_start = start_offset < g_gui_trouble_rows[i].start_offset
            ? start_offset
            : g_gui_trouble_rows[i].start_offset;
        merged_end = end_offset > g_gui_trouble_rows[i].end_offset
            ? end_offset
            : g_gui_trouble_rows[i].end_offset;
        g_gui_trouble_rows[i].start_offset = merged_start;
        g_gui_trouble_rows[i].end_offset = merged_end;
        g_gui_trouble_rows[i].hit_count++;
        if (g_gui_trouble_rows[i].first_seen_unix == 0) {
            g_gui_trouble_rows[i].first_seen_unix = now;
        }
        g_gui_trouble_rows[i].last_seen_unix = now;
        (void)app_gui_save_trouble_rows_locked(g_gui_loaded_run_dir);
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    if (!app_gui_trouble_rows_ensure_capacity_locked(g_gui_trouble_count + 1U)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    memset(&g_gui_trouble_rows[g_gui_trouble_count], 0, sizeof(g_gui_trouble_rows[0]));
    snprintf(
        g_gui_trouble_rows[g_gui_trouble_count].pass_id,
        sizeof(g_gui_trouble_rows[g_gui_trouble_count].pass_id),
        "%s",
        g_gui_current_pass_id
    );
    g_gui_trouble_rows[g_gui_trouble_count].start_offset = start_offset;
    g_gui_trouble_rows[g_gui_trouble_count].end_offset = end_offset;
    snprintf(
        g_gui_trouble_rows[g_gui_trouble_count].kind,
        sizeof(g_gui_trouble_rows[g_gui_trouble_count].kind),
        "%s",
        kind
    );
    g_gui_trouble_rows[g_gui_trouble_count].hit_count = 1U;
    g_gui_trouble_rows[g_gui_trouble_count].first_seen_unix = now;
    g_gui_trouble_rows[g_gui_trouble_count].last_seen_unix = now;
    g_gui_trouble_count++;
    (void)app_gui_save_trouble_rows_locked(g_gui_loaded_run_dir);

    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static uint64_t app_saturating_add_u64(uint64_t lhs, uint64_t rhs)
{
    if (UINT64_MAX - lhs < rhs) {
        return UINT64_MAX;
    }
    return lhs + rhs;
}

static const char *app_gui_safe_recovery_geometry_token(
    const char *geometry,
    uint64_t start_offset,
    uint64_t end_offset
)
{
    if (geometry != NULL &&
        strnlen(geometry, 16U) == 5U &&
        memcmp(geometry, "point", 5U) == 0) {
        return "point";
    }
    if (geometry != NULL &&
        strnlen(geometry, 16U) == 4U &&
        memcmp(geometry, "span", 4U) == 0 &&
        end_offset > start_offset) {
        return "span";
    }
    return end_offset > start_offset ? "span" : "point";
}

static const char *app_gui_safe_recovery_kind_token(const char *kind)
{
    if (kind != NULL &&
        strnlen(kind, 32U) == 9U &&
        memcmp(kind, "recovered", 9U) == 0) {
        return "recovered";
    }
    if (kind != NULL &&
        strnlen(kind, 32U) == 22U &&
        memcmp(kind, "recovered_from_trouble", 22U) == 0) {
        return "recovered_from_trouble";
    }
    return "recovered";
}

static const char *app_gui_safe_recovery_confidence_token(const char *confidence)
{
    if (confidence != NULL &&
        strnlen(confidence, 32U) == 5U &&
        memcmp(confidence, "exact", 5U) == 0) {
        return "exact";
    }
    if (confidence != NULL &&
        strnlen(confidence, 32U) == 9U &&
        memcmp(confidence, "estimated", 9U) == 0) {
        return "estimated";
    }
    if (confidence != NULL &&
        strnlen(confidence, 32U) == 6U &&
        memcmp(confidence, "marker", 6U) == 0) {
        return "marker";
    }
    return "estimated";
}

static void app_gui_copy_safe_pass_id(
    const char *pass_id,
    char *out,
    size_t out_size
)
{
    size_t index;

    if (out == NULL || out_size == 0U) {
        return;
    }
    snprintf(out, out_size, "p0000");
    if (!has_nonempty_text(pass_id)) {
        return;
    }
    for (index = 0U; index + 1U < out_size && index < 31U; index++) {
        unsigned char ch = (unsigned char)pass_id[index];
        if (ch == '\0') {
            break;
        }
        if (!(isalnum(ch) || ch == '_' || ch == '-')) {
            if (index == 0U) {
                snprintf(out, out_size, "p0000");
            } else {
                out[index] = '\0';
            }
            return;
        }
        out[index] = (char)ch;
    }
    out[index < out_size ? index : out_size - 1U] = '\0';
}

static void app_gui_write_recovery_evidence_row(
    FILE *file,
    const char *pass_id,
    const char *geometry,
    uint64_t start_offset,
    uint64_t end_offset,
    const char *kind,
    const char *confidence,
    uint64_t output_count
)
{
    char safe_pass_id[32];
    const char *safe_geometry;
    const char *safe_kind;
    const char *safe_confidence;

    if (file == NULL || !has_nonempty_text(pass_id)) {
        return;
    }
    safe_geometry = app_gui_safe_recovery_geometry_token(
        geometry,
        start_offset,
        end_offset
    );
    if (strcmp(safe_geometry, "point") == 0) {
        end_offset = start_offset;
    } else if (end_offset <= start_offset) {
        end_offset = start_offset;
        safe_geometry = "point";
    }
    if (output_count == 0ULL) {
        output_count = 1ULL;
    }
    app_gui_copy_safe_pass_id(pass_id, safe_pass_id, sizeof(safe_pass_id));
    safe_kind = app_gui_safe_recovery_kind_token(kind);
    safe_confidence = app_gui_safe_recovery_confidence_token(confidence);

    fprintf(
        file,
        "%s\t%s\t%llu\t%llu\t%s\t%s\t%llu\n",
        safe_pass_id,
        safe_geometry,
        (unsigned long long)start_offset,
        (unsigned long long)end_offset,
        safe_kind,
        safe_confidence,
        (unsigned long long)output_count
    );
}

static void app_gui_lock_evidence_file(FILE *file)
{
#if defined(__APPLE__) || defined(__linux__) || defined(__unix__)
    if (file != NULL) {
        (void)flock(fileno(file), LOCK_EX);
    }
#else
    (void)file;
#endif
}

static void app_gui_unlock_evidence_file(FILE *file)
{
#if defined(__APPLE__) || defined(__linux__) || defined(__unix__)
    if (file != NULL) {
        (void)flock(fileno(file), LOCK_UN);
    }
#else
    (void)file;
#endif
}

static int raw_all_revisit_status_path_local(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    if (!has_nonempty_text(run_dir) || out == NULL || out_size == 0U) {
        return 0;
    }
    return snprintf(
               out,
               out_size,
               "%s/" APP_STATE_DIR_NAME "/revisit_status.txt",
               run_dir
           ) < (int)out_size;
}

static void raw_all_revisit_status_write_local(const char *status)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 48U];
    FILE *file;
    size_t extra_files;
    time_t now;

    if (!g_raw_all_revisit_active ||
        !raw_all_revisit_status_path_local(
            g_raw_all_revisit_run_dir,
            path,
            sizeof(path)) ||
        snprintf(
            temp_path,
            sizeof(temp_path),
            "%s.tmp.%ld",
            path,
            (long)getpid()) >= (int)sizeof(temp_path)) {
        return;
    }
    file = fopen(temp_path, "w");
    if (file == NULL) {
        return;
    }
    now = time(NULL);
    extra_files =
        g_raw_all_revisit_current_recovered >=
                g_raw_all_revisit_baseline_recovered
            ? g_raw_all_revisit_current_recovered -
                  g_raw_all_revisit_baseline_recovered
            : 0U;
    (void)chmod(temp_path, 0644);
    fprintf(file, "version=1\n");
    fprintf(file, "updated_unix=%llu\n", (unsigned long long)now);
    fprintf(
        file,
        "status=%s\n",
        has_nonempty_text(status) ? status : "active");
    fprintf(
        file,
        "started_unix=%llu\n",
        (unsigned long long)g_raw_all_revisit_started_unix);
    fprintf(
        file,
        "baseline_recovered=%zu\n",
        g_raw_all_revisit_baseline_recovered);
    fprintf(
        file,
        "current_recovered=%zu\n",
        g_raw_all_revisit_current_recovered);
    fprintf(file, "extra_files=%zu\n", extra_files);
    fprintf(
        file,
        "last_complete_file_unix=%llu\n",
        (unsigned long long)g_raw_all_revisit_last_complete_unix);
    if (fclose(file) != 0 || rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return;
    }
    (void)mft_apply_output_owner_to_path(path);
    g_raw_all_revisit_last_flush_at = monotonic_seconds_local();
}

static void raw_all_revisit_status_begin(
    const char *run_dir,
    size_t recovered_count
)
{
    char path[PATH_MAX_LEN];
    FILE *file = NULL;
    char line[256];
    time_t saved_started = 0;
    time_t saved_last_complete = 0;
    size_t saved_baseline = 0U;
    size_t saved_current = 0U;

    if (!has_nonempty_text(run_dir) ||
        !raw_all_revisit_status_path_local(run_dir, path, sizeof(path))) {
        return;
    }
    pthread_mutex_lock(&g_gui_evidence_mutex);
    file = fopen(path, "r");
    if (file != NULL) {
        while (fgets(line, sizeof(line), file) != NULL) {
            unsigned long long value = 0ULL;

            if (sscanf(line, "started_unix=%llu", &value) == 1) {
                saved_started = (time_t)value;
            } else if (sscanf(line, "baseline_recovered=%llu", &value) == 1) {
                saved_baseline = (size_t)value;
            } else if (sscanf(line, "current_recovered=%llu", &value) == 1) {
                saved_current = (size_t)value;
            } else if (sscanf(line, "last_complete_file_unix=%llu", &value) == 1) {
                saved_last_complete = (time_t)value;
            }
        }
        fclose(file);
    }

    snprintf(
        g_raw_all_revisit_run_dir,
        sizeof(g_raw_all_revisit_run_dir),
        "%s",
        run_dir);
    g_raw_all_revisit_active = 1;
    g_raw_all_revisit_started_unix =
        saved_started > 0 ? saved_started : time(NULL);
    g_raw_all_revisit_baseline_recovered =
        saved_started > 0 ? saved_baseline : recovered_count;
    g_raw_all_revisit_current_recovered = recovered_count;
    if (saved_current > g_raw_all_revisit_current_recovered) {
        g_raw_all_revisit_current_recovered = saved_current;
    }
    g_raw_all_revisit_last_complete_unix = saved_last_complete;
    if (saved_started > 0 && recovered_count > saved_current) {
        /* A previous child may have produced files and then been killed
         * before its compact telemetry flush.  Heal that delta when the same
         * run is reopened instead of leaving last_complete permanently stale. */
        g_raw_all_revisit_last_complete_unix = time(NULL);
    }
    raw_all_revisit_status_write_local("active");
    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static void raw_all_revisit_status_note_recovery_local(void)
{
    double now;

    if (!g_raw_all_revisit_active) {
        return;
    }
    if (g_raw_all_revisit_current_recovered < SIZE_MAX) {
        g_raw_all_revisit_current_recovered++;
    }
    g_raw_all_revisit_last_complete_unix = time(NULL);
    now = monotonic_seconds_local();
    if (g_raw_all_revisit_last_flush_at <= 0.0 ||
        now - g_raw_all_revisit_last_flush_at >= 1.0) {
        raw_all_revisit_status_write_local("active");
    }
}

static void raw_all_revisit_status_sync(const char *status)
{
    size_t recovered_count;

    if (!g_raw_all_revisit_active) {
        return;
    }
    recovered_count = fs_backend_recovered_output_count();
    pthread_mutex_lock(&g_gui_evidence_mutex);
    if (recovered_count > g_raw_all_revisit_current_recovered) {
        g_raw_all_revisit_current_recovered = recovered_count;
        g_raw_all_revisit_last_complete_unix = time(NULL);
    }
    raw_all_revisit_status_write_local(status);
    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

void app_gui_note_recovery_path(const char *recovered_path, long long abs_offset)
{
    char evidence_path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    int append_mode = 0;
    FsScanHint hint;
    FsViewEntry view;
    const char *confidence = "marker";
    uint64_t start_offset;
    uint64_t end_offset;
    int wrote_row = 0;

    if (abs_offset < 0) {
        return;
    }

    pthread_mutex_lock(&g_gui_evidence_mutex);

    /* The backend calls this only after a complete output has been accepted.
     * Keep the post-scan counter here so HFS+, NTFS and future backends all
     * report revisit gains through the same small state file.  The evidence
     * mutex also serializes callbacks from asynchronous output workers. */
    raw_all_revisit_status_note_recovery_local();

    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id) ||
        !build_state_child_path_local(
            g_gui_loaded_run_dir,
            "gui_recovery_evidence.tsv",
            evidence_path,
            sizeof(evidence_path)) ||
        !ensure_state_dir_for_run(g_gui_loaded_run_dir)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    start_offset = (uint64_t)abs_offset;
    end_offset = start_offset;
    memset(&hint, 0, sizeof(hint));
    memset(&view, 0, sizeof(view));

    file = fopen(evidence_path, "a+");
    if (file == NULL) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    app_gui_lock_evidence_file(file);
    append_mode = (fstat(fileno(file), &st) == 0 && st.st_size > 0);
    if (!append_mode) {
        fprintf(
            file,
            "pass_id\tgeometry\tstart_offset\tend_offset\tkind\tconfidence\toutput_count\n"
        );
    }

    if (fs_backend_lookup_scan_hint(abs_offset, &hint)) {
        if (hint.exact_data_match &&
            fs_backend_get_view_entry_by_offset(abs_offset, &view)) {
            size_t run_index;

            confidence = "exact";
            for (run_index = 0U; run_index < view.run_count; run_index++) {
                uint64_t run_start = view.runs[run_index].abs_offset;
                uint64_t run_end;

                if (view.runs[run_index].byte_length == 0ULL) {
                    continue;
                }
                run_end = app_saturating_add_u64(
                    run_start,
                    view.runs[run_index].byte_length
                );
                app_gui_write_recovery_evidence_row(
                    file,
                    g_gui_current_pass_id,
                    "span",
                    run_start,
                    run_end,
                    "recovered",
                    confidence,
                    1ULL
                );
                wrote_row = 1;
            }

            if (!wrote_row && view.data_size > 0ULL) {
                start_offset = (uint64_t)abs_offset;
                end_offset = app_saturating_add_u64(start_offset, view.data_size);
                app_gui_write_recovery_evidence_row(
                    file,
                    g_gui_current_pass_id,
                    "span",
                    start_offset,
                    end_offset,
                    "recovered",
                    confidence,
                    1ULL
                );
                wrote_row = 1;
            }
        } else if (hint.inside_nonresident_run) {
            confidence = "estimated";
        }
    }

    if (!wrote_row &&
        has_nonempty_text(recovered_path) &&
        stat(recovered_path, &st) == 0 &&
        st.st_size > 0) {
        end_offset = app_saturating_add_u64(start_offset, (uint64_t)st.st_size);
        app_gui_write_recovery_evidence_row(
            file,
            g_gui_current_pass_id,
            "span",
            start_offset,
            end_offset,
            "recovered",
            confidence[0] != '\0' && strcmp(confidence, "marker") != 0 ? confidence : "estimated",
            1ULL
        );
        wrote_row = 1;
    }

    if (!wrote_row) {
        app_gui_write_recovery_evidence_row(
            file,
            g_gui_current_pass_id,
            "point",
            start_offset,
            start_offset,
            "recovered",
            confidence,
            1ULL
        );
    }
    (void)fflush(file);
    app_gui_unlock_evidence_file(file);
    fclose(file);

    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

void app_gui_note_recovery(long long abs_offset)
{
    app_gui_note_recovery_path(NULL, abs_offset);
}

static void app_gui_note_live_coverage_gap_locked(
    uint64_t read_start,
    uint64_t read_end
)
{
    uint64_t previous_end = 0ULL;
    size_t i;

    if (read_end <= read_start ||
        !has_nonempty_text(g_gui_loaded_run_dir) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        return;
    }

    for (i = 0U; i < g_gui_coverage_count; i++) {
        if (strcmp(g_gui_coverage_rows[i].pass_id, g_gui_current_pass_id) != 0) {
            continue;
        }
        if (g_gui_coverage_rows[i].start_offset <= read_start &&
            g_gui_coverage_rows[i].end_offset >= read_start) {
            return;
        }
        if (g_gui_coverage_rows[i].end_offset <= read_start &&
            g_gui_coverage_rows[i].end_offset > previous_end) {
            previous_end = g_gui_coverage_rows[i].end_offset;
        }
    }

    if (previous_end == 0ULL ||
        read_start <= previous_end ||
        read_start - previous_end <
            RAW_ALL_COVERAGE_GAP_LIVE_OBSERVATION_MIN_BYTES) {
        return;
    }

    if (strcmp(g_gui_last_live_gap_pass_id, g_gui_current_pass_id) == 0 &&
        g_gui_last_live_gap_start == previous_end &&
        g_gui_last_live_gap_end == read_start) {
        return;
    }

    append_coverage_gap_observation_for_run_dir(
        g_gui_loaded_run_dir,
        g_gui_current_pass_id,
        previous_end,
        read_start,
        read_start,
        read_end,
        "observed_live"
    );
    snprintf(
        g_gui_last_live_gap_pass_id,
        sizeof(g_gui_last_live_gap_pass_id),
        "%s",
        g_gui_current_pass_id
    );
    g_gui_last_live_gap_start = previous_end;
    g_gui_last_live_gap_end = read_start;
}

void app_gui_note_read_coverage(uint64_t start_offset, uint64_t end_offset)
{
    if (end_offset <= start_offset) {
        return;
    }

    if (app_supervisor_generation_stale()) {
        return;
    }

    pthread_mutex_lock(&g_gui_evidence_mutex);

    if (!app_gui_ensure_loaded_locked(NULL, NULL) ||
        !has_nonempty_text(g_gui_current_pass_id)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }
    if (!app_gui_current_pass_counts_for_raw_coverage_locked()) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }

    app_gui_note_live_coverage_gap_locked(start_offset, end_offset);

    if (!app_gui_merge_coverage_row_locked(
            g_gui_current_pass_id,
            start_offset,
            end_offset)) {
        pthread_mutex_unlock(&g_gui_evidence_mutex);
        return;
    }
    g_gui_coverage_dirty = 1;
    g_gui_coverage_dirty_bytes += end_offset - start_offset;
    app_gui_flush_coverage_locked(0);

    pthread_mutex_unlock(&g_gui_evidence_mutex);
}

static uint64_t probe_input_size_for_eta(const char *path)
{
    struct stat st;

    if (path == NULL) {
        return 0;
    }

    if (stat(path, &st) != 0) {
        return 0;
    }

    if (S_ISREG(st.st_mode) && st.st_size > 0) {
        return (uint64_t)st.st_size;
    }

    return 0;
}

static uint64_t raw_all_effective_scan_end_offset_for_source(
    const AppConfig *config,
    uint64_t source_size
);
static uint64_t raw_all_effective_scan_start_offset_for_source(
    const AppConfig *config,
    uint64_t source_size
);

static uint64_t raw_all_effective_progress_total_bytes_for_source(
    const AppConfig *config,
    uint64_t source_size
)
{
    uint64_t stop_offset;
    uint64_t start_offset;

    stop_offset = raw_all_effective_scan_end_offset_for_source(config, source_size);
    start_offset = raw_all_effective_scan_start_offset_for_source(config, source_size);
    return stop_offset > start_offset ? stop_offset - start_offset : stop_offset;
}

static uint64_t raw_all_effective_scan_end_offset_for_source(
    const AppConfig *config,
    uint64_t source_size
)
{
    uint64_t stop_offset = source_size;

    if (config != NULL && config->mft_limit > 0ULL) {
        stop_offset = (uint64_t)config->mft_limit;
        if (config->manual_start_explicit &&
            config->manual_start_offset > 0ULL &&
            stop_offset <= (uint64_t)config->manual_start_offset) {
            uint64_t start_offset = (uint64_t)config->manual_start_offset;
            if (UINT64_MAX - start_offset < stop_offset) {
                stop_offset = UINT64_MAX;
            } else {
                stop_offset = start_offset + stop_offset;
            }
        }
        if (source_size > 0ULL && stop_offset > source_size) {
            stop_offset = source_size;
        }
    }

    return stop_offset;
}

static uint64_t raw_all_effective_scan_start_offset_for_source(
    const AppConfig *config,
    uint64_t source_size
)
{
    uint64_t stop_offset =
        raw_all_effective_scan_end_offset_for_source(config, source_size);

    if (config != NULL &&
        config->manual_start_explicit &&
        config->manual_start_offset < stop_offset) {
        return (uint64_t)config->manual_start_offset;
    }

    return 0ULL;
}

typedef enum {
    RAW_ALL_MACHINE_TUNING_CONSTRAINED = 0,
    RAW_ALL_MACHINE_TUNING_BALANCED = 1,
    RAW_ALL_MACHINE_TUNING_AGGRESSIVE = 2
} RawAllMachineTuningProfile;

static const char *raw_all_machine_tuning_profile_label(
    RawAllMachineTuningProfile profile
)
{
    switch (profile) {
        case RAW_ALL_MACHINE_TUNING_AGGRESSIVE:
            return "aggressive";
        case RAW_ALL_MACHINE_TUNING_BALANCED:
            return "balanced";
        default:
            return "constrained";
    }
}

static RawAllMachineTuningProfile detect_raw_all_machine_tuning_profile(
    const PlatformSystemMemory *memory,
    long cpu_count
)
{
    uint64_t total_bytes = 0ULL;
    uint64_t available_bytes = 0ULL;

    if (memory != NULL) {
        total_bytes = memory->has_total ? memory->total_bytes : 0ULL;
        available_bytes = memory->has_available ? memory->available_bytes : 0ULL;
    }

    if (cpu_count > 0 &&
        cpu_count <= 4 &&
        ((available_bytes > 0ULL &&
          available_bytes < (4ULL * 1024ULL * 1024ULL * 1024ULL)) ||
         (total_bytes > 0ULL &&
          total_bytes < (8ULL * 1024ULL * 1024ULL * 1024ULL)))) {
        return RAW_ALL_MACHINE_TUNING_CONSTRAINED;
    }

    if (cpu_count >= 8 &&
        ((available_bytes >= (6ULL * 1024ULL * 1024ULL * 1024ULL)) ||
         (total_bytes >= (12ULL * 1024ULL * 1024ULL * 1024ULL)))) {
        return RAW_ALL_MACHINE_TUNING_AGGRESSIVE;
    }

    return RAW_ALL_MACHINE_TUNING_BALANCED;
}

static uint64_t raw_all_effective_progress_processed_bytes_for_offset(
    const AppConfig *config,
    uint64_t source_size,
    uint64_t processed_offset
)
{
    uint64_t total_bytes =
        raw_all_effective_progress_total_bytes_for_source(config, source_size);
    uint64_t start_offset =
        raw_all_effective_scan_start_offset_for_source(config, source_size);

    if (start_offset > 0ULL) {
        processed_offset =
            processed_offset > start_offset ? processed_offset - start_offset : 0ULL;
    }
    if (total_bytes > 0ULL && processed_offset > total_bytes) {
        processed_offset = total_bytes;
    }

    return processed_offset;
}

static void maybe_raise_raw_all_chunk_size(AppConfig *config)
{
    struct stat st;
    size_t target_chunk_size = RAW_ALL_BLOCK_DEVICE_CHUNK_SIZE;
    int regular_file_source = 0;

    if (config == NULL) {
        return;
    }

    if (config->scan_mode != APP_SCAN_MODE_RAW_ALL) {
        return;
    }

    if (has_nonempty_text(config->input_path) &&
        stat(config->input_path, &st) == 0 &&
        S_ISREG(st.st_mode)) {
        PlatformSystemMemory memory = {0};
        long cpu_count = sysconf(_SC_NPROCESSORS_ONLN);
        RawAllMachineTuningProfile tuning_profile =
            RAW_ALL_MACHINE_TUNING_BALANCED;

        regular_file_source = 1;

        if (platform_get_system_memory(&memory)) {
            tuning_profile =
                detect_raw_all_machine_tuning_profile(&memory, cpu_count);
            uint64_t available_bytes =
                memory.has_available ? memory.available_bytes : 0ULL;
            uint64_t safe_available_cap = 0ULL;

            if (tuning_profile == RAW_ALL_MACHINE_TUNING_AGGRESSIVE) {
                target_chunk_size = RAW_ALL_REGULAR_FILE_CHUNK_SIZE_HIGH;
            } else if (tuning_profile == RAW_ALL_MACHINE_TUNING_BALANCED) {
                target_chunk_size = RAW_ALL_REGULAR_FILE_CHUNK_SIZE_MEDIUM;
            }

            if (available_bytes > 0ULL) {
                safe_available_cap = available_bytes / 64ULL;
                if (safe_available_cap < (uint64_t)target_chunk_size) {
                    if (safe_available_cap >= RAW_ALL_BLOCK_DEVICE_CHUNK_SIZE) {
                        target_chunk_size = (size_t)safe_available_cap;
                    } else {
                        target_chunk_size = RAW_ALL_BLOCK_DEVICE_CHUNK_SIZE;
                    }
                }
            }
        }

        if (cpu_count > 0 &&
            cpu_count <= 4 &&
            target_chunk_size > RAW_ALL_REGULAR_FILE_CHUNK_SIZE_MEDIUM) {
            target_chunk_size = RAW_ALL_REGULAR_FILE_CHUNK_SIZE_MEDIUM;
        }

        log_info(
            "Raw-all machine tuning: source=regular-file profile=%s cpu=%ld chunk_target=%.1f MiB",
            raw_all_machine_tuning_profile_label(tuning_profile),
            cpu_count > 0 ? cpu_count : 0L,
            (double)target_chunk_size / (1024.0 * 1024.0)
        );
    }

    if (config->chunk_size < target_chunk_size) {
        log_info(
            "Raw-all chunk tuning: source=%s chunk=%.1f->%.1f MiB",
            has_nonempty_text(config->input_path) ? config->input_path : "(unknown)",
            (double)config->chunk_size / (1024.0 * 1024.0),
            (double)target_chunk_size / (1024.0 * 1024.0)
        );
        config->chunk_size = target_chunk_size;
    } else if (regular_file_source) {
        log_info(
            "Raw-all chunk tuning: source=%s chunk=%.1f MiB already meets tuned target",
            has_nonempty_text(config->input_path) ? config->input_path : "(unknown)",
            (double)config->chunk_size / (1024.0 * 1024.0)
        );
    }
}

static int parse_missed_runs(char *raw, MissedReportEntry *entry)
{
    char *token;

    if (raw == NULL || entry == NULL) {
        return 0;
    }

    token = strtok(raw, ",");
    while (token != NULL && entry->run_count < FS_VIEW_MAX_RUNS) {
        unsigned long long abs_offset = 0;
        unsigned long long byte_length = 0;

        if (strcmp(token, "-") == 0) {
            return entry->run_count == 0;
        }
        if (sscanf(token, "%llu:%llu", &abs_offset, &byte_length) != 2 ||
            byte_length == 0) {
            return 0;
        }

        entry->runs[entry->run_count].abs_offset = (uint64_t)abs_offset;
        entry->runs[entry->run_count].byte_length = (uint64_t)byte_length;
        entry->run_count++;
        token = strtok(NULL, ",");
    }

    return entry->run_count > 0;
}

static int parse_missed_report_line(char *line, MissedReportEntry *entry)
{
    char *path;
    char *name;
    char *abs_offset_text;
    char *data_size_text;
    char *run_count_text;
    char *resident_text;
    char *record_abs_offset_text;
    char *created_unix_text;
    char *runs_text;
    unsigned long long data_size = 0;
    unsigned long long expected_run_count = 0;
    long long abs_offset = 0;
    unsigned long long record_abs_offset = 0;
    long long created_unix = 0;

    if (line == NULL || entry == NULL) {
        return 0;
    }

    memset(entry, 0, sizeof(*entry));

    path = strtok(line, "\t\n");
    name = strtok(NULL, "\t\n");
    abs_offset_text = strtok(NULL, "\t\n");
    data_size_text = strtok(NULL, "\t\n");
    run_count_text = strtok(NULL, "\t\n");
    resident_text = strtok(NULL, "\t\n");
    record_abs_offset_text = strtok(NULL, "\t\n");
    created_unix_text = strtok(NULL, "\t\n");
    runs_text = strtok(NULL, "\t\n");

    (void)name;

    if (path == NULL ||
        abs_offset_text == NULL ||
        data_size_text == NULL ||
        run_count_text == NULL ||
        sscanf(abs_offset_text, "%lld", &abs_offset) != 1 ||
        sscanf(data_size_text, "%llu", &data_size) != 1 ||
        sscanf(run_count_text, "%llu", &expected_run_count) != 1 ||
        data_size == 0 ||
        strlen(path) >= sizeof(entry->path)) {
        if (path == NULL ||
            data_size_text == NULL ||
            run_count_text == NULL ||
            runs_text == NULL ||
            sscanf(data_size_text, "%llu", &data_size) != 1 ||
            sscanf(run_count_text, "%llu", &expected_run_count) != 1 ||
            data_size == 0 ||
            strlen(path) >= sizeof(entry->path)) {
            return 0;
        }
        abs_offset = 0;
    }

    snprintf(entry->path, sizeof(entry->path), "%s", path);
    entry->abs_offset = (long long)abs_offset;
    entry->expected_size = (uint64_t)data_size;
    entry->data_size = (uint64_t)data_size;

    if (resident_text != NULL && record_abs_offset_text != NULL &&
        created_unix_text != NULL && runs_text != NULL) {
        entry->resident = atoi(resident_text) != 0;
        if (sscanf(record_abs_offset_text, "%llu", &record_abs_offset) == 1) {
            entry->record_abs_offset = (uint64_t)record_abs_offset;
        }
        if (sscanf(created_unix_text, "%lld", &created_unix) == 1 && created_unix > 0) {
            entry->created_unix = (time_t)created_unix;
        }
    } else {
        runs_text = resident_text;
        entry->resident = 0;
    }

    if (entry->resident) {
        return expected_run_count == 0U &&
               entry->record_abs_offset > 0U &&
               (runs_text == NULL || strcmp(runs_text, "-") == 0);
    }

    if (expected_run_count == 0U) {
        return 0;
    }
    if (runs_text == NULL || !parse_missed_runs(runs_text, entry)) {
        return 0;
    }

    return entry->run_count == (size_t)expected_run_count;
}

static int output_mount_root_from_path_for_write_guard(
    const char *path,
    char *out_root,
    size_t out_root_size
)
{
    if (out_root != NULL && out_root_size > 0U) {
        out_root[0] = '\0';
    }
    if (!has_nonempty_text(path) || out_root == NULL || out_root_size == 0U) {
        return 0;
    }

    if (strncmp(path, "/media/", 7U) == 0) {
        const char *rest = path + 7U;
        const char *user_slash = strchr(rest, '/');
        const char *leaf_start;
        const char *leaf_slash;
        size_t root_len;

        if (user_slash == NULL || user_slash == rest || user_slash[1] == '\0') {
            return 0;
        }
        leaf_start = user_slash + 1;
        leaf_slash = strchr(leaf_start, '/');
        root_len = leaf_slash != NULL ? (size_t)(leaf_slash - path) : strlen(path);
        if (root_len == 0U || root_len >= out_root_size) {
            return 0;
        }
        memcpy(out_root, path, root_len);
        out_root[root_len] = '\0';
        return 1;
    }

    if (strncmp(path, "/Volumes/", 9U) == 0) {
        const char *leaf_start = path + 9U;
        const char *leaf_slash;
        size_t root_len;

        if (*leaf_start == '\0') {
            return 0;
        }
        leaf_slash = strchr(leaf_start, '/');
        root_len = leaf_slash != NULL ? (size_t)(leaf_slash - path) : strlen(path);
        if (root_len == 0U || root_len >= out_root_size) {
            return 0;
        }
        memcpy(out_root, path, root_len);
        out_root[root_len] = '\0';
        return 1;
    }

    return 0;
}

static int parent_path_for_write_guard(
    const char *path,
    char *out_parent,
    size_t out_parent_size
)
{
    const char *last_slash;
    size_t parent_len;

    if (out_parent != NULL && out_parent_size > 0U) {
        out_parent[0] = '\0';
    }
    if (!has_nonempty_text(path) || out_parent == NULL || out_parent_size == 0U) {
        return 0;
    }

    last_slash = strrchr(path, '/');
    if (last_slash == NULL) {
        return 0;
    }
    if (last_slash == path) {
        return snprintf(out_parent, out_parent_size, "/") < (int)out_parent_size;
    }
    parent_len = (size_t)(last_slash - path);
    if (parent_len == 0U || parent_len >= out_parent_size) {
        return 0;
    }
    memcpy(out_parent, path, parent_len);
    out_parent[parent_len] = '\0';
    return 1;
}

static int output_mount_root_is_live_for_write_guard(const char *mount_root)
{
    char parent[PATH_MAX_LEN];
    struct stat mount_st;
    struct stat parent_st;

    if (!has_nonempty_text(mount_root) ||
        stat(mount_root, &mount_st) != 0 ||
        !S_ISDIR(mount_st.st_mode) ||
        !parent_path_for_write_guard(mount_root, parent, sizeof(parent)) ||
        stat(parent, &parent_st) != 0) {
        return 0;
    }

    return mount_st.st_dev != parent_st.st_dev;
}

static int output_mount_root_is_live_for_write_guard_with_grace(const char *mount_root)
{
    double started_at;

    if (output_mount_root_is_live_for_write_guard(mount_root)) {
        return 1;
    }

    started_at = monotonic_seconds_local();
    while ((monotonic_seconds_local() - started_at) <
           OUTPUT_MOUNT_GUARD_TRANSIENT_GRACE_SECONDS) {
        usleep(250000);
        if (output_mount_root_is_live_for_write_guard(mount_root)) {
            return 1;
        }
    }
    return 0;
}

static int output_path_write_mount_guard_allows(
    const char *path,
    const char *operation
)
{
    char mount_root[PATH_MAX_LEN];
    static int warned = 0;

    if (!output_mount_root_from_path_for_write_guard(
            path,
            mount_root,
            sizeof(mount_root))) {
        return 1;
    }
    if (output_mount_root_is_live_for_write_guard_with_grace(mount_root)) {
        return 1;
    }

    if (!warned) {
        warned = 1;
        log_error(
            "Refusing to %s under %s because %s is not a live mounted output volume; reconnect the output disk or resume using its new mount path before writing.",
            has_nonempty_text(operation) ? operation : "write output",
            path,
            mount_root
        );
    }
    return 0;
}

#if !TEMP_TREE_ONLY_MODE
static int ensure_parent_directories(const char *path)
{
    char temp[1024];
    char *cursor;

    if (path == NULL || strlen(path) >= sizeof(temp)) {
        return 0;
    }
    if (!output_path_write_mount_guard_allows(path, "create output directories")) {
        return 0;
    }

    snprintf(temp, sizeof(temp), "%s", path);
    cursor = temp;

    while ((cursor = strchr(cursor + 1, '/')) != NULL) {
        *cursor = '\0';
        if (!output_path_write_mount_guard_allows(temp, "create output directory")) {
            return 0;
        }
        if (mkdir(temp, 0777) != 0 && errno != EEXIST) {
            return 0;
        }
        (void)fs_backend_apply_output_owner_to_path(temp);
        *cursor = '/';
    }

    return 1;
}

static int build_missed_report_recovery_target(
    const MissedReportEntry *entry,
    const RecoveryFormat *format,
    const char *output_path,
    uint64_t target_size,
    RecoveryTarget *out_target
)
{
    char extension[FORMAT_EXTENSION_MAX] = {0};
    size_t run_index;

    if (entry == NULL || format == NULL || output_path == NULL ||
        output_path[0] == '\0' || out_target == NULL ||
        entry->resident || entry->run_count == 0U ||
        entry->run_count > RECOVERY_TARGET_MAX_RUNS ||
        target_size == 0U) {
        return 0;
    }

    lower_extension_from_path_local(entry->path, extension, sizeof(extension));
    if (extension[0] == '\0') {
        return 0;
    }

    memset(out_target, 0, sizeof(*out_target));
    out_target->format_id = format->format_id;
    out_target->validator_id = format->validator_id;
    out_target->abs_offset = entry->runs[0].abs_offset;
    out_target->size = target_size;
    out_target->expected_size = entry->data_size;
    out_target->remaining = target_size;
    out_target->created_unix = entry->created_unix;
    out_target->run_truncated = target_size < entry->data_size;
    snprintf(out_target->extension, sizeof(out_target->extension), "%s", extension);
    snprintf(out_target->source_path, sizeof(out_target->source_path), "%s", entry->path);
    snprintf(out_target->output_path, sizeof(out_target->output_path), "%s", output_path);

    if (format->blob_start_length > 0U &&
        format->blob_start_length <= sizeof(out_target->blob_start)) {
        memcpy(out_target->blob_start, format->blob_start, format->blob_start_length);
        out_target->blob_start_length = format->blob_start_length;
    } else if (out_target->validator_id == RECOVERY_VALIDATOR_JPEG) {
        out_target->blob_start[0] = 0xFFU;
        out_target->blob_start[1] = 0xD8U;
        out_target->blob_start[2] = 0xFFU;
        out_target->blob_start_length = 3U;
    } else if (out_target->validator_id == RECOVERY_VALIDATOR_RIFF) {
        out_target->blob_start[0] = 'R';
        out_target->blob_start[1] = 'I';
        out_target->blob_start[2] = 'F';
        out_target->blob_start[3] = 'F';
        out_target->blob_start_length = 4U;
    }

    for (run_index = 0; run_index < entry->run_count; run_index++) {
        if (entry->runs[run_index].byte_length == 0U) {
            return 0;
        }
        out_target->runs[out_target->run_count].abs_offset =
            entry->runs[run_index].abs_offset;
        out_target->runs[out_target->run_count].byte_length =
            entry->runs[run_index].byte_length;
        out_target->run_count++;
    }

    return out_target->run_count > 0U;
}

static int recover_missed_report_entry(Reader *reader, const MissedReportEntry *entry)
{
    const RecoveryFormat *format = NULL;
    char output_path[1024];
    char recovered_relative_path[1024];
    char existing_path[1024];
    RecoveryTarget target;
    unsigned char *repair_buffer = NULL;
    size_t repair_buffer_size;
    uint64_t available_bytes;
    uint64_t target_size;
    int existing_reconciled = 0;
    long long abs_offset;
    int ok;

    if (reader == NULL || reader->fd < 0 || entry == NULL) {
        return 0;
    }

    abs_offset = entry->abs_offset;
    if (!entry->resident && entry->run_count == 0) {
        return 0;
    }

    if (entry->path[0] == '\0') {
        return 0;
    }

    if (!mft_missed_report_path_should_recover(entry->path, NULL)) {
        return 0;
    }
    if (!missed_report_entry_header_matches_source(reader, entry)) {
        return 0;
    }
    format = missed_report_recovery_format_for_path(entry->path);
    if (format == NULL) {
        return 0;
    }

    if (strncmp(
            entry->path,
            APP_RECOVERED_DIR_NAME "/",
            strlen(APP_RECOVERED_DIR_NAME "/")) == 0) {
        snprintf(
            recovered_relative_path,
            sizeof(recovered_relative_path),
            "%s",
            entry->path
        );
    } else if (snprintf(
                   recovered_relative_path,
                   sizeof(recovered_relative_path),
                   "%s/%s",
                   APP_RECOVERED_DIR_NAME,
                   entry->path) >= (int)sizeof(recovered_relative_path)) {
        return 0;
    }

    if (!fs_backend_build_output_path(
            output_path,
            sizeof(output_path),
            recovered_relative_path)) {
        return 0;
    }

    available_bytes = missed_report_available_bytes_local(entry);
    target_size = entry->data_size;
    if (!entry->resident && available_bytes > 0U && available_bytes < entry->data_size) {
        if (!mftprobe_format_allows_partial_target(format, available_bytes)) {
            return 0;
        }
        target_size = available_bytes;
        if (!append_partial_suffix_local(output_path, sizeof(output_path))) {
            return 0;
        }
    }

    if (!ensure_parent_directories(output_path)) {
        return 0;
    }

    if (!entry->resident &&
        fs_backend_get_recovered_output_info(
            abs_offset,
            existing_path,
            sizeof(existing_path),
            &existing_reconciled) &&
        !existing_reconciled &&
        existing_path[0] != '\0') {
        struct stat st;

        if (strcmp(existing_path, output_path) == 0) {
            if (entry->created_unix > 0) {
                (void)fs_backend_apply_created_time_value_to_path(
                    output_path,
                    entry->created_unix
                );
            } else {
                (void)fs_backend_apply_created_time_to_path(output_path, abs_offset);
            }
            fs_backend_note_recovered_output(output_path, abs_offset >= 0 ? abs_offset : 0);
            return 1;
        }

        if (stat(existing_path, &st) == 0 &&
            S_ISREG(st.st_mode) &&
            rename(existing_path, output_path) == 0) {
            (void)fs_backend_apply_output_owner_to_path(output_path);
            if (entry->created_unix > 0) {
                (void)fs_backend_apply_created_time_value_to_path(
                    output_path,
                    entry->created_unix
                );
            } else {
                (void)fs_backend_apply_created_time_to_path(output_path, abs_offset);
            }
            fs_backend_note_recovered_output(output_path, abs_offset);
            return 1;
        }
    }

    if (!build_missed_report_recovery_target(
            entry,
            format,
            output_path,
            target_size,
            &target)) {
        return 0;
    }
    repair_buffer_size = recovery_runner_default_read_size();
    repair_buffer = (unsigned char *)malloc(repair_buffer_size);
    if (repair_buffer == NULL) {
        return 0;
    }
    ok = recovery_runner_recover_target_best_effort_fd(
        reader->fd,
        &target,
        repair_buffer,
        repair_buffer_size,
        app_stop_requested
    );
    free(repair_buffer);
    if (!ok) {
        return 0;
    }

    if (entry->created_unix > 0) {
        (void)fs_backend_apply_created_time_value_to_path(
            output_path,
            entry->created_unix
        );
    } else if (abs_offset >= 0) {
        (void)fs_backend_apply_created_time_to_path(output_path, abs_offset);
    }
    if (!entry->resident && abs_offset >= 0) {
        fs_backend_note_recovered_output(output_path, abs_offset);
    }
    return 1;
}
#endif

static int run_missed_report_mode(Reader *reader, const char *report_path)
{
    FILE *report;
    char line[4096];
    size_t targeted = 0;
    size_t recovered = 0;

    if (reader == NULL || report_path == NULL) {
        return 0;
    }

    report = fopen(report_path, "r");
    if (report == NULL) {
        log_error("Failed to open missed report: %s", report_path);
        return 0;
    }

    while (fgets(line, sizeof(line), report) != NULL) {
        MissedReportEntry entry;

        if (strncmp(line, "path\t", 5) == 0) {
            continue;
        }

        if (!parse_missed_report_line(line, &entry)) {
            continue;
        }

        targeted++;
#if TEMP_TREE_ONLY_MODE
        recovered++;
#else
        if (recover_missed_report_entry(reader, &entry)) {
            recovered++;
        }
#endif
    }

    fclose(report);
    log_info(
        "Missed report targets: %zu listed, %zu %s",
        targeted,
        recovered,
        TEMP_TREE_ONLY_MODE ? "visited (recovery disabled)" : "recovered"
    );
    return 1;
}

static size_t run_missed_users_recovery_if_needed(
    Reader *reader,
    const AppConfig *config,
    int live_metadata_observation_disabled
)
{
    char missed_users_report_path[1024];
    size_t missed = 0;

    if (reader == NULL ||
        config == NULL ||
        live_metadata_observation_disabled ||
        config->only_recover_missed) {
        return 0;
    }

    if (fs_backend_build_output_path(
            missed_users_report_path,
            sizeof(missed_users_report_path),
            MISSED_USERS_REPORT_NAME)) {
        missed = fs_backend_write_missed_report(missed_users_report_path);
    }

    if (missed > 0) {
#if TEMP_TREE_ONLY_MODE
        log_info(
            "%zu %s matched requested formats and were mapped for later recovery (tree-only mode; carving disabled); see %s",
            missed,
            config->scan_mode == APP_SCAN_MODE_RAW_ALL
                ? "metadata-mapped files"
                : "Users files",
            missed_users_report_path
        );

        if (config->auto_recover_missed) {
            log_info("Automatic retry pass skipped because tree-only mode disables recovery");
        }
#else
        log_info(
            "%zu %s matched requested formats but were not recovered; see %s",
            missed,
            config->scan_mode == APP_SCAN_MODE_RAW_ALL
                ? "metadata-mapped files"
                : "Users files",
            missed_users_report_path
        );

        if (config->auto_recover_missed) {
            if (!run_missed_report_mode(reader, missed_users_report_path)) {
                log_error("Automatic retry pass failed");
            }
        }
#endif
    } else {
#if TEMP_TREE_ONLY_MODE
        log_info(
            "No mapped %s for requested formats",
            config->scan_mode == APP_SCAN_MODE_RAW_ALL
                ? "metadata-mapped files"
                : "Users files");
#else
        log_info(
            "No missed %s for requested formats",
            config->scan_mode == APP_SCAN_MODE_RAW_ALL
                ? "metadata-mapped files"
                : "Users files");
#endif
    }

    return missed;
}

static void build_working_label(
    char *out,
    size_t out_size,
    int only_recover_missed
)
{
    if (out == NULL || out_size == 0) {
        return;
    }

    out[0] = '\0';

    snprintf(
        out,
        out_size,
        "%s%s",
        only_recover_missed ? "recover-missed" : "all",
        TEMP_TREE_ONLY_MODE ? " tree-only" : ""
    );
}

static void log_quick_load_eta(
    Reader *reader,
    uint64_t start_offset
)
{
    uint64_t total_size;
    uint64_t remaining_bytes;

    if (reader == NULL) {
        return;
    }

    total_size = reader_get_source_size(reader);
    if (total_size == 0) {
        log_info("Input size: unknown (device did not report size)");
        return;
    }

    remaining_bytes = total_size > start_offset ? total_size - start_offset : 0;

    log_info(
        "Input size: %.2f GiB (remaining from offset %.2f GiB)",
        (double)total_size / (1024.0 * 1024.0 * 1024.0),
        (double)remaining_bytes / (1024.0 * 1024.0 * 1024.0)
    );

    if (remaining_bytes == 0) {
        return;
    }
}

static int ensure_parent_dirs_for_path(const char *path)
{
    char temp[1200];
    char *cursor;

    if (path == NULL || path[0] == '\0' || strlen(path) >= sizeof(temp)) {
        return 0;
    }
    if (!output_path_write_mount_guard_allows(path, "create output directories")) {
        return 0;
    }

    snprintf(temp, sizeof(temp), "%s", path);
    cursor = temp;

    while ((cursor = strchr(cursor + 1, '/')) != NULL) {
        *cursor = '\0';
        if (!output_path_write_mount_guard_allows(temp, "create output directory")) {
            return 0;
        }
        if (mkdir(temp, 0777) != 0 && errno != EEXIST) {
            return 0;
        }
        *cursor = '/';
    }

    return 1;
}

static int ensure_directory_path(const char *path)
{
    if (path == NULL || path[0] == '\0') {
        return 0;
    }
    if (!output_path_write_mount_guard_allows(path, "create output directory")) {
        return 0;
    }
    if (!ensure_parent_dirs_for_path(path)) {
        return 0;
    }
    if (mkdir(path, 0777) != 0 && errno != EEXIST) {
        return 0;
    }
    return fs_backend_apply_output_owner_to_path(path);
}

static int ensure_recovered_roots(const AppConfig *config)
{
    char recovered_dir[1200];
    char unident_dir[1200];
    char suggested_run_dir[PATH_MAX_LEN];

    if (config == NULL ||
        config->output_dir == NULL ||
        config->output_dir[0] == '\0') {
        return 0;
    }
    if (output_mount_guard_poll_should_stop(
            config->output_dir,
            suggested_run_dir,
            sizeof(suggested_run_dir))) {
        if (has_nonempty_text(suggested_run_dir)) {
            log_error(
                "Output directory %s is no longer on the mounted output volume. The same run directory appears to have remounted as %s; stop and resume there so recovered files do not spill onto the system disk.",
                config->output_dir,
                suggested_run_dir
            );
        } else {
            log_error(
                "Output directory %s is no longer on a live mounted output volume; stop and reconnect the output disk before resuming so files do not spill onto the system disk.",
                config->output_dir
            );
        }
        return 0;
    }
    if (snprintf(
            recovered_dir,
            sizeof(recovered_dir),
            "%s/" APP_RECOVERED_DIR_NAME,
            config->output_dir) >= (int)sizeof(recovered_dir)) {
        return 0;
    }
    if (snprintf(
            unident_dir,
            sizeof(unident_dir),
            "%s/" APP_UNIDENT_RELATIVE_DIR,
            config->output_dir) >= (int)sizeof(unident_dir)) {
        return 0;
    }

    if (!ensure_directory_path(recovered_dir)) {
        log_error("Failed to create recovered output directory: %s", recovered_dir);
        return 0;
    }
    if (!ensure_directory_path(unident_dir)) {
        log_error("Failed to create unident output directory: %s", unident_dir);
        return 0;
    }
    return 1;
}

#define OUTPUT_COMPARE_SCOPE_MAX_ITEMS 16U
#define OUTPUT_COMPARE_SCOPE_ITEM_MAX 128U

typedef struct {
    char rel_path[PATH_MAX_LEN];
    char compare_key[PATH_MAX_LEN];
    char name_key[PATH_MAX_LEN];
    char search_reason[32];
    uint64_t size;
} OutputCompareCandidate;

typedef struct {
    OutputCompareCandidate *items;
    size_t count;
    size_t capacity;
} OutputCompareCandidateList;

typedef struct {
    char items[OUTPUT_COMPARE_SCOPE_MAX_ITEMS][OUTPUT_COMPARE_SCOPE_ITEM_MAX];
    size_t count;
    int match_all;
} OutputCompareScope;

typedef struct {
    size_t matched;
    size_t matched_exact;
    size_t matched_suffix;
    size_t matched_name_size;
    size_t only_source;
    size_t mismatch;
} OutputCompareStats;

typedef struct {
    uint64_t size;
    size_t candidate_index;
} OutputCompareSizeIndex;

typedef struct {
    char ext[32];
    size_t count;
} OutputCompareExtCount;

typedef struct {
    int active;
    char raw[256];
    char key[PATH_MAX_LEN];
    char header_ascii[256];
} OutputCompareSearchSpec;

static void output_compare_build_key(
    const char *rel_path,
    char *out,
    size_t out_size
);

static void output_compare_build_key_from_bytes(
    const unsigned char *bytes,
    size_t byte_count,
    char *out,
    size_t out_size
);

static int output_compare_ext_count_desc(const void *left, const void *right)
{
    const OutputCompareExtCount *a = (const OutputCompareExtCount *)left;
    const OutputCompareExtCount *b = (const OutputCompareExtCount *)right;

    if (a->count < b->count) {
        return 1;
    }
    if (a->count > b->count) {
        return -1;
    }
    return strcmp(a->ext, b->ext);
}

static void output_compare_trim_ascii(char *text)
{
    size_t start = 0;
    size_t end;
    size_t len;

    if (text == NULL) {
        return;
    }

    len = strlen(text);
    end = len;
    while (start < len && isspace((unsigned char)text[start])) {
        start++;
    }
    while (end > start && isspace((unsigned char)text[end - 1U])) {
        end--;
    }
    if (start > 0 || end < len) {
        memmove(text, text + start, end - start);
        text[end - start] = '\0';
    }
}

static void output_compare_trim_trailing_slashes(char *path)
{
    size_t len;

    if (path == NULL) {
        return;
    }

    len = strlen(path);
    while (len > 1U &&
           (path[len - 1U] == '/' || path[len - 1U] == '\\')) {
        path[--len] = '\0';
    }
}

static void output_compare_scope_normalize_token(char *text)
{
    size_t i;

    if (text == NULL) {
        return;
    }

    output_compare_trim_ascii(text);
    while (text[0] == '/' || text[0] == '\\') {
        memmove(text, text + 1, strlen(text));
    }
    for (i = 0; text[i] != '\0'; i++) {
        if (text[i] == '\\') {
            text[i] = '/';
        } else {
            text[i] = (char)tolower((unsigned char)text[i]);
        }
    }
    output_compare_trim_trailing_slashes(text);
}

static int output_compare_scope_has_item(
    const OutputCompareScope *scope,
    const char *item
)
{
    size_t i;

    if (scope == NULL || item == NULL || item[0] == '\0') {
        return 0;
    }
    for (i = 0; i < scope->count; i++) {
        if (strcmp(scope->items[i], item) == 0) {
            return 1;
        }
    }
    return 0;
}

static int output_compare_scope_add_item(
    OutputCompareScope *scope,
    const char *item,
    char *error_text,
    size_t error_text_size
)
{
    if (scope == NULL || item == NULL || item[0] == '\0') {
        return 1;
    }
    if (output_compare_scope_has_item(scope, item)) {
        return 1;
    }
    if (scope->count >= OUTPUT_COMPARE_SCOPE_MAX_ITEMS) {
        snprintf(
            error_text,
            error_text_size,
            "Too many compare scope items (max %u)",
            (unsigned int)OUTPUT_COMPARE_SCOPE_MAX_ITEMS
        );
        return 0;
    }
    snprintf(
        scope->items[scope->count],
        sizeof(scope->items[scope->count]),
        "%s",
        item
    );
    scope->count++;
    return 1;
}

static int output_compare_scope_add_common(
    OutputCompareScope *scope,
    char *error_text,
    size_t error_text_size
)
{
    static const char *const common_items[] = {
        "desktop",
        "pictures",
        "documents",
        "downloads",
        "music",
        "videos"
    };
    size_t i;

    for (i = 0; i < sizeof(common_items) / sizeof(common_items[0]); i++) {
        if (!output_compare_scope_add_item(
                scope,
                common_items[i],
                error_text,
                error_text_size)) {
            return 0;
        }
    }
    return 1;
}

static int output_compare_scope_parse(
    const char *scope_csv,
    OutputCompareScope *out_scope,
    char *error_text,
    size_t error_text_size
)
{
    char copy[512];
    char *token;

    if (error_text != NULL && error_text_size > 0) {
        error_text[0] = '\0';
    }
    if (out_scope == NULL) {
        return 0;
    }

    memset(out_scope, 0, sizeof(*out_scope));
    out_scope->match_all = 1;
    if (!has_nonempty_text(scope_csv)) {
        return 1;
    }
    if (strlen(scope_csv) >= sizeof(copy)) {
        snprintf(error_text, error_text_size, "Compare scope is too long");
        return 0;
    }

    snprintf(copy, sizeof(copy), "%s", scope_csv);
    out_scope->match_all = 0;
    token = strtok(copy, ",");
    while (token != NULL) {
        char normalized[OUTPUT_COMPARE_SCOPE_ITEM_MAX];

        snprintf(normalized, sizeof(normalized), "%s", token);
        output_compare_scope_normalize_token(normalized);
        if (normalized[0] == '\0') {
            token = strtok(NULL, ",");
            continue;
        }
        if (strcmp(normalized, "all") == 0 ||
            strcmp(normalized, "*") == 0) {
            memset(out_scope, 0, sizeof(*out_scope));
            out_scope->match_all = 1;
            return 1;
        }
        if (strcmp(normalized, "common") == 0) {
            if (!output_compare_scope_add_common(
                    out_scope,
                    error_text,
                    error_text_size)) {
                return 0;
            }
            token = strtok(NULL, ",");
            continue;
        }
        if (!output_compare_scope_add_item(
                out_scope,
                normalized,
                error_text,
                error_text_size)) {
            return 0;
        }
        token = strtok(NULL, ",");
    }

    if (out_scope->count == 0) {
        out_scope->match_all = 1;
    }
    return 1;
}

static int output_compare_scope_matches_rel_path(
    const OutputCompareScope *scope,
    const char *rel_path
)
{
    char normalized[PATH_MAX_LEN];
    size_t i;

    if (scope == NULL || scope->match_all) {
        return 1;
    }
    if (!has_nonempty_text(rel_path)) {
        return 0;
    }
    snprintf(normalized, sizeof(normalized), "%s", rel_path);
    output_compare_scope_normalize_token(normalized);
    if (normalized[0] == '\0') {
        return 0;
    }

    for (i = 0; i < scope->count; i++) {
        size_t wanted_len = strlen(scope->items[i]);
        const char *cursor = normalized;
        const char *remainder = strchr(normalized, '/');

        if (wanted_len == 0) {
            continue;
        }
        if (strncmp(cursor, scope->items[i], wanted_len) == 0) {
            cursor += wanted_len;
            if (*cursor == '\0' || *cursor == '/') {
                return 1;
            }
        }
        if (remainder == NULL || remainder[1] == '\0') {
            continue;
        }
        cursor = remainder + 1;
        if (strncmp(cursor, scope->items[i], wanted_len) == 0) {
            cursor += wanted_len;
            if (*cursor == '\0' || *cursor == '/') {
                return 1;
            }
        }
    }
    return 0;
}

static const char *output_compare_path_basename(const char *path)
{
    const char *slash;
    const char *backslash;
    const char *base;

    if (!has_nonempty_text(path)) {
        return "";
    }

    base = path;
    slash = strrchr(path, '/');
    backslash = strrchr(path, '\\');
    if (slash != NULL || backslash != NULL) {
        if (slash == NULL || (backslash != NULL && backslash > slash)) {
            slash = backslash;
        }
        base = slash + 1;
    }
    return base;
}

static void output_compare_build_name_key(
    const char *rel_path,
    char *out,
    size_t out_size
)
{
    output_compare_build_key(output_compare_path_basename(rel_path), out, out_size);
}

static int output_compare_search_prepare(
    const char *text,
    OutputCompareSearchSpec *out_search
)
{
    size_t i;
    size_t header_pos = 0;

    if (out_search == NULL) {
        return 0;
    }

    memset(out_search, 0, sizeof(*out_search));
    if (!has_nonempty_text(text)) {
        return 1;
    }
    if (strlen(text) >= sizeof(out_search->raw)) {
        return 0;
    }

    snprintf(out_search->raw, sizeof(out_search->raw), "%s", text);
    output_compare_trim_ascii(out_search->raw);
    if (out_search->raw[0] == '\0') {
        return 1;
    }

    output_compare_build_key(
        out_search->raw,
        out_search->key,
        sizeof(out_search->key)
    );
    if (out_search->key[0] == '\0') {
        return 0;
    }

    for (i = 0; out_search->raw[i] != '\0' && header_pos + 1U < sizeof(out_search->header_ascii); i++) {
        unsigned char ch = (unsigned char)out_search->raw[i];

        if (ch < 0x80U) {
            out_search->header_ascii[header_pos++] =
                (char)tolower(ch);
        }
    }
    out_search->header_ascii[header_pos] = '\0';

    out_search->active = 1;
    return 1;
}

static int output_compare_search_matches_rel_path(
    const OutputCompareSearchSpec *search,
    const char *rel_path,
    char *reason,
    size_t reason_size
)
{
    char rel_key[PATH_MAX_LEN];
    char name_key[PATH_MAX_LEN];

    if (reason != NULL && reason_size > 0) {
        reason[0] = '\0';
    }
    if (search == NULL || !search->active) {
        return 1;
    }
    if (!has_nonempty_text(rel_path)) {
        return 0;
    }

    output_compare_build_name_key(rel_path, name_key, sizeof(name_key));
    if (name_key[0] != '\0' &&
        strstr(name_key, search->key) != NULL) {
        if (reason != NULL && reason_size > 0) {
            snprintf(reason, reason_size, "%s", "filename_match");
        }
        return 1;
    }

    output_compare_build_key(rel_path, rel_key, sizeof(rel_key));
    if (rel_key[0] != '\0' &&
        strstr(rel_key, search->key) != NULL) {
        if (reason != NULL && reason_size > 0) {
            snprintf(reason, reason_size, "%s", "path_match");
        }
        return 1;
    }

    return 0;
}

static int output_compare_search_matches_header(
    const OutputCompareSearchSpec *search,
    const char *file_path,
    char *reason,
    size_t reason_size
)
{
    unsigned char header[OUTPUT_COMPARE_HEADER_SEARCH_BYTES];
    char header_text[OUTPUT_COMPARE_HEADER_SEARCH_BYTES + 1U];
    FILE *file;
    size_t bytes_read;
    size_t i;
    size_t pos = 0;

    if (reason != NULL && reason_size > 0) {
        reason[0] = '\0';
    }
    if (search == NULL || !search->active || !has_nonempty_text(file_path)) {
        return 0;
    }
    if (search->header_ascii[0] == '\0') {
        return 0;
    }

    file = fopen(file_path, "rb");
    if (file == NULL) {
        return 0;
    }

    bytes_read = fread(header, 1U, sizeof(header), file);
    fclose(file);
    if (bytes_read == 0U) {
        return 0;
    }

    for (i = 0; i < bytes_read && pos + 1U < sizeof(header_text); i++) {
        unsigned char ch = header[i];

        if (ch >= 0x20U && ch < 0x7FU) {
            header_text[pos++] = (char)tolower(ch);
        } else if (ch == '\t') {
            header_text[pos++] = '\t';
        } else if (pos > 0U && header_text[pos - 1U] != ' ') {
            header_text[pos++] = ' ';
        }
    }
    header_text[pos] = '\0';

    if (header_text[0] == '\0' ||
        strstr(header_text, search->header_ascii) == NULL) {
        return 0;
    }

    if (reason != NULL && reason_size > 0) {
        snprintf(reason, reason_size, "%s", "header_match");
    }
    return 1;
}

static int output_compare_key_has_suffix(
    const char *full_key,
    const char *tail_key
)
{
    size_t full_len;
    size_t tail_len;

    if (!has_nonempty_text(full_key) || !has_nonempty_text(tail_key)) {
        return 0;
    }

    full_len = strlen(full_key);
    tail_len = strlen(tail_key);
    if (full_len < tail_len) {
        return 0;
    }
    if (strcmp(full_key + (full_len - tail_len), tail_key) != 0) {
        return 0;
    }
    if (full_len == tail_len) {
        return 1;
    }
    return full_key[full_len - tail_len - 1U] == '/';
}

static int output_compare_keys_share_structural_suffix(
    const char *left_key,
    const char *right_key
)
{
    if ((!has_nonempty_text(left_key) || strchr(left_key, '/') == NULL) &&
        (!has_nonempty_text(right_key) || strchr(right_key, '/') == NULL)) {
        return 0;
    }

    return output_compare_key_has_suffix(left_key, right_key) ||
           output_compare_key_has_suffix(right_key, left_key);
}

static int output_compare_candidate_suffix_match(
    const OutputCompareCandidate *left,
    const OutputCompareCandidate *right
)
{
    return left != NULL &&
           right != NULL &&
           left->size == right->size &&
           output_compare_keys_share_structural_suffix(
               left->compare_key,
               right->compare_key
           );
}

static int output_compare_candidate_name_match(
    const OutputCompareCandidate *left,
    const OutputCompareCandidate *right
)
{
    return left != NULL &&
           right != NULL &&
           left->size == right->size &&
           has_nonempty_text(left->name_key) &&
           strcmp(left->name_key, right->name_key) == 0;
}

static int output_compare_find_unique_group_match(
    const OutputCompareCandidateList *group_a,
    const OutputCompareCandidateList *group_b,
    const unsigned char *used_a,
    const unsigned char *used_b,
    const OutputCompareSizeIndex *group_a_index,
    size_t group_a_begin,
    size_t group_a_end,
    size_t index_a,
    const OutputCompareSizeIndex *group_b_index,
    size_t group_b_begin,
    size_t group_b_end,
    int match_mode,
    size_t *out_index_b
)
{
    size_t i;
    size_t candidate_index = SIZE_MAX;
    size_t candidate_count = 0;

    if (group_a == NULL || group_b == NULL ||
        used_a == NULL || used_b == NULL ||
        group_a_index == NULL || group_b_index == NULL ||
        index_a >= group_a->count || out_index_b == NULL) {
        return 0;
    }

    for (i = group_b_begin; i < group_b_end; i++) {
        int matches = 0;
        size_t candidate = group_b_index[i].candidate_index;

        if (used_b[candidate]) {
            continue;
        }
        if (match_mode == 1) {
            matches = output_compare_candidate_suffix_match(
                &group_a->items[index_a],
                &group_b->items[candidate]);
        } else {
            matches = output_compare_candidate_name_match(
                &group_a->items[index_a],
                &group_b->items[candidate]);
        }
        if (!matches) {
            continue;
        }
        candidate_index = candidate;
        candidate_count++;
        if (candidate_count > 1U) {
            return 0;
        }
    }

    if (candidate_count != 1U) {
        return 0;
    }

    for (i = group_a_begin; i < group_a_end; i++) {
        int matches = 0;
        size_t candidate = group_a_index[i].candidate_index;

        if (candidate == index_a || used_a[candidate]) {
            continue;
        }
        if (match_mode == 1) {
            matches = output_compare_candidate_suffix_match(
                &group_a->items[candidate],
                &group_b->items[candidate_index]);
        } else {
            matches = output_compare_candidate_name_match(
                &group_a->items[candidate],
                &group_b->items[candidate_index]);
        }
        if (matches) {
            return 0;
        }
    }

    *out_index_b = candidate_index;
    return 1;
}

static int output_compare_decode_utf8(
    const unsigned char *text,
    size_t remaining,
    uint32_t *codepoint,
    size_t *used
)
{
    uint32_t cp;

    if (text == NULL || remaining == 0 || codepoint == NULL || used == NULL) {
        return 0;
    }

    if (text[0] < 0x80U) {
        *codepoint = text[0];
        *used = 1U;
        return 1;
    }
    if ((text[0] & 0xE0U) == 0xC0U && remaining >= 2U &&
        (text[1] & 0xC0U) == 0x80U) {
        cp = ((uint32_t)(text[0] & 0x1FU) << 6) |
             (uint32_t)(text[1] & 0x3FU);
        if (cp >= 0x80U) {
            *codepoint = cp;
            *used = 2U;
            return 1;
        }
        return 0;
    }
    if ((text[0] & 0xF0U) == 0xE0U && remaining >= 3U &&
        (text[1] & 0xC0U) == 0x80U &&
        (text[2] & 0xC0U) == 0x80U) {
        cp = ((uint32_t)(text[0] & 0x0FU) << 12) |
             ((uint32_t)(text[1] & 0x3FU) << 6) |
             (uint32_t)(text[2] & 0x3FU);
        if (cp >= 0x800U) {
            *codepoint = cp;
            *used = 3U;
            return 1;
        }
        return 0;
    }
    if ((text[0] & 0xF8U) == 0xF0U && remaining >= 4U &&
        (text[1] & 0xC0U) == 0x80U &&
        (text[2] & 0xC0U) == 0x80U &&
        (text[3] & 0xC0U) == 0x80U) {
        cp = ((uint32_t)(text[0] & 0x07U) << 18) |
             ((uint32_t)(text[1] & 0x3FU) << 12) |
             ((uint32_t)(text[2] & 0x3FU) << 6) |
             (uint32_t)(text[3] & 0x3FU);
        if (cp >= 0x10000U && cp <= 0x10FFFFU) {
            *codepoint = cp;
            *used = 4U;
            return 1;
        }
    }
    return 0;
}

static int output_compare_base_letter(uint32_t codepoint)
{
    switch (codepoint) {
        case 0x00C0: case 0x00C1: case 0x00C2: case 0x00C3:
        case 0x00C4: case 0x00C5: case 0x00E0: case 0x00E1:
        case 0x00E2: case 0x00E3: case 0x00E4: case 0x00E5:
        case 0x0100: case 0x0101: case 0x0102: case 0x0103:
        case 0x0104: case 0x0105:
            return 'a';
        case 0x00C7: case 0x00E7: case 0x0106: case 0x0107:
        case 0x0108: case 0x0109: case 0x010A: case 0x010B:
        case 0x010C: case 0x010D:
            return 'c';
        case 0x00C8: case 0x00C9: case 0x00CA: case 0x00CB:
        case 0x00E8: case 0x00E9: case 0x00EA: case 0x00EB:
        case 0x0112: case 0x0113: case 0x0114: case 0x0115:
        case 0x0116: case 0x0117: case 0x0118: case 0x0119:
        case 0x011A: case 0x011B:
            return 'e';
        case 0x011C: case 0x011D: case 0x011E: case 0x011F:
        case 0x0120: case 0x0121: case 0x0122: case 0x0123:
            return 'g';
        case 0x00CC: case 0x00CD: case 0x00CE: case 0x00CF:
        case 0x00EC: case 0x00ED: case 0x00EE: case 0x00EF:
        case 0x0128: case 0x0129: case 0x012A: case 0x012B:
        case 0x012C: case 0x012D: case 0x012E: case 0x012F:
        case 0x0130: case 0x0131:
            return 'i';
        case 0x0134: case 0x0135:
            return 'j';
        case 0x0139: case 0x013A: case 0x013B: case 0x013C:
        case 0x013D: case 0x013E: case 0x0141: case 0x0142:
            return 'l';
        case 0x00D1: case 0x00F1: case 0x0143: case 0x0144:
        case 0x0145: case 0x0146: case 0x0147: case 0x0148:
            return 'n';
        case 0x00D2: case 0x00D3: case 0x00D4: case 0x00D5:
        case 0x00D6: case 0x00D8: case 0x00F2: case 0x00F3:
        case 0x00F4: case 0x00F5: case 0x00F6: case 0x00F8:
        case 0x014C: case 0x014D: case 0x014E: case 0x014F:
        case 0x0150: case 0x0151:
            return 'o';
        case 0x0154: case 0x0155: case 0x0156: case 0x0157:
        case 0x0158: case 0x0159:
            return 'r';
        case 0x015A: case 0x015B: case 0x015C: case 0x015D:
        case 0x015E: case 0x015F: case 0x0160: case 0x0161:
            return 's';
        case 0x0162: case 0x0163: case 0x0164: case 0x0165:
            return 't';
        case 0x00D9: case 0x00DA: case 0x00DB: case 0x00DC:
        case 0x00F9: case 0x00FA: case 0x00FB: case 0x00FC:
        case 0x0168: case 0x0169: case 0x016A: case 0x016B:
        case 0x016C: case 0x016D: case 0x016E: case 0x016F:
        case 0x0170: case 0x0171: case 0x0172: case 0x0173:
            return 'u';
        case 0x00DD: case 0x00FD: case 0x00FF: case 0x0176:
        case 0x0177: case 0x0178:
            return 'y';
        case 0x0179: case 0x017A: case 0x017B: case 0x017C:
        case 0x017D: case 0x017E:
            return 'z';
        default:
            return 0;
    }
}

static void output_compare_build_key_from_bytes(
    const unsigned char *bytes,
    size_t byte_count,
    char *out,
    size_t out_size
)
{
    const unsigned char *cursor;
    size_t remaining;
    size_t pos = 0;

    if (out == NULL || out_size == 0) {
        return;
    }

    out[0] = '\0';
    if (bytes == NULL || byte_count == 0) {
        return;
    }

    cursor = bytes;
    remaining = byte_count;
    while (remaining > 0 && pos + 1U < out_size) {
        const unsigned char *encoded = cursor;
        uint32_t codepoint = 0;
        size_t used = 0;
        int mapped;
        size_t i;

        if (*cursor < 0x80U) {
            unsigned char ch = *cursor;

            if (ch == '\0' || (ch < 0x20U && ch != '\t')) {
                cursor++;
                remaining--;
                continue;
            }
            if (ch == '\\') {
                ch = '/';
            }
            out[pos++] = (char)tolower(ch);
            cursor++;
            remaining--;
            continue;
        }

        if (!output_compare_decode_utf8(cursor, remaining, &codepoint, &used)) {
            cursor++;
            remaining--;
            continue;
        }
        cursor += used;
        remaining -= used;

        if (codepoint >= 0x0300U && codepoint <= 0x036FU) {
            continue;
        }

        mapped = output_compare_base_letter(codepoint);
        if (mapped != 0) {
            out[pos++] = (char)mapped;
        } else {
            for (i = 0; i < used && pos + 1U < out_size; i++) {
                out[pos++] = (char)encoded[i];
            }
        }
    }

    out[pos] = '\0';
}

static void output_compare_build_key(
    const char *rel_path,
    char *out,
    size_t out_size
)
{
    if (rel_path == NULL) {
        if (out != NULL && out_size > 0) {
            out[0] = '\0';
        }
        return;
    }

    output_compare_build_key_from_bytes(
        (const unsigned char *)rel_path,
        strlen(rel_path),
        out,
        out_size
    );
}

static int output_compare_format_matches_extension(
    const RecoveryFormat *format,
    const char *extension
)
{
    size_t i;

    if (format == NULL || !has_nonempty_text(extension)) {
        return 0;
    }
    if (format->default_extension != NULL &&
        strcasecmp(format->default_extension, extension) == 0) {
        return 1;
    }
    for (i = 0; i < format->extension_count; i++) {
        if (format->extensions != NULL &&
            format->extensions[i] != NULL &&
            strcasecmp(format->extensions[i], extension) == 0) {
            return 1;
        }
    }
    return 0;
}

static const char *output_compare_path_extension(const char *path)
{
    const char *base;
    const char *slash;
    const char *backslash;
    const char *dot;

    if (!has_nonempty_text(path)) {
        return NULL;
    }

    base = path;
    slash = strrchr(path, '/');
    backslash = strrchr(path, '\\');
    if (slash != NULL || backslash != NULL) {
        if (slash == NULL || (backslash != NULL && backslash > slash)) {
            slash = backslash;
        }
        base = slash + 1;
    }

    dot = strrchr(base, '.');
    if (dot == NULL || dot[1] == '\0') {
        return NULL;
    }
    return dot + 1;
}

static int output_compare_path_matches_selection(
    const Config *format_config,
    const OutputCompareScope *scope,
    const char *rel_path
)
{
    const RecoveryOrder *order;
    const char *extension;
    size_t i;

    if (format_config == NULL || !has_nonempty_text(rel_path)) {
        return 0;
    }
    if (!output_compare_scope_matches_rel_path(scope, rel_path)) {
        return 0;
    }

    extension = output_compare_path_extension(rel_path);
    if (extension == NULL) {
        return 0;
    }

    order = format_config->recovery_order;
    if (order == NULL || order->formats == NULL || order->count == 0) {
        return 0;
    }
    for (i = 0; i < order->count; i++) {
        if (output_compare_format_matches_extension(&order->formats[i], extension)) {
            return 1;
        }
    }
    return 0;
}

static int output_compare_candidate_list_append(
    OutputCompareCandidateList *list,
    const char *rel_path,
    const char *compare_key,
    uint64_t size,
    const char *search_reason
)
{
    OutputCompareCandidate *new_items;
    size_t new_capacity;

    if (list == NULL ||
        !has_nonempty_text(rel_path) ||
        !has_nonempty_text(compare_key) ||
        strlen(rel_path) >= PATH_MAX_LEN ||
        strlen(compare_key) >= PATH_MAX_LEN) {
        return 0;
    }

    if (list->count == list->capacity) {
        new_capacity = list->capacity == 0 ? 1024U : list->capacity * 2U;
        new_items = (OutputCompareCandidate *)realloc(
            list->items,
            new_capacity * sizeof(*new_items)
        );
        if (new_items == NULL) {
            return 0;
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }

    snprintf(list->items[list->count].rel_path, PATH_MAX_LEN, "%s", rel_path);
    snprintf(list->items[list->count].compare_key, PATH_MAX_LEN, "%s", compare_key);
    output_compare_build_name_key(
        rel_path,
        list->items[list->count].name_key,
        sizeof(list->items[list->count].name_key)
    );
    if (has_nonempty_text(search_reason)) {
        snprintf(
            list->items[list->count].search_reason,
            sizeof(list->items[list->count].search_reason),
            "%s",
            search_reason
        );
    } else {
        list->items[list->count].search_reason[0] = '\0';
    }
    list->items[list->count].size = size;
    list->count++;
    return 1;
}

static void output_compare_candidate_list_free(OutputCompareCandidateList *list)
{
    if (list == NULL) {
        return;
    }
    free(list->items);
    list->items = NULL;
    list->count = 0;
    list->capacity = 0;
}

static int output_compare_candidate_order(const void *left, const void *right)
{
    const OutputCompareCandidate *a = (const OutputCompareCandidate *)left;
    const OutputCompareCandidate *b = (const OutputCompareCandidate *)right;
    int cmp = strcmp(a->compare_key, b->compare_key);

    if (cmp != 0) {
        return cmp;
    }
    if (a->size < b->size) {
        return -1;
    }
    if (a->size > b->size) {
        return 1;
    }
    return strcmp(a->rel_path, b->rel_path);
}

static void output_compare_candidate_list_sort(OutputCompareCandidateList *list)
{
    if (list == NULL || list->count == 0) {
        return;
    }
    qsort(list->items, list->count, sizeof(list->items[0]), output_compare_candidate_order);
}

static int output_compare_size_index_order(const void *left, const void *right)
{
    const OutputCompareSizeIndex *a = (const OutputCompareSizeIndex *)left;
    const OutputCompareSizeIndex *b = (const OutputCompareSizeIndex *)right;

    if (a->size < b->size) {
        return -1;
    }
    if (a->size > b->size) {
        return 1;
    }
    if (a->candidate_index < b->candidate_index) {
        return -1;
    }
    if (a->candidate_index > b->candidate_index) {
        return 1;
    }
    return 0;
}

static OutputCompareSizeIndex *output_compare_build_size_index(
    const OutputCompareCandidateList *list
)
{
    OutputCompareSizeIndex *index;
    size_t i;

    if (list == NULL || list->count == 0) {
        return NULL;
    }

    index = (OutputCompareSizeIndex *)calloc(
        list->count,
        sizeof(*index)
    );
    if (index == NULL) {
        return NULL;
    }

    for (i = 0; i < list->count; i++) {
        index[i].size = list->items[i].size;
        index[i].candidate_index = i;
    }
    qsort(index, list->count, sizeof(*index), output_compare_size_index_order);
    return index;
}

static void output_compare_find_size_group(
    const OutputCompareSizeIndex *index,
    size_t count,
    uint64_t wanted_size,
    size_t *out_begin,
    size_t *out_end
)
{
    size_t begin = 0;
    size_t end = count;

    if (out_begin != NULL) {
        *out_begin = 0;
    }
    if (out_end != NULL) {
        *out_end = 0;
    }
    if (index == NULL || count == 0) {
        return;
    }

    while (begin < end) {
        size_t mid = begin + (end - begin) / 2U;

        if (index[mid].size < wanted_size) {
            begin = mid + 1U;
        } else {
            end = mid;
        }
    }
    if (begin >= count || index[begin].size != wanted_size) {
        return;
    }

    end = begin;
    while (end < count && index[end].size == wanted_size) {
        end++;
    }
    if (out_begin != NULL) {
        *out_begin = begin;
    }
    if (out_end != NULL) {
        *out_end = end;
    }
}

static int output_compare_path_is_directory(const char *path)
{
    struct stat st;

    return has_nonempty_text(path) &&
           stat(path, &st) == 0 &&
           S_ISDIR(st.st_mode);
}

static int output_compare_parse_yyyymmdd(const char *text, int *out_date)
{
    int year = 0;
    int month = 0;
    int day = 0;

    if (!has_nonempty_text(text) || out_date == NULL) {
        return 0;
    }
    if (sscanf(text, "%4d%2d%2d", &year, &month, &day) != 3) {
        return 0;
    }
    if (year < 1970 || month < 1 || month > 12 || day < 1 || day > 31) {
        return 0;
    }

    *out_date = (year * 10000) + (month * 100) + day;
    return 1;
}

static int output_compare_parse_date_range(
    const char *text,
    int *out_start,
    int *out_end
)
{
    const char *dash;
    char start_text[16];
    char end_text[16];
    int start_date = 0;
    int end_date = 0;

    if (!has_nonempty_text(text) || out_start == NULL || out_end == NULL) {
        return 0;
    }

    dash = strchr(text, '-');
    if (dash == NULL) {
        if (!output_compare_parse_yyyymmdd(text, &start_date)) {
            return 0;
        }
        *out_start = start_date;
        *out_end = start_date;
        return 1;
    }

    if ((size_t)(dash - text) >= sizeof(start_text) ||
        strlen(dash + 1) >= sizeof(end_text)) {
        return 0;
    }

    snprintf(start_text, sizeof(start_text), "%.*s", (int)(dash - text), text);
    snprintf(end_text, sizeof(end_text), "%s", dash + 1);
    if (!output_compare_parse_yyyymmdd(start_text, &start_date) ||
        !output_compare_parse_yyyymmdd(end_text, &end_date) ||
        end_date < start_date) {
        return 0;
    }

    *out_start = start_date;
    *out_end = end_date;
    return 1;
}

static int app_parse_deleted_filter_value(
    const char *text,
    int *out_has_filter,
    int *out_deleted_value
)
{
    if (out_has_filter == NULL || out_deleted_value == NULL) {
        return 0;
    }

    *out_has_filter = 0;
    *out_deleted_value = 0;
    if (!has_nonempty_text(text)) {
        return 1;
    }

    if (strcmp(text, "1") == 0 ||
        strcmp(text, "true") == 0 ||
        strcmp(text, "yes") == 0 ||
        strcmp(text, "deleted") == 0 ||
        strcmp(text, "trashed") == 0) {
        *out_has_filter = 1;
        *out_deleted_value = 1;
        return 1;
    }

    if (strcmp(text, "0") == 0 ||
        strcmp(text, "false") == 0 ||
        strcmp(text, "no") == 0 ||
        strcmp(text, "live") == 0 ||
        strcmp(text, "active") == 0) {
        *out_has_filter = 1;
        *out_deleted_value = 0;
        return 1;
    }

    if (strcmp(text, "2") == 0 ||
        strcmp(text, "both") == 0 ||
        strcmp(text, "all") == 0 ||
        strcmp(text, "any") == 0) {
        return 1;
    }

    return 0;
}

static int output_compare_stat_yyyymmdd(const struct stat *st, int *out_date)
{
    time_t ts = 0;
    struct tm tm_value;

    if (st == NULL || out_date == NULL) {
        return 0;
    }

    ts = st->st_mtime;

    if (ts <= 0 || localtime_r(&ts, &tm_value) == NULL) {
        return 0;
    }

    *out_date = ((tm_value.tm_year + 1900) * 10000) +
                ((tm_value.tm_mon + 1) * 100) +
                tm_value.tm_mday;
    return 1;
}

static int output_compare_find_child_directory_ci(
    const char *parent,
    const char *wanted_name,
    char *out,
    size_t out_size
)
{
    DIR *dir;
    struct dirent *entry;
    int found = 0;

    if (!has_nonempty_text(parent) ||
        !has_nonempty_text(wanted_name) ||
        out == NULL ||
        out_size == 0) {
        return 0;
    }

    dir = opendir(parent);
    if (dir == NULL) {
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        char candidate[PATH_MAX_LEN];

        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        if (strcasecmp(entry->d_name, wanted_name) != 0) {
            continue;
        }
        if (snprintf(candidate, sizeof(candidate), "%s/%s", parent, entry->d_name) >=
            (int)sizeof(candidate)) {
            continue;
        }
        if (!output_compare_path_is_directory(candidate)) {
            continue;
        }
        snprintf(out, out_size, "%s", candidate);
        found = 1;
        break;
    }

    closedir(dir);
    return found;
}

static int output_compare_resolve_source_root(
    const char *source_path,
    char *out,
    size_t out_size
)
{
    char normalized[PATH_MAX_LEN];

    if (!has_nonempty_text(source_path) || out == NULL || out_size == 0) {
        return 0;
    }
    if (strlen(source_path) >= sizeof(normalized)) {
        return 0;
    }

    snprintf(normalized, sizeof(normalized), "%s", source_path);
    output_compare_trim_trailing_slashes(normalized);
    if (output_compare_find_child_directory_ci(normalized, "Users", out, out_size)) {
        return 1;
    }
    if (output_compare_path_is_directory(normalized)) {
        snprintf(out, out_size, "%s", normalized);
        return 1;
    }

    return 0;
}

static int output_compare_resolve_recovered_root(
    const char *out_dir,
    char *out,
    size_t out_size
)
{
    char normalized[PATH_MAX_LEN];
    char candidate[PATH_MAX_LEN];

    if (!has_nonempty_text(out_dir) || out == NULL || out_size == 0) {
        return 0;
    }
    if (strlen(out_dir) >= sizeof(normalized)) {
        return 0;
    }

    snprintf(normalized, sizeof(normalized), "%s", out_dir);
    output_compare_trim_trailing_slashes(normalized);
    if (snprintf(
            candidate,
            sizeof(candidate),
            "%s/" APP_RECOVERED_DIR_NAME,
            normalized) < (int)sizeof(candidate) &&
        output_compare_path_is_directory(candidate)) {
        snprintf(out, out_size, "%s", candidate);
        return 1;
    }

    if (output_compare_path_is_directory(normalized)) {
        snprintf(out, out_size, "%s", normalized);
        return 1;
    }

    return 0;
}

static int output_compare_resolve_run_dir(
    const char *out_dir,
    char *out,
    size_t out_size
)
{
    char normalized[PATH_MAX_LEN];
    char *slash;

    if (!has_nonempty_text(out_dir) || out == NULL || out_size == 0) {
        return 0;
    }
    if (strlen(out_dir) >= sizeof(normalized)) {
        return 0;
    }

    snprintf(normalized, sizeof(normalized), "%s", out_dir);
    output_compare_trim_trailing_slashes(normalized);
    if (!output_compare_path_is_directory(normalized)) {
        return 0;
    }

    slash = strrchr(normalized, '/');
    if (slash != NULL &&
        strcmp(slash + 1, APP_RECOVERED_DIR_NAME) == 0 &&
        slash != normalized) {
        *slash = '\0';
        if (output_compare_path_is_directory(normalized)) {
            snprintf(out, out_size, "%s", normalized);
            return 1;
        }
    }

    snprintf(out, out_size, "%s", normalized);
    return 1;
}

static int output_compare_collect_recursive(
    const char *root_path,
    const char *relative_path,
    const Config *format_config,
    const OutputCompareScope *scope,
    OutputCompareCandidateList *list,
    const OutputCompareSearchSpec *search,
    int apply_date_filter,
    int date_start_yyyymmdd,
    int date_end_yyyymmdd
)
{
    DIR *dir;
    struct dirent *entry;
    int is_root;

    if (!has_nonempty_text(root_path) || format_config == NULL || list == NULL) {
        return 0;
    }

    is_root = relative_path == NULL || relative_path[0] == '\0';
    dir = opendir(root_path);
    if (dir == NULL) {
        if (is_root) {
            log_error("Could not open compare directory: %s", root_path);
            return 0;
        }
        log_verbose("Skipping unreadable compare directory: %s", root_path);
        return 1;
    }

    while ((entry = readdir(dir)) != NULL && !app_stop_requested()) {
        char child_path[PATH_MAX_LEN];
        char child_rel[PATH_MAX_LEN];
        char key[PATH_MAX_LEN];
        char search_reason[32];
        struct stat st;

        if (strcmp(entry->d_name, ".") == 0 ||
            strcmp(entry->d_name, "..") == 0 ||
            strcmp(entry->d_name, ".DS_Store") == 0) {
            continue;
        }
        if (snprintf(child_path, sizeof(child_path), "%s/%s", root_path, entry->d_name) >=
            (int)sizeof(child_path)) {
            continue;
        }
        if (has_nonempty_text(relative_path)) {
            if (snprintf(child_rel, sizeof(child_rel), "%s/%s", relative_path, entry->d_name) >=
                (int)sizeof(child_rel)) {
                continue;
            }
        } else {
            if (snprintf(child_rel, sizeof(child_rel), "%s", entry->d_name) >=
                (int)sizeof(child_rel)) {
                continue;
            }
        }
        if (lstat(child_path, &st) != 0) {
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            if (!output_compare_collect_recursive(
                    child_path,
                    child_rel,
                    format_config,
                    scope,
                    list,
                    search,
                    apply_date_filter,
                    date_start_yyyymmdd,
                    date_end_yyyymmdd)) {
                closedir(dir);
                return 0;
            }
            continue;
        }
        if (!S_ISREG(st.st_mode) ||
            !output_compare_path_matches_selection(format_config, scope, child_rel)) {
            continue;
        }
        if (apply_date_filter) {
            int file_date = 0;

            if (!output_compare_stat_yyyymmdd(&st, &file_date) ||
                file_date < date_start_yyyymmdd ||
                file_date > date_end_yyyymmdd) {
                continue;
            }
        }
        if (search != NULL && search->active) {
            if (!output_compare_search_matches_rel_path(
                    search,
                    child_rel,
                    search_reason,
                    sizeof(search_reason)) &&
                !output_compare_search_matches_header(
                    search,
                    child_path,
                    search_reason,
                    sizeof(search_reason))) {
                continue;
            }
        }

        output_compare_build_key(child_rel, key, sizeof(key));
        if (key[0] == '\0' ||
            !output_compare_candidate_list_append(
                list,
                child_rel,
                key,
                (uint64_t)st.st_size,
                search != NULL && search->active ? search_reason : NULL)) {
            closedir(dir);
            return 0;
        }
    }

    closedir(dir);
    return !app_stop_requested();
}

static int output_compare_write_snapshot(
    const char *out_dir,
    const char *file_name,
    const OutputCompareCandidateList *list
)
{
    char state_dir[PATH_MAX_LEN];
    char path[PATH_MAX_LEN];
    FILE *file;
    size_t i;

    if (!has_nonempty_text(out_dir) ||
        !has_nonempty_text(file_name) ||
        list == NULL) {
        return 0;
    }
    if (snprintf(state_dir, sizeof(state_dir), "%s/" APP_STATE_DIR_NAME, out_dir) >=
            (int)sizeof(state_dir) ||
        !ensure_directory_path(state_dir) ||
        snprintf(path, sizeof(path), "%s/%s", state_dir, file_name) >=
            (int)sizeof(path)) {
        return 0;
    }

    file = fopen(path, "wb");
    if (file == NULL) {
        return 0;
    }

    fprintf(file, "size\trel_path\tcompare_key\n");
    for (i = 0; i < list->count; i++) {
        fprintf(
            file,
            "%llu\t%s\t%s\n",
            (unsigned long long)list->items[i].size,
            list->items[i].rel_path,
            list->items[i].compare_key
        );
    }

    fclose(file);
    log_verbose("Compare snapshot: %s", path);
    return 1;
}

static int output_compare_write_search_hits(
    const char *out_dir,
    const OutputCompareCandidateList *list
)
{
    char state_dir[PATH_MAX_LEN];
    char path[PATH_MAX_LEN];
    FILE *file;
    size_t i;

    if (!has_nonempty_text(out_dir) || list == NULL) {
        return 0;
    }
    if (snprintf(state_dir, sizeof(state_dir), "%s/" APP_STATE_DIR_NAME, out_dir) >=
            (int)sizeof(state_dir) ||
        !ensure_directory_path(state_dir) ||
        snprintf(path, sizeof(path), "%s/compare_search_hits.tsv", state_dir) >=
            (int)sizeof(path)) {
        return 0;
    }

    file = fopen(path, "wb");
    if (file == NULL) {
        return 0;
    }

    fprintf(file, "size\trel_path\tmatch_reason\n");
    for (i = 0; i < list->count; i++) {
        fprintf(
            file,
            "%llu\t%s\t%s\n",
            (unsigned long long)list->items[i].size,
            list->items[i].rel_path,
            list->items[i].search_reason[0] != '\0' ?
                list->items[i].search_reason :
                "path_match"
        );
    }

    fclose(file);
    log_verbose("Compare search hits: %s", path);
    return 1;
}

static void output_compare_match_same_size_groups(
    const OutputCompareCandidateList *recovered_list,
    const OutputCompareCandidateList *source_list,
    const OutputCompareSizeIndex *recovered_index,
    const OutputCompareSizeIndex *source_index,
    unsigned char *recovered_used,
    unsigned char *source_used,
    OutputCompareStats *stats,
    int match_mode
)
{
    size_t recovered_group_begin = 0;

    if (recovered_list == NULL || source_list == NULL ||
        recovered_index == NULL || source_index == NULL ||
        recovered_used == NULL || source_used == NULL ||
        stats == NULL) {
        return;
    }

    while (recovered_group_begin < recovered_list->count) {
        uint64_t size_value = recovered_index[recovered_group_begin].size;
        size_t recovered_group_end = recovered_group_begin;
        size_t source_group_begin = 0;
        size_t source_group_end = 0;
        size_t i;

        while (recovered_group_end < recovered_list->count &&
               recovered_index[recovered_group_end].size == size_value) {
            recovered_group_end++;
        }

        output_compare_find_size_group(
            source_index,
            source_list->count,
            size_value,
            &source_group_begin,
            &source_group_end
        );
        if (source_group_end <= source_group_begin) {
            recovered_group_begin = recovered_group_end;
            continue;
        }

        for (i = recovered_group_begin; i < recovered_group_end; i++) {
            size_t recovered_candidate_index = recovered_index[i].candidate_index;
            size_t matched_source_index = SIZE_MAX;

            if (recovered_used[recovered_candidate_index]) {
                continue;
            }
            if (!output_compare_find_unique_group_match(
                    recovered_list,
                    source_list,
                    recovered_used,
                    source_used,
                    recovered_index,
                    recovered_group_begin,
                    recovered_group_end,
                    recovered_candidate_index,
                    source_index,
                    source_group_begin,
                    source_group_end,
                    match_mode,
                    &matched_source_index)) {
                continue;
            }
            if (matched_source_index == SIZE_MAX || source_used[matched_source_index]) {
                continue;
            }

            recovered_used[recovered_candidate_index] = 1U;
            source_used[matched_source_index] = 1U;
            stats->matched++;
            if (match_mode == 1) {
                stats->matched_suffix++;
            } else {
                stats->matched_name_size++;
            }
        }

        recovered_group_begin = recovered_group_end;
    }
}

static int output_compare_write_reports(
    const char *out_dir,
    const OutputCompareCandidateList *recovered_list,
    const OutputCompareCandidateList *source_list,
    OutputCompareStats *stats
)
{
    char state_dir[PATH_MAX_LEN];
    char only_source_path[PATH_MAX_LEN];
    char mismatch_path[PATH_MAX_LEN];
    FILE *only_source_file = NULL;
    FILE *mismatch_file = NULL;
    unsigned char *recovered_used = NULL;
    unsigned char *source_used = NULL;
    OutputCompareSizeIndex *recovered_size_index = NULL;
    OutputCompareSizeIndex *source_size_index = NULL;
    size_t recovered_pos = 0;
    size_t source_pos = 0;
    OutputCompareStats local_stats;

    memset(&local_stats, 0, sizeof(local_stats));
    if (stats != NULL) {
        memset(stats, 0, sizeof(*stats));
    }
    if (!has_nonempty_text(out_dir) ||
        recovered_list == NULL ||
        source_list == NULL) {
        return 0;
    }

    if (snprintf(state_dir, sizeof(state_dir), "%s/" APP_STATE_DIR_NAME, out_dir) >=
            (int)sizeof(state_dir) ||
        !ensure_directory_path(state_dir) ||
        snprintf(
            only_source_path,
            sizeof(only_source_path),
            "%s/compare_only_in_source.tsv",
            state_dir) >= (int)sizeof(only_source_path) ||
        snprintf(
            mismatch_path,
            sizeof(mismatch_path),
            "%s/compare_mismatch.tsv",
            state_dir) >= (int)sizeof(mismatch_path)) {
        return 0;
    }

    only_source_file = fopen(only_source_path, "wb");
    mismatch_file = fopen(mismatch_path, "wb");
    if (only_source_file == NULL || mismatch_file == NULL) {
        if (only_source_file != NULL) fclose(only_source_file);
        if (mismatch_file != NULL) fclose(mismatch_file);
        return 0;
    }

    fprintf(only_source_file, "size\trel_path\n");
    fprintf(mismatch_file, "recovered_size\tsource_size\trecovered_rel_path\tsource_rel_path\n");

    if (recovered_list->count > 0) {
        recovered_used = (unsigned char *)calloc(recovered_list->count, sizeof(*recovered_used));
    }
    if (source_list->count > 0) {
        source_used = (unsigned char *)calloc(source_list->count, sizeof(*source_used));
    }
    recovered_size_index = output_compare_build_size_index(recovered_list);
    source_size_index = output_compare_build_size_index(source_list);
    if ((recovered_list->count > 0 && recovered_used == NULL) ||
        (source_list->count > 0 && source_used == NULL) ||
        (recovered_list->count > 0 && recovered_size_index == NULL) ||
        (source_list->count > 0 && source_size_index == NULL)) {
        free(recovered_used);
        free(source_used);
        free(recovered_size_index);
        free(source_size_index);
        fclose(only_source_file);
        fclose(mismatch_file);
        return 0;
    }

    while (recovered_pos < recovered_list->count &&
           source_pos < source_list->count) {
        const OutputCompareCandidate *recovered =
            &recovered_list->items[recovered_pos];
        const OutputCompareCandidate *source = &source_list->items[source_pos];
        int cmp = strcmp(recovered->compare_key, source->compare_key);

        if (cmp == 0) {
            recovered_used[recovered_pos] = 1U;
            source_used[source_pos] = 1U;
            if (recovered->size == source->size) {
                local_stats.matched++;
                local_stats.matched_exact++;
            } else {
                fprintf(
                    mismatch_file,
                    "%llu\t%llu\t%s\t%s\n",
                    (unsigned long long)recovered->size,
                    (unsigned long long)source->size,
                    recovered->rel_path,
                    source->rel_path
                );
                local_stats.mismatch++;
            }
            recovered_pos++;
            source_pos++;
            continue;
        }

        if (cmp < 0) {
            recovered_pos++;
        } else {
            source_pos++;
        }
    }

    output_compare_match_same_size_groups(
        recovered_list,
        source_list,
        recovered_size_index,
        source_size_index,
        recovered_used,
        source_used,
        &local_stats,
        1
    );
    output_compare_match_same_size_groups(
        recovered_list,
        source_list,
        recovered_size_index,
        source_size_index,
        recovered_used,
        source_used,
        &local_stats,
        2
    );

    for (source_pos = 0; source_pos < source_list->count; source_pos++) {
        const OutputCompareCandidate *source = &source_list->items[source_pos];

        if (source_used[source_pos]) {
            continue;
        }

        fprintf(
            only_source_file,
            "%llu\t%s\n",
            (unsigned long long)source->size,
            source->rel_path
        );
        local_stats.only_source++;
    }

    fclose(only_source_file);
    fclose(mismatch_file);
    free(recovered_used);
    free(source_used);
    free(recovered_size_index);
    free(source_size_index);

    if (stats != NULL) {
        *stats = local_stats;
    }

    log_verbose("Compare reports: %s", only_source_path);
    log_verbose("Compare reports: %s", mismatch_path);
    return 1;
}

static void output_compare_print_only_source_paths(const char *out_dir)
{
    char state_dir[PATH_MAX_LEN];
    char only_source_path[PATH_MAX_LEN];
    FILE *file;
    char line[PATH_MAX_LEN * 2U];
    OutputCompareExtCount *ext_counts = NULL;
    size_t ext_count = 0;
    size_t ext_capacity = 0;
    size_t total_missing = 0;
    int first = 1;
    size_t i;

    if (!has_nonempty_text(out_dir) ||
        snprintf(state_dir, sizeof(state_dir), "%s/" APP_STATE_DIR_NAME, out_dir) >=
            (int)sizeof(state_dir) ||
        snprintf(only_source_path, sizeof(only_source_path), "%s/compare_only_in_source.tsv", state_dir) >=
            (int)sizeof(only_source_path)) {
        return;
    }

    file = fopen(only_source_path, "rb");
    if (file == NULL) {
        return;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *tab;
        const char *ext;
        char normalized_ext[32];
        size_t ext_len = 0;
        int found = 0;

        if (strncmp(line, "size\trel_path", 13U) == 0) {
            continue;
        }
        tab = strchr(line, '\t');
        if (tab == NULL || tab[1] == '\0') {
            continue;
        }
        output_compare_trim_ascii(tab + 1);
        if (tab[1] == '\0') {
            continue;
        }
        if (first) {
            printf("Missing from recovered:\n");
            first = 0;
        }
        printf("%s\n", tab + 1);
        total_missing++;

        ext = output_compare_path_extension(tab + 1);
        if (ext == NULL || ext[0] == '\0') {
            snprintf(normalized_ext, sizeof(normalized_ext), "noext");
        } else {
            while (ext[ext_len] != '\0' &&
                   ext_len + 1U < sizeof(normalized_ext)) {
                normalized_ext[ext_len] =
                    (char)tolower((unsigned char)ext[ext_len]);
                ext_len++;
            }
            normalized_ext[ext_len] = '\0';
            if (ext[ext_len] != '\0') {
                snprintf(normalized_ext, sizeof(normalized_ext), "%s", "other");
            }
        }

        for (i = 0; i < ext_count; i++) {
            if (strcmp(ext_counts[i].ext, normalized_ext) == 0) {
                ext_counts[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            OutputCompareExtCount *new_ext_counts;
            size_t new_capacity;

            if (ext_count == ext_capacity) {
                new_capacity = ext_capacity == 0 ? 8U : ext_capacity * 2U;
                new_ext_counts = (OutputCompareExtCount *)realloc(
                    ext_counts,
                    new_capacity * sizeof(*new_ext_counts)
                );
                if (new_ext_counts == NULL) {
                    free(ext_counts);
                    fclose(file);
                    return;
                }
                ext_counts = new_ext_counts;
                ext_capacity = new_capacity;
            }

            snprintf(ext_counts[ext_count].ext, sizeof(ext_counts[ext_count].ext), "%s", normalized_ext);
            ext_counts[ext_count].count = 1U;
            ext_count++;
        }
    }

    fclose(file);

    if (total_missing > 0) {
        qsort(ext_counts, ext_count, sizeof(*ext_counts), output_compare_ext_count_desc);

        printf("\n");
        printf(
            "%zu %s differ.",
            total_missing,
            total_missing == 1U ? "file" : "files"
        );
        for (i = 0; i < ext_count; i++) {
            printf(
                "%s%zu %s",
                i == 0 ? " " : ", ",
                ext_counts[i].count,
                ext_counts[i].ext
            );
        }
        printf("\n");
    }

    free(ext_counts);
}

static int output_compare_build_only_source_report_path(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    char state_dir[PATH_MAX_LEN];

    if (!has_nonempty_text(run_dir) || out == NULL || out_size == 0) {
        return 0;
    }
    if (snprintf(state_dir, sizeof(state_dir), "%s/" APP_STATE_DIR_NAME, run_dir) >=
            (int)sizeof(state_dir) ||
        !ensure_directory_path(state_dir) ||
        snprintf(out, out_size, "%s/compare_only_in_source.tsv", state_dir) >=
            (int)out_size) {
        return 0;
    }
    return 1;
}

static int resolve_auto_record_list_path_for_run(
    const AppConfig *config,
    char *out,
    size_t out_size
)
{
    char run_dir[PATH_MAX_LEN];

    if (config == NULL || out == NULL || out_size == 0) {
        return 0;
    }
    if (!config->record_list_auto || has_nonempty_text(config->record_list_path)) {
        return 0;
    }
    if (!output_compare_resolve_run_dir(
            config->output_dir,
            run_dir,
            sizeof(run_dir)) ||
        !output_compare_build_only_source_report_path(
            run_dir,
            out,
            out_size)) {
        return 0;
    }
    return access(out, F_OK) == 0;
}

static int output_compare_report_has_rows(const char *path)
{
    FILE *file;
    char line[PATH_MAX_LEN * 2U];

    if (!has_nonempty_text(path)) {
        return 0;
    }

    file = fopen(path, "rb");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        output_compare_trim_ascii(line);
        if (line[0] == '\0' || line[0] == '#') {
            continue;
        }
        if (strncmp(line, "size\trel_path", 13U) == 0) {
            continue;
        }
        fclose(file);
        return 1;
    }

    fclose(file);
    return 0;
}

static void output_compare_print_done(
    const OutputCompareCandidateList *recovered_list,
    const OutputCompareCandidateList *source_list,
    const OutputCompareStats *stats,
    const OutputCompareSearchSpec *search,
    const char *out_dir
)
{
    log_set_done_mode();
    printf("\n");
    printf("DONE (comp)\n");
    printf("Source files: %zu\n", source_list != NULL ? source_list->count : 0);
    printf("Recovered files: %zu\n", recovered_list != NULL ? recovered_list->count : 0);
    if (search != NULL && search->active) {
        printf(
            "Search hits: %zu for \"%s\"\n",
            source_list != NULL ? source_list->count : 0,
            search->raw
        );
    }
    printf("Matched: %zu\n", stats != NULL ? stats->matched : 0);
    if (stats != NULL) {
        printf(
            "Matched detail: exact=%zu suffix=%zu name+size=%zu\n",
            stats->matched_exact,
            stats->matched_suffix,
            stats->matched_name_size
        );
    }
    printf("Only in source: %zu\n", stats != NULL ? stats->only_source : 0);
    printf("Size mismatch: %zu\n", stats != NULL ? stats->mismatch : 0);
    if (has_nonempty_text(out_dir)) {
        printf("Reports: %s/%s\n", out_dir, APP_STATE_DIR_NAME);
        if (search != NULL && search->active) {
            printf("Search TSV: %s/%s/compare_search_hits.tsv\n", out_dir, APP_STATE_DIR_NAME);
        }
    }
    output_compare_print_only_source_paths(out_dir);
    fflush(stdout);
}

static int run_output_compare_mode(const AppConfig *config)
{
    Config format_config = {0};
    MftprobeFormatSelection selection = {0};
    OutputCompareScope scope = {0};
    OutputCompareCandidateList recovered_list = {0};
    OutputCompareCandidateList source_list = {0};
    OutputCompareStats stats = {0};
    char source_root[PATH_MAX_LEN];
    char recovered_root[PATH_MAX_LEN];
    char run_dir[PATH_MAX_LEN];
    char format_error[512];
    char scope_error[256];
    char active_formats[1024];
    OutputCompareSearchSpec search = {0};
    int compare_date_start = 0;
    int compare_date_end = 0;
    int compare_has_date = 0;
    int ok = 0;
    int handlers_installed = 0;

    if (config == NULL || !has_nonempty_text(config->input_path)) {
        log_error("Mode comp requires --src pointing to a mounted Windows volume or Users directory");
        return 0;
    }
    if (!has_nonempty_text(config->output_dir)) {
        log_error("Mode comp requires --out pointing to the recovered run root");
        return 0;
    }

    run_dir[0] = '\0';
    source_root[0] = '\0';
    recovered_root[0] = '\0';
    if (!output_compare_resolve_run_dir(
            config->output_dir,
            run_dir,
            sizeof(run_dir))) {
        log_error("Could not resolve a readable run directory under: %s", config->output_dir);
        return 0;
    }
    if (!output_compare_resolve_source_root(
            config->input_path,
            source_root,
            sizeof(source_root))) {
        log_error("Could not resolve a readable compare root under source: %s", config->input_path);
        return 0;
    }
    if (!output_compare_resolve_recovered_root(
            run_dir,
            recovered_root,
            sizeof(recovered_root))) {
        log_error(
            "Could not resolve a readable recovered compare root under: %s",
            run_dir
        );
        return 0;
    }

    if (!output_compare_scope_parse(
            config->compare_scope_csv,
            &scope,
            scope_error,
            sizeof(scope_error))) {
        log_error(
            "Compare scope failed: %s",
            scope_error[0] != '\0' ? scope_error : "unknown error"
        );
        return 0;
    }
    if (has_nonempty_text(config->target_date_value)) {
        if (!output_compare_parse_date_range(
                config->target_date_value,
                &compare_date_start,
                &compare_date_end)) {
            log_error(
                "Compare date filter is invalid: %s (expected YYYYMMDD or YYYYMMDD-YYYYMMDD)",
                config->target_date_value
            );
            return 0;
        }
        compare_has_date = 1;
    }
    if (has_nonempty_text(config->target_find_value) &&
        !output_compare_search_prepare(config->target_find_value, &search)) {
        log_error("Compare search text is invalid or too long: %s", config->target_find_value);
        return 0;
    }

    format_config.recovery_order = mftprobe_format_default_order();
    if (!mftprobe_format_load_common_profiles(&format_config, FORMAT_PROFILE_DB_PATH)) {
        log_info("Format profiles not loaded from %s; using built-in defaults", FORMAT_PROFILE_DB_PATH);
    }

    selection.categories_csv = config->mft_categories_csv;
    selection.formats_csv = config->mft_formats_csv;
    selection.dev_format = config->mft_dev_format;
    if (!has_nonempty_text(selection.categories_csv) &&
        !has_nonempty_text(selection.formats_csv) &&
        !has_nonempty_text(selection.dev_format)) {
        selection.categories_csv = "all";
    }

    format_error[0] = '\0';
    if (!mftprobe_format_configure_active_order(
            &format_config,
            &selection,
            format_error,
            sizeof(format_error))) {
        log_error(
            "Compare format selection failed: %s",
            format_error[0] != '\0' ? format_error : "unknown error"
        );
        return 0;
    }

    mftprobe_format_describe_active_order(
        &format_config,
        active_formats,
        sizeof(active_formats)
    );

    log_info("Compare mode: source files vs recovered files");
    log_info("Source root: %s", source_root);
    log_info("Recovered root: %s", recovered_root);
    log_info("Run dir: %s", run_dir);
    log_verbose("Active formats: %s", active_formats);
    if (has_nonempty_text(config->compare_scope_csv)) {
        log_info("Compare scope: %s", config->compare_scope_csv);
    }
    if (compare_has_date) {
        log_info("Compare date filter: %s", config->target_date_value);
    }
    if (search.active) {
        log_info("Compare search: %s", search.raw);
    }
    log_info("Compare matching: exact path first, then path suffix, then file name + size");
    if (has_nonempty_text(config->target_deleted_value) ||
        config->mft_limit > 0) {
        log_info("Mode comp compares files only; MFT-only filters such as deleted/limit are ignored");
    }

    handlers_installed = app_install_signal_handlers();
    if (!handlers_installed) {
        log_info("Could not install Ctrl-C handler; default interrupt behavior remains active");
    }

    log_info("Collecting recovered files...");
    if (!output_compare_collect_recursive(
            recovered_root,
            "",
            &format_config,
            &scope,
            &recovered_list,
            NULL,
            0,
            0,
            0)) {
        if (app_stop_requested()) {
            log_info("Compare interrupted by user");
        } else {
            log_error("Failed while collecting recovered files");
        }
        goto cleanup;
    }

    log_info("Collecting source files...");
    if (!output_compare_collect_recursive(
            source_root,
            "",
            &format_config,
            &scope,
            &source_list,
            &search,
            compare_has_date,
            compare_date_start,
            compare_date_end)) {
        if (app_stop_requested()) {
            log_info("Compare interrupted by user");
        } else {
            log_error("Failed while collecting source files");
        }
        goto cleanup;
    }

    output_compare_candidate_list_sort(&recovered_list);
    output_compare_candidate_list_sort(&source_list);

    if (!output_compare_write_snapshot(
            run_dir,
            "compare_recovered_snapshot.tsv",
            &recovered_list) ||
        !output_compare_write_snapshot(
            run_dir,
            "compare_source_snapshot.tsv",
            &source_list) ||
        (search.active &&
         !output_compare_write_search_hits(
             run_dir,
             &source_list)) ||
        !output_compare_write_reports(
            run_dir,
            &recovered_list,
            &source_list,
            &stats)) {
        log_error("Failed to write compare reports");
        goto cleanup;
    }

    log_info(
        "Compare finished: recovered=%zu source=%zu matched=%zu only_source=%zu mismatch=%zu",
        recovered_list.count,
        source_list.count,
        stats.matched,
        stats.only_source,
        stats.mismatch
    );
    output_compare_print_done(&recovered_list, &source_list, &stats, &search, run_dir);
    ok = 1;

cleanup:
    if (handlers_installed) {
        app_restore_signal_handlers();
    }
    output_compare_candidate_list_free(&recovered_list);
    output_compare_candidate_list_free(&source_list);
    return ok;
}

static int run_output_compare_then_recover_mode(const AppConfig *config)
{
    AppConfig compare_config;
    AppConfig recover_config;
    char run_dir[PATH_MAX_LEN];
    char diff_path[PATH_MAX_LEN];
    int have_existing_diff = 0;
    int compare_ok = 1;

    if (config == NULL) {
        return 0;
    }
    if (!output_compare_resolve_run_dir(
            config->output_dir,
            run_dir,
            sizeof(run_dir))) {
        log_error("Mode comp could not resolve a readable run directory under: %s", config->output_dir);
        return 0;
    }

    diff_path[0] = '\0';
    if (has_nonempty_text(config->record_list_path)) {
        if (strlen(config->record_list_path) >= sizeof(diff_path)) {
            log_error("Compare diff path is too long");
            return 0;
        }
        snprintf(diff_path, sizeof(diff_path), "%s", config->record_list_path);
        have_existing_diff = access(diff_path, F_OK) == 0;
    } else if (config->record_list_auto) {
        if (!output_compare_build_only_source_report_path(
                run_dir,
                diff_path,
                sizeof(diff_path))) {
            log_error("Could not build compare diff path under run directory");
            return 0;
        }
        have_existing_diff = access(diff_path, F_OK) == 0;
    }

    if (!have_existing_diff) {
        compare_config = *config;
        compare_config.output_dir = run_dir;
        compare_ok = run_output_compare_mode(&compare_config);
        if (!compare_ok) {
            return 0;
        }
        if (!has_nonempty_text(diff_path)) {
            if (!output_compare_build_only_source_report_path(
                    run_dir,
                    diff_path,
                    sizeof(diff_path))) {
                log_error("Could not locate compare diff TSV after compare");
                return 0;
            }
        }
    } else {
        log_info("Using existing compare diff: %s", diff_path);
    }

    if (!output_compare_report_has_rows(diff_path)) {
        log_info("Compare found no files missing from recovered; nothing to recover");
        return 1;
    }

    recover_config = *config;
    recover_config.output_dir = run_dir;
    recover_config.record_list_path = diff_path;
    recover_config.record_list_auto = 0;
    recover_config.compare_mount_path = NULL;
    recover_config.target_filter_csv = NULL;
    recover_config.target_date_value = NULL;
    recover_config.target_deleted_value = NULL;

    log_info("Recovering only files listed in compare diff: %s", diff_path);
    return run_targeted_filter_mode(&recover_config);
}

static int build_scan_state_path(
    const char *out_dir,
    char *out,
    size_t out_size
)
{
    if (out_dir == NULL || out == NULL || out_size == 0) {
        return 0;
    }

    return snprintf(
               out,
               out_size,
               "%s/" APP_STATE_DIR_NAME "/scan_state.txt",
               out_dir
           ) < (int)out_size;
}

static void log_reconnect_debug_info(const char *fmt, ...)
{
    char message[768];
    va_list args;

    if (fmt == NULL || fmt[0] == '\0') {
        return;
    }

    va_start(args, fmt);
    if (vsnprintf(message, sizeof(message), fmt, args) >= (int)sizeof(message)) {
        message[sizeof(message) - 1U] = '\0';
    }
    va_end(args);

    log_info("%s", message);
    log_runtime_event_info("%s", message);
}

static void persist_relocated_source_path_in_scan_state(
    const char *run_dir,
    const char *new_source_path
)
{
    char scan_state_path[PATH_MAX_LEN];
    ScanState state = {0};

    if (run_dir == NULL ||
        run_dir[0] == '\0' ||
        new_source_path == NULL ||
        new_source_path[0] == '\0' ||
        !build_scan_state_path(
            run_dir,
            scan_state_path,
            sizeof(scan_state_path)) ||
        !scan_state_load(scan_state_path, &state) ||
        strcmp(state.source_path, new_source_path) == 0) {
        return;
    }

    scan_state_identity_seed_from_loaded(&state);
    capture_source_device_identity_if_available(new_source_path);
    if (!scan_state_write(
            scan_state_path,
            new_source_path,
            state.scan_mode,
            state.source_size,
            state.scan_offset,
            state.scan_completed,
            state.completed)) {
        log_runtime_event_error(
            "Reconnect matched a new source path %s, but scan_state.txt could not be updated from %s",
            new_source_path,
            state.source_path
        );
        return;
    }

    log_reconnect_debug_info(
        "Updated saved source path in scan_state.txt from %s to %s after reconnect rematch",
        state.source_path,
        new_source_path
    );
}

