static uint64_t hash_u64_local(uint64_t value)
{
    value ^= value >> 33;
    value *= 0xff51afd7ed558ccdULL;
    value ^= value >> 33;
    value *= 0xc4ceb9fe1a85ec53ULL;
    value ^= value >> 33;
    return value;
}

typedef struct {
    uint64_t *keys;
    size_t count;
    size_t capacity;
    char path[PATH_MAX_LEN];
} NameOnlyWholeRecordSet;

static void name_only_whole_record_set_init(NameOnlyWholeRecordSet *set)
{
    if (set == NULL) {
        return;
    }
    memset(set, 0, sizeof(*set));
}

static void name_only_whole_record_set_free(NameOnlyWholeRecordSet *set)
{
    if (set == NULL) {
        return;
    }
    free(set->keys);
    set->keys = NULL;
    set->count = 0U;
    set->capacity = 0U;
    set->path[0] = '\0';
}

static int name_only_whole_record_set_ensure_capacity(NameOnlyWholeRecordSet *set)
{
    size_t new_capacity;
    uint64_t *new_keys;
    size_t i;

    if (set == NULL) {
        return 0;
    }
    if (set->capacity > 0U &&
        (set->count + 1U) * 10U < set->capacity * 7U) {
        return 1;
    }

    new_capacity = set->capacity == 0U ? 1024U : set->capacity * 2U;
    new_keys = (uint64_t *)calloc(new_capacity, sizeof(*new_keys));
    if (new_keys == NULL) {
        return 0;
    }

    for (i = 0U; i < set->capacity; i++) {
        uint64_t key = set->keys[i];
        size_t index;

        if (key == 0U) {
            continue;
        }
        index = (size_t)hash_u64_local(key) & (new_capacity - 1U);
        while (new_keys[index] != 0U) {
            index = (index + 1U) & (new_capacity - 1U);
        }
        new_keys[index] = key;
    }

    free(set->keys);
    set->keys = new_keys;
    set->capacity = new_capacity;
    return 1;
}

static int name_only_whole_record_set_contains(
    const NameOnlyWholeRecordSet *set,
    uint64_t absolute_offset
)
{
    uint64_t key;
    size_t index;

    if (set == NULL || set->capacity == 0U) {
        return 0;
    }

    key = absolute_offset + 1U;
    if (key == 0U) {
        return 0;
    }

    index = (size_t)hash_u64_local(key) & (set->capacity - 1U);
    while (set->keys[index] != 0U) {
        if (set->keys[index] == key) {
            return 1;
        }
        index = (index + 1U) & (set->capacity - 1U);
    }
    return 0;
}

static int name_only_whole_record_set_insert(
    NameOnlyWholeRecordSet *set,
    uint64_t absolute_offset
)
{
    uint64_t key;
    size_t index;

    if (set == NULL) {
        return 0;
    }
    if (!name_only_whole_record_set_ensure_capacity(set)) {
        return 0;
    }

    key = absolute_offset + 1U;
    if (key == 0U) {
        return 0;
    }

    index = (size_t)hash_u64_local(key) & (set->capacity - 1U);
    while (set->keys[index] != 0U) {
        if (set->keys[index] == key) {
            return 1;
        }
        index = (index + 1U) & (set->capacity - 1U);
    }

    set->keys[index] = key;
    set->count++;
    return 1;
}

static int initialize_name_only_trouble_positions_file(const char *run_dir)
{
    char path[PATH_MAX_LEN];
    FILE *file;

    if (!has_nonempty_text(run_dir) ||
        !ensure_state_dir_for_run(run_dir) ||
        !build_state_child_path_local(run_dir, "name_salvage_trouble_positions.tsv", path, sizeof(path))) {
        return 0;
    }

    file = fopen(path, "w");
    if (file == NULL) {
        return 0;
    }
    fprintf(
        file,
        "offset\tend_offset\tkind\trecord_index\tsector_index\tfailed_sectors\tskipped_sectors\tfirst_sector_bytes\tstage\n"
    );
    fclose(file);
    return 1;
}

static int append_name_only_trouble_position(
    const char *run_dir,
    const char *stage,
    uint64_t absolute_offset,
    size_t record_size,
    const Reader *reader
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    long long base_ll;
    uint64_t base_offset = 0ULL;
    uint64_t sector_size;
    uint64_t relative_offset;
    uint64_t relative_record_index;
    uint64_t relative_sector_index;
    uint64_t span_start_offset;
    uint64_t span_bytes;
    const char *kind = NULL;

    if (!has_nonempty_text(run_dir) ||
        reader == NULL ||
        record_size == 0U ||
        !build_state_child_path_local(run_dir, "name_salvage_trouble_positions.tsv", path, sizeof(path))) {
        return 0;
    }

    sector_size = reader->precise_record_sector_size > 0U
                      ? (uint64_t)reader->precise_record_sector_size
                      : 512ULL;
    span_bytes = reader->last_precise_record_skipped_sectors * sector_size;
    if (reader->last_precise_record_failed_sectors > 0U) {
        span_bytes += reader->last_precise_record_failed_sectors * sector_size;
    }
    if (span_bytes == 0ULL) {
        if (reader->last_precise_record_first_sector_partial) {
            span_bytes = sector_size;
        } else {
            return 1;
        }
    }

    span_start_offset = absolute_offset;
    if (reader->last_precise_record_first_sector_failed) {
        kind = "drop";
    } else if (reader->last_precise_record_skipped_sectors > 0U &&
               reader->last_precise_record_first_sector_partial) {
        kind = "partial_keep";
    } else if (reader->last_precise_record_skipped_sectors > 0U) {
        kind = "tail_skip";
        span_start_offset = absolute_offset + sector_size;
        span_bytes = reader->last_precise_record_skipped_sectors * sector_size;
    } else if (reader->last_precise_record_later_sector_failed) {
        kind = "later_bad";
        span_start_offset = absolute_offset + sector_size;
        span_bytes = reader->last_precise_record_failed_sectors * sector_size;
    } else if (reader->last_precise_record_first_sector_partial) {
        kind = "partial_first";
    } else {
        return 1;
    }

    base_ll = fs_backend_primary_scan_start_offset();
    if (base_ll >= 0LL && absolute_offset >= (uint64_t)base_ll) {
        base_offset = (uint64_t)base_ll;
    }

    relative_offset = span_start_offset >= base_offset
                          ? span_start_offset - base_offset
                          : span_start_offset;
    relative_record_index = relative_offset / (uint64_t)record_size;
    relative_sector_index = relative_offset / sector_size;

    file = fopen(path, "a");
    if (file == NULL) {
        return 0;
    }
    fprintf(
        file,
        "%llu\t%llu\t%s\t%llu\t%llu\t%zu\t%zu\t%zu\t%s\n",
        (unsigned long long)span_start_offset,
        (unsigned long long)(span_start_offset + span_bytes),
        kind,
        (unsigned long long)relative_record_index,
        (unsigned long long)relative_sector_index,
        reader->last_precise_record_failed_sectors,
        reader->last_precise_record_skipped_sectors,
        reader->last_precise_record_first_sector_bytes_read,
        has_nonempty_text(stage) ? stage : ""
    );
    fclose(file);
    return 1;
}

static int name_only_whole_record_set_load(
    NameOnlyWholeRecordSet *set,
    const char *run_dir
)
{
    FILE *file;
    char path[PATH_MAX_LEN];
    char line[128];

    if (set == NULL || !has_nonempty_text(run_dir) ||
        !build_state_child_path_local(run_dir, "name_salvage_whole_records.tsv", path, sizeof(path))) {
        return 0;
    }

    snprintf(set->path, sizeof(set->path), "%s", path);
    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long absolute_offset = 0ULL;

        if (line[0] == '#' || line[0] == '\n' || line[0] == '\r') {
            continue;
        }
        if (sscanf(line, "%llu", &absolute_offset) != 1) {
            continue;
        }
        if (!name_only_whole_record_set_insert(set, (uint64_t)absolute_offset)) {
            fclose(file);
            return 0;
        }
    }

    fclose(file);
    return 1;
}

static size_t count_saved_whole_record_rows_for_run_dir(const char *run_dir)
{
    NameOnlyWholeRecordSet set;
    size_t count = 0U;

    name_only_whole_record_set_init(&set);
    if (name_only_whole_record_set_load(&set, run_dir)) {
        count = set.count;
    }
    name_only_whole_record_set_free(&set);
    return count;
}

static int name_only_whole_record_set_remember(
    NameOnlyWholeRecordSet *set,
    uint64_t absolute_offset
)
{
    FILE *file;

    if (set == NULL) {
        return 0;
    }
    if (name_only_whole_record_set_contains(set, absolute_offset)) {
        return 1;
    }
    if (!name_only_whole_record_set_insert(set, absolute_offset)) {
        return 0;
    }
    if (set->path[0] == '\0') {
        return 1;
    }

    file = fopen(set->path, "a");
    if (file == NULL) {
        return 0;
    }
    fprintf(file, "%llu\n", (unsigned long long)absolute_offset);
    fclose(file);
    return 1;
}

static int name_only_whole_record_can_be_skipped_now(
    const NameOnlyWholeRecordSet *set,
    uint64_t absolute_offset
)
{
    return name_only_whole_record_set_contains(set, absolute_offset) &&
           fs_backend_record_offset_is_naming_ready(absolute_offset);
}

