static void write_tsv_text_field_local(FILE *file, const char *text)
{
    const char *cursor;

    if (file == NULL || text == NULL) {
        return;
    }
    for (cursor = text; *cursor != '\0'; cursor++) {
        char ch = *cursor;
        if (ch == '\t' || ch == '\n' || ch == '\r') {
            ch = ' ';
        }
        fputc(ch, file);
    }
}

static void append_run_work_time_event_for_run_dir(
    const char *run_dir,
    const char *event,
    unsigned long long generation,
    pid_t pid,
    time_t started_at,
    time_t ended_at,
    int counted,
    const char *reason
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    int write_header = 0;
    unsigned long long elapsed_seconds = 0ULL;

    if (!has_nonempty_text(run_dir) ||
        !has_nonempty_text(event) ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_run_work_time_path_for_run_dir(run_dir, path, sizeof(path))) {
        return;
    }

    if (started_at > 0 && ended_at > started_at) {
        elapsed_seconds = (unsigned long long)(ended_at - started_at);
    }

    write_header = stat(path, &st) != 0 || st.st_size == 0;
    file = fopen(path, "a");
    if (file == NULL) {
        return;
    }
    if (write_header) {
        fprintf(
            file,
            "updated_unix\tevent\tgeneration\tpid\tstarted_unix\tended_unix\telapsed_seconds\tcounted\treason\n"
        );
    }
    fprintf(
        file,
        "%llu\t",
        (unsigned long long)time(NULL)
    );
    write_tsv_text_field_local(file, event);
    fprintf(
        file,
        "\t%llu\t%ld\t%llu\t%llu\t%llu\t%d\t",
        generation,
        (long)pid,
        (unsigned long long)started_at,
        (unsigned long long)ended_at,
        elapsed_seconds,
        counted ? 1 : 0
    );
    write_tsv_text_field_local(file, reason != NULL ? reason : "");
    fputc('\n', file);
    fclose(file);
}

static int raw_all_run_had_source_reconnect(
    const char *run_dir
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[1024];
    int found = 0;

    if (!has_nonempty_text(run_dir) ||
        !build_run_work_time_path_for_run_dir(run_dir, path, sizeof(path))) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        if (strstr(line, "\tchild_exit_source_reconnect\t") != NULL ||
            strstr(line, "\tsource_reconnect\n") != NULL ||
            strstr(line, "\tsource_reconnect\r\n") != NULL) {
            found = 1;
            break;
        }
    }

    fclose(file);
    return found;
}

static void append_extraction_zone_event_for_run_dir(
    const char *run_dir,
    const char *event,
    uint64_t zone_start,
    uint64_t zone_end,
    uint64_t anchor_offset,
    uint64_t scan_offset_before,
    uint64_t scan_offset_after,
    uint64_t hits,
    const char *reason
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    int write_header = 0;

    if (!has_nonempty_text(run_dir) ||
        !has_nonempty_text(event) ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_extraction_zone_events_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return;
    }

    write_header = stat(path, &st) != 0 || st.st_size == 0;
    file = fopen(path, "a");
    if (file == NULL) {
        return;
    }
    if (write_header) {
        fprintf(
            file,
            "updated_unix\tevent\tzone_start\tzone_end\tanchor_offset\tscan_offset_before\tscan_offset_after\thits\treason\n"
        );
    }
    fprintf(
        file,
        "%llu\t%s\t%llu\t%llu\t%llu\t%llu\t%llu\t%llu\t%s\n",
        (unsigned long long)time(NULL),
        event,
        (unsigned long long)zone_start,
        (unsigned long long)zone_end,
        (unsigned long long)anchor_offset,
        (unsigned long long)scan_offset_before,
        (unsigned long long)scan_offset_after,
        (unsigned long long)hits,
        reason != NULL ? reason : ""
    );
    fclose(file);
}

