static int raw_all_metadata_followup_required_for_run_dir(
    const char *run_dir
)
{
    char path[PATH_MAX_LEN];
    struct stat st;

    return has_nonempty_text(run_dir) &&
           build_raw_all_metadata_followup_required_path_for_run_dir(
               run_dir,
               path,
               sizeof(path)) &&
           stat(path, &st) == 0 &&
           S_ISREG(st.st_mode);
}

static void raw_all_mark_metadata_followup_required(
    const char *run_dir,
    const char *reason
)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    FILE *file;

    if (!has_nonempty_text(run_dir) ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_raw_all_metadata_followup_required_path_for_run_dir(
            run_dir,
            path,
            sizeof(path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", path) >=
            (int)sizeof(temp_path)) {
        return;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return;
    }

    fprintf(file, "version=1\n");
    fprintf(file, "required=1\n");
    fprintf(file, "reason=%s\n", reason != NULL ? reason : "metadata_observation_skipped");
    fprintf(file, "updated_unix=%llu\n", (unsigned long long)time(NULL));

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return;
    }
    if (rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
    }
}

static void raw_all_clear_metadata_followup_required(
    const char *run_dir
)
{
    char path[PATH_MAX_LEN];

    if (!has_nonempty_text(run_dir) ||
        !build_raw_all_metadata_followup_required_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return;
    }

    if (unlink(path) != 0 && errno != ENOENT) {
        log_info(
            "Could not clear raw-all metadata follow-up marker at %s; later name runs may conservatively reopen the source again",
            path
        );
    }
}

static int raw_all_activity_contains_token(
    const char *activity,
    const char *token
)
{
    size_t activity_len;
    size_t token_len;
    size_t i;

    if (activity == NULL || token == NULL) {
        return 0;
    }

    activity_len = strlen(activity);
    token_len = strlen(token);
    if (token_len == 0U || activity_len < token_len) {
        return 0;
    }

    for (i = 0U; i + token_len <= activity_len; i++) {
        if (strncasecmp(activity + i, token, token_len) == 0) {
            return 1;
        }
    }

    return 0;
}

static int raw_all_stage_activity_is_audio_validation(const char *activity)
{
    if (activity == NULL || strncasecmp(activity, "validating ", 11U) != 0) {
        return 0;
    }

    return raw_all_activity_contains_token(activity, "Audio @") ||
           raw_all_activity_contains_token(activity, "MP3 @") ||
           raw_all_activity_contains_token(activity, "AAC @") ||
           raw_all_activity_contains_token(activity, "FLAC @") ||
           raw_all_activity_contains_token(activity, "WAV @") ||
           raw_all_activity_contains_token(activity, "M4A @") ||
           raw_all_activity_contains_token(activity, "M4B @");
}

static int raw_all_stage_activity_is_video_validation(const char *activity)
{
    if (activity == NULL || strncasecmp(activity, "validating ", 11U) != 0) {
        return 0;
    }

    return raw_all_activity_contains_token(activity, "Video @") ||
           raw_all_activity_contains_token(activity, "Multimedia @") ||
           raw_all_activity_contains_token(activity, "Media @") ||
           raw_all_activity_contains_token(activity, "MOV @") ||
           raw_all_activity_contains_token(activity, "MP4 @") ||
           raw_all_activity_contains_token(activity, "M4V @") ||
           raw_all_activity_contains_token(activity, "MKV @") ||
           raw_all_activity_contains_token(activity, "AVI @") ||
           raw_all_activity_contains_token(activity, "MPEG @") ||
           raw_all_activity_contains_token(activity, "MPEG-PS @") ||
           raw_all_activity_contains_token(activity, "MPG @") ||
           raw_all_activity_contains_token(activity, "WMV @");
}

static unsigned long long raw_all_validation_stall_timeout_cap_seconds(
    const RawAllStageState *stage_state
)
{
    const char *validator_budget;

    if (stage_state == NULL) {
        return 0ULL;
    }

    validator_budget =
        stage_state->validator_budget[0] != '\0'
            ? stage_state->validator_budget
            : stage_state->trouble_budget;

    if (raw_all_stage_activity_is_audio_validation(stage_state->activity)) {
        if (strcmp(validator_budget, "red") == 0) {
            return RAW_ALL_AUDIO_VALIDATION_STALL_TIMEOUT_RED_SECONDS;
        }
        if (strcmp(validator_budget, "yellow") == 0) {
            return RAW_ALL_AUDIO_VALIDATION_STALL_TIMEOUT_YELLOW_SECONDS;
        }
        return RAW_ALL_AUDIO_VALIDATION_STALL_TIMEOUT_GREEN_SECONDS;
    }

    if (raw_all_stage_activity_is_video_validation(stage_state->activity)) {
        if (strcmp(validator_budget, "red") == 0) {
            return RAW_ALL_VIDEO_VALIDATION_STALL_TIMEOUT_RED_SECONDS;
        }
        if (strcmp(validator_budget, "yellow") == 0) {
            return RAW_ALL_VIDEO_VALIDATION_STALL_TIMEOUT_YELLOW_SECONDS;
        }
        return RAW_ALL_VIDEO_VALIDATION_STALL_TIMEOUT_GREEN_SECONDS;
    }

    return 0ULL;
}

static int ensure_raw_all_supervisor_state_dir(const char *run_dir)
{
    char state_dir[PATH_MAX_LEN];

    if (run_dir == NULL || run_dir[0] == '\0') {
        return 0;
    }
    if (snprintf(state_dir, sizeof(state_dir), "%s/%s", run_dir, APP_STATE_DIR_NAME) >=
        (int)sizeof(state_dir)) {
        return 0;
    }
    return ensure_directory_path(state_dir);
}

static int save_raw_all_stage_state_for_run_dir(
    const char *run_dir,
    const RawAllStageState *state
)
{
    char stage_path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    FILE *file;

    if (run_dir == NULL || run_dir[0] == '\0' ||
        state == NULL ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_raw_all_stage_path_for_run_dir(run_dir, stage_path, sizeof(stage_path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", stage_path) >=
            (int)sizeof(temp_path)) {
        return 0;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(file, "version=1\n");
    fprintf(file, "updated_unix=%llu\n", (unsigned long long)state->updated_unix);
    fprintf(file, "stage=%s\n", state->stage);
    fprintf(file, "detail=%s\n", state->detail);
    fprintf(file, "fs_backend=%s\n", state->fs_backend);
    fprintf(file, "fs_backend_name=%s\n", state->fs_backend_name);
    fprintf(file, "fs_backend_kind=%d\n", state->fs_backend_kind);
    fprintf(file, "throughput_profile=%s\n", state->throughput_profile);
    fprintf(file, "throughput_profile_ui=%s\n", state->throughput_profile_ui);
    fprintf(
        file,
        "metadata_context_available=%d\n",
        state->metadata_context_available
    );
    fprintf(
        file,
        "live_metadata_observation_available=%d\n",
        state->live_metadata_observation_available
    );
    fprintf(file, "budget_base_bytes=%llu\n", (unsigned long long)state->budget_base_bytes);
    fprintf(file, "budget_penalty_bytes=%llu\n",
            (unsigned long long)state->budget_penalty_bytes);
    fprintf(file, "progress_bytes=%llu\n", (unsigned long long)state->progress_bytes);
    fprintf(file, "total_bytes=%llu\n", (unsigned long long)state->total_bytes);
    fprintf(file, "source_size_bytes=%llu\n",
            (unsigned long long)state->source_size_bytes);
    fprintf(file, "selected_scope_start_bytes=%llu\n",
            (unsigned long long)state->selected_scope_start_bytes);
    fprintf(file, "selected_scope_end_bytes=%llu\n",
            (unsigned long long)state->selected_scope_end_bytes);
    fprintf(file, "selected_scope_progress_bytes=%llu\n",
            (unsigned long long)state->selected_scope_progress_bytes);
    fprintf(file, "selected_scope_complete=%d\n", state->selected_scope_complete);
    fprintf(file, "full_source_complete=%d\n", state->full_source_complete);
    fprintf(file, "recent_mib_per_sec=%.3f\n", state->recent_mib_per_sec);
    fprintf(file, "target_mib_per_sec=%.3f\n", state->target_mib_per_sec);
    fprintf(file, "eta_seconds=%llu\n", state->eta_seconds);
    fprintf(file, "elapsed_seconds=%llu\n", state->elapsed_seconds);
    fprintf(file, "budget_elapsed_seconds=%llu\n", state->budget_elapsed_seconds);
    fprintf(file, "stalled_seconds=%llu\n", state->stalled_seconds);
    fprintf(file, "nominal_total_seconds=%llu\n", state->nominal_total_seconds);
    fprintf(file, "nominal_remaining_seconds=%llu\n", state->nominal_remaining_seconds);
    fprintf(file, "budget_eta_seconds=%llu\n", state->budget_eta_seconds);
    fprintf(file, "schedule_delta_seconds=%lld\n", state->schedule_delta_seconds);
    fprintf(file, "eta_phase=%d\n", state->eta_phase);
    fprintf(file, "load_eta_done=%d\n", state->load_eta_done);
    fprintf(file, "trouble_budget=%s\n", state->trouble_budget);
    fprintf(file, "validator_budget=%s\n", state->validator_budget);
    fprintf(file, "recovered_files=%llu\n", (unsigned long long)state->recovered_files);
    fprintf(file, "named_files=%llu\n", (unsigned long long)state->named_files);
    fprintf(file, "files_outside_unident=%llu\n", (unsigned long long)state->named_files);
    fprintf(file, "activity=%s\n", state->activity);
    fprintf(file, "background_activity=%s\n", state->background_activity);

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, stage_path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int write_raw_all_stage_file_with_metrics(
    const char *run_dir,
    const char *stage,
    const char *detail,
    const LogWorkingSnapshot *snapshot,
    double stage_started_at
)
{
    char stage_path[PATH_MAX_LEN];
    double now_seconds = 0.0;
    RawAllStageState previous_state = {0};
    RawAllStageState next_state = {0};
    int current_backend_kind = FS_BACKEND_KIND_NONE;

    if (run_dir == NULL || run_dir[0] == '\0' ||
        stage == NULL || stage[0] == '\0' ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_raw_all_stage_path_for_run_dir(run_dir, stage_path, sizeof(stage_path))) {
        return 0;
    }

    (void)load_raw_all_stage_state(stage_path, &previous_state);
    next_state = previous_state;

    if (snapshot == NULL) {
        if (strcmp(stage, "startup") == 0) {
            /* A supervised post-scan restart needs a fresh phase label, not
             * amnesia.  Retaining proven byte completion lets the child and
             * GUI distinguish resume/finalize work from another disk scan. */
            if (!raw_all_stage_indicates_scan_completed(&previous_state)) {
                next_state.progress_bytes = 0ULL;
                next_state.total_bytes = 0ULL;
                next_state.selected_scope_start_bytes = 0ULL;
                next_state.selected_scope_end_bytes = 0ULL;
                next_state.selected_scope_progress_bytes = 0ULL;
                next_state.selected_scope_complete = 0;
                next_state.full_source_complete = 0;
            }
            next_state.eta_seconds = 0ULL;
            next_state.nominal_remaining_seconds = 0ULL;
            next_state.budget_eta_seconds = 0ULL;
            next_state.stalled_seconds = 0ULL;
        }
        if (next_state.target_mib_per_sec <= 0.0) {
            next_state.target_mib_per_sec = log_get_target_throughput_mib_per_sec();
        }
    } else {
        next_state.budget_base_bytes = snapshot->budget_base_bytes;
        next_state.budget_penalty_bytes = snapshot->budget_penalty_bytes;
        next_state.progress_bytes = snapshot->processed_bytes;
        next_state.total_bytes = snapshot->total_bytes;
        next_state.recent_mib_per_sec = snapshot->recent_mib_per_sec;
        next_state.target_mib_per_sec = snapshot->target_mib_per_sec;
        next_state.budget_elapsed_seconds = (unsigned long long)(
            snapshot->budget_elapsed_seconds > 0.0
                ? (snapshot->budget_elapsed_seconds + 0.5)
                : 0.0
        );
        if (next_state.budget_elapsed_seconds < previous_state.budget_elapsed_seconds) {
            next_state.budget_elapsed_seconds = previous_state.budget_elapsed_seconds;
        }
        next_state.stalled_seconds = snapshot->stalled_seconds;
        next_state.eta_phase = snapshot->eta_phase;
        next_state.load_eta_done = snapshot->load_eta_done;
        next_state.nominal_total_seconds = snapshot->nominal_total_seconds;
        next_state.nominal_remaining_seconds = snapshot->nominal_remaining_seconds;
        next_state.budget_eta_seconds = snapshot->budget_eta_seconds;
        next_state.schedule_delta_seconds = snapshot->schedule_delta_seconds;
        snprintf(
            next_state.trouble_budget,
            sizeof(next_state.trouble_budget),
            "%s",
            log_trouble_budget_state_label(
            (LogTroubleBudgetState)snapshot->trouble_budget_state
            )
        );
        snprintf(
            next_state.validator_budget,
            sizeof(next_state.validator_budget),
            "%s",
            log_trouble_budget_state_label(
            (LogTroubleBudgetState)snapshot->validator_budget_state
            )
        );
        next_state.recovered_files = snapshot->recovered_files;
        next_state.named_files = snapshot->named_files;
        snprintf(next_state.activity, sizeof(next_state.activity), "%s",
                 snapshot->activity);
        snprintf(
            next_state.background_activity,
            sizeof(next_state.background_activity),
            "%s",
            snapshot->background_activity
        );
        next_state.eta_seconds = snapshot->eta_seconds;
        if (previous_state.updated_unix > 0 &&
            previous_state.progress_bytes == next_state.progress_bytes &&
            time(NULL) > previous_state.updated_unix &&
            (time(NULL) - previous_state.updated_unix) >= 5) {
            next_state.recent_mib_per_sec = 0.0;
        }
    }

    current_backend_kind = (int)fs_backend_current_kind();
    if (current_backend_kind != FS_BACKEND_KIND_NONE &&
        (getenv(CRASH_RETRY_CHILD_ENV) != NULL ||
         fs_backend_has_metadata_context_for_raw_scan() ||
         !raw_all_stage_state_has_backend_identity(&next_state) ||
         next_state.fs_backend_kind == current_backend_kind)) {
        raw_all_stage_set_backend_identity(
            &next_state,
            current_backend_kind,
            fs_backend_current_id(),
            fs_backend_current_name(),
            fs_backend_has_metadata_context_for_raw_scan() ? 1 : 0,
            fs_backend_supports_live_metadata_observation() ? 1 : 0
        );
    } else {
        raw_all_stage_restore_saved_backend_identity(run_dir, &next_state);
    }
    snprintf(
        next_state.throughput_profile,
        sizeof(next_state.throughput_profile),
        "%s",
        log_target_throughput_profile_label(next_state.target_mib_per_sec)
    );
    snprintf(
        next_state.throughput_profile_ui,
        sizeof(next_state.throughput_profile_ui),
        "%s",
        log_target_throughput_profile_ui_label(next_state.target_mib_per_sec)
    );

    now_seconds = monotonic_seconds_local();
    if (stage_started_at > 0.0 && now_seconds >= stage_started_at) {
        next_state.elapsed_seconds =
            (unsigned long long)(now_seconds - stage_started_at);
    }
    if (next_state.target_mib_per_sec <= 0.0) {
        next_state.target_mib_per_sec = log_get_target_throughput_mib_per_sec();
    }
    if (next_state.trouble_budget[0] == '\0') {
        snprintf(next_state.trouble_budget, sizeof(next_state.trouble_budget), "unknown");
    }
    if (next_state.validator_budget[0] == '\0') {
        snprintf(next_state.validator_budget, sizeof(next_state.validator_budget), "unknown");
    }
    next_state.updated_unix = time(NULL);
    if (app_best_effort_recovered_count_for_run(run_dir) > next_state.recovered_files) {
        next_state.recovered_files =
            app_best_effort_recovered_count_for_run(run_dir);
    }
    if (app_best_effort_named_count_for_run(run_dir) > next_state.named_files) {
        next_state.named_files = app_best_effort_named_count_for_run(run_dir);
    }
    snprintf(next_state.stage, sizeof(next_state.stage), "%s", stage);
    snprintf(next_state.detail, sizeof(next_state.detail), "%s",
             detail != NULL ? detail : "");
    return save_raw_all_stage_state_for_run_dir(run_dir, &next_state);
}

static void accumulate_raw_all_stage_budget_elapsed_for_supervisor(
    const char *run_dir,
    time_t child_started_at,
    int include_active_elapsed,
    unsigned long long explicit_extra_seconds
)
{
    char stage_path[PATH_MAX_LEN];
    RawAllStageState stage_state = {0};
    time_t now = time(NULL);
    time_t accounted_from = 0;
    unsigned long long new_budget_elapsed_seconds;
    LogTroubleBudgetState trouble_state = LOG_TROUBLE_BUDGET_UNKNOWN;
    LogTroubleBudgetState validator_state = LOG_TROUBLE_BUDGET_UNKNOWN;

    if (run_dir == NULL || run_dir[0] == '\0' ||
        !build_raw_all_stage_path_for_run_dir(run_dir, stage_path, sizeof(stage_path)) ||
        !load_raw_all_stage_state(stage_path, &stage_state)) {
        return;
    }

    new_budget_elapsed_seconds = stage_state.budget_elapsed_seconds;
    if (include_active_elapsed) {
        if (stage_state.updated_unix > 0) {
            accounted_from = stage_state.updated_unix;
        }
        if (child_started_at > accounted_from) {
            accounted_from = child_started_at;
        }
        if (accounted_from > 0 && now > accounted_from) {
            new_budget_elapsed_seconds +=
                (unsigned long long)(now - accounted_from);
        }
    }
    if (ULLONG_MAX - new_budget_elapsed_seconds < explicit_extra_seconds) {
        new_budget_elapsed_seconds = ULLONG_MAX;
    } else {
        new_budget_elapsed_seconds += explicit_extra_seconds;
    }
    if (new_budget_elapsed_seconds < stage_state.budget_elapsed_seconds) {
        new_budget_elapsed_seconds = stage_state.budget_elapsed_seconds;
    }

    stage_state.updated_unix = now;
    stage_state.budget_elapsed_seconds = new_budget_elapsed_seconds;
    if (stage_state.total_bytes > 0ULL) {
        log_calculate_budget_metrics_for_values(
            stage_state.progress_bytes,
            stage_state.total_bytes,
            stage_state.budget_base_bytes,
            stage_state.budget_penalty_bytes,
            (double)stage_state.budget_elapsed_seconds,
            stage_state.recent_mib_per_sec,
            &stage_state.nominal_total_seconds,
            &stage_state.nominal_remaining_seconds,
            &stage_state.budget_eta_seconds,
            &stage_state.schedule_delta_seconds,
            &trouble_state,
            &validator_state
        );
        snprintf(
            stage_state.trouble_budget,
            sizeof(stage_state.trouble_budget),
            "%s",
            log_trouble_budget_state_label(trouble_state)
        );
        snprintf(
            stage_state.validator_budget,
            sizeof(stage_state.validator_budget),
            "%s",
            log_trouble_budget_state_label(validator_state)
        );
        if (stage_state.eta_phase == 1 &&
            stage_state.progress_bytes < stage_state.total_bytes) {
            stage_state.eta_seconds = stage_state.budget_eta_seconds;
        } else {
            stage_state.eta_seconds = 0ULL;
        }
    }

    (void)save_raw_all_stage_state_for_run_dir(run_dir, &stage_state);
}

static void *raw_all_startup_metrics_writer_main(void *arg)
{
    RawAllStartupMetricsWriter *writer = (RawAllStartupMetricsWriter *)arg;
    time_t last_deferred_plan_update = 0;

    if (writer == NULL) {
        return NULL;
    }

    for (;;) {
        LogWorkingSnapshot snapshot = {0};
        char run_dir[PATH_MAX_LEN];
        char stage[64];
        char detail[160];
        double stage_started_at = 0.0;
        uint64_t deferred_budget_penalty_bytes = 0ULL;
        int stop_requested = 0;

        pthread_mutex_lock(&writer->mutex);
        stop_requested = writer->stop_requested;
        snprintf(run_dir, sizeof(run_dir), "%s", writer->run_dir);
        snprintf(stage, sizeof(stage), "%s", writer->stage);
        snprintf(detail, sizeof(detail), "%s", writer->detail);
        stage_started_at = writer->stage_started_at;
        pthread_mutex_unlock(&writer->mutex);

        if (stop_requested) {
            break;
        }

        {
            char suggested_run_dir[PATH_MAX_LEN];

            if (output_mount_guard_poll_should_stop(
                    run_dir,
                    suggested_run_dir,
                    sizeof(suggested_run_dir))) {
                if (!g_output_mount_guard_triggered) {
                    g_output_mount_guard_triggered = 1;
                    write_output_loss_emergency_breadcrumb(
                        run_dir,
                        suggested_run_dir,
                        "raw_all",
                        stage,
                        detail
                    );
                    fs_backend_set_state_writes_suppressed(1);
                    if (has_nonempty_text(suggested_run_dir)) {
                        log_error(
                            "Output volume moved during the run: %s is no longer on a live mounted output disk. Stopping now so you can resume from %s instead of spilling output onto the system disk.",
                            run_dir,
                            suggested_run_dir
                        );
                    } else {
                        log_error(
                            "Output volume disappeared during the run: %s is no longer on a live mounted output disk. Stopping now so output does not spill onto the system disk.",
                            run_dir
                        );
                    }
                } else {
                    fs_backend_set_state_writes_suppressed(1);
                }
                g_stop_requested = 1;
                usleep(500000);
                continue;
            }
        }

        deferred_budget_penalty_bytes =
            sum_deferred_bad_zone_bytes_for_run_dir(run_dir);
        log_set_working_budget_penalty(deferred_budget_penalty_bytes);
        (void)log_get_working_snapshot(&snapshot);
        (void)write_raw_all_stage_file_with_metrics(
            run_dir,
            stage,
            detail,
            &snapshot,
            stage_started_at
        );
        if (time(NULL) - last_deferred_plan_update >= 5) {
            (void)write_deferred_plan_for_run_dir(run_dir);
            last_deferred_plan_update = time(NULL);
        }
        usleep(500000);
    }

    return NULL;
}

static void raw_all_startup_metrics_writer_init(
    RawAllStartupMetricsWriter *writer,
    const char *run_dir
)
{
    if (writer == NULL) {
        return;
    }

    memset(writer, 0, sizeof(*writer));
    if (!has_nonempty_text(run_dir)) {
        return;
    }

    pthread_mutex_init(&writer->mutex, NULL);
    snprintf(writer->run_dir, sizeof(writer->run_dir), "%s", run_dir);
    writer->enabled = 1;
}

static void raw_all_startup_metrics_writer_set_stage(
    RawAllStartupMetricsWriter *writer,
    const char *stage,
    const char *detail,
    double stage_started_at
)
{
    if (writer == NULL || !writer->enabled) {
        return;
    }

    pthread_mutex_lock(&writer->mutex);
    snprintf(writer->stage, sizeof(writer->stage), "%s", stage != NULL ? stage : "");
    snprintf(writer->detail, sizeof(writer->detail), "%s", detail != NULL ? detail : "");
    writer->stage_started_at = stage_started_at;
    pthread_mutex_unlock(&writer->mutex);

    if (stage != NULL && stage[0] != '\0') {
        LogWorkingSnapshot snapshot = {0};

        (void)log_get_working_snapshot(&snapshot);
        (void)write_raw_all_stage_file_with_metrics(
            writer->run_dir,
            stage,
            detail,
            &snapshot,
            stage_started_at
        );
        (void)write_deferred_plan_for_run_dir(writer->run_dir);
    }

    if (!writer->enabled || writer->thread_started) {
        return;
    }
    if (pthread_create(&writer->thread, NULL, raw_all_startup_metrics_writer_main, writer) != 0) {
        pthread_mutex_destroy(&writer->mutex);
        writer->enabled = 0;
    } else {
        writer->thread_started = 1;
    }
}

static void raw_all_startup_metrics_writer_stop(RawAllStartupMetricsWriter *writer)
{
    if (writer == NULL || !writer->enabled) {
        return;
    }

    pthread_mutex_lock(&writer->mutex);
    writer->stop_requested = 1;
    pthread_mutex_unlock(&writer->mutex);
    if (writer->thread_started) {
        pthread_join(writer->thread, NULL);
    }
    pthread_mutex_destroy(&writer->mutex);
    writer->enabled = 0;
    writer->thread_started = 0;
}

static int build_supervisor_generation_path_for_run_dir(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    if (run_dir == NULL || out == NULL || out_size == 0U) {
        return 0;
    }

    return snprintf(
               out,
               out_size,
               "%s/" APP_STATE_DIR_NAME "/raw_all_supervisor_generation.txt",
               run_dir
           ) < (int)out_size;
}

static int build_name_supervisor_generation_path_for_run_dir(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    if (run_dir == NULL || out == NULL || out_size == 0U) {
        return 0;
    }

    return snprintf(
               out,
               out_size,
               "%s/" APP_STATE_DIR_NAME "/name_supervisor_generation.txt",
               run_dir
           ) < (int)out_size;
}

static int build_run_output_dir_for_supervisor(
    const AppConfig *config,
    char *out,
    size_t out_size
)
{
    size_t len;
    const char *base;

    if (config == NULL ||
        out == NULL ||
        out_size == 0 ||
        !has_nonempty_text(config->output_dir)) {
        return 0;
    }

    if (!has_nonempty_text(config->run_name)) {
        return snprintf(out, out_size, "%s", config->output_dir) < (int)out_size;
    }

    if (strlen(config->output_dir) < out_size) {
        snprintf(out, out_size, "%s", config->output_dir);
        len = strlen(out);
        while (len > 1U && out[len - 1U] == '/') {
            out[--len] = '\0';
        }
        base = strrchr(out, '/');
        base = base != NULL ? base + 1 : out;
        if (strcmp(base, config->run_name) == 0) {
            return 1;
        }
    }

    return snprintf(
               out,
               out_size,
               "%s/%s",
               config->output_dir,
               config->run_name) < (int)out_size;
}

static unsigned long long emergency_runtime_path_hash_local(const char *text)
{
    unsigned long long hash = 1469598103934665603ULL;
    const unsigned char *cursor = (const unsigned char *)text;

    if (cursor == NULL) {
        return hash;
    }
    while (*cursor != '\0') {
        hash ^= (unsigned long long)(*cursor++);
        hash *= 1099511628211ULL;
    }
    return hash;
}

static int copy_file_local(const char *src_path, const char *dst_path)
{
    FILE *src;
    FILE *dst;
    char buffer[8192];
    size_t n;
    char temp_path[PATH_MAX_LEN + 32];

    if (!has_nonempty_text(src_path) ||
        !has_nonempty_text(dst_path) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", dst_path) >=
            (int)sizeof(temp_path)) {
        return 0;
    }

    src = fopen(src_path, "r");
    if (src == NULL) {
        return 0;
    }
    dst = fopen(temp_path, "w");
    if (dst == NULL) {
        fclose(src);
        return 0;
    }

    while ((n = fread(buffer, 1U, sizeof(buffer), src)) > 0U) {
        if (fwrite(buffer, 1U, n, dst) != n) {
            fclose(src);
            fclose(dst);
            (void)unlink(temp_path);
            return 0;
        }
    }
    if (ferror(src)) {
        fclose(src);
        fclose(dst);
        (void)unlink(temp_path);
        return 0;
    }
    fclose(src);
    if (fclose(dst) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, dst_path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int tsv_second_field_equals_local(const char *line, const char *value)
{
    const char *field;
    const char *end;
    size_t len;

    if (!has_nonempty_text(line) || !has_nonempty_text(value)) {
        return 0;
    }
    field = strchr(line, '\t');
    if (field == NULL) {
        return 0;
    }
    field++;
    end = strchr(field, '\t');
    if (end == NULL) {
        return 0;
    }
    len = (size_t)(end - field);
    return strlen(value) == len && strncmp(field, value, len) == 0;
}

static int copy_emergency_events_for_run_local(
    const char *src_path,
    const char *dst_path,
    const char *run_leaf
)
{
    FILE *src;
    FILE *dst;
    char line[8192];
    char temp_path[PATH_MAX_LEN + 32];
    int header_written = 0;
    int rows_written = 0;

    if (!has_nonempty_text(src_path) ||
        !has_nonempty_text(dst_path) ||
        !has_nonempty_text(run_leaf) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", dst_path) >=
            (int)sizeof(temp_path)) {
        return 0;
    }

    src = fopen(src_path, "r");
    if (src == NULL) {
        return 0;
    }
    dst = fopen(temp_path, "w");
    if (dst == NULL) {
        fclose(src);
        return 0;
    }

    while (fgets(line, sizeof(line), src) != NULL) {
        if (!header_written && strncmp(line, "updated_unix\t", 13U) == 0) {
            fputs(line, dst);
            header_written = 1;
            continue;
        }
        if (tsv_second_field_equals_local(line, run_leaf)) {
            if (!header_written) {
                fputs(
                    "updated_unix\trun\tpid\tgeneration\tcontext\trun_dir\tsuggested_run_dir\tstage\tdetail\tprocessed_bytes\ttotal_bytes\trecovered\tnamed\tunident\tactivity\n",
                    dst
                );
                header_written = 1;
            }
            fputs(line, dst);
            rows_written++;
        }
    }
    if (ferror(src) || rows_written == 0) {
        fclose(src);
        fclose(dst);
        (void)unlink(temp_path);
        return 0;
    }
    fclose(src);
    if (fclose(dst) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, dst_path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int path_has_segment_local(const char *path, const char *segment)
{
    const char *cursor;
    size_t len;

    if (!has_nonempty_text(path) || !has_nonempty_text(segment)) {
        return 0;
    }
    len = strlen(segment);
    cursor = path;
    while ((cursor = strstr(cursor, segment)) != NULL) {
        int left_ok = cursor == path || cursor[-1] == '/';
        int right_ok = cursor[len] == '\0' || cursor[len] == '/';
        if (left_ok && right_ok) {
            return 1;
        }
        cursor++;
    }
    return 0;
}

static int emergency_runtime_log_matches_run_local(
    const char *src_path,
    const char *run_leaf
)
{
    FILE *src;
    char line[4096];
    int lines_read = 0;
    const char *prefix = "# original_path=";
    size_t prefix_len = strlen(prefix);

    src = fopen(src_path, "r");
    if (src == NULL) {
        return 0;
    }
    while (lines_read++ < 8 && fgets(line, sizeof(line), src) != NULL) {
        size_t len;
        if (strncmp(line, prefix, prefix_len) != 0) {
            continue;
        }
        len = strlen(line);
        while (len > 0U && (line[len - 1U] == '\n' || line[len - 1U] == '\r')) {
            line[--len] = '\0';
        }
        fclose(src);
        return path_has_segment_local(line + prefix_len, run_leaf);
    }
    fclose(src);
    return 0;
}

static int append_file_contents_local(FILE *dst, const char *src_path)
{
    FILE *src;
    char buffer[8192];
    size_t n;

    if (dst == NULL || !has_nonempty_text(src_path)) {
        return 0;
    }
    src = fopen(src_path, "r");
    if (src == NULL) {
        return 0;
    }
    while ((n = fread(buffer, 1U, sizeof(buffer), src)) > 0U) {
        if (fwrite(buffer, 1U, n, dst) != n) {
            fclose(src);
            return 0;
        }
    }
    if (ferror(src)) {
        fclose(src);
        return 0;
    }
    fclose(src);
    return 1;
}

static int import_emergency_runtime_logs_for_run_local(
    const char *dst_path,
    const char *run_leaf
)
{
    DIR *dir;
    struct dirent *entry;
    FILE *dst;
    char src_path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    int imported = 0;

    if (!has_nonempty_text(dst_path) ||
        !has_nonempty_text(run_leaf) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", dst_path) >=
            (int)sizeof(temp_path)) {
        return 0;
    }

    dir = opendir("/tmp/carv_emergency_logs");
    if (dir == NULL) {
        return 0;
    }
    dst = fopen(temp_path, "w");
    if (dst == NULL) {
        closedir(dir);
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "runtime_", 8U) != 0 ||
            strstr(entry->d_name, ".log") == NULL ||
            snprintf(
                src_path,
                sizeof(src_path),
                "/tmp/carv_emergency_logs/%s",
                entry->d_name) >= (int)sizeof(src_path) ||
            !emergency_runtime_log_matches_run_local(src_path, run_leaf)) {
            continue;
        }
        fprintf(dst, "# imported_from=%s\n", src_path);
        if (append_file_contents_local(dst, src_path)) {
            imported++;
            fputc('\n', dst);
        }
    }

    closedir(dir);
    if (fclose(dst) != 0 || imported == 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, dst_path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return imported;
}

static void import_emergency_temp_artifacts_for_run(
    const char *run_dir,
    const char *runtime_events_path
)
{
    char state_path[PATH_MAX_LEN];
    char run_leaf[NAME_MAX + 1];
    char src_path[PATH_MAX_LEN];
    char dst_path[PATH_MAX_LEN];
    unsigned long long hash;
    int imported = 0;
    int runtime_imported;

    if (!has_nonempty_text(run_dir) ||
        !ensure_raw_all_supervisor_state_dir(run_dir)) {
        return;
    }

    sanitize_emergency_filename_component(
        path_leaf_for_emergency_breadcrumb(run_dir),
        run_leaf,
        sizeof(run_leaf)
    );

    if (snprintf(state_path, sizeof(state_path), "%s/%s", run_dir, APP_STATE_DIR_NAME) >=
        (int)sizeof(state_path)) {
        return;
    }

    if (snprintf(
            src_path,
            sizeof(src_path),
            "/tmp/carv_output_loss/%s-latest.txt",
            run_leaf) < (int)sizeof(src_path) &&
        snprintf(
            dst_path,
            sizeof(dst_path),
            "%s/output_loss_breadcrumb_latest.txt",
            state_path) < (int)sizeof(dst_path) &&
        copy_file_local(src_path, dst_path)) {
        imported++;
        (void)unlink(src_path);
    }

    if (snprintf(
            src_path,
            sizeof(src_path),
            "/tmp/carv_output_loss/events.tsv") < (int)sizeof(src_path) &&
        snprintf(
            dst_path,
            sizeof(dst_path),
            "%s/output_loss_events_recovered.tsv",
            state_path) < (int)sizeof(dst_path) &&
        copy_emergency_events_for_run_local(src_path, dst_path, run_leaf)) {
        imported++;
    }

    if (build_raw_all_finalize_checkpoint_temp_path_for_run_dir(
            run_dir,
            src_path,
            sizeof(src_path)) &&
        build_state_child_path_local(
            run_dir,
            "finalize_checkpoint_recovered.txt",
            dst_path,
            sizeof(dst_path))) {
        if (emergency_temp_file_is_older_than_reference_path(src_path, run_dir)) {
            (void)unlink(src_path);
        } else if (copy_file_local(src_path, dst_path)) {
            imported++;
            (void)unlink(src_path);
        }
    }

    if (has_nonempty_text(runtime_events_path)) {
        hash = emergency_runtime_path_hash_local(runtime_events_path);
        if (snprintf(
                src_path,
                sizeof(src_path),
                "/tmp/carv_emergency_logs/runtime_%016llx.log",
                hash) < (int)sizeof(src_path) &&
            snprintf(
                dst_path,
                sizeof(dst_path),
                "%s/runtime_events.emergency_recovered.log",
                state_path) < (int)sizeof(dst_path)) {
            runtime_imported = import_emergency_runtime_logs_for_run_local(dst_path, run_leaf);
            if (runtime_imported > 0) {
                imported += runtime_imported;
            } else if (copy_file_local(src_path, dst_path)) {
                imported++;
            }
        }
    }

    if (imported > 0) {
        log_runtime_event_info(
            "Imported %d emergency temp artifact%s from /tmp after the output volume became writable again",
            imported,
            imported == 1 ? "" : "s"
        );
    }
}

static void app_configure_runtime_event_logging(const AppConfig *config)
{
    char run_dir[PATH_MAX_LEN];
    char events_path[PATH_MAX_LEN];

    log_set_runtime_event_path(NULL);
    if (config == NULL ||
        !build_run_output_dir_for_supervisor(config, run_dir, sizeof(run_dir)) ||
        !build_runtime_events_path_for_run_dir(run_dir, events_path, sizeof(events_path))) {
        return;
    }

    log_set_runtime_event_path(events_path);
    import_emergency_temp_artifacts_for_run(run_dir, events_path);
}

static int signal_is_retryable_crash(int signum)
{
    return signum == SIGSEGV ||
           signum == SIGBUS ||
           signum == SIGABRT ||
           signum == SIGILL;
}

static int build_named_live_stats_path_for_supervisor(
    const char *run_dir,
    const char *file_name,
    char *out,
    size_t out_size
)
{
    if (run_dir == NULL || run_dir[0] == '\0' ||
        file_name == NULL || file_name[0] == '\0' ||
        out == NULL || out_size == 0U) {
        return 0;
    }

    return snprintf(
               out,
               out_size,
               "%s/%s/%s",
               run_dir,
               APP_STATE_DIR_NAME,
               file_name
           ) < (int)out_size;
}

static int build_metadata_live_stats_path_for_supervisor(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    return build_named_live_stats_path_for_supervisor(
        run_dir,
        "metadata_live_stats.txt",
        out,
        out_size
    );
}

static int build_legacy_spool_live_stats_path_for_supervisor(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    return build_named_live_stats_path_for_supervisor(
        run_dir,
        "spool_live_stats.txt",
        out,
        out_size
    );
}

static int resolve_metadata_live_stats_path_for_supervisor(
    const char *run_dir,
    char *out,
    size_t out_size
)
{
    char metadata_path[PATH_MAX_LEN];
    char legacy_path[PATH_MAX_LEN];

    if (run_dir == NULL || run_dir[0] == '\0' ||
        out == NULL || out_size == 0U) {
        return 0;
    }

    if (build_metadata_live_stats_path_for_supervisor(
            run_dir,
            metadata_path,
            sizeof(metadata_path)) &&
        access(metadata_path, F_OK) == 0) {
        return snprintf(out, out_size, "%s", metadata_path) < (int)out_size;
    }

    if (build_legacy_spool_live_stats_path_for_supervisor(
            run_dir,
            legacy_path,
            sizeof(legacy_path)) &&
        access(legacy_path, F_OK) == 0) {
        return snprintf(out, out_size, "%s", legacy_path) < (int)out_size;
    }

    return build_metadata_live_stats_path_for_supervisor(run_dir, out, out_size);
}

static int load_live_stats_file_for_supervisor(
    const char *path,
    FsBackendLiveStats *out_stats
)
{
    FILE *file;
    char line[256];
    FsBackendLiveStats stats = {0};

    if (path == NULL || path[0] == '\0' || out_stats == NULL) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long value = 0ULL;
        char *end_ptr = NULL;

        if (strncmp(line, "scan_stalled_seconds=", 21U) == 0) {
            value = strtoull(line + 21U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.scan_stalled_seconds = value;
            }
        } else if (strncmp(line, "renamed_outputs=", 16U) == 0 ||
                   strncmp(line, "rename_operations=", 18U) == 0) {
            const char *value_text =
                line + (line[6] == '_' ? 18U : 16U);
            value = strtoull(value_text, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.renamed_outputs = value;
            }
        } else if (strncmp(line, "repaired_outputs=", 17U) == 0) {
            value = strtoull(line + 17U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.repaired_outputs = value;
            }
        } else if (strncmp(line, "recovered_outputs_current=", 26U) == 0) {
            value = strtoull(line + 26U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.recovered_outputs_current = value;
            }
        } else if (strncmp(line, "named_outputs_current=", 22U) == 0 ||
                   strncmp(line, "files_outside_unident=", 22U) == 0) {
            value = strtoull(line + 22U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.named_outputs_current = value;
            }
        } else if (strncmp(line, "unident_outputs_current=", 24U) == 0 ||
                   strncmp(line, "files_still_in_unident=", 23U) == 0) {
            const char *value_text =
                line + (line[0] == 'u' ? 24U : 23U);
            value = strtoull(value_text, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.unident_outputs_current = value;
            }
        } else if (strncmp(line, "repair_pending_outputs=", 23U) == 0 ||
                   strncmp(line, "repair_pending_files=", 21U) == 0) {
            const char *value_text =
                line + (line[15] == 'o' ? 23U : 21U);
            value = strtoull(value_text, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.repair_pending_outputs = value;
            }
        } else if (strncmp(line, "repair_queue_events=", 20U) == 0) {
            value = strtoull(line + 20U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.repair_queue_events = value;
            }
        } else if (strncmp(line, "record_index_count=", 19U) == 0) {
            value = strtoull(line + 19U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.record_index_count = (size_t)value;
            }
        } else if (strncmp(line, "range_index_count=", 18U) == 0) {
            value = strtoull(line + 18U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.range_index_count = (size_t)value;
            }
        } else if (strncmp(line, "background_phase=", 17U) == 0) {
            value = strtoull(line + 17U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.background_phase = (unsigned int)value;
            }
        } else if (strncmp(line, "background_conservative=", 24U) == 0) {
            value = strtoull(line + 24U, &end_ptr, 10);
            if (end_ptr != NULL) {
                stats.background_conservative = (unsigned int)value;
            }
        }
    }

    fclose(file);
    *out_stats = stats;
    return 1;
}

static int load_metadata_live_stats_for_supervisor(
    const char *run_dir,
    FsBackendLiveStats *out_stats
)
{
    char path[PATH_MAX_LEN];

    if (run_dir == NULL || run_dir[0] == '\0' || out_stats == NULL) {
        return 0;
    }

    if (!resolve_metadata_live_stats_path_for_supervisor(
            run_dir,
            path,
            sizeof(path))) {
        return 0;
    }

    return load_live_stats_file_for_supervisor(path, out_stats);
}

static int reset_live_stats_file_for_supervisor(
    const char *path
)
{
    char temp_path[PATH_MAX_LEN + 40];
    FILE *file;

    if (path == NULL ||
        path[0] == '\0' ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", path) >= (int)sizeof(temp_path)) {
        return 0;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(file, "version=1\n");
    fprintf(file, "renamed_outputs=0\n");
    fprintf(file, "rename_operations=0\n");
    fprintf(file, "repaired_outputs=0\n");
    fprintf(file, "recovered_outputs_current=0\n");
    fprintf(file, "named_outputs_current=0\n");
    fprintf(file, "files_outside_unident=0\n");
    fprintf(file, "unident_outputs_current=0\n");
    fprintf(file, "files_still_in_unident=0\n");
    fprintf(file, "repair_pending_outputs=0\n");
    fprintf(file, "repair_pending_files=0\n");
    fprintf(file, "repair_queue_events=0\n");
    fprintf(file, "record_index_count=0\n");
    fprintf(file, "range_index_count=0\n");
    fprintf(file, "scan_stalled_seconds=0\n");
    fprintf(file, "background_phase=0\n");

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int reset_metadata_live_stats_for_supervisor(
    const char *run_dir
)
{
    char metadata_path[PATH_MAX_LEN];
    char legacy_path[PATH_MAX_LEN];
    int reset_any = 0;

    if (run_dir == NULL || run_dir[0] == '\0') {
        return 0;
    }

    if (build_metadata_live_stats_path_for_supervisor(
            run_dir,
            metadata_path,
            sizeof(metadata_path)) &&
        reset_live_stats_file_for_supervisor(metadata_path)) {
        reset_any = 1;
    }
    if (build_legacy_spool_live_stats_path_for_supervisor(
            run_dir,
            legacy_path,
            sizeof(legacy_path)) &&
        reset_live_stats_file_for_supervisor(legacy_path)) {
        reset_any = 1;
    }

    return reset_any;
}

static int reset_thread_activity_for_supervisor(
    const char *run_dir
)
{
    char path[PATH_MAX_LEN];

    if (run_dir == NULL ||
        run_dir[0] == '\0' ||
        !build_thread_activity_path_for_run_dir(run_dir, path, sizeof(path))) {
        return 0;
    }

    if (unlink(path) != 0 && errno != ENOENT) {
        return 0;
    }

    return 1;
}

