static void load_raw_all_budget_resume_state(
    const AppConfig *config,
    uint64_t *io_budget_base_bytes,
    double *io_budget_elapsed_bias_seconds,
    RawAllStageState *out_previous_stage
)
{
    char stage_path[PATH_MAX_LEN];
    RawAllStageState previous_stage = {0};

    if (out_previous_stage != NULL) {
        memset(out_previous_stage, 0, sizeof(*out_previous_stage));
    }
    if (config == NULL ||
        io_budget_base_bytes == NULL ||
        io_budget_elapsed_bias_seconds == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !has_nonempty_text(config->output_dir) ||
        config->additive_pass ||
        (!config->resume_active &&
         !config->resume_scan_completed &&
         !config->resume_completed)) {
        return;
    }

    if (!build_raw_all_stage_path_for_run_dir(
            config->output_dir,
            stage_path,
            sizeof(stage_path)) ||
        !load_raw_all_stage_state(stage_path, &previous_stage)) {
        return;
    }

    if (previous_stage.budget_base_bytes > 0ULL ||
        *io_budget_base_bytes == 0ULL) {
        *io_budget_base_bytes = previous_stage.budget_base_bytes;
    }
    if (previous_stage.budget_elapsed_seconds > 0ULL) {
        *io_budget_elapsed_bias_seconds =
            (double)previous_stage.budget_elapsed_seconds;
    }
    if (out_previous_stage != NULL) {
        *out_previous_stage = previous_stage;
    }
}

static int maybe_advance_scan_state_for_crash_retry(
    const AppConfig *config,
    int crash_failure_count,
    const char *reason
)
{
    char run_dir[1024];
    char scan_state_path[1200];
    char stage_path[PATH_MAX_LEN];
    ScanState state = {0};
    RawAllStageState stage_state = {0};
    uint64_t skip_bytes;
    uint64_t anchor_offset;
    uint64_t zone_start;
    uint64_t next_offset;

    if (config == NULL ||
        !build_run_output_dir_for_supervisor(config, run_dir, sizeof(run_dir)) ||
        !build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) ||
        !scan_state_load(scan_state_path, &state) ||
        state.scan_completed ||
        state.completed) {
        return 0;
    }

    skip_bytes = config->crash_retry_skip_bytes;
    if (skip_bytes == 0ULL) {
        if (crash_failure_count < 2) {
            return 0;
        }
        skip_bytes = RAW_ALL_CRASH_RETRY_DEFAULT_SKIP_BYTES;
    }
    if (skip_bytes == 0ULL) {
        return 0;
    }

    anchor_offset = state.scan_offset;
    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &stage_state) &&
        stage_state.progress_bytes > anchor_offset &&
        (state.source_size == 0ULL ||
         stage_state.progress_bytes <= state.source_size)) {
        anchor_offset = stage_state.progress_bytes;
    }

    next_offset = anchor_offset;
    if (UINT64_MAX - next_offset < skip_bytes) {
        next_offset = UINT64_MAX;
    } else {
        next_offset += skip_bytes;
    }
    if (state.source_size > 0U && next_offset > state.source_size) {
        next_offset = state.source_size;
    }
    next_offset -= next_offset % RAW_ALL_RESUME_ALIGNMENT;
    if (next_offset <= state.scan_offset) {
        return 0;
    }

    zone_start = state.scan_offset;
    if (stage_state.progress_bytes > 0ULL &&
        stage_state.progress_bytes < zone_start) {
        zone_start = stage_state.progress_bytes;
    }
    if (anchor_offset < zone_start) {
        zone_start = anchor_offset;
    }

    if (scan_state_write(
            scan_state_path,
            state.source_path,
            state.scan_mode,
            state.source_size,
            next_offset,
            0,
            0)) {
        log_runtime_event_error(
            "Crash retry advanced saved scan_offset from %llu to %llu after %d crash-class failure%s; deferred %llu..%llu for later revisit",
            (unsigned long long)state.scan_offset,
            (unsigned long long)next_offset,
            crash_failure_count,
            crash_failure_count == 1 ? "" : "s",
            (unsigned long long)zone_start,
            (unsigned long long)next_offset
        );
        if (next_offset > zone_start) {
            (void)remember_deferred_bad_zone(run_dir, zone_start, next_offset);
            append_extraction_zone_event_for_run_dir(
                run_dir,
                "crash_retry_advanced_scan_offset",
                zone_start,
                next_offset,
                anchor_offset,
                state.scan_offset,
                next_offset,
                (uint64_t)crash_failure_count,
                has_nonempty_text(reason) ? reason : "child_crash"
            );
            append_coverage_gap_observation_for_run_dir(
                run_dir,
                "crash_skip",
                zone_start,
                next_offset,
                next_offset,
                next_offset + (next_offset < state.source_size ? 1ULL : 0ULL),
                "crash_retry_deferred"
            );
        }
        (void)write_error_summary_file_for_run_dir(run_dir);
        return 1;
    }

    return 0;
}

static int raw_all_stalled_stage_is_candidate_validation(
    const char *run_dir,
    time_t child_started_at,
    RawAllStageState *out_stage
)
{
    char stage_path[PATH_MAX_LEN];
    RawAllStageState stage = {0};

    if (out_stage != NULL) {
        memset(out_stage, 0, sizeof(*out_stage));
    }
    if (!has_nonempty_text(run_dir) ||
        !build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) ||
        !load_raw_all_stage_state(stage_path, &stage) ||
        stage.updated_unix < child_started_at ||
        strcmp(stage.stage, "scan_loop") != 0 ||
        strncasecmp(stage.activity, "validating ", 11U) != 0) {
        return 0;
    }
    if (out_stage != NULL) {
        *out_stage = stage;
    }
    return 1;
}

static int maybe_advance_scan_state_past_stalled_validator(
    const AppConfig *config,
    const char *run_dir,
    time_t child_started_at,
    const RawAllStageState *captured_stage,
    const char *reason
)
{
    char scan_state_path[1200];
    char activity_path[PATH_MAX_LEN];
    char trouble_map_path[PATH_MAX_LEN];
    ScanState state = {0};
    RawAllStageState stage = {0};
    SupervisorThreadActivityState activity = {0};
    ReadTroubleMapEntry trouble_entry = {0};
    uint64_t anchor_offset;
    uint64_t next_offset;
    uint64_t zone_start;
    int used_trouble_map_end = 0;

    if (config == NULL || !has_nonempty_text(run_dir) ||
        !build_scan_state_path(
            run_dir,
            scan_state_path,
            sizeof(scan_state_path)) ||
        !scan_state_load(scan_state_path, &state) ||
        state.scan_completed || state.completed ||
        captured_stage == NULL ||
        captured_stage->updated_unix < child_started_at ||
        strcmp(captured_stage->stage, "scan_loop") != 0 ||
        strncasecmp(captured_stage->activity, "validating ", 11U) != 0) {
        return 0;
    }
    /* The supervisor proved this was a validator stall before terminating
     * the child.  Keep that exact snapshot: the child shutdown path may
     * legitimately replace raw_all_stage.txt with "writer catching up" or a
     * terminal phase before we publish the forward resume point. */
    stage = *captured_stage;

    anchor_offset = state.scan_offset;
    if (stage.progress_bytes > anchor_offset &&
        (state.source_size == 0ULL || stage.progress_bytes <= state.source_size)) {
        anchor_offset = stage.progress_bytes;
    }
    if (build_thread_activity_path_for_run_dir(
            run_dir,
            activity_path,
            sizeof(activity_path)) &&
        load_thread_activity_state_for_supervisor(
            activity_path,
            &activity) &&
        activity.updated_unix >= child_started_at &&
        activity.scan_offset > anchor_offset &&
        (state.source_size == 0ULL || activity.scan_offset <= state.source_size)) {
        anchor_offset = activity.scan_offset;
    }

    next_offset = anchor_offset;
    if (UINT64_MAX - next_offset < RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES) {
        next_offset = UINT64_MAX;
    } else {
        next_offset += RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES;
    }
    /* Repeated silent stalls are recorded as a wider trouble zone.  A
     * one-MiB validator escape can otherwise land back inside that same zone
     * and burn the next child on identical work.  Only trust a repeated zone
     * that overlaps the saved/observed validator position. */
    if (build_read_trouble_map_path_for_run_dir(
            run_dir,
            trouble_map_path,
            sizeof(trouble_map_path)) &&
        load_best_trouble_map_entry_for_offset(
            trouble_map_path,
            anchor_offset,
            RAW_ALL_FAR_AHEAD_BAD_READ_WINDOW_BYTES,
            &trouble_entry) &&
        trouble_entry.hit_count >= 2ULL &&
        trouble_entry.end_offset > state.scan_offset &&
        (trouble_entry.offset <= anchor_offset ||
         (anchor_offset <= UINT64_MAX - RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES &&
          trouble_entry.offset <=
              anchor_offset + RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES))) {
        uint64_t trouble_resume = trouble_entry.end_offset;

        if (UINT64_MAX - trouble_resume <
            RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES) {
            trouble_resume = UINT64_MAX;
        } else {
            trouble_resume += RAW_ALL_VALIDATOR_ESCAPE_PADDING_BYTES;
        }
        if (trouble_resume > next_offset) {
            next_offset = trouble_resume;
            used_trouble_map_end = 1;
        }
    }
    if (next_offset < UINT64_MAX - (RAW_ALL_RESUME_ALIGNMENT - 1ULL)) {
        next_offset += RAW_ALL_RESUME_ALIGNMENT - 1ULL;
    }
    next_offset -= next_offset % RAW_ALL_RESUME_ALIGNMENT;
    if (state.source_size > 0ULL && next_offset > state.source_size) {
        next_offset = state.source_size;
    }
    if (next_offset <= state.scan_offset) {
        return 0;
    }

    zone_start = state.scan_offset;
    /* Never move the durable resume point beyond bytes that we failed to
     * register for a later targeted revisit.  An extra deferred range is
     * harmless if the following scan-state write fails; an unrecorded skip is
     * not. */
    if (!remember_deferred_bad_zone(run_dir, zone_start, next_offset)) {
        return 0;
    }
    if (!scan_state_write(
            scan_state_path,
            state.source_path,
            state.scan_mode,
            state.source_size,
            next_offset,
            0,
            0)) {
        return 0;
    }

    append_extraction_zone_event_for_run_dir(
        run_dir,
        "validator_watchdog_escape",
        zone_start,
        next_offset,
        anchor_offset,
        state.scan_offset,
        next_offset,
        1ULL,
        has_nonempty_text(reason) ? reason : "candidate_no_progress"
    );
    append_coverage_gap_observation_for_run_dir(
        run_dir,
        "validator_watchdog",
        zone_start,
        next_offset,
        next_offset,
        next_offset + (next_offset < state.source_size ? 1ULL : 0ULL),
        "deferred_after_candidate_stall"
    );
    log_runtime_event_error(
        "Validator escape advanced saved scan_offset from %llu to %llu after %s stopped making progress%s; deferred %llu..%llu for a later targeted revisit",
        (unsigned long long)state.scan_offset,
        (unsigned long long)next_offset,
        stage.activity[0] != '\0' ? stage.activity : "a raw candidate",
        used_trouble_map_end
            ? " and cleared the end of its repeated trouble-map zone"
            : "",
        (unsigned long long)zone_start,
        (unsigned long long)next_offset
    );
    (void)write_error_summary_file_for_run_dir(run_dir);
    return 1;
}

static int raw_all_continue_after_crash_bypass(
    const AppConfig *config,
    const char *generation_path,
    unsigned long long *io_current_generation,
    const char *run_dir,
    time_t child_started_at,
    int crash_failure_count,
    int *io_total_retry_attempts_used,
    int total_retry_limit,
    unsigned long long *io_child_generation,
    const char *reason
)
{
    if (config == NULL ||
        generation_path == NULL ||
        io_current_generation == NULL ||
        io_total_retry_attempts_used == NULL ||
        io_child_generation == NULL ||
        *io_total_retry_attempts_used >= total_retry_limit) {
        return 0;
    }

    if (!maybe_advance_scan_state_for_crash_retry(
            config,
            crash_failure_count,
            reason)) {
        return 0;
    }

    (*io_total_retry_attempts_used)++;
    (*io_current_generation)++;
    *io_child_generation = *io_current_generation;
    if (!write_supervisor_generation_file(
            generation_path,
            *io_current_generation)) {
        log_runtime_event_error(
            "Raw-all crash-zone bypass is restarting with generation %llu, but the supervisor token file could not be updated; stale-child protection is weakened for this retry",
            *io_current_generation
        );
    }
    accumulate_raw_all_stage_budget_elapsed_for_supervisor(
        run_dir,
        child_started_at,
        1,
        0ULL
    );
    log_runtime_event_error(
        "Raw-all will continue after isolating a repeated crash zone (generation %llu, total retries %d/%d)",
        *io_current_generation,
        *io_total_retry_attempts_used,
        total_retry_limit
    );
    sleep(1);
    accumulate_raw_all_stage_budget_elapsed_for_supervisor(
        run_dir,
        0,
        0,
        1ULL
    );
    return 1;
}

static void maybe_rewind_scan_state_for_stall_retry(
    const AppConfig *config,
    int allow_forward_bypass,
    const RawAllStageState *captured_stage
)
{
    char run_dir[1024];
    char scan_state_path[1200];
    char events_path[PATH_MAX_LEN];
    char bad_read_path[PATH_MAX_LEN];
    char trouble_map_path[PATH_MAX_LEN];
    char thread_activity_path[PATH_MAX_LEN];
    ScanState state = {0};
    LastBadReadState bad_read_state = {0};
    ReadTroubleMapEntry trouble_entry = {0};
    ReadTroubleMapTractSummary tract_summary = {0};
    RawAllStageState stage_state = {0};
    SupervisorThreadActivityState thread_activity_state = {0};
    uint64_t next_offset;
    uint64_t preferred_forward_offset = 0ULL;
    uint64_t far_ahead_guard_bytes = RAW_ALL_FAR_AHEAD_BAD_READ_WINDOW_BYTES;
    uint64_t silent_extra_skip_bytes = 0ULL;
    int have_recent_read_trouble = 0;
    int stage_audio_validation = 0;
    int stage_video_validation = 0;
    int stage_validator_yellow = 0;
    int stage_validator_red = 0;
    int allow_far_ahead_retry_bypass = 0;
    int metadata_observation_disabled = 0;

    if (config == NULL ||
        config->stall_retry_backtrack_bytes == 0ULL ||
        !build_run_output_dir_for_supervisor(config, run_dir, sizeof(run_dir)) ||
        !build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) ||
        !scan_state_load(scan_state_path, &state) ||
        state.scan_completed ||
        state.completed) {
        return;
    }

    metadata_observation_disabled = config->skip_mft_observation ? 1 : 0;
    if (build_thread_activity_path_for_run_dir(
            run_dir,
            thread_activity_path,
            sizeof(thread_activity_path)) &&
        load_thread_activity_state_for_supervisor(
            thread_activity_path,
            &thread_activity_state) &&
        thread_activity_state.scan_skip_live_metadata_observation) {
        metadata_observation_disabled = 1;
    }
    if (metadata_observation_disabled &&
        far_ahead_guard_bytes < RAW_ALL_METADATALESS_BYPASS_BYTES_L2) {
        far_ahead_guard_bytes = RAW_ALL_METADATALESS_BYPASS_BYTES_L2;
    }

    /* This function runs after the stalled child has been terminated.  Use
     * the state that justified that termination; shutdown or a stale child
     * may otherwise replace raw_all_stage.txt with a later-looking phase and
     * falsely turn a partial scan into full-source completion. */
    if (captured_stage != NULL && captured_stage->updated_unix > 0) {
        stage_state = *captured_stage;
        if (raw_all_stage_indicates_scan_completed(&stage_state)) {
            uint64_t completed_offset =
                raw_all_completed_scan_offset_from_stage_or_state(
                    &stage_state,
                    &state
                );
            uint64_t selected_scope_end =
                raw_all_effective_scan_end_offset_for_source(
                    config,
                    state.source_size
                );

            if (selected_scope_end > 0ULL &&
                (completed_offset == 0ULL ||
                 completed_offset > selected_scope_end)) {
                completed_offset = selected_scope_end;
            }

            if (state.source_size > 0ULL &&
                completed_offset >= state.source_size &&
                scan_state_write(
                    scan_state_path,
                    state.source_path,
                    state.scan_mode,
                    state.source_size,
                    state.source_size,
                    1,
                    raw_all_stage_indicates_run_completed(&stage_state))) {
                log_runtime_event_info(
                    "Stall retry found raw_all_stage already past the raw scan (%s); preserving scan_completed=1 at byte %llu instead of rewinding",
                    stage_state.stage,
                    (unsigned long long)state.source_size
                );
            } else if (completed_offset > 0ULL &&
                       completed_offset > state.scan_offset &&
                       scan_state_write(
                           scan_state_path,
                           state.source_path,
                           state.scan_mode,
                           state.source_size,
                           completed_offset,
                           0,
                           0)) {
                log_runtime_event_info(
                    "Stall retry found a completed selected raw scope (%s); preserving its endpoint at byte %llu without claiming the full %llu-byte source",
                    stage_state.stage,
                    (unsigned long long)completed_offset,
                    (unsigned long long)state.source_size
                );
            } else if (completed_offset > 0ULL) {
                log_runtime_event_info(
                    "Stall retry kept ordinary resume state because the selected-scope completion hint at byte %llu did not advance saved scan_offset %llu (source_size=%llu)",
                    (unsigned long long)completed_offset,
                    (unsigned long long)state.scan_offset,
                    (unsigned long long)state.source_size
                );
            }
            return;
        }
        stage_audio_validation =
            raw_all_stage_activity_is_audio_validation(stage_state.activity);
        stage_video_validation =
            raw_all_stage_activity_is_video_validation(stage_state.activity);
        stage_validator_red =
            strcmp(stage_state.validator_budget, "red") == 0 ||
            strcmp(stage_state.trouble_budget, "red") == 0;
        stage_validator_yellow =
            !stage_validator_red &&
            (strcmp(stage_state.validator_budget, "yellow") == 0 ||
             strcmp(stage_state.trouble_budget, "yellow") == 0);
    }

    if (build_last_bad_read_path_for_run_dir(
            run_dir,
            bad_read_path,
            sizeof(bad_read_path)) &&
        load_last_bad_read_state(bad_read_path, &bad_read_state)) {
        preferred_forward_offset =
            bad_read_state.end_offset > bad_read_state.offset
                ? bad_read_state.end_offset
                : (bad_read_state.offset + bad_read_state.length);

        if (bad_read_state.length < config->stall_retry_backtrack_bytes) {
            preferred_forward_offset =
                bad_read_state.offset + config->stall_retry_backtrack_bytes;
        }
        if (strcmp(bad_read_state.kind, "silent_stall") == 0) {
            silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L1;
            if (UINT64_MAX - preferred_forward_offset < silent_extra_skip_bytes) {
                preferred_forward_offset = UINT64_MAX;
            } else {
                preferred_forward_offset += silent_extra_skip_bytes;
            }
        }
        have_recent_read_trouble = preferred_forward_offset > 0ULL;
    }

    if (build_read_trouble_map_path_for_run_dir(
            run_dir,
            trouble_map_path,
            sizeof(trouble_map_path)) &&
        load_best_trouble_map_entry_for_offset(
            trouble_map_path,
            state.scan_offset,
            metadata_observation_disabled
                ? RAW_ALL_METADATALESS_BYPASS_BYTES_L2
                : RAW_ALL_FAR_AHEAD_BAD_READ_WINDOW_BYTES,
            &trouble_entry) &&
        trouble_entry.hit_count >= 2U) {
        unsigned long long observed_span_seconds = 0ULL;
        int silent_stall_like = 0;
        uint64_t extra_skip =
            config->stall_retry_backtrack_bytes *
            (trouble_entry.hit_count > 4U ? 4U : trouble_entry.hit_count);
        uint64_t candidate = trouble_entry.end_offset + extra_skip;

        if (trouble_entry.last_seen_unix > trouble_entry.first_seen_unix) {
            observed_span_seconds =
                (unsigned long long)(
                    trouble_entry.last_seen_unix - trouble_entry.first_seen_unix
                );
        }
        silent_stall_like =
            trouble_entry.errno_code == ETIMEDOUT ||
            strcmp(bad_read_state.kind, "silent_stall") == 0;
        if ((stage_audio_validation || stage_video_validation) &&
            trouble_entry.hit_count >= 2U) {
            uint64_t validation_extra_skip =
                config->stall_retry_backtrack_bytes * 16ULL;

            if (stage_validator_red) {
                validation_extra_skip =
                    config->stall_retry_backtrack_bytes * 32ULL;
            } else if (stage_validator_yellow) {
                validation_extra_skip =
                    config->stall_retry_backtrack_bytes * 24ULL;
            }
            if (validation_extra_skip > extra_skip) {
                extra_skip = validation_extra_skip;
            }
            if (UINT64_MAX - trouble_entry.end_offset < extra_skip) {
                candidate = UINT64_MAX;
            } else {
                candidate = trouble_entry.end_offset + extra_skip;
            }
        }
        if (metadata_observation_disabled &&
            trouble_entry.hit_count >= 2U) {
            uint64_t metadata_light_extra_skip =
                raw_all_metadata_light_bypass_bytes_local(
                    (unsigned long long)trouble_entry.hit_count,
                    observed_span_seconds,
                    silent_stall_like
                );

            if (metadata_light_extra_skip > extra_skip) {
                extra_skip = metadata_light_extra_skip;
                if (UINT64_MAX - trouble_entry.end_offset < extra_skip) {
                    candidate = UINT64_MAX;
                } else {
                    candidate = trouble_entry.end_offset + extra_skip;
                }
            }
        }
        if (observed_span_seconds >= 900ULL &&
            extra_skip < config->stall_retry_backtrack_bytes * 16ULL) {
            extra_skip = config->stall_retry_backtrack_bytes * 16ULL;
            candidate = trouble_entry.end_offset + extra_skip;
        } else if (observed_span_seconds >= 300ULL &&
                   extra_skip < config->stall_retry_backtrack_bytes * 8ULL) {
            extra_skip = config->stall_retry_backtrack_bytes * 8ULL;
            candidate = trouble_entry.end_offset + extra_skip;
        }
        if (far_ahead_guard_bytes < extra_skip + config->stall_retry_backtrack_bytes) {
            far_ahead_guard_bytes = extra_skip + config->stall_retry_backtrack_bytes;
        }
        if ((stage_audio_validation || stage_video_validation ||
             metadata_observation_disabled) &&
            trouble_entry.hit_count >= 2U) {
            uint64_t forward_guard_bytes =
                extra_skip + RAW_ALL_TRACT_TROUBLE_WINDOW_BYTES;

            allow_far_ahead_retry_bypass = 1;
            if (forward_guard_bytes < extra_skip) {
                forward_guard_bytes = UINT64_MAX;
            }
            if (far_ahead_guard_bytes < forward_guard_bytes) {
                far_ahead_guard_bytes = forward_guard_bytes;
            }
        }

        if (candidate > preferred_forward_offset) {
            preferred_forward_offset = candidate;
            have_recent_read_trouble = 1;
            log_runtime_event_info(
                "Repeated trouble zone remembered: offset=%llu end=%llu hits=%llu observed=%llus; stall retry will try to jump farther past it",
                (unsigned long long)trouble_entry.offset,
                (unsigned long long)trouble_entry.end_offset,
                (unsigned long long)trouble_entry.hit_count,
                observed_span_seconds
            );
        }

        if (silent_stall_like) {
            if (trouble_entry.hit_count >= 3U) {
                silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L3;
            } else if (trouble_entry.hit_count >= 2U) {
                silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L2;
            } else if (silent_extra_skip_bytes < RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L1) {
                silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L1;
            }
            if (stage_audio_validation || stage_video_validation) {
                if (stage_validator_red) {
                    silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L4;
                } else if (stage_validator_yellow &&
                           silent_extra_skip_bytes < RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L3) {
                    silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L3;
                } else if (silent_extra_skip_bytes < RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L2) {
                    silent_extra_skip_bytes = RAW_ALL_SILENT_STALL_EXTRA_SKIP_BYTES_L2;
                }
            }
            if (metadata_observation_disabled) {
                uint64_t metadata_light_silent_skip =
                    raw_all_metadata_light_bypass_bytes_local(
                        (unsigned long long)trouble_entry.hit_count,
                        observed_span_seconds,
                        1
                    );

                if (silent_extra_skip_bytes < metadata_light_silent_skip) {
                    silent_extra_skip_bytes = metadata_light_silent_skip;
                }
            }

            if (silent_extra_skip_bytes > 0U) {
                uint64_t candidate = trouble_entry.end_offset;

                if (UINT64_MAX - candidate < silent_extra_skip_bytes) {
                    candidate = UINT64_MAX;
                } else {
                    candidate += silent_extra_skip_bytes;
                }
                if (candidate > preferred_forward_offset) {
                    preferred_forward_offset = candidate;
                    have_recent_read_trouble = 1;
                    log_runtime_event_info(
                        "Silent-stall zone remembered: offset=%llu end=%llu hits=%llu%s%s; stall retry will bypass an extra %llu MiB to avoid chewing on the same sour region",
                        (unsigned long long)trouble_entry.offset,
                        (unsigned long long)trouble_entry.end_offset,
                        (unsigned long long)trouble_entry.hit_count,
                        stage_audio_validation ? " during audio validation" : "",
                        stage_video_validation ? " during video validation" : "",
                        (unsigned long long)(silent_extra_skip_bytes / (1024ULL * 1024ULL))
                    );
                }
            }
        }
    }

    if ((stage_audio_validation || stage_video_validation ||
         metadata_observation_disabled) &&
        build_read_trouble_map_path_for_run_dir(
            run_dir,
            trouble_map_path,
            sizeof(trouble_map_path)) &&
        load_trouble_map_tract_summary_for_offset(
            trouble_map_path,
            state.scan_offset,
            RAW_ALL_TRACT_TROUBLE_WINDOW_BYTES,
            &tract_summary) &&
        (tract_summary.total_hit_count >= 3U ||
         tract_summary.zone_count >= 2U)) {
        uint64_t tract_extra_skip =
            metadata_observation_disabled
                ? RAW_ALL_METADATALESS_BYPASS_BYTES_L1
                : RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L1;
        uint64_t tract_candidate;

        if (metadata_observation_disabled) {
            if (tract_summary.total_hit_count >= 24U ||
                tract_summary.zone_count >= 6U ||
                tract_summary.total_bytes >=
                    (RAW_ALL_METADATALESS_BYPASS_BYTES_L4 +
                     RAW_ALL_METADATALESS_BYPASS_BYTES_L3)) {
                tract_extra_skip = RAW_ALL_METADATALESS_BYPASS_BYTES_L5;
            } else if (tract_summary.total_hit_count >= 16U ||
                       tract_summary.zone_count >= 5U ||
                       tract_summary.total_bytes >=
                           (RAW_ALL_METADATALESS_BYPASS_BYTES_L3 +
                            RAW_ALL_METADATALESS_BYPASS_BYTES_L2)) {
                tract_extra_skip = RAW_ALL_METADATALESS_BYPASS_BYTES_L4;
            } else if (tract_summary.total_hit_count >= 10U ||
                       tract_summary.zone_count >= 4U ||
                       tract_summary.total_bytes >=
                           (RAW_ALL_METADATALESS_BYPASS_BYTES_L2 +
                            RAW_ALL_METADATALESS_BYPASS_BYTES_L1)) {
                tract_extra_skip = RAW_ALL_METADATALESS_BYPASS_BYTES_L3;
            } else if (tract_summary.total_hit_count >= 6U ||
                       tract_summary.zone_count >= 3U ||
                       tract_summary.total_bytes >=
                           RAW_ALL_METADATALESS_BYPASS_BYTES_L1) {
                tract_extra_skip = RAW_ALL_METADATALESS_BYPASS_BYTES_L2;
            }
        } else if (tract_summary.total_hit_count >= 16U ||
                   tract_summary.zone_count >= 5U ||
                   tract_summary.total_bytes >=
                       (RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L3 +
                        RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L2)) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L4;
        } else if (tract_summary.total_hit_count >= 10U ||
                   tract_summary.zone_count >= 4U ||
                   tract_summary.total_bytes >=
                       (RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L2 +
                        RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L1)) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L3;
        } else if (tract_summary.total_hit_count >= 6U ||
                   tract_summary.zone_count >= 3U ||
                   tract_summary.total_bytes >= RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L1) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L2;
        }
        if (stage_validator_red &&
            tract_summary.total_hit_count >= 10U &&
            tract_extra_skip < RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L4) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L4;
        } else if (stage_validator_red &&
                   tract_extra_skip < RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L3) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L3;
        } else if (stage_validator_yellow &&
                   tract_extra_skip < RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L2) {
            tract_extra_skip = RAW_ALL_AUDIO_VALIDATION_BYPASS_BYTES_L2;
        }

        tract_candidate = tract_summary.end_offset;
        if (UINT64_MAX - tract_candidate < tract_extra_skip) {
            tract_candidate = UINT64_MAX;
        } else {
            tract_candidate += tract_extra_skip;
        }
        if (tract_candidate > preferred_forward_offset) {
            preferred_forward_offset = tract_candidate;
            have_recent_read_trouble = 1;
            allow_far_ahead_retry_bypass = 1;
            if (far_ahead_guard_bytes <
                tract_extra_skip + RAW_ALL_TRACT_TROUBLE_WINDOW_BYTES) {
                far_ahead_guard_bytes =
                    tract_extra_skip + RAW_ALL_TRACT_TROUBLE_WINDOW_BYTES;
            }
            if (metadata_observation_disabled &&
                !stage_audio_validation &&
                !stage_video_validation) {
                log_runtime_event_info(
                    "Metadata-light raw scan keeps stalling across a local trouble tract %llu..%llu (zones=%zu hits=%llu); stall retry will bypass %.0f MiB to keep forward progress up",
                    (unsigned long long)tract_summary.start_offset,
                    (unsigned long long)tract_summary.end_offset,
                    tract_summary.zone_count,
                    (unsigned long long)tract_summary.total_hit_count,
                    (double)tract_extra_skip / (1024.0 * 1024.0)
                );
            } else {
                log_runtime_event_info(
                    "Audio/video validation keeps stalling across a local trouble tract %llu..%llu (zones=%zu hits=%llu%s%s); stall retry will bypass %.0f MiB to get past it faster",
                    (unsigned long long)tract_summary.start_offset,
                    (unsigned long long)tract_summary.end_offset,
                    tract_summary.zone_count,
                    (unsigned long long)tract_summary.total_hit_count,
                    stage_audio_validation ? " during audio validation" : "",
                    stage_video_validation ? " during video validation" : "",
                    (double)tract_extra_skip / (1024.0 * 1024.0)
                );
            }
        }
    }

    if (!have_recent_read_trouble &&
        build_runtime_events_path_for_run_dir(
            run_dir,
            events_path,
            sizeof(events_path))) {
        FILE *events_file = fopen(events_path, "r");

        if (events_file != NULL) {
            char line[512];

            while (fgets(line, sizeof(line), events_file) != NULL) {
                unsigned long long failed_offset = 0ULL;
                unsigned long long failed_length = 0ULL;
                unsigned long long skipped_start = 0ULL;
                unsigned long long skipped_end = 0ULL;

                if (sscanf(
                        line,
                        "%*[^R]Read failed at byte %llu for %llu bytes",
                        &failed_offset,
                        &failed_length) == 2) {
                    uint64_t candidate =
                        (uint64_t)failed_offset +
                        (uint64_t)(
                            failed_length > config->stall_retry_backtrack_bytes
                                ? failed_length
                                : config->stall_retry_backtrack_bytes);

                    if (candidate > preferred_forward_offset) {
                        preferred_forward_offset = candidate;
                    }
                    have_recent_read_trouble = 1;
                    continue;
                }

                if (sscanf(
                        line,
                        "%*[^R]Reader skipped unreadable range %llu..%llu",
                        &skipped_start,
                        &skipped_end) == 2) {
                    uint64_t candidate = (uint64_t)skipped_end;

                    if (candidate > preferred_forward_offset) {
                        preferred_forward_offset = candidate;
                    }
                    have_recent_read_trouble = 1;
                    continue;
                }
            }

            fclose(events_file);
        }
    }

    if (have_recent_read_trouble &&
        !allow_forward_bypass &&
        preferred_forward_offset > state.scan_offset) {
        log_runtime_event_info(
            "Problem-area bypass is being held back until the ordinary retry allowance has been used; retrying with overlap before deferring source bytes"
        );
        have_recent_read_trouble = 0;
    }

    if (have_recent_read_trouble &&
        preferred_forward_offset > state.scan_offset) {
        if (config->stall_retry_backtrack_bytes > 0ULL &&
            far_ahead_guard_bytes < config->stall_retry_backtrack_bytes * 4ULL) {
            far_ahead_guard_bytes = config->stall_retry_backtrack_bytes * 4ULL;
        }
        if (!allow_far_ahead_retry_bypass &&
            preferred_forward_offset >
            state.scan_offset + far_ahead_guard_bytes) {
            log_runtime_event_info(
                "Ignoring far-ahead bad-read hint at %llu while saved scan_offset is %llu; it likely came from startup probing rather than the current raw scan position",
                (unsigned long long)preferred_forward_offset,
                (unsigned long long)state.scan_offset
            );
            have_recent_read_trouble = 0;
        }
    }

    if (have_recent_read_trouble &&
        preferred_forward_offset > state.scan_offset) {
        uint64_t deferred_start = state.scan_offset;
        uint64_t deferred_end = preferred_forward_offset;

        if (trouble_entry.end_offset > trouble_entry.offset) {
            deferred_start = trouble_entry.offset;
            deferred_end = trouble_entry.end_offset;
        } else if (bad_read_state.end_offset > bad_read_state.offset) {
            deferred_start = bad_read_state.offset;
            deferred_end = bad_read_state.end_offset;
        }

        if (preferred_forward_offset > deferred_end) {
            deferred_end = preferred_forward_offset;
        }

        if (deferred_end > deferred_start &&
            remember_deferred_bad_zone(
                run_dir,
                deferred_start,
                deferred_end)) {
            log_runtime_event_info(
                "Deferred trouble zone %llu..%llu for a later targeted revisit after the main raw scan has moved on",
                (unsigned long long)deferred_start,
                (unsigned long long)deferred_end
            );
            append_extraction_zone_event_for_run_dir(
                run_dir,
                "deferred_trouble_zone",
                deferred_start,
                deferred_end,
                state.scan_offset,
                state.scan_offset,
                preferred_forward_offset,
                trouble_entry.hit_count,
                "main_scan_moved_on_for_later_retry"
            );
        }

        next_offset = preferred_forward_offset;
        if (state.source_size > 0U && next_offset > state.source_size) {
            next_offset = state.source_size;
        }
        if (next_offset > state.scan_offset &&
            scan_state_write(
                scan_state_path,
                state.source_path,
                state.scan_mode,
                state.source_size,
                next_offset,
                0,
                0)) {
            log_runtime_event_error(
                "Stall retry advanced saved scan_offset from %llu to %llu to move past recently confirmed read trouble",
                (unsigned long long)state.scan_offset,
                (unsigned long long)next_offset
            );
            append_extraction_zone_event_for_run_dir(
                run_dir,
                "stall_retry_advanced_scan_offset",
                deferred_start,
                deferred_end,
                state.scan_offset,
                state.scan_offset,
                next_offset,
                trouble_entry.hit_count,
                "confirmed_read_trouble"
            );
            (void)write_error_summary_file_for_run_dir(run_dir);
            return;
        }
    }

    next_offset = state.scan_offset;
    if (next_offset > config->stall_retry_backtrack_bytes) {
        next_offset -= config->stall_retry_backtrack_bytes;
    } else {
        next_offset = 0ULL;
    }

    if (next_offset >= state.scan_offset) {
        return;
    }

    if (scan_state_write(
            scan_state_path,
            state.source_path,
            state.scan_mode,
            state.source_size,
            next_offset,
            0,
            0)) {
        log_runtime_event_error(
            "Stall retry rewound saved scan_offset from %llu to %llu before restart",
            (unsigned long long)state.scan_offset,
            (unsigned long long)next_offset
        );
        append_extraction_zone_event_for_run_dir(
            run_dir,
            "stall_retry_rewound_scan_offset",
            next_offset,
            state.scan_offset,
            state.scan_offset,
            state.scan_offset,
            next_offset,
            0ULL,
            "backtrack_before_retry"
        );
    }
}

static int raw_all_last_bad_read_is_source_reconnect(
    const LastBadReadState *state
)
{
    if (state == NULL || state->kind[0] == '\0') {
        return 0;
    }

    return strcmp(state->kind, "source_path_unavailable") == 0 ||
           strcmp(state->kind, "device_unavailable") == 0;
}

static uint64_t raw_all_source_reconnect_rewind_overlap(
    const AppConfig *config
)
{
    uint64_t overlap = SOURCE_RECONNECT_REWIND_OVERLAP_BYTES;

    if (config != NULL &&
        config->stall_retry_backtrack_bytes > overlap) {
        overlap = config->stall_retry_backtrack_bytes;
    }

    return overlap;
}

static int maybe_rewind_scan_state_for_source_reconnect(
    const AppConfig *config,
    const char *run_dir,
    time_t child_started_at
)
{
    char scan_state_path[1200];
    char bad_read_path[PATH_MAX_LEN];
    ScanState state = {0};
    LastBadReadState bad_read = {0};
    uint64_t anchor_offset;
    uint64_t old_offset = 0ULL;
    uint64_t source_size = 0ULL;
    uint64_t overlap;
    uint64_t next_offset;
    int have_state;

    if (config == NULL ||
        !has_nonempty_text(run_dir) ||
        !build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) ||
        !build_last_bad_read_path_for_run_dir(
            run_dir,
            bad_read_path,
            sizeof(bad_read_path)) ||
        !load_last_bad_read_state(bad_read_path, &bad_read) ||
        !raw_all_last_bad_read_is_source_reconnect(&bad_read)) {
        return 0;
    }

    if (child_started_at > 0 &&
        (bad_read.updated_unix == 0 ||
         bad_read.updated_unix + SOURCE_RECONNECT_RETRY_DELAY_SECONDS + 2 <
             child_started_at)) {
        return 0;
    }

    if (child_started_at == 0 &&
        bad_read.updated_unix > 0 &&
        time(NULL) > bad_read.updated_unix + SOURCE_RECONNECT_RETRY_BUDGET_SECONDS) {
        return 0;
    }

    anchor_offset = bad_read.offset;
    if (anchor_offset == 0ULL &&
        bad_read.end_offset > bad_read.length) {
        anchor_offset = bad_read.end_offset - bad_read.length;
    }
    if (anchor_offset == 0ULL && bad_read.end_offset > 0ULL) {
        anchor_offset = bad_read.end_offset;
    }

    have_state = scan_state_load(scan_state_path, &state);
    if (have_state) {
        old_offset = state.scan_offset;
        source_size = state.source_size;
    }
    if (source_size == 0ULL) {
        source_size = probe_input_size_for_eta(config->input_path);
    }
    if (source_size > 0ULL && anchor_offset > source_size) {
        anchor_offset = source_size;
    }

    overlap = raw_all_source_reconnect_rewind_overlap(config);
    next_offset = anchor_offset > overlap ? anchor_offset - overlap : 0ULL;
    next_offset -= next_offset % RAW_ALL_RESUME_ALIGNMENT;

    if (have_state &&
        old_offset <= next_offset &&
        !state.scan_completed &&
        !state.completed) {
        return 0;
    }

    if (!have_state) {
        memset(&state, 0, sizeof(state));
        snprintf(
            state.source_path,
            sizeof(state.source_path),
            "%s",
            has_nonempty_text(config->input_path) ? config->input_path : ""
        );
        snprintf(
            state.scan_mode,
            sizeof(state.scan_mode),
            "%s",
            config_scan_mode_label(config)
        );
    }

    if (state.source_path[0] == '\0' && has_nonempty_text(config->input_path)) {
        snprintf(state.source_path, sizeof(state.source_path), "%s", config->input_path);
    }
    if (state.scan_mode[0] == '\0') {
        snprintf(state.scan_mode, sizeof(state.scan_mode), "%s", config_scan_mode_label(config));
    }
    if (source_size > 0ULL) {
        state.source_size = source_size;
    }

    if (!scan_state_write(
            scan_state_path,
            state.source_path,
            state.scan_mode,
            state.source_size,
            next_offset,
            0,
            0)) {
        return 0;
    }

    log_runtime_event_error(
        "Source reconnect rewind: saved scan_offset %llu -> %llu after %s at byte %llu; next scan will overlap %.1f MiB instead of leaving a coverage gap",
        (unsigned long long)old_offset,
        (unsigned long long)next_offset,
        bad_read.kind,
        (unsigned long long)anchor_offset,
        (double)overlap / (1024.0 * 1024.0)
    );
    append_extraction_zone_event_for_run_dir(
        run_dir,
        "source_reconnect_rewound_scan_offset",
        next_offset,
        anchor_offset,
        anchor_offset,
        old_offset,
        next_offset,
        bad_read.span_count,
        "overlap_after_source_loss"
    );

    return 1;
}

static uint64_t load_scan_offset_for_supervisor(
    const char *run_dir
)
{
    char scan_state_path[1200];
    ScanState state = {0};

    if (run_dir == NULL ||
        run_dir[0] == '\0' ||
        !build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) ||
        !scan_state_load(scan_state_path, &state)) {
        return 0ULL;
    }

    return state.scan_offset;
}

static int raw_all_supervisor_source_is_regular_file(
    const AppConfig *config
)
{
    struct stat st;

    return config != NULL &&
           has_nonempty_text(config->input_path) &&
           stat(config->input_path, &st) == 0 &&
           S_ISREG(st.st_mode);
}

static unsigned long long raw_all_scan_stall_cap_for_source_seconds(
    const AppConfig *config,
    unsigned long long block_device_cap_seconds
)
{
    if (!raw_all_supervisor_source_is_regular_file(config)) {
        return block_device_cap_seconds;
    }
    if (block_device_cap_seconds >
        ULLONG_MAX / RAW_ALL_REGULAR_FILE_SCAN_STALL_TIMEOUT_MULTIPLIER) {
        return ULLONG_MAX;
    }

    return block_device_cap_seconds *
           RAW_ALL_REGULAR_FILE_SCAN_STALL_TIMEOUT_MULTIPLIER;
}

static int raw_all_startup_stage_is_metadata_phase(
    const char *stage
)
{
    return stage != NULL &&
           (strcmp(stage, "resume_loading") == 0 ||
            strcmp(stage, "primary_metadata_bootstrap") == 0 ||
            strcmp(stage, "primary_mft_bootstrap") == 0 ||
            strcmp(stage, "mft_index") == 0 ||
            strcmp(stage, "metadata_index") == 0);
}

static int raw_all_stage_is_post_scan_nonrestart_phase(
    const char *stage
)
{
    if (stage == NULL || stage[0] == '\0') {
        return 0;
    }

    return strcmp(stage, "post_scan_finalize") == 0 ||
           strcmp(stage, "post_scan_reconcile") == 0 ||
           strcmp(stage, "auto_name_handoff") == 0 ||
           strcmp(stage, "name_followup_incomplete") == 0 ||
           strcmp(stage, "completed") == 0 ||
           strcmp(stage, "crash_resume_ready") == 0 ||
           strcmp(stage, "failed") == 0 ||
           strcmp(stage, "stopped") == 0 ||
           strcmp(stage, "done") == 0;
}

static int raw_all_stage_should_use_startup_stall_guard(
    const char *stage,
    int saved_scan_completed
)
{
    if (stage == NULL || stage[0] == '\0') {
        return !saved_scan_completed;
    }
    if (strcmp(stage, "scan_loop") == 0) {
        return 0;
    }
    if (strcmp(stage, "retry_hotspots") == 0) {
        /* This is post-scan work even when a bounded selected range correctly
         * leaves the full-source scan_completed flag clear.  Its dedicated
         * watchdog below follows byte/file progress. */
        return 0;
    }
    if (raw_all_stage_is_post_scan_nonrestart_phase(stage)) {
        return 0;
    }
    return !saved_scan_completed;
}

static unsigned long long raw_all_startup_stage_timeout_seconds(
    const AppConfig *config,
    const char *stage
)
{
    unsigned long long timeout_seconds = RAW_ALL_PRIMING_STALL_TIMEOUT_SECONDS;

    if (stage != NULL && strcmp(stage, "resume_loading") == 0) {
        /* Large recovered-output ledgers and compact metadata maps can take
         * minutes to reopen on a slow or damaged output disk.  This is local
         * state work, not a source-read stall, so keep a separate finite
         * guard instead of recycling the 45-second scan-start timeout. */
        timeout_seconds = RAW_ALL_RESUME_LOADING_STALL_TIMEOUT_SECONDS;
    } else if (raw_all_startup_stage_is_metadata_phase(stage)) {
        timeout_seconds = RAW_ALL_PRIMARY_METADATA_BOOTSTRAP_STALL_TIMEOUT_SECONDS;
    }

    if (raw_all_supervisor_source_is_regular_file(config) &&
        timeout_seconds < RAW_ALL_REGULAR_FILE_STARTUP_STALL_TIMEOUT_SECONDS) {
        timeout_seconds = RAW_ALL_REGULAR_FILE_STARTUP_STALL_TIMEOUT_SECONDS;
    }
    if (config != NULL &&
        config->stall_timeout_seconds > 0ULL &&
        raw_all_supervisor_source_is_regular_file(config) &&
        timeout_seconds < config->stall_timeout_seconds) {
        timeout_seconds = config->stall_timeout_seconds;
    }

    return timeout_seconds;
}

static int raw_all_primary_metadata_progress_is_recent(
    const char *run_dir,
    time_t child_started_at,
    time_t now,
    unsigned long long timeout_seconds,
    PrimaryMetadataProgressState *out_progress,
    unsigned long long *out_progress_age
)
{
    char progress_path[PATH_MAX_LEN];
    PrimaryMetadataProgressState progress = {0};
    unsigned long long progress_age = ULLONG_MAX;

    if (out_progress != NULL) {
        memset(out_progress, 0, sizeof(*out_progress));
    }
    if (out_progress_age != NULL) {
        *out_progress_age = ULLONG_MAX;
    }

    if (!has_nonempty_text(run_dir) ||
        !build_primary_metadata_progress_path_for_run_dir(
            run_dir,
            progress_path,
            sizeof(progress_path)) ||
        !load_primary_metadata_progress_state(progress_path, &progress) ||
        progress.updated_unix < child_started_at) {
        return 0;
    }

    if (now >= progress.updated_unix) {
        progress_age = (unsigned long long)(now - progress.updated_unix);
    } else {
        progress_age = 0ULL;
    }

    if (out_progress != NULL) {
        *out_progress = progress;
    }
    if (out_progress_age != NULL) {
        *out_progress_age = progress_age;
    }

    return progress_age < timeout_seconds;
}

static int raw_all_startup_stage_should_skip_mft_on_retry(
    const AppConfig *config,
    const char *stage
)
{
    if (raw_all_supervisor_source_is_regular_file(config)) {
        return 0;
    }
    if (raw_all_startup_stage_is_metadata_phase(stage)) {
        return 0;
    }

    return stage == NULL ||
           stage[0] == '\0' ||
           strcmp(stage, "startup") == 0 ||
           strcmp(stage, "reader_open") == 0;
}

static int raw_all_child_should_restart_for_stall(
    const AppConfig *config,
    const char *run_dir,
    time_t child_started_at,
    unsigned long long *out_effective_timeout_seconds,
    int *out_accelerated_for_read_trouble,
    int *out_inferred_from_silent_state,
    int *out_startup_stage_stall,
    char *out_stage,
    size_t out_stage_size,
    RawAllStageState *out_stage_state
)
{
    char scan_state_path[1200];
    char stats_path[1200];
    char events_path[PATH_MAX_LEN];
    char bad_read_path[PATH_MAX_LEN];
    char trouble_map_path[PATH_MAX_LEN];
    char stage_path[PATH_MAX_LEN];
    char thread_activity_path[PATH_MAX_LEN];
    ScanState state = {0};
    FsBackendLiveStats live_stats = {0};
    SupervisorThreadActivityState activity_state = {0};
    LastBadReadState bad_read_state = {0};
    ReadTroubleMapEntry trouble_entry = {0};
    RawAllStageState stage_state = {0};
    struct stat scan_state_stat;
    struct stat stats_stat;
    struct stat events_stat;
    time_t now;
    time_t latest_progress_mtime = 0;
    unsigned long long effective_stalled_seconds = 0ULL;
    unsigned long long startup_grace_seconds = 15ULL;
    unsigned long long effective_timeout_seconds = 0ULL;
    int accelerated_for_read_trouble = 0;
    int inferred_from_silent_state = 0;
    static char cached_events_path[PATH_MAX_LEN] = "";
    static time_t cached_events_mtime = 0;
    static int cached_has_read_trouble = 0;
    static int cached_events_known = 0;
    static char cached_stage_progress_path[PATH_MAX_LEN] = "";
    static time_t cached_stage_progress_change_unix = 0;
    static uint64_t cached_stage_progress_bytes = 0ULL;
    static char cached_retry_hotspots_path[PATH_MAX_LEN] = "";
    static time_t cached_retry_hotspots_change_unix = 0;
    static size_t cached_retry_hotspots_recovered_files = 0U;
    static size_t cached_retry_hotspots_named_files = 0U;
    static uint64_t cached_retry_hotspots_progress_bytes = 0ULL;
    int have_scan_loop_stage = 0;
    int stage_audio_validation = 0;
    int stage_video_validation = 0;
    int stage_validator_yellow = 0;
    int stage_validator_red = 0;
    int have_saved_scan_state = 0;
    int have_activity_state = 0;
    int saved_scan_completed = 0;
    unsigned long long stage_progress_stalled_seconds = 0ULL;

    if (out_effective_timeout_seconds != NULL) {
        *out_effective_timeout_seconds = 0ULL;
    }
    if (out_accelerated_for_read_trouble != NULL) {
        *out_accelerated_for_read_trouble = 0;
    }
    if (out_inferred_from_silent_state != NULL) {
        *out_inferred_from_silent_state = 0;
    }
    if (out_startup_stage_stall != NULL) {
        *out_startup_stage_stall = 0;
    }
    if (out_stage != NULL && out_stage_size > 0U) {
        out_stage[0] = '\0';
    }
    if (out_stage_state != NULL) {
        memset(out_stage_state, 0, sizeof(*out_stage_state));
    }

    if (config == NULL ||
        config->stall_retries <= 0 ||
        config->stall_timeout_seconds == 0ULL ||
        run_dir == NULL ||
        run_dir[0] == '\0' ||
        !build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) ||
        !resolve_metadata_live_stats_path_for_supervisor(
            run_dir,
            stats_path,
            sizeof(stats_path))) {
        return 0;
    }

    have_saved_scan_state = scan_state_load(scan_state_path, &state);
    saved_scan_completed =
        have_saved_scan_state && (state.scan_completed || state.completed);

    effective_timeout_seconds = config->stall_timeout_seconds;
    {
        int startup_stage_active = 0;

        if (build_raw_all_stage_path_for_run_dir(
                run_dir,
                stage_path,
                sizeof(stage_path)) &&
            load_raw_all_stage_state(stage_path, &stage_state)) {
            if (out_stage_state != NULL &&
                stage_state.updated_unix >= child_started_at) {
                *out_stage_state = stage_state;
            }
            if (raw_all_stage_indicates_scan_completed(&stage_state)) {
                saved_scan_completed = 1;
            }
            if (stage_state.updated_unix >= child_started_at &&
                raw_all_stage_should_use_startup_stall_guard(
                    stage_state.stage,
                    saved_scan_completed)) {
                startup_stage_active = 1;
            }
        }

        if (build_last_bad_read_path_for_run_dir(
                run_dir,
                bad_read_path,
                sizeof(bad_read_path)) &&
            load_last_bad_read_state(bad_read_path, &bad_read_state)) {
            if (!raw_all_supervisor_source_is_regular_file(config) &&
                startup_stage_active &&
                strcmp(bad_read_state.kind, "read_fail") == 0 &&
                effective_timeout_seconds > RAW_ALL_STARTUP_READ_FAIL_TIMEOUT_SECONDS) {
                effective_timeout_seconds = RAW_ALL_STARTUP_READ_FAIL_TIMEOUT_SECONDS;
                accelerated_for_read_trouble = 1;
            } else if (!raw_all_supervisor_source_is_regular_file(config) &&
                       effective_timeout_seconds >
                           RAW_ALL_READ_TROUBLE_STALL_TIMEOUT_SECONDS) {
                effective_timeout_seconds =
                    RAW_ALL_READ_TROUBLE_STALL_TIMEOUT_SECONDS;
                accelerated_for_read_trouble = 1;
            }
        }
    }

    if (build_runtime_events_path_for_run_dir(
            run_dir,
            events_path,
            sizeof(events_path)) &&
        stat(events_path, &events_stat) == 0) {
        int path_changed = strcmp(cached_events_path, events_path) != 0;
        int mtime_changed = !cached_events_known ||
                            path_changed ||
                            cached_events_mtime != events_stat.st_mtime;

        if (mtime_changed) {
            FILE *events_file = fopen(events_path, "r");
            int has_read_trouble = 0;

            if (events_file != NULL) {
                char line[512];

                while (fgets(line, sizeof(line), events_file) != NULL) {
                    if (strstr(line, "Read failed at byte ") != NULL ||
                        strstr(line, "Reader skipped unreadable range ") != NULL) {
                        has_read_trouble = 1;
                        break;
                    }
                }

                fclose(events_file);
            }

            snprintf(
                cached_events_path,
                sizeof(cached_events_path),
                "%s",
                events_path
            );
            cached_events_mtime = events_stat.st_mtime;
            cached_has_read_trouble = has_read_trouble;
            cached_events_known = 1;
        }

        if (!accelerated_for_read_trouble &&
            cached_has_read_trouble &&
            !raw_all_supervisor_source_is_regular_file(config) &&
            effective_timeout_seconds >
                RAW_ALL_READ_TROUBLE_STALL_TIMEOUT_SECONDS) {
            effective_timeout_seconds =
                RAW_ALL_READ_TROUBLE_STALL_TIMEOUT_SECONDS;
            accelerated_for_read_trouble = 1;
        }
    }

    now = time(NULL);
    if (config->stall_timeout_seconds < startup_grace_seconds) {
        startup_grace_seconds = config->stall_timeout_seconds;
    }
    if (effective_timeout_seconds < startup_grace_seconds) {
        startup_grace_seconds = effective_timeout_seconds;
    }
    if (child_started_at > 0 &&
        now >= child_started_at &&
        (unsigned long long)(now - child_started_at) < startup_grace_seconds) {
        return 0;
    }

    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &stage_state) &&
        stage_state.updated_unix >= child_started_at &&
        raw_all_stage_should_use_startup_stall_guard(
            stage_state.stage,
            saved_scan_completed) &&
        now >= child_started_at) {
        unsigned long long startup_timeout =
            raw_all_startup_stage_timeout_seconds(config, stage_state.stage);
        unsigned long long elapsed =
            (unsigned long long)(now - child_started_at);

        if (!raw_all_startup_stage_is_metadata_phase(stage_state.stage) &&
            effective_timeout_seconds > 0ULL &&
            effective_timeout_seconds < startup_timeout) {
            startup_timeout = effective_timeout_seconds;
        }

        if (strcmp(stage_state.stage, "primary_metadata_bootstrap") == 0) {
            PrimaryMetadataProgressState progress = {0};
            unsigned long long progress_age = ULLONG_MAX;

            if (raw_all_primary_metadata_progress_is_recent(
                    run_dir,
                    child_started_at,
                    now,
                    startup_timeout,
                    &progress,
                    &progress_age)) {
                return 0;
            }
            if (progress.updated_unix >= child_started_at) {
                elapsed = progress_age;
            }
        }

        if (elapsed >= startup_timeout) {
            if (out_effective_timeout_seconds != NULL) {
                *out_effective_timeout_seconds = startup_timeout;
            }
            if (out_startup_stage_stall != NULL) {
                *out_startup_stage_stall = 1;
            }
            if (out_stage != NULL && out_stage_size > 0U) {
                snprintf(out_stage, out_stage_size, "%s", stage_state.stage);
            }
            return 1;
        }
    }

    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &stage_state) &&
        stage_state.updated_unix >= child_started_at &&
        raw_all_stage_is_post_scan_nonrestart_phase(stage_state.stage)) {
        return 0;
    }

    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &stage_state) &&
        stage_state.updated_unix >= child_started_at &&
        strcmp(stage_state.stage, "retry_hotspots") == 0) {
        int retry_path_changed =
            strcmp(cached_retry_hotspots_path, stage_path) != 0;
        int retry_useful_progress_changed =
            retry_path_changed ||
            cached_retry_hotspots_change_unix < child_started_at ||
            stage_state.recovered_files != cached_retry_hotspots_recovered_files ||
            stage_state.named_files != cached_retry_hotspots_named_files ||
            stage_state.progress_bytes != cached_retry_hotspots_progress_bytes;
        unsigned long long retry_no_progress_seconds = 0ULL;
        unsigned long long retry_timeout_seconds = effective_timeout_seconds;
        unsigned long long validation_timeout_cap =
            raw_all_validation_stall_timeout_cap_seconds(&stage_state);

        if (retry_useful_progress_changed) {
            snprintf(
                cached_retry_hotspots_path,
                sizeof(cached_retry_hotspots_path),
                "%s",
                stage_path
            );
            cached_retry_hotspots_recovered_files = stage_state.recovered_files;
            cached_retry_hotspots_named_files = stage_state.named_files;
            cached_retry_hotspots_progress_bytes = stage_state.progress_bytes;
            cached_retry_hotspots_change_unix =
                stage_state.updated_unix > 0 ? stage_state.updated_unix : now;
        }

        if (cached_retry_hotspots_change_unix < child_started_at) {
            cached_retry_hotspots_change_unix = child_started_at;
        }
        if (now >= cached_retry_hotspots_change_unix) {
            retry_no_progress_seconds =
                (unsigned long long)(now - cached_retry_hotspots_change_unix);
        }
        if (validation_timeout_cap > 0ULL &&
            (retry_timeout_seconds == 0ULL ||
             retry_timeout_seconds > validation_timeout_cap)) {
            retry_timeout_seconds = validation_timeout_cap;
        }
        if (retry_timeout_seconds == 0ULL ||
            retry_timeout_seconds >
                RAW_ALL_RETRY_HOTSPOTS_NO_PROGRESS_TIMEOUT_SECONDS) {
            retry_timeout_seconds =
                RAW_ALL_RETRY_HOTSPOTS_NO_PROGRESS_TIMEOUT_SECONDS;
        }

        if (retry_no_progress_seconds >= retry_timeout_seconds) {
            if (out_effective_timeout_seconds != NULL) {
                *out_effective_timeout_seconds = retry_timeout_seconds;
            }
            if (out_accelerated_for_read_trouble != NULL) {
                *out_accelerated_for_read_trouble = accelerated_for_read_trouble;
            }
            if (out_inferred_from_silent_state != NULL) {
                *out_inferred_from_silent_state = 1;
            }
            if (out_startup_stage_stall != NULL) {
                *out_startup_stage_stall = 1;
            }
            if (out_stage != NULL && out_stage_size > 0U) {
                snprintf(out_stage, out_stage_size, "%s", stage_state.stage);
            }
            return 1;
        }
        return 0;
    }

    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &stage_state) &&
        stage_state.updated_unix >= child_started_at &&
        strcmp(stage_state.stage, "scan_loop") == 0) {
        int stage_path_changed =
            strcmp(cached_stage_progress_path, stage_path) != 0;

        have_scan_loop_stage = 1;
        stage_audio_validation =
            raw_all_stage_activity_is_audio_validation(stage_state.activity);
        stage_video_validation =
            raw_all_stage_activity_is_video_validation(stage_state.activity);
        stage_validator_red =
            strcmp(stage_state.validator_budget, "red") == 0 ||
            strcmp(stage_state.trouble_budget, "red") == 0;
        stage_validator_yellow =
            !stage_validator_red &&
            (strcmp(stage_state.validator_budget, "yellow") == 0 ||
             strcmp(stage_state.trouble_budget, "yellow") == 0);
        if (stage_path_changed ||
            cached_stage_progress_change_unix < child_started_at ||
            stage_state.progress_bytes != cached_stage_progress_bytes) {
            snprintf(
                cached_stage_progress_path,
                sizeof(cached_stage_progress_path),
                "%s",
                stage_path
            );
            cached_stage_progress_bytes = stage_state.progress_bytes;
            cached_stage_progress_change_unix =
                stage_state.updated_unix > 0 ? stage_state.updated_unix : now;
        }
        if (cached_stage_progress_change_unix > 0 &&
            now >= cached_stage_progress_change_unix) {
            stage_progress_stalled_seconds =
                (unsigned long long)(now - cached_stage_progress_change_unix);
        }

        if (strcmp(stage_state.trouble_budget, "red") == 0) {
            unsigned long long trouble_timeout_cap =
                raw_all_scan_stall_cap_for_source_seconds(config, 120ULL);

            if (effective_timeout_seconds > trouble_timeout_cap) {
                effective_timeout_seconds = trouble_timeout_cap;
                accelerated_for_read_trouble = 1;
            }
        } else if (strcmp(stage_state.trouble_budget, "yellow") == 0) {
            unsigned long long trouble_timeout_cap =
                raw_all_scan_stall_cap_for_source_seconds(config, 180ULL);

            if (effective_timeout_seconds > trouble_timeout_cap) {
                effective_timeout_seconds = trouble_timeout_cap;
                accelerated_for_read_trouble = 1;
            }
        }

        {
            unsigned long long validation_timeout_cap =
                raw_all_validation_stall_timeout_cap_seconds(&stage_state);

            if (validation_timeout_cap > 0ULL &&
                effective_timeout_seconds > validation_timeout_cap) {
                effective_timeout_seconds = validation_timeout_cap;
                accelerated_for_read_trouble = 1;
            }
        }
    }

    if (!have_saved_scan_state) {
        return 0;
    }
    if (!load_metadata_live_stats_for_supervisor(run_dir, &live_stats)) {
        memset(&live_stats, 0, sizeof(live_stats));
    }
    if (build_thread_activity_path_for_run_dir(
            run_dir,
            thread_activity_path,
            sizeof(thread_activity_path)) &&
        load_thread_activity_state_for_supervisor(
            thread_activity_path,
            &activity_state) &&
        activity_state.updated_unix >= child_started_at) {
        have_activity_state = 1;
    }

    if (build_read_trouble_map_path_for_run_dir(
            run_dir,
            trouble_map_path,
            sizeof(trouble_map_path)) &&
        load_best_trouble_map_entry_for_offset(
            trouble_map_path,
            state.scan_offset,
            RAW_ALL_FAR_AHEAD_BAD_READ_WINDOW_BYTES,
            &trouble_entry) &&
        trouble_entry.hit_count >= 2U) {
        unsigned long long repeated_trouble_timeout_cap =
            raw_all_scan_stall_cap_for_source_seconds(config, 60ULL);

        if (effective_timeout_seconds > repeated_trouble_timeout_cap) {
            effective_timeout_seconds = repeated_trouble_timeout_cap;
            accelerated_for_read_trouble = 1;
        }
    }

    if ((stage_audio_validation || stage_video_validation) &&
        build_read_trouble_map_path_for_run_dir(
            run_dir,
            trouble_map_path,
            sizeof(trouble_map_path))) {
        ReadTroubleMapTractSummary tract_summary = {0};

        if (load_trouble_map_tract_summary_for_offset(
                trouble_map_path,
                state.scan_offset,
                RAW_ALL_TRACT_TROUBLE_WINDOW_BYTES,
                &tract_summary) &&
            tract_summary.zone_count >= 2U) {
            if ((stage_validator_red ||
                 tract_summary.total_hit_count >= 10U ||
                 tract_summary.zone_count >= 4U) &&
                effective_timeout_seconds > 30ULL) {
                effective_timeout_seconds = 30ULL;
                accelerated_for_read_trouble = 1;
            } else if ((stage_validator_yellow ||
                        tract_summary.total_hit_count >= 6U ||
                        tract_summary.zone_count >= 3U) &&
                       effective_timeout_seconds > 45ULL) {
                effective_timeout_seconds = 45ULL;
                accelerated_for_read_trouble = 1;
            } else if (tract_summary.total_hit_count >= 3U &&
                       effective_timeout_seconds > 60ULL) {
                effective_timeout_seconds = 60ULL;
                accelerated_for_read_trouble = 1;
            }
        }
    }

    if (have_scan_loop_stage &&
        raw_all_supervisor_metadata_progress_is_recent(
            run_dir,
            child_started_at,
            now,
            effective_timeout_seconds,
            &live_stats,
            &stage_state,
            have_activity_state ? &activity_state : NULL,
            stage_progress_stalled_seconds)) {
        return 0;
    }

    if (stat(scan_state_path, &scan_state_stat) != 0 ||
        stat(stats_path, &stats_stat) != 0) {
        return 0;
    }
    latest_progress_mtime = scan_state_stat.st_mtime;
    if (!have_scan_loop_stage && stats_stat.st_mtime > latest_progress_mtime) {
        latest_progress_mtime = stats_stat.st_mtime;
    }
    if (child_started_at > 0 && latest_progress_mtime < child_started_at) {
        return 0;
    }

    if (saved_scan_completed || state.scan_completed || state.completed) {
        return 0;
    }

    if (live_stats.background_phase != FS_BACKEND_BACKGROUND_PHASE_IDLE) {
        return 0;
    }

    effective_stalled_seconds =
        (unsigned long long)live_stats.scan_stalled_seconds;
    if (latest_progress_mtime > 0 && now >= latest_progress_mtime) {
        unsigned long long inferred_silent_seconds =
            (unsigned long long)(now - latest_progress_mtime);
        if (inferred_silent_seconds > effective_stalled_seconds) {
            effective_stalled_seconds = inferred_silent_seconds;
            inferred_from_silent_state = 1;
        }
    }
    if (have_scan_loop_stage &&
        stage_progress_stalled_seconds > effective_stalled_seconds) {
        effective_stalled_seconds = stage_progress_stalled_seconds;
    }

    if (out_effective_timeout_seconds != NULL) {
        *out_effective_timeout_seconds = effective_timeout_seconds;
    }
    if (out_accelerated_for_read_trouble != NULL) {
        *out_accelerated_for_read_trouble = accelerated_for_read_trouble;
    }
    if (out_inferred_from_silent_state != NULL) {
        *out_inferred_from_silent_state = inferred_from_silent_state;
    }

    return effective_stalled_seconds >= effective_timeout_seconds;
}

static int terminate_supervised_child(pid_t child_pid)
{
    int status = 0;
    int polls = 0;
    const int term_polls = 50;
    const int kill_polls = 300;

    if (child_pid <= 0) {
        return 0;
    }

    (void)kill(-child_pid, SIGTERM);
    (void)kill(child_pid, SIGTERM);
    if (app_stop_requested()) {
        app_note_shutdown_progress("waiting for stalled child to stop");
        return 0;
    }
    for (polls = 0; polls < term_polls; polls++) {
        pid_t waited = waitpid(child_pid, &status, WNOHANG);
        if (waited == child_pid) {
            return 1;
        }
        if (waited < 0) {
            return 0;
        }
        if (app_stop_requested()) {
            app_note_shutdown_progress("waiting for stalled child to stop");
            return 0;
        }
        usleep(100000);
    }

    log_runtime_event_error(
        "Raw-all stall retry: child did not stop after SIGTERM; escalating to SIGKILL and waiting for the OS to release the blocked read"
    );
    (void)kill(-child_pid, SIGKILL);
    (void)kill(child_pid, SIGKILL);
    if (app_stop_requested()) {
        app_note_shutdown_progress("waiting for stalled child after SIGKILL");
        return 0;
    }
    for (polls = 0; polls < kill_polls; polls++) {
        pid_t waited = waitpid(child_pid, &status, WNOHANG);
        if (waited == child_pid) {
            return 1;
        }
        if (waited < 0) {
            return 0;
        }
        if (app_stop_requested()) {
            app_note_shutdown_progress("waiting for stalled child after SIGKILL");
            return 0;
        }
        if (polls > 0 && (polls % 50) == 0) {
            log_runtime_event_error(
                "Raw-all stall retry: still waiting %.1f seconds for the stalled child to exit after SIGKILL",
                (double)polls * 0.1
            );
        }
        usleep(100000);
    }

    return 0;
}

static void set_supervised_child_process_group(pid_t child_pid)
{
    if (child_pid <= 0) {
        return;
    }

    if (setpgid(child_pid, child_pid) != 0 &&
        errno != EACCES &&
        errno != ESRCH &&
        errno != EPERM) {
        log_runtime_event_error(
            "Could not move supervised child pid=%ld into its own process group (%s); stop/kill may be less reliable for nested helper processes",
            (long)child_pid,
            strerror(errno)
        );
    }
}

static unsigned long long age_seconds_from_time_local(time_t now, time_t then)
{
    if (then <= 0) {
        return ULLONG_MAX;
    }
    if (now >= then) {
        return (unsigned long long)(now - then);
    }
    return 0ULL;
}

static void format_wait_status_local(
    int status,
    char *out,
    size_t out_size
)
{
    if (out == NULL || out_size == 0U) {
        return;
    }

    if (WIFEXITED(status)) {
        snprintf(out, out_size, "exit_code=%d", WEXITSTATUS(status));
        return;
    }
    if (WIFSIGNALED(status)) {
#ifdef WCOREDUMP
        snprintf(
            out,
            out_size,
            "signal=%d%s",
            WTERMSIG(status),
            WCOREDUMP(status) ? " core=1" : ""
        );
#else
        snprintf(out, out_size, "signal=%d", WTERMSIG(status));
#endif
        return;
    }

    snprintf(out, out_size, "status=0x%x", status);
}

static void log_raw_all_child_exit_diagnostics(
    const char *run_dir,
    pid_t child_pid,
    int status,
    time_t child_started_at,
    unsigned long long generation,
    const char *decision,
    int crash_attempts_used,
    int stall_attempts_used,
    int startup_stall_attempts_used,
    int total_retry_attempts_used,
    int total_retry_limit
)
{
    char status_text[80];
    char scan_state_path[PATH_MAX_LEN];
    char stage_path[PATH_MAX_LEN];
    char progress_path[PATH_MAX_LEN];
    ScanState scan_state = {0};
    RawAllStageState stage_state = {0};
    PrimaryMetadataProgressState progress_state = {0};
    FsBackendLiveStats live_stats = {0};
    time_t now = time(NULL);
    int have_scan_state = 0;
    int have_stage = 0;
    int have_progress = 0;
    int have_live_stats = 0;
    unsigned long long elapsed =
        age_seconds_from_time_local(now, child_started_at);

    format_wait_status_local(status, status_text, sizeof(status_text));
    log_runtime_event_error(
        "Raw-all supervised child stopped unexpectedly: pid=%ld generation=%llu %s elapsed=%llus decision=%s retries(total=%d/%d crash=%d stall=%d startup=%d)",
        (long)child_pid,
        generation,
        status_text,
        elapsed,
        (decision != NULL && decision[0] != '\0') ? decision : "none",
        total_retry_attempts_used,
        total_retry_limit,
        crash_attempts_used,
        stall_attempts_used,
        startup_stall_attempts_used
    );

    if (run_dir == NULL || run_dir[0] == '\0') {
        log_runtime_event_error(
            "Raw-all child exit diagnostics could not read state files because run_dir was empty"
        );
        return;
    }

    if (build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path))) {
        have_scan_state = scan_state_load(scan_state_path, &scan_state);
    }
    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path))) {
        have_stage = load_raw_all_stage_state(stage_path, &stage_state);
    }
    if (build_primary_metadata_progress_path_for_run_dir(
            run_dir,
            progress_path,
            sizeof(progress_path))) {
        have_progress =
            load_primary_metadata_progress_state(progress_path, &progress_state);
    }
    have_live_stats = load_metadata_live_stats_for_supervisor(run_dir, &live_stats);

    if (have_stage) {
        log_runtime_event_error(
            "Raw-all child last stage: stage=%s activity=%s progress=%llu/%llu elapsed=%llus budget_elapsed=%llus stalled=%llus trouble=%s validator=%s updated_age=%llus",
            stage_state.stage[0] != '\0' ? stage_state.stage : "(empty)",
            stage_state.activity[0] != '\0' ? stage_state.activity : "(empty)",
            (unsigned long long)stage_state.progress_bytes,
            (unsigned long long)stage_state.total_bytes,
            stage_state.elapsed_seconds,
            stage_state.budget_elapsed_seconds,
            stage_state.stalled_seconds,
            stage_state.trouble_budget[0] != '\0'
                ? stage_state.trouble_budget
                : "(empty)",
            stage_state.validator_budget[0] != '\0'
                ? stage_state.validator_budget
                : "(empty)",
            age_seconds_from_time_local(now, stage_state.updated_unix)
        );
    } else {
        log_runtime_event_error(
            "Raw-all child exit diagnostics found no readable raw_all_stage.txt"
        );
    }

    if (have_progress) {
        log_runtime_event_error(
            "Raw-all child metadata progress: phase=%s step=%s records=%llu bytes_scanned=%llu reader_offset=%llu range=%llu..%llu primary_runs=%zu i30_names=%zu record_index=%zu range_index=%zu read_errors=%llu updated_age=%llus",
            progress_state.phase_label[0] != '\0'
                ? progress_state.phase_label
                : "(empty)",
            progress_state.step[0] != '\0' ? progress_state.step : "(empty)",
            (unsigned long long)progress_state.records_observed,
            (unsigned long long)progress_state.bytes_scanned,
            (unsigned long long)progress_state.reader_offset,
            (unsigned long long)progress_state.range_start,
            (unsigned long long)progress_state.range_end,
            progress_state.primary_run_count,
            progress_state.directory_index_names,
            progress_state.record_index_count,
            progress_state.range_index_count,
            (unsigned long long)progress_state.read_errors,
            age_seconds_from_time_local(now, progress_state.updated_unix)
        );
    } else {
        log_runtime_event_error(
            "Raw-all child exit diagnostics found no readable primary_metadata_progress.txt"
        );
    }

    if (have_scan_state) {
        log_runtime_event_error(
            "Raw-all child saved scan state: source_size=%llu scan_offset=%llu scan_completed=%d completed=%d source=%s",
            (unsigned long long)scan_state.source_size,
            (unsigned long long)scan_state.scan_offset,
            scan_state.scan_completed,
            scan_state.completed,
            scan_state.source_path[0] != '\0'
                ? scan_state.source_path
                : "(empty)"
        );
    } else {
        log_runtime_event_error(
            "Raw-all child exit diagnostics found no readable scan_state.txt"
        );
    }

    if (have_live_stats) {
        log_runtime_event_error(
            "Raw-all child live stats at exit: recovered=%llu named=%llu unident=%llu repair_pending=%llu record_index=%zu range_index=%zu scan_stalled=%llus background_phase=%u conservative=%u",
            (unsigned long long)live_stats.recovered_outputs_current,
            (unsigned long long)live_stats.named_outputs_current,
            (unsigned long long)live_stats.unident_outputs_current,
            (unsigned long long)live_stats.repair_pending_outputs,
            live_stats.record_index_count,
            live_stats.range_index_count,
            (unsigned long long)live_stats.scan_stalled_seconds,
            live_stats.background_phase,
            live_stats.background_conservative
        );
    } else {
        log_runtime_event_error(
            "Raw-all child exit diagnostics found no readable metadata/spool live stats"
        );
    }
}

static uint64_t raw_all_crash_snapshot_source_size_for_run_dir(
    const char *run_dir,
    const ScanState *scan_state,
    int have_scan_state,
    const RawAllStageState *stage_state,
    int have_stage
)
{
    char scan_state_path[PATH_MAX_LEN];
    char stage_path[PATH_MAX_LEN];
    ScanState loaded_scan_state = {0};
    RawAllStageState loaded_stage_state = {0};

    if (have_scan_state &&
        scan_state != NULL &&
        scan_state->source_size > 0ULL) {
        return scan_state->source_size;
    }
    if (have_stage &&
        stage_state != NULL &&
        stage_state->total_bytes > 0ULL) {
        return stage_state->total_bytes;
    }
    if (build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path)) &&
        scan_state_load(scan_state_path, &loaded_scan_state) &&
        loaded_scan_state.source_size > 0ULL) {
        return loaded_scan_state.source_size;
    }
    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path)) &&
        load_raw_all_stage_state(stage_path, &loaded_stage_state) &&
        loaded_stage_state.total_bytes > 0ULL) {
        return loaded_stage_state.total_bytes;
    }
    return 0ULL;
}

static void write_raw_all_crash_breadcrumbs_for_run_dir(
    const char *run_dir,
    pid_t child_pid,
    int status,
    time_t child_started_at,
    unsigned long long generation,
    const char *event_label,
    const char *decision,
    int crash_attempts_used,
    int stall_attempts_used,
    int startup_stall_attempts_used,
    int total_retry_attempts_used,
    int total_retry_limit
)
{
    char summary_path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    char breadcrumbs_path[PATH_MAX_LEN];
    char scan_state_path[PATH_MAX_LEN];
    char stage_path[PATH_MAX_LEN];
    char progress_path[PATH_MAX_LEN];
    char last_bad_path[PATH_MAX_LEN];
    char status_text[80];
    ScanState scan_state = {0};
    RawAllStageState stage_state = {0};
    PrimaryMetadataProgressState progress_state = {0};
    FsBackendLiveStats live_stats = {0};
    LastBadReadState last_bad = {0};
    time_t now = time(NULL);
    unsigned long long elapsed =
        age_seconds_from_time_local(now, child_started_at);
    uint64_t source_size = 0ULL;
    size_t coverage_gap_count = 0U;
    uint64_t coverage_gap_bytes = 0ULL;
    int coverage_available = 0;
    int coverage_snapshot_written = 0;
    int have_scan_state = 0;
    int have_stage = 0;
    int have_progress = 0;
    int have_live_stats = 0;
    int have_last_bad = 0;
    int signal_number = 0;
    int core_dumped = 0;
    size_t fs_recovered = 0U;
    size_t fs_named = 0U;
    size_t fs_unident = 0U;
    FILE *file;

    if (!has_nonempty_text(run_dir) ||
        !ensure_raw_all_supervisor_state_dir(run_dir)) {
        return;
    }

    format_wait_status_local(status, status_text, sizeof(status_text));
    if (WIFSIGNALED(status)) {
        signal_number = WTERMSIG(status);
#ifdef WCOREDUMP
        core_dumped = WCOREDUMP(status) ? 1 : 0;
#endif
    }

    if (build_scan_state_path(run_dir, scan_state_path, sizeof(scan_state_path))) {
        have_scan_state = scan_state_load(scan_state_path, &scan_state);
    }
    if (build_raw_all_stage_path_for_run_dir(
            run_dir,
            stage_path,
            sizeof(stage_path))) {
        have_stage = load_raw_all_stage_state(stage_path, &stage_state);
    }
    if (build_primary_metadata_progress_path_for_run_dir(
            run_dir,
            progress_path,
            sizeof(progress_path))) {
        have_progress =
            load_primary_metadata_progress_state(progress_path, &progress_state);
    }
    have_live_stats = load_metadata_live_stats_for_supervisor(run_dir, &live_stats);
    if (build_last_bad_read_path_for_run_dir(
            run_dir,
            last_bad_path,
            sizeof(last_bad_path))) {
        have_last_bad = load_last_bad_read_state(last_bad_path, &last_bad);
    }

    source_size = raw_all_crash_snapshot_source_size_for_run_dir(
        run_dir,
        &scan_state,
        have_scan_state,
        &stage_state,
        have_stage
    );
    if (source_size > 0ULL) {
        coverage_snapshot_written = write_coverage_gap_snapshot_for_run_dir(
            run_dir,
            source_size,
            "on_raw_all_child_crash",
            has_nonempty_text(decision) ? decision : "child_crash",
            &coverage_gap_count,
            &coverage_gap_bytes,
            &coverage_available
        );
    }

    fs_recovered = app_best_effort_recovered_count_for_run(run_dir);
    fs_named = app_best_effort_named_count_for_run(run_dir);
    fs_unident = app_best_effort_unident_count_for_run(run_dir);

    if (build_state_child_path_local(run_dir, "raw_all_crash_summary.txt", summary_path, sizeof(summary_path)) &&
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", summary_path) <
            (int)sizeof(temp_path)) {
        file = fopen(temp_path, "w");
        if (file != NULL) {
            fprintf(file, "version=1\n");
            fprintf(file, "summary_kind=raw_all_crash_snapshot\n");
            fprintf(file, "updated_unix=%llu\n", (unsigned long long)now);
            fprintf(file, "event=%s\n", has_nonempty_text(event_label) ? event_label : "child_crash");
            fprintf(file, "pid=%ld\n", (long)child_pid);
            fprintf(file, "generation=%llu\n", generation);
            fprintf(file, "wait_status=%s\n", status_text);
            fprintf(file, "signal=%d\n", signal_number);
            fprintf(file, "core_dumped=%d\n", core_dumped);
            fprintf(file, "decision=%s\n", has_nonempty_text(decision) ? decision : "");
            fprintf(file, "elapsed_seconds=%llu\n", elapsed);
            fprintf(file, "retries_total=%d\n", total_retry_attempts_used);
            fprintf(file, "retries_total_limit=%d\n", total_retry_limit);
            fprintf(file, "retries_crash=%d\n", crash_attempts_used);
            fprintf(file, "retries_stall=%d\n", stall_attempts_used);
            fprintf(file, "retries_startup=%d\n", startup_stall_attempts_used);
            fprintf(file, "source_size=%llu\n", (unsigned long long)source_size);
            fprintf(file, "scan_state_available=%d\n", have_scan_state);
            fprintf(file, "scan_source=%s\n", have_scan_state ? scan_state.source_path : "");
            fprintf(file, "scan_offset=%llu\n", (unsigned long long)(have_scan_state ? scan_state.scan_offset : 0ULL));
            fprintf(file, "scan_completed=%d\n", have_scan_state ? scan_state.scan_completed : 0);
            fprintf(file, "completed=%d\n", have_scan_state ? scan_state.completed : 0);
            fprintf(file, "stage_available=%d\n", have_stage);
            fprintf(file, "stage=%s\n", have_stage ? stage_state.stage : "");
            fprintf(file, "activity=%s\n", have_stage ? stage_state.activity : "");
            fprintf(file, "stage_detail=%s\n", have_stage ? stage_state.detail : "");
            fprintf(file, "stage_progress_bytes=%llu\n", (unsigned long long)(have_stage ? stage_state.progress_bytes : 0ULL));
            fprintf(file, "stage_total_bytes=%llu\n", (unsigned long long)(have_stage ? stage_state.total_bytes : 0ULL));
            fprintf(file, "primary_metadata_available=%d\n", have_progress);
            fprintf(file, "primary_phase=%s\n", have_progress ? progress_state.phase_label : "");
            fprintf(file, "primary_step=%s\n", have_progress ? progress_state.step : "");
            fprintf(file, "primary_records=%llu\n", (unsigned long long)(have_progress ? progress_state.records_observed : 0ULL));
            fprintf(file, "primary_bytes_scanned=%llu\n", (unsigned long long)(have_progress ? progress_state.bytes_scanned : 0ULL));
            fprintf(file, "primary_reader_offset=%llu\n", (unsigned long long)(have_progress ? progress_state.reader_offset : 0ULL));
            fprintf(file, "primary_runs=%zu\n", have_progress ? progress_state.primary_run_count : 0U);
            fprintf(file, "i30_names=%zu\n", have_progress ? progress_state.directory_index_names : 0U);
            fprintf(file, "record_index=%zu\n", have_progress ? progress_state.record_index_count : 0U);
            fprintf(file, "range_index=%zu\n", have_progress ? progress_state.range_index_count : 0U);
            fprintf(file, "primary_read_errors=%llu\n", (unsigned long long)(have_progress ? progress_state.read_errors : 0ULL));
            fprintf(file, "live_stats_available=%d\n", have_live_stats);
            fprintf(file, "live_recovered=%llu\n", (unsigned long long)(have_live_stats ? live_stats.recovered_outputs_current : 0ULL));
            fprintf(file, "live_named=%llu\n", (unsigned long long)(have_live_stats ? live_stats.named_outputs_current : 0ULL));
            fprintf(file, "live_unident=%llu\n", (unsigned long long)(have_live_stats ? live_stats.unident_outputs_current : 0ULL));
            fprintf(file, "last_bad_read_available=%d\n", have_last_bad);
            fprintf(file, "last_bad_kind=%s\n", have_last_bad ? last_bad.kind : "");
            fprintf(file, "last_bad_offset=%llu\n", (unsigned long long)(have_last_bad ? last_bad.offset : 0ULL));
            fprintf(file, "last_bad_end=%llu\n", (unsigned long long)(have_last_bad ? last_bad.end_offset : 0ULL));
            fprintf(file, "last_bad_length=%llu\n", (unsigned long long)(have_last_bad ? last_bad.length : 0ULL));
            fprintf(file, "last_bad_errno=%d\n", have_last_bad ? last_bad.errno_code : 0);
            fprintf(file, "coverage_snapshot_written=%d\n", coverage_snapshot_written);
            fprintf(file, "coverage_available=%d\n", coverage_available);
            fprintf(file, "coverage_gap_count=%zu\n", coverage_gap_count);
            fprintf(file, "coverage_gap_bytes=%llu\n", (unsigned long long)coverage_gap_bytes);
            fprintf(file, "fs_recovered=%zu\n", fs_recovered);
            fprintf(file, "fs_named=%zu\n", fs_named);
            fprintf(file, "fs_unident=%zu\n", fs_unident);

            if (fclose(file) != 0) {
                (void)unlink(temp_path);
            } else if (rename(temp_path, summary_path) != 0) {
                (void)unlink(temp_path);
            }
        }
    }

    if (build_state_child_path_local(run_dir, "raw_all_crash_breadcrumbs.tsv", breadcrumbs_path, sizeof(breadcrumbs_path))) {
        struct stat st;
        int write_header = stat(breadcrumbs_path, &st) != 0 || st.st_size == 0;

        file = fopen(breadcrumbs_path, write_header ? "w" : "a");
        if (file != NULL) {
            if (write_header) {
                fprintf(
                    file,
                    "updated_unix\tgeneration\tpid\tevent\twait_status\tsignal\tcore_dumped\tdecision\telapsed_seconds\tretries_total\tretries_total_limit\tretries_crash\tretries_stall\tretries_startup\tsource_path\tsource_size\tscan_offset\tscan_completed\tcompleted\tstage\tactivity\tprogress_bytes\ttotal_bytes\tprimary_phase\tprimary_records\tprimary_reader_offset\tprimary_runs\ti30_names\trecord_index\trange_index\tlive_recovered\tlive_named\tlive_unident\tlast_bad_kind\tlast_bad_offset\tlast_bad_end\tlast_bad_errno\tcoverage_available\tcoverage_gap_count\tcoverage_gap_bytes\tfs_recovered\tfs_named\tfs_unident\n"
                );
            }
            fprintf(
                file,
                "%llu\t%llu\t%ld\t",
                (unsigned long long)now,
                generation,
                (long)child_pid
            );
            write_tsv_text_field_local(file, has_nonempty_text(event_label) ? event_label : "child_crash");
            fputc('\t', file);
            write_tsv_text_field_local(file, status_text);
            fprintf(file, "\t%d\t%d\t", signal_number, core_dumped);
            write_tsv_text_field_local(file, has_nonempty_text(decision) ? decision : "");
            fprintf(
                file,
                "\t%llu\t%d\t%d\t%d\t%d\t%d\t",
                elapsed,
                total_retry_attempts_used,
                total_retry_limit,
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used
            );
            write_tsv_text_field_local(file, have_scan_state ? scan_state.source_path : "");
            fprintf(
                file,
                "\t%llu\t%llu\t%d\t%d\t",
                (unsigned long long)source_size,
                (unsigned long long)(have_scan_state ? scan_state.scan_offset : 0ULL),
                have_scan_state ? scan_state.scan_completed : 0,
                have_scan_state ? scan_state.completed : 0
            );
            write_tsv_text_field_local(file, have_stage ? stage_state.stage : "");
            fputc('\t', file);
            write_tsv_text_field_local(file, have_stage ? stage_state.activity : "");
            fprintf(
                file,
                "\t%llu\t%llu\t",
                (unsigned long long)(have_stage ? stage_state.progress_bytes : 0ULL),
                (unsigned long long)(have_stage ? stage_state.total_bytes : 0ULL)
            );
            write_tsv_text_field_local(file, have_progress ? progress_state.phase_label : "");
            fprintf(
                file,
                "\t%llu\t%llu\t%zu\t%zu\t%zu\t%zu\t%llu\t%llu\t%llu\t",
                (unsigned long long)(have_progress ? progress_state.records_observed : 0ULL),
                (unsigned long long)(have_progress ? progress_state.reader_offset : 0ULL),
                have_progress ? progress_state.primary_run_count : 0U,
                have_progress ? progress_state.directory_index_names : 0U,
                have_progress ? progress_state.record_index_count : 0U,
                have_progress ? progress_state.range_index_count : 0U,
                (unsigned long long)(have_live_stats ? live_stats.recovered_outputs_current : 0ULL),
                (unsigned long long)(have_live_stats ? live_stats.named_outputs_current : 0ULL),
                (unsigned long long)(have_live_stats ? live_stats.unident_outputs_current : 0ULL)
            );
            write_tsv_text_field_local(file, have_last_bad ? last_bad.kind : "");
            fprintf(
                file,
                "\t%llu\t%llu\t%d\t%d\t%zu\t%llu\t%zu\t%zu\t%zu\n",
                (unsigned long long)(have_last_bad ? last_bad.offset : 0ULL),
                (unsigned long long)(have_last_bad ? last_bad.end_offset : 0ULL),
                have_last_bad ? last_bad.errno_code : 0,
                coverage_available,
                coverage_gap_count,
                (unsigned long long)coverage_gap_bytes,
                fs_recovered,
                fs_named,
                fs_unident
            );
            fclose(file);
        }
    }

    log_runtime_event_error(
        "Raw-all crash breadcrumbs saved: status=%s event=%s scan_offset=%llu source_size=%llu coverage_gaps=%zu coverage_gap_bytes=%llu recovered=%zu named=%zu unident=%zu",
        status_text,
        has_nonempty_text(event_label) ? event_label : "child_crash",
        (unsigned long long)(have_scan_state ? scan_state.scan_offset : 0ULL),
        (unsigned long long)source_size,
        coverage_gap_count,
        (unsigned long long)coverage_gap_bytes,
        fs_recovered,
        fs_named,
        fs_unident
    );
}

static int stop_raw_all_supervisor_promptly(
    pid_t child_pid,
    const pid_t *abandoned_children,
    size_t abandoned_child_count,
    const char *generation_path,
    unsigned long long *io_current_generation,
    const char *run_dir,
    time_t child_started_at,
    unsigned long long active_generation,
    int installed_signal_handlers_here,
    const char *reason
)
{
    size_t stop_index;
    int status = 0;
    int current_child_reaped = 0;
    int stop_polls;
    unsigned long long session_generation = active_generation;

    if (session_generation == 0ULL && io_current_generation != NULL) {
        session_generation = *io_current_generation;
    }

    append_run_work_time_event_for_run_dir(
        run_dir,
        "child_stop_requested",
        session_generation,
        child_pid,
        child_started_at,
        time(NULL),
        1,
        reason != NULL ? reason : "stop_requested"
    );

    if (io_current_generation != NULL) {
        if (*io_current_generation < ULLONG_MAX) {
            (*io_current_generation)++;
        }
        if (!write_supervisor_generation_file(
                generation_path,
                *io_current_generation)) {
            log_runtime_event_error(
                "Stop requested, but the raw-all supervisor could not publish generation %llu; a blocked child may wake up later without realizing it is stale",
                *io_current_generation
            );
        }
    }

    log_runtime_event_error(
        "%s; invalidating the active raw-all generation and asking child pid=%ld to stop immediately",
        (reason != NULL && reason[0] != '\0')
            ? reason
            : "Stop requested",
        (long)child_pid
    );

    if (child_pid > 0) {
        (void)kill(-child_pid, SIGTERM);
        (void)kill(child_pid, SIGTERM);
    }
    for (stop_index = 0U; stop_index < abandoned_child_count; stop_index++) {
        if (abandoned_children != NULL && abandoned_children[stop_index] > 0) {
            (void)kill(-abandoned_children[stop_index], SIGTERM);
            (void)kill(abandoned_children[stop_index], SIGTERM);
        }
    }

    for (stop_polls = 0; stop_polls < 10; stop_polls++) {
        pid_t waited;

        if (child_pid <= 0) {
            current_child_reaped = 1;
            break;
        }
        waited = waitpid(child_pid, &status, WNOHANG);
        if (waited == child_pid) {
            current_child_reaped = 1;
            break;
        }
        if (waited < 0 && errno == ECHILD) {
            current_child_reaped = 1;
            break;
        }
        usleep(100000);
    }

    if (!current_child_reaped) {
        if (child_pid > 0) {
            (void)kill(-child_pid, SIGKILL);
            (void)kill(child_pid, SIGKILL);
        }
        for (stop_index = 0U; stop_index < abandoned_child_count; stop_index++) {
            if (abandoned_children != NULL && abandoned_children[stop_index] > 0) {
                (void)kill(-abandoned_children[stop_index], SIGKILL);
                (void)kill(abandoned_children[stop_index], SIGKILL);
            }
        }

        for (stop_polls = 0; stop_polls < 10; stop_polls++) {
            pid_t waited;

            if (child_pid <= 0) {
                current_child_reaped = 1;
                break;
            }
            waited = waitpid(child_pid, &status, WNOHANG);
            if (waited == child_pid) {
                current_child_reaped = 1;
                break;
            }
            if (waited < 0 && errno == ECHILD) {
                current_child_reaped = 1;
                break;
            }
            usleep(100000);
        }
    }

    if (!current_child_reaped) {
        log_runtime_event_error(
            "Stop requested but raw-all child is still blocked in kernel I/O; exiting supervisor promptly and leaving a stale child behind that will self-abort if it wakes later"
        );
    }

    {
        const char *scan_pass_id = getenv(GUI_PASS_ID_ENV);

        if (has_nonempty_text(run_dir) && has_nonempty_text(scan_pass_id)) {
            app_gui_end_pass_if_running(run_dir, scan_pass_id, "stopped");
        }
    }

    if (installed_signal_handlers_here) {
        app_restore_signal_handlers();
    }
    return 130;
}

static int stop_name_supervisor_promptly(
    pid_t child_pid,
    const char *generation_path,
    unsigned long long *io_current_generation,
    int installed_signal_handlers_here,
    const char *reason
)
{
    int status = 0;
    int reaped = 0;
    int polls;

    if (io_current_generation != NULL) {
        if (*io_current_generation < ULLONG_MAX) {
            (*io_current_generation)++;
        }
        if (!write_supervisor_generation_file(
                generation_path,
                *io_current_generation)) {
            log_runtime_event_error(
                "Stop requested, but the name-salvage supervisor could not publish generation %llu; a blocked child may wake up later without realizing it is stale",
                *io_current_generation
            );
        }
    }

    log_runtime_event_error(
        "%s; invalidating the active name-salvage generation and asking child pid=%ld to stop immediately",
        (reason != NULL && reason[0] != '\0')
            ? reason
            : "Stop requested",
        (long)child_pid
    );

    if (child_pid > 0) {
        (void)kill(-child_pid, SIGTERM);
        (void)kill(child_pid, SIGTERM);
    }
    for (polls = 0; polls < 10; polls++) {
        pid_t waited;

        if (child_pid <= 0) {
            reaped = 1;
            break;
        }
        waited = waitpid(child_pid, &status, WNOHANG);
        if (waited == child_pid) {
            reaped = 1;
            break;
        }
        if (waited < 0 && errno == ECHILD) {
            reaped = 1;
            break;
        }
        usleep(100000);
    }

    if (!reaped) {
        if (child_pid > 0) {
            (void)kill(-child_pid, SIGKILL);
            (void)kill(child_pid, SIGKILL);
        }
        for (polls = 0; polls < 10; polls++) {
            pid_t waited;

            if (child_pid <= 0) {
                reaped = 1;
                break;
            }
            waited = waitpid(child_pid, &status, WNOHANG);
            if (waited == child_pid) {
                reaped = 1;
                break;
            }
            if (waited < 0 && errno == ECHILD) {
                reaped = 1;
                break;
            }
            usleep(100000);
        }
    }

    if (!reaped) {
        log_runtime_event_error(
            "Stop requested but name-salvage child is still blocked in kernel I/O; exiting supervisor promptly and leaving a stale child behind that will self-abort if it wakes later"
        );
    }

    if (installed_signal_handlers_here) {
        app_restore_signal_handlers();
    }
    return 130;
}

static void reap_abandoned_supervised_children(pid_t *children, size_t *io_count)
{
    size_t i;
    size_t kept = 0U;

    if (children == NULL || io_count == NULL) {
        return;
    }

    for (i = 0U; i < *io_count; i++) {
        int status = 0;
        pid_t child_pid = children[i];
        pid_t waited;

        if (child_pid <= 0) {
            continue;
        }

        waited = waitpid(child_pid, &status, WNOHANG);
        if (waited == child_pid) {
            log_runtime_event_info(
                "Reaped previously abandoned raw-all child pid=%ld after the OS finally released the blocked read",
                (long)child_pid
            );
            continue;
        }
        if (waited < 0 && errno == ECHILD) {
            continue;
        }

        children[kept++] = child_pid;
    }

    *io_count = kept;
}

#ifdef __linux__
static void strip_linux_deleted_executable_suffix(char *path)
{
    static const char suffix[] = " (deleted)";
    size_t path_len;
    size_t suffix_len;

    if (!has_nonempty_text(path)) {
        return;
    }
    path_len = strlen(path);
    suffix_len = sizeof(suffix) - 1U;
    if (path_len > suffix_len &&
        strcmp(path + path_len - suffix_len, suffix) == 0) {
        path[path_len - suffix_len] = '\0';
    }
}
#endif

static int copy_supervisor_exec_candidate(
    const char *candidate,
    char *out,
    size_t out_size
)
{
    char *resolved = NULL;

    if (!has_nonempty_text(candidate) || out == NULL || out_size == 0U) {
        return 0;
    }
    resolved = realpath(candidate, NULL);
    if (resolved != NULL &&
        access(resolved, X_OK) == 0) {
        snprintf(out, out_size, "%s", resolved);
        free(resolved);
        return has_nonempty_text(out);
    }
    if (resolved != NULL) {
        free(resolved);
    }
    if (candidate[0] == '/' && access(candidate, X_OK) == 0) {
        snprintf(out, out_size, "%s", candidate);
        return has_nonempty_text(out);
    }
    return 0;
}

static int resolve_supervisor_exec_path(
    const char *argv0,
    char *out,
    size_t out_size
)
{
#ifdef __linux__
    char proc_path[PATH_MAX_LEN];
    ssize_t len;
#endif
#ifdef __APPLE__
    char dyld_path[PATH_MAX_LEN];
    uint32_t dyld_size = (uint32_t)sizeof(dyld_path);
#endif

    if (out == NULL || out_size == 0U) {
        return 0;
    }
    out[0] = '\0';

#ifdef __linux__
    len = readlink("/proc/self/exe", proc_path, sizeof(proc_path) - 1U);
    if (len > 0) {
        proc_path[len] = '\0';
        strip_linux_deleted_executable_suffix(proc_path);
        if (copy_supervisor_exec_candidate(proc_path, out, out_size)) {
            return 1;
        }
    }
#endif

#ifdef __APPLE__
    if (_NSGetExecutablePath(dyld_path, &dyld_size) == 0 &&
        copy_supervisor_exec_candidate(dyld_path, out, out_size)) {
        return 1;
    }
#endif

    return copy_supervisor_exec_candidate(argv0, out, out_size);
}

static int maybe_run_under_crash_supervisor(
    const AppConfig *config,
    int argc,
    char *argv[]
)
{
    char run_dir[1024];
    char generation_path[PATH_MAX_LEN];
    char supervisor_exec_path[PATH_MAX_LEN];
    char scan_pass_id[16] = "";
    unsigned long long current_generation = 1ULL;
    unsigned long long observed_generation = 0ULL;
    pid_t abandoned_children[32];
    size_t abandoned_child_count = 0U;
    int installed_signal_handlers_here = 0;
    int force_skip_mft_observation_retry = 0;
    int force_skip_retry_hotspots_retry = 0;
    int crash_attempts_used = 0;
    int startup_stall_attempts_used = 0;
    int stall_attempts_used = 0;
    int validator_escape_attempts_used = 0;
    int source_reconnect_attempts_used = 0;
    int total_retry_attempts_used = 0;
    int total_retry_limit = 0;
    uint64_t stall_retry_progress_anchor = 0ULL;

    supervisor_exec_path[0] = '\0';

    if (config == NULL ||
        argc <= 0 ||
        argv == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        config->hypersafe_folder_fetch ||
        config->hypersafe_strategy != APP_HYPERSAFE_STRATEGY_NONE ||
        getenv(CRASH_RETRY_CHILD_ENV) != NULL) {
        return -1;
    }

    if (raw_all_completed_resume_should_skip_deferred_hotspot_reread(config)) {
        return -1;
    }

    if (config->crash_retries <= 0 &&
        config->stall_retries <= 0) {
        return -1;
    }
    total_retry_limit = raw_all_supervisor_total_retry_limit(config);
    if (!build_run_output_dir_for_supervisor(config, run_dir, sizeof(run_dir)) ||
        !build_supervisor_generation_path_for_run_dir(
            run_dir,
            generation_path,
            sizeof(generation_path))) {
        return -1;
    }
    if (!resolve_supervisor_exec_path(
            (argc > 0 && argv != NULL) ? argv[0] : NULL,
            supervisor_exec_path,
            sizeof(supervisor_exec_path))) {
        log_runtime_event_error(
            "Raw-all supervisor could not resolve an absolute executable path; retry will fall back to argv[0]=%s and may fail if the current bundle directory is replaced or remounted",
            (argc > 0 && argv != NULL && has_nonempty_text(argv[0]))
                ? argv[0]
                : "(empty)"
        );
    }
    if (!g_signal_handlers_installed &&
        app_install_signal_handlers()) {
        installed_signal_handlers_here = 1;
    }
    memset(abandoned_children, 0, sizeof(abandoned_children));

    if (!ensure_raw_all_supervisor_state_dir(run_dir)) {
        log_runtime_event_error(
            "Could not create state directory for raw-all supervision under %s",
            run_dir
        );
    }
    if (getenv(GUI_PASS_ID_ENV) == NULL) {
        (void)app_gui_begin_pass(
            run_dir,
            "all",
            config->additive_pass ? "additive_scan" : "scan",
            config->additive_pass ? "Additive scan" : "All scan",
            "full_source",
            0ULL,
            0ULL,
            0ULL,
            scan_pass_id,
            sizeof(scan_pass_id)
        );
    } else {
        snprintf(scan_pass_id, sizeof(scan_pass_id), "%s", getenv(GUI_PASS_ID_ENV));
    }

    if (read_supervisor_generation_file(
            generation_path,
            &observed_generation) &&
        observed_generation > 0ULL) {
        current_generation =
            (observed_generation < ULLONG_MAX)
                ? (observed_generation + 1ULL)
                : observed_generation;
        log_runtime_event_info(
            "Raw-all supervisor detected an earlier generation token (%llu) for %s; this manual session will start at generation %llu so the new child can resume without being mistaken for stale work",
            observed_generation,
            run_dir,
            current_generation
        );
    }

    if (!write_supervisor_generation_file(
            generation_path,
            current_generation)) {
        log_runtime_event_error(
            "Could not publish initial raw-all supervisor generation %llu for %s before starting the first child; a resumed run may mistakenly see itself as stale",
            current_generation,
            run_dir
        );
    }

    stall_retry_progress_anchor = load_scan_offset_for_supervisor(run_dir);

    for (;;) {
        pid_t child_pid;
        int status = 0;
        int stalled_restart = 0;
        int abandoned_restart = 0;
        char generation_text[32];
        time_t child_started_at = 0;
        unsigned long long effective_stall_timeout_seconds = 0ULL;
        int accelerated_for_read_trouble = 0;
        int inferred_from_silent_state = 0;
        int startup_stage_stall = 0;
        int allow_retry_hotspots_skip_restart = 0;
        int allow_validator_escape_restart = 0;
        RawAllStageState stalled_child_stage = {0};
        RawAllStageState validator_escape_stage = {0};
        int coverage_zone_active = 0;
        int coverage_zone_timed_out = 0;
        unsigned long long coverage_zone_elapsed_seconds = 0ULL;
        CoverageGapRetryState coverage_retry_state = {0};
        int should_restart_for_stall = 0;
        char stalled_stage[64] = "";
        uint64_t latest_progress_offset = load_scan_offset_for_supervisor(run_dir);
        unsigned long long child_generation = current_generation;

        reap_abandoned_supervised_children(
            abandoned_children,
            &abandoned_child_count
        );

        if (latest_progress_offset >=
            stall_retry_progress_anchor + RAW_ALL_STALL_RETRY_RESET_PROGRESS_BYTES) {
            if (stall_attempts_used > 0) {
                log_runtime_event_info(
                    "Raw-all supervisor restored the stall-retry budget after %.1f GiB of forward scan progress",
                    (double)(latest_progress_offset - stall_retry_progress_anchor) /
                        (1024.0 * 1024.0 * 1024.0)
                );
            }
            stall_attempts_used = 0;
            validator_escape_attempts_used = 0;
            stall_retry_progress_anchor = latest_progress_offset;
        }

        child_started_at = time(NULL);

        if (!reset_metadata_live_stats_for_supervisor(run_dir)) {
            log_runtime_event_error(
                "Could not reset metadata_live_stats.txt before starting raw-all child generation %llu; stale stall counters may briefly confuse supervision",
                current_generation
            );
        }
        if (!reset_thread_activity_for_supervisor(run_dir)) {
            log_runtime_event_error(
                "Could not reset thread_activity.txt before starting raw-all child generation %llu; stale activity counters may briefly confuse supervision",
                current_generation
            );
        }
        if (!reset_raw_all_stage_for_supervisor(
                run_dir,
                monotonic_seconds_local())) {
            log_runtime_event_error(
                "Could not publish a fresh raw_all_stage.txt placeholder before starting raw-all child generation %llu; stale startup phase text may linger until the child reports in",
                current_generation
            );
        }

        child_pid = fork();
        if (child_pid < 0) {
            perror("fork");
            if (installed_signal_handlers_here) {
                app_restore_signal_handlers();
            }
            return 1;
        }
        if (child_pid == 0) {
            (void)setpgid(0, 0);
            (void)setenv(CRASH_RETRY_CHILD_ENV, "1", 1);
            if (force_skip_mft_observation_retry) {
                (void)setenv(RAW_ALL_SUPERVISED_SKIP_MFT_ENV, "1", 1);
            } else {
                (void)unsetenv(RAW_ALL_SUPERVISED_SKIP_MFT_ENV);
            }
            if (force_skip_retry_hotspots_retry) {
                (void)setenv(RAW_ALL_SUPERVISED_SKIP_RETRY_HOTSPOTS_ENV, "1", 1);
            } else {
                (void)unsetenv(RAW_ALL_SUPERVISED_SKIP_RETRY_HOTSPOTS_ENV);
            }
            snprintf(
                generation_text,
                sizeof(generation_text),
                "%llu",
                current_generation
            );
            if (has_nonempty_text(run_dir) && has_nonempty_text(scan_pass_id)) {
                (void)setenv(GUI_PASS_RUN_DIR_ENV, run_dir, 1);
                (void)setenv(GUI_PASS_ID_ENV, scan_pass_id, 1);
                (void)setenv(
                    GUI_SUPERVISOR_PASS_ID_ENV,
                    scan_pass_id,
                    1
                );
            }
            (void)setenv(SUPERVISOR_GENERATION_ENV, generation_text, 1);
            (void)setenv(SUPERVISOR_GENERATION_PATH_ENV, generation_path, 1);
            if (has_nonempty_text(supervisor_exec_path)) {
                execv(supervisor_exec_path, argv);
            }
            execvp(argv[0], argv);
            perror("execvp");
            _exit(127);
        }
        set_supervised_child_process_group(child_pid);

        for (;;) {
            pid_t waited = waitpid(child_pid, &status, WNOHANG);

            if (waited == child_pid) {
                break;
            }
            if (waited < 0) {
                perror("waitpid");
                if (installed_signal_handlers_here) {
                    app_restore_signal_handlers();
                }
                return 1;
            }

            if (app_stop_requested()) {
                return stop_raw_all_supervisor_promptly(
                    child_pid,
                    abandoned_children,
                    abandoned_child_count,
                    generation_path,
                    &current_generation,
                    run_dir,
                    child_started_at,
                    child_generation,
                    installed_signal_handlers_here,
                    "Stop requested"
                );
            }

            if (stall_attempts_used > 0) {
                uint64_t live_progress_offset =
                    load_best_live_scan_offset_for_supervisor(
                        run_dir,
                        child_started_at
                    );

                if (live_progress_offset >=
                    stall_retry_progress_anchor +
                        RAW_ALL_STALL_RETRY_RESET_PROGRESS_BYTES) {
                    log_runtime_event_info(
                        "Raw-all supervisor restored the stall-retry budget after %.1f GiB of forward scan progress in the current child",
                        (double)(live_progress_offset - stall_retry_progress_anchor) /
                            (1024.0 * 1024.0 * 1024.0)
                    );
                    stall_attempts_used = 0;
                    validator_escape_attempts_used = 0;
                    stall_retry_progress_anchor = live_progress_offset;
                }
            }

            coverage_zone_active = 0;
            coverage_zone_timed_out = 0;
            coverage_zone_elapsed_seconds = 0ULL;
            memset(&coverage_retry_state, 0, sizeof(coverage_retry_state));
            should_restart_for_stall =
                raw_all_child_should_restart_for_stall(
                    config,
                    run_dir,
                    child_started_at,
                    &effective_stall_timeout_seconds,
                    &accelerated_for_read_trouble,
                    &inferred_from_silent_state,
                    &startup_stage_stall,
                    stalled_stage,
                    sizeof(stalled_stage),
                    &stalled_child_stage);

            if (load_coverage_gap_retry_state_for_run_dir(
                    run_dir,
                    &coverage_retry_state) &&
                coverage_retry_state.supervisor_pid == getpid() &&
                coverage_retry_state.updated_unix >= child_started_at &&
                coverage_retry_state.zone_started_unix > 0 &&
                coverage_retry_state.chunk_end >
                    coverage_retry_state.chunk_start &&
                strcmp(coverage_retry_state.status, "scanning") == 0) {
                time_t coverage_now = time(NULL);

                coverage_zone_active = 1;
                if (coverage_now >= coverage_retry_state.zone_started_unix) {
                    coverage_zone_elapsed_seconds =
                        (unsigned long long)(
                            coverage_now -
                            coverage_retry_state.zone_started_unix);
                }
                /* raw_all_stage intentionally describes the whole outer
                 * post-scan pass as retry_hotspots.  The smaller durable state
                 * tells us this child is actually inside a coverage chunk. */
                if (should_restart_for_stall) {
                    startup_stage_stall = 1;
                    snprintf(
                        stalled_stage,
                        sizeof(stalled_stage),
                        "%s",
                        "coverage_gap_retry");
                }
                if (coverage_zone_elapsed_seconds >=
                    RAW_ALL_COVERAGE_ZONE_MAX_SECONDS) {
                    coverage_zone_timed_out = 1;
                    should_restart_for_stall = 1;
                    startup_stage_stall = 1;
                    effective_stall_timeout_seconds =
                        RAW_ALL_COVERAGE_ZONE_MAX_SECONDS;
                    snprintf(
                        stalled_stage,
                        sizeof(stalled_stage),
                        "%s",
                        "coverage_gap_retry");
                }
            }
            allow_retry_hotspots_skip_restart =
                should_restart_for_stall &&
                startup_stage_stall &&
                strcmp(stalled_stage, "retry_hotspots") == 0 &&
                !force_skip_retry_hotspots_retry;
            allow_validator_escape_restart =
                should_restart_for_stall &&
                !startup_stage_stall &&
                stall_attempts_used >= config->stall_retries &&
                validator_escape_attempts_used <
                    RAW_ALL_VALIDATOR_ESCAPE_LIMIT_PER_PROGRESS_WAVE &&
                raw_all_stalled_stage_is_candidate_validation(
                    run_dir,
                    child_started_at,
                    &validator_escape_stage);

            if ((should_restart_for_stall &&
                    ((startup_stage_stall
                        ? startup_stall_attempts_used
                        : stall_attempts_used) < config->stall_retries)) ||
                allow_retry_hotspots_skip_restart ||
                allow_validator_escape_restart ||
                coverage_zone_timed_out) {
                uint64_t silent_trouble_start = 0ULL;
                uint64_t silent_trouble_end = 0ULL;
                uint64_t silent_trouble_hits = 0ULL;
                uint64_t silent_trouble_anchor = 0ULL;
                int child_terminated_for_retry = 0;
                int skip_retry_hotspots_on_next_retry =
                    allow_retry_hotspots_skip_restart;
                int escape_stalled_validator_on_next_retry =
                    allow_validator_escape_restart;
                int retrying_coverage_zone_on_next_retry =
                    coverage_zone_active && should_restart_for_stall;
                int abandon_coverage_zone_on_next_retry =
                    coverage_zone_timed_out;

                if (app_stop_requested()) {
                    return stop_raw_all_supervisor_promptly(
                        child_pid,
                        abandoned_children,
                        abandoned_child_count,
                        generation_path,
                        &current_generation,
                        run_dir,
                        child_started_at,
                        child_generation,
                        installed_signal_handlers_here,
                        "Stop requested while a raw-all stall retry was about to start"
                    );
                }

                if (effective_stall_timeout_seconds == 0ULL) {
                    effective_stall_timeout_seconds = config->stall_timeout_seconds;
                }
                if (!startup_stage_stall) {
                    silent_trouble_anchor = load_best_live_scan_offset_for_supervisor(
                        run_dir,
                        child_started_at
                    );
                    if (silent_trouble_anchor == 0ULL) {
                        silent_trouble_anchor = load_scan_offset_for_supervisor(run_dir);
                    }
                    if (silent_trouble_anchor > 0ULL &&
                        remember_silent_stall_trouble_zone(
                            config,
                            run_dir,
                            silent_trouble_anchor,
                            &silent_trouble_start,
                            &silent_trouble_end,
                            &silent_trouble_hits)) {
                        log_runtime_event_info(
                            "Recorded suspected raw-all trouble zone %llu..%llu after a stalled child around scan offset %llu (hits=%llu); the next retry will treat this area as a problem region even without a clean read-fail callback",
                            (unsigned long long)silent_trouble_start,
                            (unsigned long long)silent_trouble_end,
                            (unsigned long long)silent_trouble_anchor,
                            (unsigned long long)silent_trouble_hits
                        );
                    }
                }
                if (abandon_coverage_zone_on_next_retry) {
                    force_skip_retry_hotspots_retry = 1;
                    log_runtime_event_error(
                        "Coverage retry zone %.2f-%.2f GiB reached its hard %llu-second wall-clock limit across %zu attempt%s; Carv will record it as unreadable and continue automatically with the next uncovered zone",
                        (double)coverage_retry_state.chunk_start /
                            (1024.0 * 1024.0 * 1024.0),
                        (double)coverage_retry_state.chunk_end /
                            (1024.0 * 1024.0 * 1024.0),
                        RAW_ALL_COVERAGE_ZONE_MAX_SECONDS,
                        coverage_retry_state.zone_attempts,
                        coverage_retry_state.zone_attempts == 1U ? "" : "s"
                    );
                } else if (retrying_coverage_zone_on_next_retry) {
                    force_skip_retry_hotspots_retry = 1;
                    log_runtime_event_error(
                        "Coverage retry zone %.2f-%.2f GiB stopped making progress after %llu seconds in this child (%llu/%llu seconds used across restarts); restarting the same bounded zone without repeating earlier hotspot work",
                        (double)coverage_retry_state.chunk_start /
                            (1024.0 * 1024.0 * 1024.0),
                        (double)coverage_retry_state.chunk_end /
                            (1024.0 * 1024.0 * 1024.0),
                        effective_stall_timeout_seconds,
                        coverage_zone_elapsed_seconds,
                        RAW_ALL_COVERAGE_ZONE_MAX_SECONDS
                    );
                } else if (skip_retry_hotspots_on_next_retry) {
                    force_skip_retry_hotspots_retry = 1;
                    log_runtime_event_error(
                        "Deferred hotspot reread made no useful progress after the primary raw scan had already finished; the next retry will skip retry_hotspots and continue straight to finalize/name so a damaged disk cannot get stuck here overnight"
                    );
                } else if (escape_stalled_validator_on_next_retry) {
                    log_runtime_event_error(
                        "A single raw format validator still made no useful progress after the ordinary stall retry budget was exhausted; quarantining its candidate range and restarting beyond it instead of leaving recovery spinning forever"
                    );
                } else if (startup_stage_stall) {
                    log_runtime_event_error(
                        "Raw-all startup appears stalled during %s for %llu seconds before entering the main scan loop; attempting stall retry %d/%d",
                        stalled_stage[0] != '\0' ? stalled_stage : "startup",
                        effective_stall_timeout_seconds,
                        startup_stall_attempts_used + 1,
                        config->stall_retries
                    );
                } else if (accelerated_for_read_trouble) {
                    log_runtime_event_error(
                        "Raw-all child appears stalled in I/O for %llu seconds with no scan progress after earlier read trouble%s; using a shorter stall threshold and attempting stall retry %d/%d",
                        effective_stall_timeout_seconds,
                        inferred_from_silent_state ? " (child state files went silent)" : "",
                        stall_attempts_used + 1,
                        config->stall_retries
                    );
                } else {
                    log_runtime_event_error(
                        "Raw-all child appears stalled in I/O for %llu seconds with no scan progress%s; attempting stall retry %d/%d",
                        effective_stall_timeout_seconds,
                        inferred_from_silent_state ? " (child state files went silent)" : "",
                        stall_attempts_used + 1,
                        config->stall_retries
                    );
                }
                if (!skip_retry_hotspots_on_next_retry &&
                    startup_stage_stall &&
                    !force_skip_mft_observation_retry &&
                    raw_all_startup_stage_should_skip_mft_on_retry(
                        config,
                        stalled_stage)) {
                    force_skip_mft_observation_retry = 1;
                    raw_all_mark_metadata_followup_required(
                        run_dir,
                        "supervisor_forced_metadata_skip_after_startup_stall"
                    );
                    log_runtime_event_error(
                        "Because the stall happened during raw-all startup before any real scan progress, the next retry will temporarily skip live filesystem metadata observation and continue with raw recovery only"
                    );
                }
                child_terminated_for_retry = terminate_supervised_child(child_pid);
                accumulate_raw_all_stage_budget_elapsed_for_supervisor(
                    run_dir,
                    child_started_at,
                    1,
                    0ULL
                );
                if (app_stop_requested()) {
                    return stop_raw_all_supervisor_promptly(
                        child_pid,
                        abandoned_children,
                        abandoned_child_count,
                        generation_path,
                        &current_generation,
                        run_dir,
                        child_started_at,
                        child_generation,
                        installed_signal_handlers_here,
                        child_terminated_for_retry
                            ? "Stop requested while preparing a raw-all stall retry"
                            : "Stop requested while waiting for a stalled raw-all child to exit"
                    );
                }
                append_run_work_time_event_for_run_dir(
                    run_dir,
                    child_terminated_for_retry
                        ? "child_stall_retry"
                        : "child_stall_retry_abandoned",
                    child_generation,
                    child_pid,
                    child_started_at,
                    time(NULL),
                    1,
                    abandon_coverage_zone_on_next_retry
                        ? "coverage_zone_timeout"
                        : retrying_coverage_zone_on_next_retry
                        ? "coverage_zone_stall"
                        : skip_retry_hotspots_on_next_retry
                        ? "retry_hotspots_stall"
                        : (escape_stalled_validator_on_next_retry
                            ? "validator_no_progress_escape"
                            : (startup_stage_stall ? "startup_stall" : "scan_stall"))
                );
                if (!child_terminated_for_retry) {
                    if (abandoned_child_count >= (sizeof(abandoned_children) / sizeof(abandoned_children[0]))) {
                        log_runtime_event_error(
                            "Could not terminate stalled raw-all child cleanly and the abandoned-child queue is full; refusing to start another retry"
                        );
                        if (installed_signal_handlers_here) {
                            app_restore_signal_handlers();
                        }
                        return 1;
                    }
                    current_generation++;
                    if (!write_supervisor_generation_file(
                            generation_path,
                            current_generation)) {
                        log_runtime_event_error(
                            "Could not publish raw-all supervisor generation %llu for a forced stall retry; the stale child might wake up later and collide, so the retry is aborted",
                            current_generation
                        );
                        if (installed_signal_handlers_here) {
                            app_restore_signal_handlers();
                        }
                        return 1;
                    }
                    abandoned_children[abandoned_child_count++] = child_pid;
                    abandoned_restart = 1;
                    log_runtime_event_error(
                        "Could not terminate stalled raw-all child cleanly; the OS is still holding a blocking disk read, so generation %llu will take over while pid=%ld is quarantined in the background",
                        current_generation,
                        (long)child_pid
                    );
                } else {
                    current_generation++;
                    if (!write_supervisor_generation_file(
                            generation_path,
                            current_generation)) {
                        log_runtime_event_error(
                            "Raw-all stall retry is restarting with generation %llu, but the supervisor token file could not be updated; stale-child protection is weakened for this retry",
                            current_generation
                        );
                    }
                }
                if (app_stop_requested()) {
                    return stop_raw_all_supervisor_promptly(
                        child_pid,
                        abandoned_children,
                        abandoned_child_count,
                        generation_path,
                        &current_generation,
                        run_dir,
                        child_started_at,
                        child_generation,
                        installed_signal_handlers_here,
                        "Stop requested after the stalled child was stopped; skipping raw-all retry restart"
                    );
                }
                if (abandon_coverage_zone_on_next_retry &&
                    !append_terminal_coverage_range_for_run_dir(
                        run_dir,
                        coverage_retry_state.chunk_start,
                        coverage_retry_state.chunk_end,
                        coverage_retry_state.zone_started_unix,
                        coverage_retry_state.zone_attempts,
                        "coverage_zone_timeout")) {
                    log_runtime_event_error(
                        "Coverage retry reached its hard limit, but Carv could not save the terminal unreadable range; stopping with resume state intact instead of entering the same zone again"
                    );
                    (void)write_error_summary_file_for_run_dir(run_dir);
                    if (installed_signal_handlers_here) {
                        app_restore_signal_handlers();
                    }
                    return 1;
                }
                if (!abandon_coverage_zone_on_next_retry &&
                    total_retry_attempts_used >= total_retry_limit) {
                    log_runtime_event_error(
                        "Raw-all supervisor exhausted its total retry budget (%d restart%s) while handling damaged-source stalls; stopping here with saved state intact instead of looping forever",
                        total_retry_limit,
                        total_retry_limit == 1 ? "" : "s"
                    );
                    (void)write_raw_all_stage_file_with_metrics(
                        run_dir,
                        "done",
                        "Raw-all stopped after exhausting the total retry budget on a damaged source; saved state was preserved for later resume/name",
                        NULL,
                        monotonic_seconds_local()
                    );
                    (void)write_error_summary_file_for_run_dir(run_dir);
                    reap_abandoned_supervised_children(
                        abandoned_children,
                        &abandoned_child_count
                    );
                    if (installed_signal_handlers_here) {
                        app_restore_signal_handlers();
                    }
                    if (has_nonempty_text(scan_pass_id)) {
                        app_gui_end_pass_if_running(run_dir, scan_pass_id, "failed");
                    }
                    return 1;
                }
                if (!skip_retry_hotspots_on_next_retry &&
                    !escape_stalled_validator_on_next_retry &&
                    !retrying_coverage_zone_on_next_retry &&
                    strcmp(stalled_stage, "resume_loading") != 0) {
                    maybe_rewind_scan_state_for_stall_retry(
                        config,
                        startup_stage_stall
                            ? startup_stall_attempts_used + 1 >= config->stall_retries
                            : stall_attempts_used + 1 >= config->stall_retries,
                        &stalled_child_stage
                    );
                } else if (strcmp(stalled_stage, "resume_loading") == 0) {
                    log_runtime_event_info(
                        "Resume-state loading reached its bounded watchdog; restarting artifact loading without rewinding the saved source scan cursor"
                    );
                } else if (escape_stalled_validator_on_next_retry &&
                           !maybe_advance_scan_state_past_stalled_validator(
                               config,
                               run_dir,
                               child_started_at,
                               &validator_escape_stage,
                               "ordinary_stall_retry_budget_exhausted")) {
                    log_runtime_event_error(
                        "Validator escape could not publish a safe forward resume point; stopping with existing resume state instead of restarting into the same candidate"
                    );
                    (void)write_raw_all_stage_file_with_metrics(
                        run_dir,
                        "done",
                        "Raw-all stopped because a stalled validator could not be safely quarantined; saved state remains available",
                        NULL,
                        monotonic_seconds_local()
                    );
                    (void)write_error_summary_file_for_run_dir(run_dir);
                    if (installed_signal_handlers_here) {
                        app_restore_signal_handlers();
                    }
                    if (has_nonempty_text(scan_pass_id)) {
                        app_gui_end_pass_if_running(
                            run_dir,
                            scan_pass_id,
                            "failed"
                        );
                    }
                    return 1;
                }
                if (!abandon_coverage_zone_on_next_retry) {
                    total_retry_attempts_used++;
                }
                if (abandon_coverage_zone_on_next_retry) {
                    startup_stall_attempts_used = 0;
                    log_runtime_event_error(
                        "Raw-all coverage escape: the terminal range is saved and red-marked; restarting beyond it now%s",
                        abandoned_restart
                            ? " while the stale child is quarantined"
                            : ""
                    );
                } else if (retrying_coverage_zone_on_next_retry) {
                    startup_stall_attempts_used++;
                    log_runtime_event_error(
                        "Raw-all coverage retry %d/%d for this child wave (total retries %d/%d)%s",
                        startup_stall_attempts_used,
                        config->stall_retries,
                        total_retry_attempts_used,
                        total_retry_limit,
                        abandoned_restart
                            ? " while the stale child is quarantined"
                            : ""
                    );
                } else if (skip_retry_hotspots_on_next_retry) {
                    log_runtime_event_error(
                        "Raw-all post-scan stall recovery: restarting once more with deferred hotspot reread disabled so finalize/name can continue (total retries %d/%d)%s",
                        total_retry_attempts_used,
                        total_retry_limit,
                        abandoned_restart ? " while the stale child is quarantined" : ""
                    );
                } else if (escape_stalled_validator_on_next_retry) {
                    validator_escape_attempts_used++;
                    log_runtime_event_error(
                        "Raw-all validator escape %d/%d: restarting from the saved forward quarantine point (total retries %d/%d)%s",
                        validator_escape_attempts_used,
                        RAW_ALL_VALIDATOR_ESCAPE_LIMIT_PER_PROGRESS_WAVE,
                        total_retry_attempts_used,
                        total_retry_limit,
                        abandoned_restart ? " while the stale child is quarantined" : ""
                    );
                } else if (startup_stage_stall) {
                    startup_stall_attempts_used++;
                } else {
                    stall_attempts_used++;
                }
                if (!skip_retry_hotspots_on_next_retry &&
                    !escape_stalled_validator_on_next_retry &&
                    !retrying_coverage_zone_on_next_retry &&
                    !abandon_coverage_zone_on_next_retry) {
                    log_runtime_event_error(
                        "Raw-all stall retry %d/%d: restarting in a fresh process from the rewound scan position (total retries %d/%d)%s",
                        startup_stage_stall
                            ? startup_stall_attempts_used
                            : stall_attempts_used,
                        config->stall_retries,
                        total_retry_attempts_used,
                        total_retry_limit,
                        abandoned_restart ? " while the stale child is quarantined" : ""
                    );
                }
                (void)write_error_summary_file_for_run_dir(run_dir);
                stalled_restart = 1;
                if (app_stop_requested()) {
                    return stop_raw_all_supervisor_promptly(
                        child_pid,
                        abandoned_children,
                        abandoned_child_count,
                        generation_path,
                        &current_generation,
                        run_dir,
                        child_started_at,
                        child_generation,
                        installed_signal_handlers_here,
                        "Stop requested after the raw-all retry state was prepared; skipping child restart"
                    );
                }
                sleep(1);
                accumulate_raw_all_stage_budget_elapsed_for_supervisor(
                    run_dir,
                    0,
                    0,
                    1ULL
                );
                break;
            }

            usleep(250000);
        }

        if (stalled_restart) {
            continue;
        }

        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) == 0) {
                append_run_work_time_event_for_run_dir(
                    run_dir,
                    "child_exit_success",
                    child_generation,
                    child_pid,
                    child_started_at,
                    time(NULL),
                    1,
                    "exit_0"
                );
                reap_abandoned_supervised_children(
                    abandoned_children,
                    &abandoned_child_count
                );
                if (abandoned_child_count > 0U) {
                    log_runtime_event_error(
                        "Raw-all supervisor is returning while %zu previously quarantined child process(es) are still waiting for the OS to release blocked disk reads",
                        abandoned_child_count
                    );
                }
                if (installed_signal_handlers_here) {
                    app_restore_signal_handlers();
                }
                if (has_nonempty_text(scan_pass_id)) {
                    app_gui_end_pass_if_running(
                        run_dir,
                        scan_pass_id,
                        "completed"
                    );
                }
                return 0;
            }
            if (WEXITSTATUS(status) == SOURCE_RECONNECT_EXIT_CODE) {
                append_run_work_time_event_for_run_dir(
                    run_dir,
                    "child_exit_source_reconnect",
                    child_generation,
                    child_pid,
                    child_started_at,
                    time(NULL),
                    1,
                    "source_reconnect"
                );
                raw_all_mark_metadata_followup_required(
                    run_dir,
                    "source_reconnect_during_raw_scan_metadata_may_be_thin"
                );
                source_reconnect_attempts_used++;
                if (source_reconnect_attempts_used > SOURCE_RECONNECT_RETRY_LIMIT) {
                    log_runtime_event_error(
                        "Raw-all could not reconnect to the source within %d seconds (%d reopen waits); the run is stopping here with resume state intact so it is obvious that the source is gone",
                        SOURCE_RECONNECT_RETRY_BUDGET_SECONDS,
                        source_reconnect_attempts_used - 1
                    );
                    (void)write_raw_all_stage_file_with_metrics(
                        run_dir,
                        "done",
                        "Source disk could not be reconnected within 3 minutes; resume state was preserved",
                        NULL,
                        monotonic_seconds_local()
                    );
                    (void)write_error_summary_file_for_run_dir(run_dir);
                    reap_abandoned_supervised_children(
                        abandoned_children,
                        &abandoned_child_count
                    );
                    if (abandoned_child_count > 0U) {
                        log_runtime_event_error(
                            "Raw-all supervisor is stopping after source-reconnect failure while %zu previously quarantined child process(es) are still waiting for the OS to release blocked disk reads",
                            abandoned_child_count
                        );
                    }
                    if (installed_signal_handlers_here) {
                        app_restore_signal_handlers();
                    }
                    app_gui_end_pass_if_running(run_dir, scan_pass_id, "failed");
                    return 1;
                } else {
                    accumulate_raw_all_stage_budget_elapsed_for_supervisor(
                        run_dir,
                        child_started_at,
                        1,
                        0ULL
                    );
                    if (total_retry_attempts_used >= total_retry_limit) {
                        log_runtime_event_error(
                            "Raw-all supervisor exhausted its total retry budget (%d restart%s) while trying to reconnect to the source; stopping here with saved state intact instead of looping forever",
                            total_retry_limit,
                            total_retry_limit == 1 ? "" : "s"
                        );
                        (void)write_raw_all_stage_file_with_metrics(
                            run_dir,
                            "done",
                            "Raw-all stopped after exhausting the total retry budget while reconnecting to the source; saved state was preserved for later resume/name",
                            NULL,
                            monotonic_seconds_local()
                        );
                        (void)write_error_summary_file_for_run_dir(run_dir);
                        reap_abandoned_supervised_children(
                            abandoned_children,
                            &abandoned_child_count
                        );
                        if (installed_signal_handlers_here) {
                            app_restore_signal_handlers();
                        }
                        if (has_nonempty_text(scan_pass_id)) {
                            app_gui_end_pass_if_running(run_dir, scan_pass_id, "failed");
                        }
                        return 1;
                    }
                    (void)maybe_rewind_scan_state_for_source_reconnect(
                        config,
                        run_dir,
                        child_started_at
                    );
                    total_retry_attempts_used++;
                    current_generation++;
                    if (!write_supervisor_generation_file(
                            generation_path,
                            current_generation)) {
                        log_runtime_event_error(
                            "Could not publish raw-all supervisor generation %llu for a source reconnect retry; stale-child protection is weakened for this reopen attempt",
                            current_generation
                        );
                    }
                    (void)write_raw_all_stage_file_with_metrics(
                        run_dir,
                        "source_reconnect_wait",
                        "Source disappeared; trying to reopen and resume",
                        NULL,
                        monotonic_seconds_local()
                    );
                    log_runtime_event_error(
                        "Raw-all lost contact with the source; waiting %d seconds before retrying reopen/resume attempt %d/%d (up to %d seconds total, total retries %d/%d)",
                        SOURCE_RECONNECT_RETRY_DELAY_SECONDS,
                        source_reconnect_attempts_used,
                        SOURCE_RECONNECT_RETRY_LIMIT,
                        SOURCE_RECONNECT_RETRY_BUDGET_SECONDS,
                        total_retry_attempts_used,
                        total_retry_limit
                    );
                    sleep(SOURCE_RECONNECT_RETRY_DELAY_SECONDS);
                    accumulate_raw_all_stage_budget_elapsed_for_supervisor(
                        run_dir,
                        0,
                        0,
                        SOURCE_RECONNECT_RETRY_DELAY_SECONDS
                    );
                    continue;
                }
            }
            append_run_work_time_event_for_run_dir(
                run_dir,
                "child_exit_nonzero",
                child_generation,
                child_pid,
                child_started_at,
                time(NULL),
                1,
                WEXITSTATUS(status) == 130
                    ? "exit_130_stop_requested"
                    : "nonzero_exit_no_retry"
            );
            reap_abandoned_supervised_children(
                abandoned_children,
                &abandoned_child_count
            );
            log_raw_all_child_exit_diagnostics(
                run_dir,
                child_pid,
                status,
                child_started_at,
                current_generation,
                WEXITSTATUS(status) == 130
                    ? "nonzero_exit_stop_requested"
                    : "nonzero_exit_no_retry",
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used,
                total_retry_attempts_used,
                total_retry_limit
            );
            if (abandoned_child_count > 0U) {
                log_runtime_event_error(
                    "Raw-all supervisor is returning while %zu previously quarantined child process(es) are still waiting for the OS to release blocked disk reads",
                    abandoned_child_count
                );
            }
            if (installed_signal_handlers_here) {
                app_restore_signal_handlers();
            }
            if (has_nonempty_text(scan_pass_id)) {
                app_gui_end_pass_if_running(
                    run_dir,
                    scan_pass_id,
                    WEXITSTATUS(status) == 130 ? "stopped" : "failed"
                );
            }
            return WEXITSTATUS(status);
        }

        if (!WIFSIGNALED(status) ||
            !signal_is_retryable_crash(WTERMSIG(status)) ||
            crash_attempts_used >= config->crash_retries) {
            append_run_work_time_event_for_run_dir(
                run_dir,
                "child_signal_no_retry",
                child_generation,
                child_pid,
                child_started_at,
                time(NULL),
                1,
                WIFSIGNALED(status)
                    ? (signal_is_retryable_crash(WTERMSIG(status))
                           ? "retryable_signal_retry_limit_reached"
                           : "non_retryable_signal_no_retry")
                    : "unknown_wait_status_no_retry"
            );
            log_raw_all_child_exit_diagnostics(
                run_dir,
                child_pid,
                status,
                child_started_at,
                child_generation,
                WIFSIGNALED(status)
                    ? (signal_is_retryable_crash(WTERMSIG(status))
                           ? "retryable_signal_retry_limit_reached"
                           : "non_retryable_signal_no_retry")
                    : "unknown_wait_status_no_retry",
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used,
                total_retry_attempts_used,
                total_retry_limit
            );
            write_raw_all_crash_breadcrumbs_for_run_dir(
                run_dir,
                child_pid,
                status,
                child_started_at,
                child_generation,
                "signal_no_retry",
                WIFSIGNALED(status)
                    ? (signal_is_retryable_crash(WTERMSIG(status))
                           ? "retryable_signal_retry_limit_reached"
                           : "non_retryable_signal_no_retry")
                    : "unknown_wait_status_no_retry",
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used,
                total_retry_attempts_used,
                total_retry_limit
            );
            if (WIFSIGNALED(status) &&
                signal_is_retryable_crash(WTERMSIG(status)) &&
                raw_all_continue_after_crash_bypass(
                    config,
                    generation_path,
                    &current_generation,
                    run_dir,
                    child_started_at,
                    crash_attempts_used + 1,
                    &total_retry_attempts_used,
                    total_retry_limit,
                    &child_generation,
                    "retryable_signal_retry_limit_reached")) {
                continue;
            }
            (void)write_raw_all_stage_file_with_metrics(
                run_dir,
                "crash_resume_ready",
                "Raw-all child crashed before completion; resume state, coverage gaps, and crash breadcrumbs were preserved",
                NULL,
                monotonic_seconds_local()
            );
            (void)write_error_summary_file_for_run_dir(run_dir);
            if (installed_signal_handlers_here) {
                app_restore_signal_handlers();
            }
            if (has_nonempty_text(scan_pass_id)) {
                app_gui_end_pass_if_running(
                    run_dir,
                    scan_pass_id,
                    app_stop_requested() ? "stopped" : "failed"
                );
            }
            return WIFSIGNALED(status) ? 128 + WTERMSIG(status) : 1;
        }

        log_runtime_event_error(
            "Raw-all child crashed with signal %d; retrying %d/%d in a fresh process",
            WTERMSIG(status),
            crash_attempts_used + 1,
            config->crash_retries
        );
        append_run_work_time_event_for_run_dir(
            run_dir,
            "child_signal_retry",
            child_generation,
            child_pid,
            child_started_at,
            time(NULL),
            1,
            "retryable_signal_retry"
        );
        if (total_retry_attempts_used >= total_retry_limit) {
            log_runtime_event_error(
                "Raw-all supervisor exhausted its total retry budget (%d restart%s) after repeated crashes/stalls; stopping here with saved state intact instead of looping forever",
                total_retry_limit,
                total_retry_limit == 1 ? "" : "s"
            );
            log_raw_all_child_exit_diagnostics(
                run_dir,
                child_pid,
                status,
                child_started_at,
                child_generation,
                "total_retry_budget_exhausted_after_crash",
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used,
                total_retry_attempts_used,
                total_retry_limit
            );
            write_raw_all_crash_breadcrumbs_for_run_dir(
                run_dir,
                child_pid,
                status,
                child_started_at,
                child_generation,
                "signal_retry_budget_exhausted",
                "total_retry_budget_exhausted_after_crash",
                crash_attempts_used,
                stall_attempts_used,
                startup_stall_attempts_used,
                total_retry_attempts_used,
                total_retry_limit
            );
            (void)write_raw_all_stage_file_with_metrics(
                run_dir,
                "crash_resume_ready",
                "Raw-all stopped after exhausting the retry budget after a child crash; resume state, coverage gaps, and crash breadcrumbs were preserved",
                NULL,
                monotonic_seconds_local()
            );
            (void)write_error_summary_file_for_run_dir(run_dir);
            reap_abandoned_supervised_children(
                abandoned_children,
                &abandoned_child_count
            );
            if (installed_signal_handlers_here) {
                app_restore_signal_handlers();
            }
            if (has_nonempty_text(scan_pass_id)) {
                app_gui_end_pass_if_running(run_dir, scan_pass_id, "failed");
            }
            return 1;
        }
        write_raw_all_crash_breadcrumbs_for_run_dir(
            run_dir,
            child_pid,
            status,
            child_started_at,
            child_generation,
            "signal_retry",
            "retryable_signal_retry",
            crash_attempts_used,
            stall_attempts_used,
            startup_stall_attempts_used,
            total_retry_attempts_used,
            total_retry_limit
        );
        total_retry_attempts_used++;
        crash_attempts_used++;
        current_generation++;
        if (!write_supervisor_generation_file(
                generation_path,
                current_generation)) {
            log_runtime_event_error(
                "Raw-all crash retry is restarting with generation %llu, but the supervisor token file could not be updated; stale-child protection is weakened for this retry",
                current_generation
            );
        }
        (void)maybe_advance_scan_state_for_crash_retry(
            config,
            crash_attempts_used,
            "retryable_signal_retry");
        accumulate_raw_all_stage_budget_elapsed_for_supervisor(
            run_dir,
            child_started_at,
            1,
            0ULL
        );
        log_runtime_event_error(
            "Raw-all crash retry progress: total retries %d/%d",
            total_retry_attempts_used,
            total_retry_limit
        );
        sleep(1);
        accumulate_raw_all_stage_budget_elapsed_for_supervisor(
            run_dir,
            0,
            0,
            1ULL
        );
    }

    if (installed_signal_handlers_here) {
        app_restore_signal_handlers();
    }
    return 1;
}

static int build_source_image_paths(
    const AppConfig *config,
    char *image_path,
    size_t image_path_size,
    char *map_path,
    size_t map_path_size
)
{
    if (config == NULL ||
        config->output_dir == NULL ||
        config->output_dir[0] == '\0' ||
        image_path == NULL ||
        image_path_size == 0 ||
        map_path == NULL ||
        map_path_size == 0) {
        return 0;
    }

    if (snprintf(
            image_path,
            image_path_size,
            "%s/source_image.img",
            config->output_dir) >= (int)image_path_size) {
        return 0;
    }

    if (snprintf(
            map_path,
            map_path_size,
            "%s/source_image.map",
            config->output_dir) >= (int)map_path_size) {
        return 0;
    }

    return 1;
}

static int maybe_restore_empty_ddrescue_map_from_backup(const char *map_path)
{
    char backup_path[PATH_MAX_LEN];
    struct stat map_st;
    struct stat backup_st;

    if (!has_nonempty_text(map_path) ||
        snprintf(backup_path, sizeof(backup_path), "%s.bak", map_path) >=
            (int)sizeof(backup_path)) {
        return 0;
    }
    if (stat(map_path, &map_st) != 0 ||
        !S_ISREG(map_st.st_mode) ||
        map_st.st_size != 0) {
        return 0;
    }
    if (stat(backup_path, &backup_st) != 0 ||
        !S_ISREG(backup_st.st_mode) ||
        backup_st.st_size <= 0) {
        return 0;
    }

    if (copy_file_local(backup_path, map_path)) {
        log_runtime_event_info(
            "Image-first mode: restored empty ddrescue map %s from backup %s before resume",
            map_path,
            backup_path
        );
        return 1;
    }

    log_runtime_event_error(
        "Image-first mode: %s is empty and backup %s exists, but Carv could not restore the backup before resume",
        map_path,
        backup_path
    );
    return 0;
}

typedef struct {
    uint64_t rescued_bytes;
    uint64_t bad_sector_bytes;
    uint64_t non_tried_bytes;
    uint64_t non_trimmed_bytes;
    uint64_t non_scraped_bytes;
    uint64_t unknown_bytes;
    uint64_t total_tracked_bytes;
    uint64_t rescued_ranges;
    uint64_t bad_sector_ranges;
    uint64_t non_tried_ranges;
    uint64_t non_trimmed_ranges;
    uint64_t non_scraped_ranges;
    uint64_t unknown_ranges;
    uint64_t total_tracked_ranges;
    uint64_t unresolved_ranges;
    uint64_t largest_unresolved_bytes;
} DdrescueMapSummary;

