static uint64_t read_regular_file_size_local(const char *path)
{
    struct stat st;

    if (!has_nonempty_text(path) || stat(path, &st) != 0 || !S_ISREG(st.st_mode) || st.st_size < 0) {
        return 0ULL;
    }

    return (uint64_t)st.st_size;
}

static int summarize_ddrescue_map_file(const char *map_path, DdrescueMapSummary *summary)
{
    FILE *file;
    char line[512];

    if (summary == NULL) {
        return 0;
    }

    memset(summary, 0, sizeof(*summary));

    if (!has_nonempty_text(map_path)) {
        return 0;
    }

    file = fopen(map_path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long pos_ull = 0ULL;
        unsigned long long size_ull = 0ULL;
        char status = '\0';
        uint64_t span_size;

        if (sscanf(line, " 0x%llx 0x%llx %c", &pos_ull, &size_ull, &status) != 3 &&
            sscanf(line, " %llx %llx %c", &pos_ull, &size_ull, &status) != 3) {
            continue;
        }

        (void)pos_ull;
        span_size = (uint64_t)size_ull;
        summary->total_tracked_bytes += span_size;
        summary->total_tracked_ranges++;

        switch (status) {
            case '+':
                summary->rescued_bytes += span_size;
                summary->rescued_ranges++;
                break;
            case '-':
                summary->bad_sector_bytes += span_size;
                summary->bad_sector_ranges++;
                break;
            case '?':
                summary->non_tried_bytes += span_size;
                summary->non_tried_ranges++;
                break;
            case '*':
                summary->non_trimmed_bytes += span_size;
                summary->non_trimmed_ranges++;
                break;
            case '/':
                summary->non_scraped_bytes += span_size;
                summary->non_scraped_ranges++;
                break;
            default:
                summary->unknown_bytes += span_size;
                summary->unknown_ranges++;
                break;
        }
        if (status != '+') {
            summary->unresolved_ranges++;
            if (span_size > summary->largest_unresolved_bytes) {
                summary->largest_unresolved_bytes = span_size;
            }
        }
    }

    fclose(file);
    return 1;
}

static const char *ddrescue_map_status_kind(char status)
{
    switch (status) {
        case '+':
            return "rescued";
        case '-':
            return "bad_sector";
        case '?':
            return "non_tried";
        case '*':
            return "non_trimmed";
        case '/':
            return "non_scraped";
        default:
            return "unknown";
    }
}

static int mirror_source_image_map_to_state(
    const AppConfig *config,
    const char *map_path,
    char *state_map_path,
    size_t state_map_path_size
)
{
    char local_state_map_path[PATH_MAX_LEN];
    char *target_path = state_map_path != NULL ? state_map_path : local_state_map_path;
    size_t target_size = state_map_path != NULL ? state_map_path_size : sizeof(local_state_map_path);

    if (state_map_path != NULL && state_map_path_size > 0) {
        state_map_path[0] = '\0';
    }
    if (config == NULL ||
        !has_nonempty_text(map_path) ||
        !build_source_image_state_map_path(config, target_path, target_size) ||
        !ensure_parent_dirs_for_path(target_path)) {
        return 0;
    }
    if (copy_file_local(map_path, target_path)) {
        return 1;
    }
    if (state_map_path != NULL && state_map_path_size > 0) {
        state_map_path[0] = '\0';
    }
    return 0;
}

static int build_live_source_image_state_map_path(
    const char *map_path,
    char *state_map_path,
    size_t state_map_path_size
)
{
    const char *slash;
    size_t run_dir_length;

    if (!has_nonempty_text(map_path) ||
        state_map_path == NULL ||
        state_map_path_size == 0U) {
        return 0;
    }
    slash = strrchr(map_path, '/');
    if (slash == NULL || slash == map_path) {
        return 0;
    }
    run_dir_length = (size_t)(slash - map_path);
    return snprintf(
        state_map_path,
        state_map_path_size,
        "%.*s/%s/source_image.map",
        (int)run_dir_length,
        map_path,
        APP_STATE_DIR_NAME
    ) < (int)state_map_path_size;
}

static int mirror_live_source_image_map_to_state(const char *map_path)
{
    char state_map_path[PATH_MAX_LEN];
    char candidate_path[PATH_MAX_LEN + 32];
    struct stat before_copy;
    struct stat after_copy;
    DdrescueMapSummary summary;
    int candidate_fd;

    if (!build_live_source_image_state_map_path(
            map_path,
            state_map_path,
            sizeof(state_map_path)) ||
        snprintf(
            candidate_path,
            sizeof(candidate_path),
            "%s.candidate",
            state_map_path) >= (int)sizeof(candidate_path) ||
        !ensure_parent_dirs_for_path(state_map_path) ||
        stat(map_path, &before_copy) != 0 ||
        !S_ISREG(before_copy.st_mode) ||
        before_copy.st_size <= 0 ||
        !copy_file_local(map_path, candidate_path) ||
        stat(map_path, &after_copy) != 0 ||
        before_copy.st_size != after_copy.st_size ||
        before_copy.st_mtime != after_copy.st_mtime ||
        !summarize_ddrescue_map_file(candidate_path, &summary) ||
        summary.total_tracked_ranges == 0ULL ||
        summary.total_tracked_bytes == 0ULL) {
        (void)unlink(candidate_path);
        return 0;
    }

    candidate_fd = open(candidate_path, O_RDWR);
    if (candidate_fd < 0 || fsync(candidate_fd) != 0) {
        if (candidate_fd >= 0) (void)close(candidate_fd);
        (void)unlink(candidate_path);
        return 0;
    }
    (void)close(candidate_fd);
    if (rename(candidate_path, state_map_path) != 0) {
        (void)unlink(candidate_path);
        return 0;
    }
    (void)fs_backend_apply_output_owner_to_path(state_map_path);
    return 1;
}

static double source_image_state_map_mirror_interval_seconds(void)
{
    const char *override = getenv(
        "CARV_TEST_STATE_MAP_MIRROR_INTERVAL_SECONDS"
    );
    char *end = NULL;
    double value;

    if (!has_nonempty_text(override)) {
        return SOURCE_IMAGE_STATE_MAP_MIRROR_INTERVAL_SECONDS;
    }
    errno = 0;
    value = strtod(override, &end);
    if (errno != 0 || end == override || *end != '\0' || value <= 0.0) {
        return SOURCE_IMAGE_STATE_MAP_MIRROR_INTERVAL_SECONDS;
    }
    return value;
}

static int write_source_image_bad_ranges_file(
    const AppConfig *config,
    const char *map_path,
    DdrescueMapSummary *out_summary
)
{
    char bad_ranges_path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    FILE *map_file = NULL;
    FILE *out_file = NULL;
    char line[512];
    DdrescueMapSummary summary;
    int ok = 0;
    uint64_t written_ranges = 0ULL;

    if (out_summary != NULL) {
        memset(out_summary, 0, sizeof(*out_summary));
    }
    if (config == NULL ||
        !has_nonempty_text(map_path) ||
        !build_source_image_bad_ranges_path(config, bad_ranges_path, sizeof(bad_ranges_path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", bad_ranges_path) >= (int)sizeof(temp_path) ||
        !ensure_parent_dirs_for_path(bad_ranges_path)) {
        return 0;
    }

    memset(&summary, 0, sizeof(summary));
    map_file = fopen(map_path, "r");
    if (map_file == NULL) {
        return 0;
    }
    out_file = fopen(temp_path, "w");
    if (out_file == NULL) {
        fclose(map_file);
        return 0;
    }

    fprintf(out_file, "offset\tend_offset\tbytes\tstatus\tkind\n");
    while (fgets(line, sizeof(line), map_file) != NULL) {
        unsigned long long pos_ull = 0ULL;
        unsigned long long size_ull = 0ULL;
        char status = '\0';
        uint64_t start_offset;
        uint64_t span_size;
        uint64_t end_offset;
        const char *kind;

        if (sscanf(line, " 0x%llx 0x%llx %c", &pos_ull, &size_ull, &status) != 3 &&
            sscanf(line, " %llx %llx %c", &pos_ull, &size_ull, &status) != 3) {
            continue;
        }

        start_offset = (uint64_t)pos_ull;
        span_size = (uint64_t)size_ull;
        if (span_size == 0ULL) {
            continue;
        }
        summary.total_tracked_bytes += span_size;
        summary.total_tracked_ranges++;
        kind = ddrescue_map_status_kind(status);
        switch (status) {
            case '+':
                summary.rescued_bytes += span_size;
                summary.rescued_ranges++;
                continue;
            case '-':
                summary.bad_sector_bytes += span_size;
                summary.bad_sector_ranges++;
                break;
            case '?':
                summary.non_tried_bytes += span_size;
                summary.non_tried_ranges++;
                break;
            case '*':
                summary.non_trimmed_bytes += span_size;
                summary.non_trimmed_ranges++;
                break;
            case '/':
                summary.non_scraped_bytes += span_size;
                summary.non_scraped_ranges++;
                break;
            default:
                summary.unknown_bytes += span_size;
                summary.unknown_ranges++;
                break;
        }
        summary.unresolved_ranges++;
        if (span_size > summary.largest_unresolved_bytes) {
            summary.largest_unresolved_bytes = span_size;
        }
        end_offset = app_saturating_add_u64(start_offset, span_size);
        fprintf(
            out_file,
            "%llu\t%llu\t%llu\t%c\t%s\n",
            (unsigned long long)start_offset,
            (unsigned long long)end_offset,
            (unsigned long long)span_size,
            status,
            kind
        );
        written_ranges++;
    }

    if (fclose(out_file) != 0) {
        out_file = NULL;
        goto cleanup;
    }
    out_file = NULL;
    if (rename(temp_path, bad_ranges_path) != 0) {
        goto cleanup;
    }
    ok = 1;

cleanup:
    if (out_file != NULL) {
        fclose(out_file);
    }
    if (map_file != NULL) {
        fclose(map_file);
    }
    if (!ok) {
        (void)unlink(temp_path);
        return 0;
    }
    if (out_summary != NULL) {
        *out_summary = summary;
    }
    if (written_ranges > 0ULL) {
        log_info(
            "Recorded %llu imaged bad/unresolved range%s from ddrescue map in state/%s",
            (unsigned long long)written_ranges,
            written_ranges == 1ULL ? "" : "s",
            SOURCE_IMAGE_BAD_RANGES_FILE_NAME
        );
    }
    return 1;
}

static void write_source_image_status_file(
    const AppConfig *config,
    const char *source_path,
    const char *image_path,
    const char *map_path,
    int imaging_succeeded,
    int continue_requested
)
{
    char status_path[PATH_MAX_LEN];
    char state_map_path[PATH_MAX_LEN];
    char bad_ranges_path[PATH_MAX_LEN];
    FILE *file;
    DdrescueMapSummary summary;
    DdrescueMapSummary bad_range_summary;
    uint64_t image_size = 0ULL;
    uint64_t unresolved_bytes = 0ULL;
    double quality_percent = -1.0;
    double unresolved_percent = -1.0;
    int needs_thorough_retry = 0;
    int have_summary;
    int mirrored_map = 0;
    int wrote_bad_ranges = 0;

    if (config == NULL ||
        !build_source_image_status_path(config, status_path, sizeof(status_path))) {
        return;
    }

    state_map_path[0] = '\0';
    bad_ranges_path[0] = '\0';
    memset(&bad_range_summary, 0, sizeof(bad_range_summary));
    mirrored_map = mirror_source_image_map_to_state(
        config,
        map_path,
        state_map_path,
        sizeof(state_map_path)
    );
    wrote_bad_ranges = write_source_image_bad_ranges_file(
        config,
        map_path,
        &bad_range_summary
    );
    (void)build_source_image_bad_ranges_path(
        config,
        bad_ranges_path,
        sizeof(bad_ranges_path)
    );

    file = fopen(status_path, "w");
    if (file == NULL) {
        return;
    }

    have_summary = summarize_ddrescue_map_file(map_path, &summary);
    image_size = read_regular_file_size_local(image_path);
    if (have_summary) {
        unresolved_bytes = summary.total_tracked_bytes >= summary.rescued_bytes
            ? summary.total_tracked_bytes - summary.rescued_bytes
            : 0ULL;
        if (summary.total_tracked_bytes > 0ULL) {
            quality_percent =
                ((double)summary.rescued_bytes * 100.0) /
                (double)summary.total_tracked_bytes;
            unresolved_percent =
                ((double)unresolved_bytes * 100.0) /
                (double)summary.total_tracked_bytes;
        }
        if (config->image_ddrescue_mode == APP_IMAGE_DDRESCUE_MODE_BASIC &&
            unresolved_bytes > 0ULL) {
            needs_thorough_retry = 1;
        }
    }

    fprintf(
        file,
        "status=%s\n",
        imaging_succeeded ? (continue_requested ? "partial_continue" : "ok") : "failed"
    );
    fprintf(file, "mode=%s\n", image_ddrescue_mode_label(config->image_ddrescue_mode));
    fprintf(file, "continue_requested=%d\n", continue_requested ? 1 : 0);
    fprintf(file, "source_path=%s\n", has_nonempty_text(source_path) ? source_path : "");
    fprintf(file, "image_path=%s\n", has_nonempty_text(image_path) ? image_path : "");
    fprintf(file, "map_path=%s\n", has_nonempty_text(map_path) ? map_path : "");
    fprintf(file, "state_map_path=%s\n", mirrored_map ? state_map_path : "");
    fprintf(file, "bad_ranges_path=%s\n", wrote_bad_ranges ? bad_ranges_path : "");
    fprintf(file, "image_size=%llu\n", (unsigned long long)image_size);
    fprintf(file, "have_map_summary=%d\n", have_summary ? 1 : 0);
    fprintf(file, "map_mirrored_to_state=%d\n", mirrored_map ? 1 : 0);
    fprintf(file, "bad_ranges_written=%d\n", wrote_bad_ranges ? 1 : 0);
    fprintf(file, "quality_percent=%.3f\n", quality_percent);
    fprintf(file, "unresolved_percent=%.3f\n", unresolved_percent);
    fprintf(file, "needs_thorough_retry=%d\n", needs_thorough_retry);
    if (have_summary) {
        fprintf(file, "tracked_bytes=%llu\n", (unsigned long long)summary.total_tracked_bytes);
        fprintf(file, "tracked_ranges=%llu\n", (unsigned long long)summary.total_tracked_ranges);
        fprintf(file, "rescued_bytes=%llu\n", (unsigned long long)summary.rescued_bytes);
        fprintf(file, "rescued_ranges=%llu\n", (unsigned long long)summary.rescued_ranges);
        fprintf(file, "bad_sector_bytes=%llu\n", (unsigned long long)summary.bad_sector_bytes);
        fprintf(file, "bad_sector_ranges=%llu\n", (unsigned long long)summary.bad_sector_ranges);
        fprintf(file, "non_tried_bytes=%llu\n", (unsigned long long)summary.non_tried_bytes);
        fprintf(file, "non_tried_ranges=%llu\n", (unsigned long long)summary.non_tried_ranges);
        fprintf(file, "non_trimmed_bytes=%llu\n", (unsigned long long)summary.non_trimmed_bytes);
        fprintf(file, "non_trimmed_ranges=%llu\n", (unsigned long long)summary.non_trimmed_ranges);
        fprintf(file, "non_scraped_bytes=%llu\n", (unsigned long long)summary.non_scraped_bytes);
        fprintf(file, "non_scraped_ranges=%llu\n", (unsigned long long)summary.non_scraped_ranges);
        fprintf(file, "unknown_bytes=%llu\n", (unsigned long long)summary.unknown_bytes);
        fprintf(file, "unknown_ranges=%llu\n", (unsigned long long)summary.unknown_ranges);
        fprintf(file, "unresolved_bytes=%llu\n", (unsigned long long)unresolved_bytes);
        fprintf(file, "unresolved_ranges=%llu\n", (unsigned long long)summary.unresolved_ranges);
        fprintf(file, "largest_unresolved_bytes=%llu\n", (unsigned long long)summary.largest_unresolved_bytes);
    }
    if (wrote_bad_ranges) {
        fprintf(file, "imaged_bad_range_count=%llu\n", (unsigned long long)bad_range_summary.unresolved_ranges);
        fprintf(
            file,
            "imaged_bad_range_bytes=%llu\n",
            (unsigned long long)(
                bad_range_summary.bad_sector_bytes +
                bad_range_summary.non_tried_bytes +
                bad_range_summary.non_trimmed_bytes +
                bad_range_summary.non_scraped_bytes +
                bad_range_summary.unknown_bytes
            )
        );
        fprintf(
            file,
            "imaged_bad_largest_bytes=%llu\n",
            (unsigned long long)bad_range_summary.largest_unresolved_bytes
        );
    }
    fprintf(file, "updated_unix=%llu\n", (unsigned long long)time(NULL));
    fclose(file);

    if (have_summary) {
        log_info(
            "Source image summary: mode=%s rescued=%.1f MiB unresolved=%.1f MiB bad=%.1f MiB nontried=%.1f MiB",
            image_ddrescue_mode_label(config->image_ddrescue_mode),
            (double)summary.rescued_bytes / (1024.0 * 1024.0),
            (double)unresolved_bytes / (1024.0 * 1024.0),
            (double)summary.bad_sector_bytes / (1024.0 * 1024.0),
            (double)summary.non_tried_bytes / (1024.0 * 1024.0)
        );
        if (unresolved_bytes > 0ULL &&
            config->image_ddrescue_mode == APP_IMAGE_DDRESCUE_MODE_BASIC) {
            if (config->hypersafe_strategy ==
                APP_HYPERSAFE_STRATEGY_SELECTED_FOLDERS) {
                log_info(
                    "Source image still has unresolved blocks after the quick pass; Hypersafe will inspect the map and continue automatically with selected areas first"
                );
            } else if (config->hypersafe_strategy ==
                       APP_HYPERSAFE_STRATEGY_IMAGE_IMMEDIATELY) {
                log_info(
                    "Source image still has unresolved blocks after the quick pass; Hypersafe will continue automatically with the bounded retry passes"
                );
            } else {
                log_info(
                    "Source image still has unresolved blocks after basic imaging; rerun later with --ddrescue-mode thorough if you want a slower, more persistent image pass"
                );
            }
        }
    } else {
        log_info(
            "Source image status written to %s (ddrescue map summary was not available)",
            status_path
        );
    }
}

static int scan_state_matches_source(
    const ScanState *state,
    const char *input_path
)
{
    return state != NULL &&
           input_path != NULL &&
           state->source_path[0] != '\0' &&
           strcmp(state->source_path, input_path) == 0;
}

static int scan_state_matches_mode(
    const ScanState *state,
    const AppConfig *config
)
{
    const char *mode_label;

    if (state == NULL || config == NULL) {
        return 0;
    }

    mode_label = config_scan_mode_label(config);
    if (mode_label == NULL || mode_label[0] == '\0' ||
        state->scan_mode[0] == '\0') {
        return 0;
    }

    return strcmp(state->scan_mode, mode_label) == 0;
}

static int is_internal_output_artifact_name(const char *name)
{
    return fs_backend_is_internal_output_artifact_name(name);
}

static size_t count_recovered_files_recursive(const char *path)
{
    DIR *dir;
    struct dirent *entry;
    size_t count = 0;

    if (path == NULL) {
        return 0;
    }

    dir = opendir(path);
    if (dir == NULL) {
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        char child_path[2048];
        struct stat st;

        if (strcmp(entry->d_name, ".") == 0 ||
            strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        if (snprintf(
                child_path,
                sizeof(child_path),
                "%s/%s",
                path,
                entry->d_name) >= (int)sizeof(child_path)) {
            continue;
        }

        if (stat(child_path, &st) != 0) {
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            count += count_recovered_files_recursive(child_path);
            continue;
        }

        if (S_ISREG(st.st_mode) &&
            !is_internal_output_artifact_name(entry->d_name)) {
            count++;
        }
    }

    closedir(dir);
    return count;
}

static int has_nonempty_text(const char *text)
{
    return text != NULL && text[0] != '\0';
}

static int app_adopt_inherited_run_lock(void)
{
#if defined(__APPLE__) || defined(__linux__) || defined(__unix__)
    const char *fd_text = getenv(CARV_RUN_LOCK_FD_ENV);
    char *end = NULL;
    long inherited_fd;

    if (!has_nonempty_text(fd_text)) {
        return 0;
    }
    errno = 0;
    inherited_fd = strtol(fd_text, &end, 10);
    if (errno != 0 || end == fd_text || *end != '\0' ||
        inherited_fd < 0 || inherited_fd > INT_MAX ||
        fcntl((int)inherited_fd, F_GETFD) < 0 ||
        flock((int)inherited_fd, LOCK_EX | LOCK_NB) != 0) {
        (void)unsetenv(CARV_RUN_LOCK_FD_ENV);
        return 0;
    }
    g_carv_run_lock_fd = (int)inherited_fd;
    return 1;
#else
    return 0;
#endif
}

static int app_acquire_run_lock(const AppConfig *config)
{
#if defined(__APPLE__) || defined(__linux__) || defined(__unix__)
    char lock_path[PATH_MAX_LEN];
    char owner_text[2048];
    char inherited_fd_text[32];
    char existing_owner[1024];
    ssize_t existing_length;
    int fd;
    int owner_length;

    if (g_carv_run_lock_fd >= 0 || app_adopt_inherited_run_lock()) {
        return 1;
    }
    if (config == NULL || !has_nonempty_text(config->output_dir)) {
        log_error("Cannot acquire recovery run ownership without an output directory");
        return 0;
    }
    if (!ensure_directory_path(config->output_dir)) {
        log_error("Could not create recovery run directory for run lock: %s", config->output_dir);
        return 0;
    }
    if (snprintf(
            lock_path,
            sizeof(lock_path),
            "%s/%s",
            config->output_dir,
            CARV_RUN_LOCK_SUFFIX) >= (int)sizeof(lock_path)) {
        log_error("Recovery run lock path is too long");
        return 0;
    }

    fd = open(lock_path, O_RDWR | O_CREAT, 0666);
    if (fd < 0) {
        log_error("Could not open recovery run lock %s: %s", lock_path, strerror(errno));
        return 0;
    }
    (void)fchmod(fd, 0666);
    if (flock(fd, LOCK_EX | LOCK_NB) != 0) {
        existing_owner[0] = '\0';
        if (lseek(fd, 0, SEEK_SET) >= 0) {
            existing_length = read(fd, existing_owner, sizeof(existing_owner) - 1U);
            if (existing_length > 0) {
                existing_owner[existing_length] = '\0';
                existing_owner[strcspn(existing_owner, "\r\n")] = '\0';
            }
        }
        if (existing_owner[0] != '\0') {
            log_error(
                "Recovery run is already active for %s (owner: %s). Stop or kill the active run before resuming this Service ID.",
                config->output_dir,
                existing_owner
            );
        } else {
            log_error(
                "Recovery run is already active for %s. Stop or kill the active run before resuming this Service ID.",
                config->output_dir
            );
        }
        (void)close(fd);
        return 0;
    }

    owner_length = snprintf(
        owner_text,
        sizeof(owner_text),
        "pid=%ld source=%s mode=%s started_unix=%lld\n",
        (long)getpid(),
        has_nonempty_text(config->input_path) ? config->input_path : "unknown",
        config_scan_mode_label(config),
        (long long)time(NULL)
    );
    if (ftruncate(fd, 0) != 0 || lseek(fd, 0, SEEK_SET) < 0 ||
        owner_length <= 0 || owner_length >= (int)sizeof(owner_text) ||
        write(fd, owner_text, (size_t)owner_length) != (ssize_t)owner_length) {
        log_error("Could not publish recovery run ownership in %s: %s", lock_path, strerror(errno));
        (void)close(fd);
        return 0;
    }
    (void)fsync(fd);
    snprintf(inherited_fd_text, sizeof(inherited_fd_text), "%d", fd);
    if (setenv(CARV_RUN_LOCK_FD_ENV, inherited_fd_text, 1) != 0) {
        log_error("Could not preserve recovery run ownership across worker restart: %s", strerror(errno));
        (void)close(fd);
        return 0;
    }
    g_carv_run_lock_fd = fd;
    log_info("Recovery run ownership acquired for %s", config->output_dir);
    return 1;
#else
    (void)config;
    log_error("Recovery run locking is unavailable on this platform");
    return 0;
#endif
}

static void app_apply_filesystem_target_to_backend_config(
    const AppConfig *config,
    FsBackendConfig *backend_config
)
{
    if (backend_config == NULL) {
        return;
    }

    backend_config->force_ntfs_target =
        config != NULL &&
        config->filesystem_target == APP_FILESYSTEM_TARGET_NTFS;
    backend_config->force_hfsplus_target =
        config != NULL &&
        config->filesystem_target == APP_FILESYSTEM_TARGET_HFSPLUS;
}

static int raw_all_saved_metadata_background_available(const AppConfig *config)
{
    return config != NULL &&
           has_nonempty_text(config->output_dir) &&
           fs_backend_current_kind() != FS_BACKEND_KIND_NONE &&
           fs_backend_saved_metadata_available_for_phase(
               FS_BACKEND_ARTIFACT_PHASE_SCAN_RESUME
           );
}

static int raw_all_name_follow_up_enabled(const AppConfig *config)
{
    return config != NULL;
}

static int raw_all_extra_name_follow_up_requested(const AppConfig *config)
{
    (void)config;
    return 0;
}

static int raw_all_completed_resume_should_skip_deferred_hotspot_reread(
    const AppConfig *config
)
{
    return config != NULL &&
           config->quick_resume &&
           !config->additive_pass &&
           (config->resume_scan_completed || config->resume_completed);
}

static void raw_all_startup_scan_state_values(
    const AppConfig *config,
    const ScanState *existing_scan_state,
    uint64_t fallback_total_bytes,
    uint64_t *out_scan_offset,
    int *out_scan_completed,
    int *out_completed
)
{
    uint64_t scan_offset = 0ULL;
    int scan_completed = 0;
    int completed = 0;

    if (out_scan_offset == NULL ||
        out_scan_completed == NULL ||
        out_completed == NULL) {
        return;
    }

    if (config != NULL) {
        if (config->resume_active) {
            scan_offset = (uint64_t)config->resume_offset;
        }

        if (config->quick_resume &&
            !config->additive_pass &&
            (config->resume_scan_completed || config->resume_completed)) {
            if (existing_scan_state != NULL &&
                existing_scan_state->scan_offset > 0U) {
                scan_offset = existing_scan_state->scan_offset;
            } else if (fallback_total_bytes > 0U) {
                scan_offset = fallback_total_bytes;
            }
            scan_completed = 1;
            completed = config->resume_completed ? 1 : 0;
        }
    }

    *out_scan_offset = scan_offset;
    *out_scan_completed = scan_completed;
    *out_completed = completed;
}

static int raw_all_stage_indicates_scan_completed(
    const RawAllStageState *state
)
{
    if (state == NULL) {
        return 0;
    }
    if (strcmp(state->stage, "scan_loop") == 0 &&
        state->total_bytes > 0ULL &&
        state->progress_bytes >= state->total_bytes) {
        return 1;
    }

    /* A phase label is telemetry, not proof of disk coverage.  A terminating
     * or stale child can briefly publish a post-scan label even though its
     * durable cursor is still in the middle of the source. */
    return state->selected_scope_complete || state->full_source_complete;
}

static int raw_all_stage_indicates_run_completed(
    const RawAllStageState *state
)
{
    return state != NULL &&
           (strcmp(state->stage, "completed") == 0 ||
            strcmp(state->stage, "done") == 0) &&
           raw_all_stage_indicates_scan_completed(state);
}

static uint64_t raw_all_completed_scan_offset_from_stage_or_state(
    const RawAllStageState *stage_state,
    const ScanState *scan_state
)
{
    uint64_t completed_offset = 0ULL;

    if (stage_state != NULL) {
        /* Post-scan phase writers may use the carrier size as total_bytes
         * even when the operator selected a bounded range.  The durable
         * selected-scope endpoint is the truthful raw-read endpoint. */
        if (stage_state->selected_scope_end_bytes >
            stage_state->selected_scope_start_bytes) {
            completed_offset = stage_state->selected_scope_end_bytes;
        } else if (stage_state->total_bytes > 0ULL) {
            completed_offset = stage_state->total_bytes;
        } else if (stage_state->progress_bytes > 0ULL) {
            completed_offset = stage_state->progress_bytes;
        }
    }
    if (completed_offset == 0ULL && scan_state != NULL) {
        if (scan_state->source_size > 0ULL) {
            completed_offset = scan_state->source_size;
        } else {
            completed_offset = scan_state->scan_offset;
        }
    }
    return completed_offset;
}

static int parse_simple_state_value_local(
    const char *line,
    const char *key,
    char *out,
    size_t out_size
)
{
    size_t key_len;
    size_t value_len;
    const char *value;

    if (line == NULL ||
        key == NULL ||
        out == NULL ||
        out_size == 0U) {
        return 0;
    }

    key_len = strlen(key);
    if (strncmp(line, key, key_len) != 0 || line[key_len] != '=') {
        return 0;
    }

    value = line + key_len + 1U;
    value_len = strlen(value);
    while (value_len > 0U &&
           (value[value_len - 1U] == '\n' ||
            value[value_len - 1U] == '\r')) {
        value_len--;
    }
    if (value_len >= out_size) {
        value_len = out_size - 1U;
    }
    memcpy(out, value, value_len);
    out[value_len] = '\0';
    return 1;
}

static int load_raw_all_finalize_checkpoint_file(
    const char *path,
    RawAllFinalizeCheckpointState *out
)
{
    FILE *file;
    char line[1400];
    char value[1024];
    RawAllFinalizeCheckpointState state = {0};

    if (!has_nonempty_text(path) || out == NULL) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        if (parse_simple_state_value_local(
                line,
                "updated_unix",
                value,
                sizeof(value))) {
            state.updated_unix = (time_t)strtoull(value, NULL, 10);
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "run_dir",
                state.run_dir,
                sizeof(state.run_dir))) {
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "source_path",
                state.source_path,
                sizeof(state.source_path))) {
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "scan_mode",
                state.scan_mode,
                sizeof(state.scan_mode))) {
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "source_size",
                value,
                sizeof(value))) {
            state.source_size = strtoull(value, NULL, 10);
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "scan_offset",
                value,
                sizeof(value))) {
            state.scan_offset = strtoull(value, NULL, 10);
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "scan_completed",
                value,
                sizeof(value))) {
            state.scan_completed = atoi(value) != 0;
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "completed",
                value,
                sizeof(value))) {
            state.completed = atoi(value) != 0;
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "stage",
                state.stage,
                sizeof(state.stage))) {
            continue;
        }
        if (parse_simple_state_value_local(
                line,
                "detail",
                state.detail,
                sizeof(state.detail))) {
            continue;
        }
    }
    fclose(file);

    if (!state.scan_completed ||
        state.completed ||
        state.source_size == 0ULL) {
        return 0;
    }
    if (state.scan_offset == 0ULL ||
        state.scan_offset > state.source_size) {
        state.scan_offset = state.source_size;
    }
    if (state.scan_offset < state.source_size) {
        return 0;
    }

    state.present = 1;
    snprintf(state.source_file, sizeof(state.source_file), "%s", path);
    *out = state;
    return 1;
}

static int load_raw_all_finalize_checkpoint_for_run(
    const char *run_dir,
    RawAllFinalizeCheckpointState *out
)
{
    char temp_path[PATH_MAX_LEN];
    char state_path[PATH_MAX_LEN];
    RawAllFinalizeCheckpointState best = {0};
    RawAllFinalizeCheckpointState candidate = {0};

    if (!has_nonempty_text(run_dir) || out == NULL) {
        return 0;
    }

    if (build_state_child_path_local(run_dir, "finalize_checkpoint_recovered.txt", state_path, sizeof(state_path)) &&
        load_raw_all_finalize_checkpoint_file(state_path, &candidate)) {
        best = candidate;
    }
    memset(&candidate, 0, sizeof(candidate));
    if (build_raw_all_finalize_checkpoint_temp_path_for_run_dir(
            run_dir,
            temp_path,
            sizeof(temp_path)) &&
        load_raw_all_finalize_checkpoint_file(temp_path, &candidate)) {
        if (emergency_temp_file_is_older_than_reference_path(temp_path, run_dir)) {
            (void)unlink(temp_path);
        } else if (!best.present ||
                   candidate.updated_unix >= best.updated_unix) {
            best = candidate;
        }
    }

    if (!best.present) {
        return 0;
    }
    *out = best;
    return 1;
}

static void scan_state_copy_identity_from_loaded_local(
    ScanState *dst,
    const ScanState *src
)
{
    if (dst == NULL || src == NULL) {
        return;
    }
    dst->source_ntfs_serial = src->source_ntfs_serial;
    dst->accepted_ntfs_serial_count = src->accepted_ntfs_serial_count;
    memcpy(
        dst->accepted_ntfs_serials,
        src->accepted_ntfs_serials,
        sizeof(dst->accepted_ntfs_serials)
    );
    snprintf(
        dst->source_device_name,
        sizeof(dst->source_device_name),
        "%s",
        src->source_device_name
    );
    dst->source_is_internal = src->source_is_internal;
}

static int recover_scan_state_from_raw_all_finalize_checkpoint(
    const AppConfig *config,
    ScanState *out_state
)
{
    RawAllFinalizeCheckpointState checkpoint = {0};
    uint64_t current_source_size;

    if (config == NULL ||
        out_state == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !has_nonempty_text(config->output_dir) ||
        !has_nonempty_text(config->input_path) ||
        !load_raw_all_finalize_checkpoint_for_run(
            config->output_dir,
            &checkpoint)) {
        return 0;
    }

    current_source_size = probe_input_size_for_eta(config->input_path);
    if (has_nonempty_text(checkpoint.source_path) &&
        strcmp(checkpoint.source_path, config->input_path) != 0) {
        log_runtime_event_error(
            "Ignoring raw-all finalize checkpoint from %s because source path changed: checkpoint=%s current=%s",
            checkpoint.source_file,
            checkpoint.source_path,
            config->input_path
        );
        return 0;
    }
    if (current_source_size > 0ULL &&
        current_source_size != checkpoint.source_size) {
        log_runtime_event_error(
            "Ignoring raw-all finalize checkpoint from %s because source size changed: checkpoint=%llu current=%llu",
            checkpoint.source_file,
            (unsigned long long)checkpoint.source_size,
            (unsigned long long)current_source_size
        );
        return 0;
    }

    memset(out_state, 0, sizeof(*out_state));
    snprintf(
        out_state->source_path,
        sizeof(out_state->source_path),
        "%s",
        has_nonempty_text(config->input_path)
            ? config->input_path
            : checkpoint.source_path
    );
    snprintf(
        out_state->scan_mode,
        sizeof(out_state->scan_mode),
        "%s",
        has_nonempty_text(checkpoint.scan_mode)
            ? checkpoint.scan_mode
            : config_scan_mode_label(config)
    );
    out_state->source_size = checkpoint.source_size;
    out_state->scan_offset = checkpoint.source_size;
    out_state->scan_completed = 1;
    out_state->completed = 0;
    log_runtime_event_info(
        "Recovered raw-all completed-scan checkpoint from %s; resume should continue with finalize/name instead of rescanning the source",
        checkpoint.source_file
    );
    return 1;
}

static void raw_all_preserve_completed_scan_state_for_name_retry(
    const AppConfig *config
)
{
    char stage_path[PATH_MAX_LEN];
    RawAllStageState stage_state = {0};
    ScanState scan_state = {0};
    uint64_t completed_offset;

    if (config == NULL ||
        config->scan_state_path == NULL ||
        config->scan_state_path[0] == '\0') {
        return;
    }

    (void)scan_state_load(config->scan_state_path, &scan_state);
    if (has_nonempty_text(config->output_dir) &&
        build_raw_all_stage_path_for_run_dir(
            config->output_dir,
            stage_path,
            sizeof(stage_path))) {
        (void)load_raw_all_stage_state(stage_path, &stage_state);
    }

    completed_offset = raw_all_completed_scan_offset_from_stage_or_state(
        &stage_state,
        &scan_state
    );
    if (completed_offset == 0ULL) {
        return;
    }
    if (scan_state.source_size > 0ULL &&
        completed_offset < scan_state.source_size) {
        log_runtime_event_error(
            "Not preserving completed raw-all scan state for name retry: completion hint is byte %llu but saved source_size is %llu",
            (unsigned long long)completed_offset,
            (unsigned long long)scan_state.source_size
        );
        return;
    }
    if (scan_state.source_size > 0ULL) {
        completed_offset = scan_state.source_size;
    }

    (void)scan_state_write(
        config->scan_state_path,
        has_nonempty_text(config->input_path)
            ? config->input_path
            : scan_state.source_path,
        config_scan_mode_label(config),
        completed_offset,
        completed_offset,
        1,
        0
    );
}

static int recover_scan_state_from_raw_all_stage(
    const AppConfig *config,
    ScanState *out_state
)
{
    char stage_path[PATH_MAX_LEN];
    RawAllStageState stage_state = {0};
    uint64_t recovered_offset = 0ULL;
    uint64_t current_source_size = 0ULL;
    int stage_scan_completed = 0;
    int stage_is_post_scan = 0;
    int stage_covers_full_source = 0;

    if (config == NULL ||
        out_state == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !has_nonempty_text(config->output_dir) ||
        !has_nonempty_text(config->input_path) ||
        !build_raw_all_stage_path_for_run_dir(
            config->output_dir,
            stage_path,
            sizeof(stage_path)) ||
        !load_raw_all_stage_state(stage_path, &stage_state)) {
        return 0;
    }

    stage_scan_completed = raw_all_stage_indicates_scan_completed(&stage_state);
    stage_is_post_scan =
        stage_scan_completed &&
        (strcmp(stage_state.stage, "retry_hotspots") == 0 ||
         raw_all_stage_is_post_scan_nonrestart_phase(stage_state.stage));
    current_source_size = probe_input_size_for_eta(config->input_path);
    if (current_source_size == 0ULL &&
        stage_state.source_size_bytes > 0ULL) {
        /* stat().st_size is commonly zero for Linux block devices.  The
         * durable stage carries the Reader-probed carrier size. */
        current_source_size = stage_state.source_size_bytes;
    }

    stage_covers_full_source = stage_state.full_source_complete;
    if (!stage_covers_full_source && current_source_size > 0ULL) {
        if (stage_state.selected_scope_end_bytes >
            stage_state.selected_scope_start_bytes) {
            stage_covers_full_source =
                stage_state.selected_scope_end_bytes >= current_source_size;
        } else {
            uint64_t configured_end =
                raw_all_effective_scan_end_offset_for_source(
                    config, current_source_size);

            stage_covers_full_source = configured_end >= current_source_size;
        }
    }

    recovered_offset =
        stage_state.selected_scope_end_bytes >
            stage_state.selected_scope_start_bytes
            ? stage_state.selected_scope_end_bytes
            : stage_state.progress_bytes;
    if (recovered_offset == 0ULL &&
        stage_state.budget_base_bytes > 0ULL) {
        recovered_offset = stage_state.budget_base_bytes;
    }
    if (stage_is_post_scan && stage_covers_full_source &&
        current_source_size > 0ULL &&
        recovered_offset < current_source_size) {
        recovered_offset = current_source_size;
    }

    if (recovered_offset == 0ULL &&
        !stage_scan_completed) {
        return 0;
    }

    memset(out_state, 0, sizeof(*out_state));
    snprintf(
        out_state->source_path,
        sizeof(out_state->source_path),
        "%s",
        config->input_path
    );
    snprintf(
        out_state->scan_mode,
        sizeof(out_state->scan_mode),
        "%s",
        config_scan_mode_label(config)
    );
    out_state->source_size = stage_state.total_bytes;
    if (stage_is_post_scan &&
        current_source_size > out_state->source_size) {
        out_state->source_size = current_source_size;
    }
    out_state->scan_offset = recovered_offset;
    if (out_state->source_size > 0ULL &&
        out_state->scan_offset > out_state->source_size) {
        out_state->scan_offset = out_state->source_size;
    }
    out_state->scan_completed =
        stage_scan_completed && stage_covers_full_source;
    out_state->completed =
        raw_all_stage_indicates_run_completed(&stage_state);
    {
        if (current_source_size > 0ULL) {
            if (out_state->source_size == 0ULL ||
                out_state->source_size < current_source_size) {
                out_state->source_size = current_source_size;
            }
            if (out_state->scan_completed &&
                out_state->scan_offset < current_source_size) {
                log_runtime_event_error(
                    "Saved raw_all_stage.txt looked complete at byte %llu, but the current source is %llu bytes; treating it as incomplete resume progress instead of completed state",
                    (unsigned long long)out_state->scan_offset,
                    (unsigned long long)current_source_size
                );
                out_state->scan_completed = 0;
                out_state->completed = 0;
            }
            if (out_state->completed && !out_state->scan_completed) {
                out_state->completed = 0;
            }
        }
    }
    return 1;
}

static int raw_all_sanitize_loaded_scan_state_against_current_source(
    const AppConfig *config,
    ScanState *state
)
{
    uint64_t current_source_size;
    uint64_t selected_scope_end;
    uint64_t mismatch_slack = 1024ULL * 1024ULL;
    int changed = 0;

    if (config == NULL ||
        state == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !has_nonempty_text(config->input_path)) {
        return 0;
    }

    current_source_size = probe_input_size_for_eta(config->input_path);
    if (current_source_size == 0ULL && state->source_size > 0ULL) {
        /* Linux block devices usually report st_size=0.  Source identity is
         * checked separately; use the saved Reader-probed size for scope
         * repair instead of silently skipping physical disks. */
        current_source_size = state->source_size;
    }
    if (current_source_size == 0ULL) {
        return 0;
    }

    if (state->source_size == 0ULL) {
        state->source_size = current_source_size;
        changed = 1;
    }

    if (current_source_size > state->source_size &&
        current_source_size - state->source_size > mismatch_slack) {
        log_runtime_event_error(
            "Saved raw-all scan_state source_size=%llu is smaller than the current source size=%llu; clearing completed flags so resume cannot treat a small window/finalize state as a completed full-disk scan",
            (unsigned long long)state->source_size,
            (unsigned long long)current_source_size
        );
        state->source_size = current_source_size;
        state->scan_completed = 0;
        state->completed = 0;
        changed = 1;
    }

    if (state->scan_offset > current_source_size) {
        state->scan_offset = current_source_size;
        changed = 1;
    }
    selected_scope_end = raw_all_effective_scan_end_offset_for_source(
        config,
        current_source_size
    );
    if (selected_scope_end > 0ULL &&
        selected_scope_end < current_source_size &&
        state->scan_offset > selected_scope_end) {
        log_runtime_event_error(
            "Saved raw-all scan_state offset=%llu is past the currently selected scope end=%llu; clamping resume to the selected endpoint and clearing full-source completion flags",
            (unsigned long long)state->scan_offset,
            (unsigned long long)selected_scope_end
        );
        state->scan_offset = selected_scope_end;
        state->scan_completed = 0;
        state->completed = 0;
        changed = 1;
    }
    if (state->source_size == current_source_size &&
        state->scan_offset < state->source_size &&
        (state->scan_completed || state->completed)) {
        log_runtime_event_error(
            "Saved raw-all scan_state claimed completion at byte %llu of %llu; clearing completed flags and preserving the resume offset",
            (unsigned long long)state->scan_offset,
            (unsigned long long)state->source_size
        );
        state->scan_completed = 0;
        state->completed = 0;
        changed = 1;
    }
    if (state->completed && !state->scan_completed) {
        state->completed = 0;
        changed = 1;
    }
    return changed;
}

static uint64_t raw_all_clamp_resume_hint_to_source(
    uint64_t offset,
    uint64_t source_size
)
{
    if (source_size > 0ULL && offset > source_size) {
        return source_size;
    }
    return offset;
}

static void raw_all_consider_resume_hint(
    uint64_t offset,
    uint64_t source_size,
    const char *source_label,
    uint64_t *best_offset,
    char *best_source,
    size_t best_source_size
)
{
    if (best_offset == NULL || offset == 0ULL) {
        return;
    }

    offset = raw_all_clamp_resume_hint_to_source(offset, source_size);
    if (offset <= *best_offset) {
        return;
    }

    *best_offset = offset;
    if (best_source != NULL && best_source_size > 0U) {
        snprintf(
            best_source,
            best_source_size,
            "%s",
            has_nonempty_text(source_label) ? source_label : "unknown"
        );
    }
}

static int raw_all_parse_u64_at(
    const char *text,
    uint64_t *out_value
)
{
    char *end = NULL;
    unsigned long long value = 0ULL;

    if (out_value != NULL) {
        *out_value = 0ULL;
    }
    if (text == NULL || out_value == NULL) {
        return 0;
    }

    while (*text != '\0' && isspace((unsigned char)*text)) {
        text++;
    }

    errno = 0;
    value = strtoull(text, &end, 10);
    if (errno != 0 || end == text) {
        return 0;
    }

    *out_value = (uint64_t)value;
    return 1;
}

static int raw_all_parse_u64_after_marker(
    const char *line,
    const char *marker,
    uint64_t *out_value
)
{
    const char *cursor;

    if (line == NULL || marker == NULL || out_value == NULL) {
        return 0;
    }

    cursor = strstr(line, marker);
    if (cursor == NULL) {
        return 0;
    }

    cursor += strlen(marker);
    return raw_all_parse_u64_at(cursor, out_value);
}

static uint64_t raw_all_resume_hint_from_runtime_line(
    const char *line
)
{
    uint64_t value = 0ULL;
    const char *to_marker;

    if (line == NULL) {
        return 0ULL;
    }

    if (strstr(line, "Stall retry rewound saved scan_offset from ") != NULL ||
        strstr(line, "Stall retry advanced saved scan_offset from ") != NULL ||
        strstr(line, "Crash retry advanced saved scan_offset from ") != NULL) {
        to_marker = strstr(line, " to ");
        if (to_marker != NULL &&
            raw_all_parse_u64_at(to_marker + 4, &value)) {
            return value;
        }
    }

    if (raw_all_parse_u64_after_marker(line, "scan_offset=", &value) ||
        raw_all_parse_u64_after_marker(line, "Resuming raw-all scan from byte ", &value) ||
        raw_all_parse_u64_after_marker(line, "around scan offset ", &value)) {
        return value;
    }

    return 0ULL;
}

static uint64_t raw_all_farthest_runtime_resume_hint(
    const char *run_dir,
    uint64_t source_size
)
{
    char path[PATH_MAX_LEN];
    char line[512];
    FILE *file;
    uint64_t best_offset = 0ULL;

    if (!has_nonempty_text(run_dir) ||
        snprintf(
            path,
            sizeof(path),
            "%s/" APP_STATE_DIR_NAME "/" RUNTIME_EVENTS_LOG_NAME,
            run_dir) >= (int)sizeof(path)) {
        return 0ULL;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0ULL;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        uint64_t value = raw_all_resume_hint_from_runtime_line(line);

        value = raw_all_clamp_resume_hint_to_source(value, source_size);
        if (value > best_offset) {
            best_offset = value;
        }
    }

    fclose(file);
    return best_offset;
}

static uint64_t raw_all_farthest_read_trouble_resume_hint(
    const char *run_dir,
    uint64_t source_size
)
{
    char path[PATH_MAX_LEN];
    ReadTroubleMapEntry *entries = NULL;
    size_t count = 0U;
    size_t i;
    uint64_t best_offset = 0ULL;

    if (!has_nonempty_text(run_dir) ||
        !build_read_trouble_map_path_for_run_dir(
            run_dir,
            path,
            sizeof(path)) ||
        !load_read_trouble_map_entries(path, &entries, &count)) {
        return 0ULL;
    }

    for (i = 0U; i < count; i++) {
        uint64_t value = raw_all_clamp_resume_hint_to_source(
            entries[i].end_offset > entries[i].offset
                ? entries[i].end_offset
                : entries[i].offset,
            source_size
        );
        if (value > best_offset) {
            best_offset = value;
        }
    }

    free(entries);
    return best_offset;
}

static uint64_t raw_all_farthest_deferred_zone_resume_hint(
    const char *run_dir,
    uint64_t source_size
)
{
    char path[PATH_MAX_LEN];
    char line[256];
    FILE *file;
    uint64_t best_offset = 0ULL;

    if (!has_nonempty_text(run_dir) ||
        !build_deferred_bad_zones_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return 0ULL;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0ULL;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long start = 0ULL;
        unsigned long long end = 0ULL;
        unsigned long long bytes = 0ULL;
        size_t ranges = 0U;
        uint64_t value;

        if (strncmp(line, "offset\t", 7U) == 0) {
            continue;
        }
        if (sscanf(line, "%llu\t%llu\t%llu\t%zu", &start, &end, &bytes, &ranges) != 4 ||
            end <= start ||
            bytes == 0ULL) {
            continue;
        }

        value = raw_all_clamp_resume_hint_to_source((uint64_t)end, source_size);
        if (value > best_offset) {
            best_offset = value;
        }
    }

    fclose(file);
    return best_offset;
}

static uint64_t raw_all_farthest_gui_coverage_resume_hint(
    const char *run_dir,
    uint64_t source_size
)
{
    char path[PATH_MAX_LEN];
    char line[256];
    FILE *file;
    uint64_t best_offset = 0ULL;
    uint64_t pass_contiguous_end = 0ULL;
    char current_pass_id[64] = "";

    if (!has_nonempty_text(run_dir) ||
        snprintf(
            path,
            sizeof(path),
            "%s/" APP_STATE_DIR_NAME "/gui_read_coverage.tsv",
            run_dir) >= (int)sizeof(path)) {
        return 0ULL;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 0ULL;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char pass_id[64];
        unsigned long long start = 0ULL;
        unsigned long long end = 0ULL;
        uint64_t value;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }
        if (sscanf(line, "%63[^\t]\t%llu\t%llu", pass_id, &start, &end) != 3 ||
            end <= start) {
            continue;
        }

        if (strcmp(current_pass_id, pass_id) != 0) {
            snprintf(current_pass_id, sizeof(current_pass_id), "%s", pass_id);
            pass_contiguous_end = 0ULL;
        }
        if ((uint64_t)start <= pass_contiguous_end) {
            if ((uint64_t)end > pass_contiguous_end) {
                pass_contiguous_end = (uint64_t)end;
            }
            value = raw_all_clamp_resume_hint_to_source(pass_contiguous_end, source_size);
            if (value > best_offset) {
                best_offset = value;
            }
        }
    }

    fclose(file);
    return best_offset;
}

static int recover_raw_all_farthest_resume_hint(
    const AppConfig *config,
    const ScanState *base_state,
    uint64_t *out_offset,
    char *out_source,
    size_t out_source_size
)
{
    uint64_t source_size = 0ULL;
    uint64_t best_offset = 0ULL;
    char best_source[64] = "";
    uint64_t candidate;

    if (out_offset != NULL) {
        *out_offset = 0ULL;
    }
    if (out_source != NULL && out_source_size > 0U) {
        out_source[0] = '\0';
    }
    if (config == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        config->manual_start_explicit ||
        config->additive_requested ||
        !has_nonempty_text(config->output_dir)) {
        return 0;
    }

    if (base_state != NULL && base_state->source_size > 0ULL) {
        source_size = base_state->source_size;
    }
    if (source_size == 0ULL && has_nonempty_text(config->input_path)) {
        source_size = probe_input_size_for_eta(config->input_path);
    }

    if (base_state != NULL && base_state->scan_offset > 0ULL) {
        raw_all_consider_resume_hint(
            base_state->scan_offset,
            source_size,
            "scan_state.txt",
            &best_offset,
            best_source,
            sizeof(best_source)
        );
    }

    candidate = raw_all_farthest_read_trouble_resume_hint(config->output_dir, source_size);
    raw_all_consider_resume_hint(
        candidate,
        source_size,
        "read_trouble_map.tsv",
        &best_offset,
        best_source,
        sizeof(best_source)
    );

    candidate = raw_all_farthest_deferred_zone_resume_hint(config->output_dir, source_size);
    raw_all_consider_resume_hint(
        candidate,
        source_size,
        "deferred_bad_zones.tsv",
        &best_offset,
        best_source,
        sizeof(best_source)
    );

    candidate = raw_all_farthest_gui_coverage_resume_hint(config->output_dir, source_size);
    raw_all_consider_resume_hint(
        candidate,
        source_size,
        "gui_read_coverage.tsv",
        &best_offset,
        best_source,
        sizeof(best_source)
    );

    candidate = raw_all_farthest_runtime_resume_hint(config->output_dir, source_size);
    raw_all_consider_resume_hint(
        candidate,
        source_size,
        RUNTIME_EVENTS_LOG_NAME,
        &best_offset,
        best_source,
        sizeof(best_source)
    );

    if (best_offset == 0ULL) {
        return 0;
    }

    if (out_offset != NULL) {
        *out_offset = best_offset;
    }
    if (out_source != NULL && out_source_size > 0U) {
        snprintf(
            out_source,
            out_source_size,
            "%s",
            best_source[0] != '\0' ? best_source : "resume-sidecar"
        );
    }
    return 1;
}

static int raw_all_should_defer_background_helper(const AppConfig *config)
{
    if (fs_backend_current_kind() != FS_BACKEND_KIND_NTFS) {
        return raw_all_extra_name_follow_up_requested(config);
    }

    /*
     * During raw-all we now want the metadata helper to stay alive so the
     * first pass can keep filling in MFT/$I30 state while bytes are being
     * read. The helper itself runs in conservative metadata-first mode for
     * NTFS, so we no longer need to defer it just because a later name pass
     * is planned.
     */
    return 0;
}

static int raw_all_should_use_conservative_metadata_background(
    const AppConfig *config,
    int live_mft_observation_disabled
)
{
    if (fs_backend_current_kind() == FS_BACKEND_KIND_NONE) {
        return 0;
    }

    /*
     * For NTFS raw-all we want the helper to spend the scan pass on
     * metadata accumulation and index building, not on renaming/moving
     * outputs mid-scan. Final reconcile still happens after the source has
     * been read.
     */
    if (fs_backend_current_kind() == FS_BACKEND_KIND_NTFS) {
        return 1;
    }

    if (!fs_backend_supports_live_metadata_observation()) {
        return 1;
    }

    if (live_mft_observation_disabled) {
        return 1;
    }

    return raw_all_extra_name_follow_up_requested(config);
}

static int app_apply_default_users_root_scope(AppConfig *config)
{
    if (config == NULL ||
        config->scan_mode != APP_SCAN_MODE_MFT_USERS ||
        has_nonempty_text(config->root_scope_csv)) {
        return 1;
    }

    if (snprintf(
            config->root_scope_csv_storage,
            sizeof(config->root_scope_csv_storage),
            "%s",
            "Users") >= (int)sizeof(config->root_scope_csv_storage)) {
        log_error("Default folders --fold is too long");
        return 0;
    }

    config->root_scope_csv = config->root_scope_csv_storage;
    config->root_scope_defaulted = 1;
    log_info(
        "Folder path default --fold: %s",
        config->root_scope_csv
    );
    return 1;
}

static int normalize_posix_path_text(
    const char *input,
    char *out,
    size_t out_size
)
{
    size_t write_pos = 0U;
    int previous_was_slash = 0;

    if (out == NULL || out_size == 0U) {
        return 0;
    }

    out[0] = '\0';
    if (input == NULL) {
        return 1;
    }

    while (*input != '\0') {
        char ch = *input++;

        if (ch == '/') {
            if (previous_was_slash) {
                continue;
            }
            previous_was_slash = 1;
        } else {
            previous_was_slash = 0;
        }

        if (write_pos + 1U >= out_size) {
            return 0;
        }
        out[write_pos++] = ch;
    }

    while (write_pos > 1U && out[write_pos - 1U] == '/') {
        write_pos--;
    }

    out[write_pos] = '\0';
    return 1;
}

static size_t count_recovered_files_for_run(const char *output_dir)
{
    char recovered_dir[2048];

    if (!has_nonempty_text(output_dir) ||
        snprintf(
            recovered_dir,
            sizeof(recovered_dir),
            "%s/%s",
            output_dir,
            APP_RECOVERED_DIR_NAME) >= (int)sizeof(recovered_dir)) {
        return 0;
    }

    return count_recovered_files_recursive(recovered_dir);
}

static size_t count_unident_files_for_run(const char *output_dir)
{
    char unident_dir[2048];
    char legacy_unident_dir[2048];
    size_t count = 0U;

    if (!has_nonempty_text(output_dir)) {
        return 0U;
    }

    if (snprintf(
            unident_dir,
            sizeof(unident_dir),
            "%s/%s/%s",
            output_dir,
            APP_RECOVERED_DIR_NAME,
            APP_UNIDENT_DIR_NAME) < (int)sizeof(unident_dir)) {
        count += count_recovered_files_recursive(unident_dir);
    }
    if (snprintf(
            legacy_unident_dir,
            sizeof(legacy_unident_dir),
            "%s/%s/%s",
            output_dir,
            APP_RECOVERED_DIR_NAME,
            APP_LEGACY_UNIDENT_DIR_NAME) < (int)sizeof(legacy_unident_dir)) {
        count += count_recovered_files_recursive(legacy_unident_dir);
    }

    return count;
}

static void remove_empty_unident_directories_for_run(const char *output_dir)
{
    char path[2048];
    const char *names[] = {
        APP_UNIDENT_DIR_NAME,
        APP_LEGACY_UNIDENT_DIR_NAME
    };
    size_t index;

    if (!has_nonempty_text(output_dir)) {
        return;
    }

    for (index = 0U; index < sizeof(names) / sizeof(names[0]); ++index) {
        if (snprintf(
                path,
                sizeof(path),
                "%s/%s/%s",
                output_dir,
                APP_RECOVERED_DIR_NAME,
                names[index]) >= (int)sizeof(path)) {
            continue;
        }
        if (rmdir(path) == 0) {
            log_verbose("Removed empty recovery directory: %s", path);
        }
    }
}

static size_t count_photorec_import_files_for_run(const char *output_dir)
{
    char photorec_dir[2048];

    if (!has_nonempty_text(output_dir) ||
        snprintf(
            photorec_dir,
            sizeof(photorec_dir),
            "%s/%s",
            output_dir,
            APP_PHOTOREC_IMPORT_RELATIVE_DIR) >= (int)sizeof(photorec_dir)) {
        return 0U;
    }

    return count_recovered_files_recursive(photorec_dir);
}

typedef struct {
    char label[32];
    size_t files;
    uint64_t bytes;
} RunFormatStat;

typedef struct {
    char label[64];
    size_t files;
    uint64_t bytes;
} RunBucketStat;

typedef struct {
    size_t total_files;
    uint64_t total_bytes;
    RunFormatStat *formats;
    size_t format_count;
    size_t format_capacity;
    RunBucketStat *buckets;
    size_t bucket_count;
    size_t bucket_capacity;
} RunRecoverySummary;

typedef struct {
    uint64_t offset;
    uint64_t end_offset;
    uint64_t bytes;
    int errno_code;
    uint64_t granularity_bytes;
    char source_path[PATH_MAX_LEN];
    char run_id[256];
    char note[160];
} ReadErrorRange;

typedef struct {
    uint64_t start_offset;
    uint64_t end_offset;
    uint64_t bytes;
    size_t ranges;
} ReadErrorCluster;

typedef struct {
    int errno_code;
    char note[160];
    size_t ranges;
    uint64_t bytes;
} ReadErrorKindStat;

#define RUN_LOG_READ_ERROR_CLUSTER_GAP_BYTES (1ULL * 1024ULL * 1024ULL)
#define RUN_LOG_MAX_EXACT_READ_ERRORS 20U
#define RUN_LOG_MAX_HOTSPOTS 5U
#define RUN_LOG_LIGHTWEIGHT_TRACKED_THRESHOLD 2000U
#define NAME_VISIBLE_COUNT_MAX_FILES 2048U
#define NAME_VISIBLE_COUNT_TIME_BUDGET_SECONDS 0.20
#define NAME_CONTEXT_SUMMARY_MAX_FILES 2048U
#define NAME_CONTEXT_SUMMARY_TIME_BUDGET_SECONDS 0.50
#define NAME_HINT_SUMMARY_MAX_FILES 2048U
#define NAME_HINT_SUMMARY_TIME_BUDGET_SECONDS 0.50
#define RUN_LOG_MAX_READ_ERROR_SUMMARY_FILE_BYTES (32ULL * 1024ULL * 1024ULL)

typedef struct {
    size_t total_files;
    size_t reconciled_files;
    size_t unreconciled_files;
    size_t embedded_files;
    int available;
} RecoveredOutputLogSummary;

typedef struct {
    size_t recovered_files;
    size_t named_files;
    size_t unident_files;
    int available;
    int artifact_state_available;
    int used_backend_artifacts;
    FsBackendArtifactState artifact_state;
} RunRecoveredStateSummary;

typedef struct {
    long long abs_offset;
    int reconciled;
    int embedded;
    char *path;
    uint64_t path_hash;
    size_t order;
} RecoveredOutputLogRow;

static int compare_recovered_output_log_rows(
    const void *left,
    const void *right
)
{
    const RecoveredOutputLogRow *a = (const RecoveredOutputLogRow *)left;
    const RecoveredOutputLogRow *b = (const RecoveredOutputLogRow *)right;

    if (a->abs_offset < b->abs_offset) {
        return -1;
    }
    if (a->abs_offset > b->abs_offset) {
        return 1;
    }
    return 0;
}

static uint64_t hash_text_local(const char *text)
{
    uint64_t hash = 1469598103934665603ULL;

    if (text == NULL) {
        return hash_u64_local(0ULL);
    }
    while (*text != '\0') {
        hash ^= (uint64_t)(unsigned char)*text++;
        hash *= 1099511628211ULL;
    }
    return hash_u64_local(hash);
}

static int compare_recovered_output_log_rows_by_path(
    const void *left,
    const void *right
)
{
    const RecoveredOutputLogRow *a = (const RecoveredOutputLogRow *)left;
    const RecoveredOutputLogRow *b = (const RecoveredOutputLogRow *)right;
    const char *ap = a->path != NULL ? a->path : "";
    const char *bp = b->path != NULL ? b->path : "";
    int cmp;

    if (a->path_hash < b->path_hash) {
        return -1;
    }
    if (a->path_hash > b->path_hash) {
        return 1;
    }
    cmp = strcmp(ap, bp);
    if (cmp != 0) {
        return cmp;
    }
    if (a->order < b->order) {
        return -1;
    }
    if (a->order > b->order) {
        return 1;
    }
    return 0;
}

static int force_detailed_run_log(void)
{
    const char *value = getenv("CARV_FORCE_DETAILED_RUN_LOG");

    return value != NULL &&
           value[0] != '\0' &&
           strcmp(value, "0") != 0;
}

static int regular_file_size_bytes(
    const char *path,
    uint64_t *out_size
)
{
    struct stat st;

    if (out_size != NULL) {
        *out_size = 0U;
    }
    if (!has_nonempty_text(path) || out_size == NULL) {
        return 0;
    }
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode) || st.st_size < 0) {
        return 0;
    }

    *out_size = (uint64_t)st.st_size;
    return 1;
}

static int build_run_child_path(
    const char *output_dir,
    const char *child_name,
    char *out,
    size_t out_size
)
{
    if (!has_nonempty_text(output_dir) ||
        !has_nonempty_text(child_name) ||
        out == NULL ||
        out_size == 0U) {
        return 0;
    }

    return snprintf(out, out_size, "%s/%s", output_dir, child_name) < (int)out_size;
}

static void append_runtime_events_section(
    FILE *file,
    const char *output_dir
)
{
    char events_path[PATH_MAX_LEN];
    char size_text[96];
    char line[512];
    FILE *events = NULL;
    uint64_t file_size = 0U;
    uint64_t skip_bytes = 0U;

    if (file == NULL) {
        return;
    }

    fprintf(file, "\nruntime_events:\n");
    if (!build_state_child_path_local(
            output_dir,
            RUNTIME_EVENTS_LOG_NAME,
            events_path,
            sizeof(events_path)) ||
        !regular_file_size_bytes(events_path, &file_size) ||
        file_size == 0U) {
        fprintf(file, "- none logged in this run\n");
        return;
    }

    format_size_summary(file_size, size_text, sizeof(size_text));
    fprintf(file, "- file: %s/%s\n", APP_STATE_DIR_NAME, RUNTIME_EVENTS_LOG_NAME);
    fprintf(file, "- size: %s\n", size_text);

    events = fopen(events_path, "r");
    if (events == NULL) {
        fprintf(file, "- could not open runtime event log for embedding\n");
        return;
    }

    if (file_size > RUN_LOG_MAX_RUNTIME_EVENT_BYTES) {
        skip_bytes = file_size - RUN_LOG_MAX_RUNTIME_EVENT_BYTES;
        if (fseeko(events, (off_t)skip_bytes, SEEK_SET) == 0) {
            if (fgets(line, sizeof(line), events) != NULL) {
                fprintf(
                    file,
                    "- detail_note: event log is large; showing the last %.0f KiB here and keeping the full file in state/%s\n",
                    (double)RUN_LOG_MAX_RUNTIME_EVENT_BYTES / 1024.0,
                    RUNTIME_EVENTS_LOG_NAME
                );
            }
        } else {
            rewind(events);
            skip_bytes = 0U;
        }
    }

    fprintf(file, "- entries:\n");
    while (fgets(line, sizeof(line), events) != NULL) {
        size_t line_length = strlen(line);

        fprintf(file, "  %s", line);
        if (line_length == 0U || line[line_length - 1U] != '\n') {
            fputc('\n', file);
        }
    }

    fclose(events);
}

static int load_recovered_output_summary_from_live_stats(
    const char *output_dir,
    RecoveredOutputLogSummary *out_summary
)
{
    char stats_path[PATH_MAX_LEN];
    char legacy_stats_path[PATH_MAX_LEN];
    uint64_t stats_size = 0U;
    FsBackendLiveStats live_stats = {0};
    FsBackendLiveStats candidate_stats = {0};
    int have_live_stats = 0;

    if (out_summary == NULL) {
        return 0;
    }

    memset(out_summary, 0, sizeof(*out_summary));
    if (build_state_child_path_local(
             output_dir,
             "metadata_live_stats.txt",
             stats_path,
             sizeof(stats_path)) &&
        regular_file_size_bytes(stats_path, &stats_size) &&
        stats_size > 0U &&
        load_live_stats_file_for_supervisor(stats_path, &candidate_stats)) {
        live_stats = candidate_stats;
        have_live_stats = 1;
    }

    if (build_state_child_path_local(
            output_dir,
            "spool_live_stats.txt",
            legacy_stats_path,
            sizeof(legacy_stats_path)) &&
        regular_file_size_bytes(legacy_stats_path, &stats_size) &&
        stats_size > 0U &&
        load_live_stats_file_for_supervisor(legacy_stats_path, &candidate_stats)) {
        if (!have_live_stats ||
            live_stats.recovered_outputs_current == 0ULL ||
            candidate_stats.recovered_outputs_current >
                live_stats.recovered_outputs_current ||
            (candidate_stats.recovered_outputs_current ==
                 live_stats.recovered_outputs_current &&
             candidate_stats.unident_outputs_current <
                 live_stats.unident_outputs_current)) {
            live_stats = candidate_stats;
            have_live_stats = 1;
        }
    }

    if (!have_live_stats) {
        return 0;
    }

    out_summary->total_files = (size_t)live_stats.recovered_outputs_current;
    out_summary->reconciled_files = (size_t)live_stats.named_outputs_current;
    out_summary->unreconciled_files = (size_t)live_stats.unident_outputs_current;
    out_summary->available = 1;
    return 1;
}

static int load_recovered_output_summary_from_backend_artifacts(
    const char *output_dir,
    RecoveredOutputLogSummary *out_summary
)
{
    FsBackendArtifactState artifact_state = {0};
    const char *backend_output_dir = fs_backend_current_output_dir();

    if (out_summary == NULL) {
        return 0;
    }

    memset(out_summary, 0, sizeof(*out_summary));
    if (!has_nonempty_text(output_dir) ||
        fs_backend_current_kind() == FS_BACKEND_KIND_NONE ||
        !has_nonempty_text(backend_output_dir) ||
        strcmp(output_dir, backend_output_dir) != 0) {
        return 0;
    }

    fs_backend_get_artifact_state(
        FS_BACKEND_ARTIFACT_PHASE_NAME_RESUME,
        &artifact_state
    );
    if (!artifact_state.metadata_snapshot_ready &&
        !artifact_state.recovered_output_log_ready &&
        !artifact_state.finalize_state_ready &&
        fs_backend_recovered_output_count() == 0U) {
        return 0;
    }

    out_summary->total_files = fs_backend_recovered_output_count();
    out_summary->reconciled_files = fs_backend_named_output_count();
    out_summary->unreconciled_files = fs_backend_unreconciled_output_count();
    out_summary->available = 1;
    return 1;
}

static void append_metadata_backend_summary(
    FILE *file,
    const char *output_dir,
    const RecoveredOutputLogSummary *tracked_summary
)
{
    RawAllStageState stage_state = {0};
    FsBackendLiveStats live_stats = {0};
    SupervisorThreadActivityState activity_state = {0};
    char stage_path[PATH_MAX_LEN];
    char thread_activity_path[PATH_MAX_LEN];
    int have_stage = 0;
    int have_live_stats = 0;
    int have_activity = 0;
    size_t record_index_count = 0U;
    size_t range_index_count = 0U;
    uint64_t named_outputs_current = 0ULL;
    uint64_t recovered_outputs_current = 0ULL;

    if (file == NULL) {
        return;
    }

    fprintf(file, "\nmetadata_backend:\n");
    if (has_nonempty_text(output_dir) &&
        build_raw_all_stage_path_for_run_dir(
            output_dir,
            stage_path,
            sizeof(stage_path))) {
        have_stage = load_raw_all_stage_state(stage_path, &stage_state);
    }
    if (has_nonempty_text(output_dir)) {
        have_live_stats = load_metadata_live_stats_for_supervisor(
            output_dir,
            &live_stats
        );
    }
    if (has_nonempty_text(output_dir) &&
        build_thread_activity_path_for_run_dir(
            output_dir,
            thread_activity_path,
            sizeof(thread_activity_path))) {
        have_activity = load_thread_activity_state_for_supervisor(
            thread_activity_path,
            &activity_state
        );
    }

    if (!have_stage && !have_live_stats && !have_activity) {
        fprintf(file, "- no metadata backend state was captured for this run\n");
        return;
    }

    if (have_stage) {
        fprintf(
            file,
            "- backend: %s\n",
            has_nonempty_text(stage_state.fs_backend_name)
                ? stage_state.fs_backend_name
                : (has_nonempty_text(stage_state.fs_backend)
                       ? stage_state.fs_backend
                       : "unknown")
        );
        fprintf(
            file,
            "- metadata_context_available: %s\n",
            stage_state.metadata_context_available ? "yes" : "no"
        );
        fprintf(
            file,
            "- live_metadata_observation_available: %s\n",
            stage_state.live_metadata_observation_available ? "yes" : "no"
        );
    }

    if (have_live_stats) {
        record_index_count = live_stats.record_index_count;
        range_index_count = live_stats.range_index_count;
        named_outputs_current = live_stats.named_outputs_current;
        recovered_outputs_current = live_stats.recovered_outputs_current;
    } else if (have_activity) {
        record_index_count = activity_state.metadata_record_index_count;
        range_index_count = activity_state.metadata_range_index_count;
    }

    fprintf(file, "- record_index_count: %zu\n", record_index_count);
    fprintf(file, "- range_index_count: %zu\n", range_index_count);
    if (have_live_stats) {
        fprintf(
            file,
            "- recovered_outputs_current: %llu\n",
            (unsigned long long)recovered_outputs_current
        );
        fprintf(
            file,
            "- named_outputs_current: %llu\n",
            (unsigned long long)named_outputs_current
        );
    }
    if (tracked_summary != NULL &&
        tracked_summary->available &&
        tracked_summary->total_files > 0U &&
        (!have_live_stats ||
         (recovered_outputs_current == 0ULL && named_outputs_current == 0ULL))) {
        fprintf(
            file,
            "- tracked_outputs_log: recovered=%zu named=%zu unreconciled=%zu\n",
            tracked_summary->total_files,
            tracked_summary->reconciled_files,
            tracked_summary->unreconciled_files
        );
    }

    if ((have_stage &&
         strcmp(stage_state.fs_backend, "ntfs") == 0 &&
         stage_state.metadata_context_available &&
         record_index_count == 0U &&
         range_index_count == 0U &&
         named_outputs_current == 0ULL &&
         tracked_summary != NULL &&
         tracked_summary->available &&
         tracked_summary->total_files > 0U) ||
        (have_stage &&
         strcmp(stage_state.fs_backend, "ntfs") == 0 &&
         stage_state.metadata_context_available &&
         record_index_count == 0U &&
         range_index_count == 0U &&
         tracked_summary != NULL &&
         tracked_summary->available &&
         tracked_summary->reconciled_files == 0U &&
         tracked_summary->total_files > 0U)) {
        fprintf(
            file,
            "- diagnosis_hint: NTFS metadata was selected, but no usable record/range index rows were built in this pass; recovered files therefore stayed in unident and did not receive folder/path naming\n"
        );
    }
}

static int get_backend_artifact_state_for_run(
    const char *output_dir,
    FsBackendArtifactState *out_state
)
{
    const char *backend_output_dir = fs_backend_current_output_dir();

    if (out_state == NULL) {
        return 0;
    }

    memset(out_state, 0, sizeof(*out_state));
    if (!has_nonempty_text(output_dir) ||
        fs_backend_current_kind() == FS_BACKEND_KIND_NONE ||
        !has_nonempty_text(backend_output_dir) ||
        strcmp(output_dir, backend_output_dir) != 0) {
        return 0;
    }

    fs_backend_get_artifact_state(
        FS_BACKEND_ARTIFACT_PHASE_NAME_RESUME,
        out_state
    );
    return out_state->metadata_snapshot_ready ||
           out_state->recovered_output_log_ready ||
           out_state->finalize_status_present ||
           out_state->finalize_state_ready ||
           fs_backend_recovered_output_count() > 0U;
}

static int load_saved_hfsplus_artifact_state_for_run(
    const char *output_dir,
    FsBackendArtifactState *out_state,
    size_t *out_recovered_files,
    size_t *out_named_files
)
{
    char snapshot_path[PATH_MAX_LEN];
    char outputs_path[PATH_MAX_LEN];
    char finalize_path[PATH_MAX_LEN];
    FILE *file = NULL;
    int have_hfs_specific_artifact = 0;
    int have_outputs_log = 0;
    int found_any = 0;
    uint64_t ignored_size = 0U;
    uint64_t outputs_log_size = 0U;

    if (out_state == NULL) {
        return 0;
    }
    if (out_recovered_files != NULL) {
        *out_recovered_files = 0U;
    }
    if (out_named_files != NULL) {
        *out_named_files = 0U;
    }

    memset(out_state, 0, sizeof(*out_state));
    if (!has_nonempty_text(output_dir)) {
        return 0;
    }

    if (build_state_child_path_local(
            output_dir,
            "hfsplus_metadata_snapshot.bin",
            snapshot_path,
            sizeof(snapshot_path)) &&
        regular_file_size_bytes(snapshot_path, &ignored_size)) {
        out_state->metadata_snapshot_ready = 1;
        have_hfs_specific_artifact = 1;
        found_any = 1;
    }

    if (build_state_child_path_local(
            output_dir,
            "recovered_outputs.tsv",
            outputs_path,
            sizeof(outputs_path)) &&
        regular_file_size_bytes(outputs_path, &outputs_log_size)) {
        have_outputs_log = 1;
    }

    if (!build_state_child_path_local(
            output_dir,
            "hfsplus_finalize_status.txt",
            finalize_path,
            sizeof(finalize_path))) {
        goto phase_ready;
    }

    file = fopen(finalize_path, "r");
    if (file != NULL) {
        char line[256];
        int have_status = 0;
        int status_ready = 0;
        unsigned long long recovered_value = 0ULL;
        unsigned long long named_value = 0ULL;
        unsigned long long recorded_outputs_log_bytes = 0ULL;
        int have_recovered_value = 0;
        int have_named_value = 0;
        int have_recorded_outputs_log_bytes = 0;

        out_state->finalize_status_present = 1;
        have_hfs_specific_artifact = 1;
        found_any = 1;
        while (fgets(line, sizeof(line), file) != NULL) {
            if (strncmp(line, "status=", 7) == 0) {
                have_status = 1;
                status_ready = strncmp(line + 7, "ready", 5) == 0;
            } else if (strncmp(line, "pending_outputs=", 16) == 0) {
                unsigned long long pending_value = 0ULL;

                if (sscanf(line + 16, "%llu", &pending_value) == 1) {
                    out_state->pending_outputs = (size_t)pending_value;
                }
            } else if (strncmp(line, "recovered_outputs=", 18) == 0) {
                if (sscanf(line + 18, "%llu", &recovered_value) == 1) {
                    have_recovered_value = 1;
                }
            } else if (strncmp(line, "named_outputs=", 14) == 0) {
                if (sscanf(line + 14, "%llu", &named_value) == 1) {
                    have_named_value = 1;
                }
            } else if (strncmp(
                           line,
                           "recovered_outputs_log_bytes=",
                           28) == 0) {
                if (sscanf(
                        line + 28,
                        "%llu",
                        &recorded_outputs_log_bytes) == 1) {
                    have_recorded_outputs_log_bytes = 1;
                }
            }
        }
        fclose(file);
        file = NULL;

        if (have_status) {
            out_state->finalize_state_ready = status_ready ? 1 : 0;
        }
        if (out_state->finalize_state_ready &&
            have_outputs_log &&
            (!have_recorded_outputs_log_bytes ||
             (uint64_t)recorded_outputs_log_bytes != outputs_log_size)) {
            out_state->finalize_state_ready = 0;
        }
        if (out_recovered_files != NULL && have_recovered_value) {
            *out_recovered_files = (size_t)recovered_value;
        }
        if (out_named_files != NULL && have_named_value) {
            *out_named_files = (size_t)named_value;
        }
    }

phase_ready:
    if (have_hfs_specific_artifact && have_outputs_log) {
        out_state->recovered_output_log_ready = 1;
    }
    out_state->ready_for_phase =
        out_state->finalize_state_ready ||
        (out_state->metadata_snapshot_ready &&
         out_state->recovered_output_log_ready);
    return found_any;
}

static int saved_hfsplus_finalize_is_pending(const char *output_dir)
{
    FsBackendArtifactState state = {0};

    if (!load_saved_hfsplus_artifact_state_for_run(
            output_dir,
            &state,
            NULL,
            NULL)) {
        return 0;
    }
    return !state.finalize_state_ready &&
           (state.finalize_status_present ||
            state.metadata_snapshot_ready ||
            state.recovered_output_log_ready);
}

static void repair_saved_hfsplus_lookup_ready_status(const char *output_dir)
{
    char status_path[PATH_MAX_LEN];
    char manifest_path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN];
    char line[512];
    FILE *source = NULL;
    FILE *target = NULL;
    uint64_t manifest_size = 0ULL;
    int status_ready = 0;
    int compact_loaded = 0;
    int catalog_loaded = 0;
    int lookup_ready = 0;
    int wrote_lookup = 0;

    if (!has_nonempty_text(output_dir) ||
        !build_state_child_path_local(
            output_dir,
            "hfsplus_finalize_status.txt",
            status_path,
            sizeof(status_path)) ||
        snprintf(
            manifest_path,
            sizeof(manifest_path),
            "%s/%s/metadata/index/manifest.bin",
            output_dir,
            APP_STATE_DIR_NAME) >= (int)sizeof(manifest_path)) {
        return;
    }

    source = fopen(status_path, "r");
    if (source == NULL) return;
    while (fgets(line, sizeof(line), source) != NULL) {
        if (strncmp(line, "status=ready", 12U) == 0) {
            status_ready = 1;
        } else if (strncmp(line, "compact_index_loaded=1", 22U) == 0) {
            compact_loaded = 1;
        } else if (strncmp(line, "catalog_loaded=1", 16U) == 0) {
            catalog_loaded = 1;
        } else if (strncmp(line, "metadata_lookup_ready=1", 23U) == 0) {
            lookup_ready = 1;
        }
    }
    if (!status_ready || lookup_ready ||
        (!catalog_loaded &&
         (!compact_loaded ||
          !regular_file_size_bytes(manifest_path, &manifest_size) ||
          manifest_size == 0ULL))) {
        fclose(source);
        return;
    }
    rewind(source);
    if (snprintf(temp_path, sizeof(temp_path), "%s.tmp.%ld", status_path,
                 (long)getpid()) >= (int)sizeof(temp_path)) {
        fclose(source);
        return;
    }
    target = fopen(temp_path, "w");
    if (target == NULL) {
        fclose(source);
        return;
    }
    (void)chmod(temp_path, 0644);
    while (fgets(line, sizeof(line), source) != NULL) {
        if (strncmp(line, "metadata_lookup_ready=", 22U) == 0) {
            if (fputs("metadata_lookup_ready=1\n", target) == EOF) goto failed;
            wrote_lookup = 1;
        } else if (fputs(line, target) == EOF) {
            goto failed;
        }
    }
    if (ferror(source) ||
        (!wrote_lookup && fputs("metadata_lookup_ready=1\n", target) == EOF)) {
        goto failed;
    }
    if (fclose(target) != 0) {
        target = NULL;
        goto failed;
    }
    target = NULL;
    fclose(source);
    source = NULL;
    if (rename(temp_path, status_path) != 0) goto failed;
    (void)mft_apply_output_owner_to_path(status_path);
    return;

failed:
    if (target != NULL) fclose(target);
    if (source != NULL) fclose(source);
    (void)unlink(temp_path);
}

static int raw_all_stage_state_has_backend_identity(
    const RawAllStageState *state
)
{
    if (state == NULL) {
        return 0;
    }

    return (state->fs_backend_kind != FS_BACKEND_KIND_NONE) ||
           (has_nonempty_text(state->fs_backend) &&
            strcmp(state->fs_backend, "none") != 0);
}

static void raw_all_stage_set_backend_identity(
    RawAllStageState *state,
    int kind,
    const char *backend_id,
    const char *backend_name,
    int metadata_context_available,
    int live_metadata_observation_available
)
{
    if (state == NULL) {
        return;
    }

    state->fs_backend_kind = kind;
    snprintf(
        state->fs_backend,
        sizeof(state->fs_backend),
        "%s",
        has_nonempty_text(backend_id) ? backend_id : "none"
    );
    snprintf(
        state->fs_backend_name,
        sizeof(state->fs_backend_name),
        "%s",
        has_nonempty_text(backend_name) ? backend_name : "None"
    );
    state->metadata_context_available = metadata_context_available ? 1 : 0;
    state->live_metadata_observation_available =
        live_metadata_observation_available ? 1 : 0;
}

static int load_saved_ntfs_backend_identity_for_run(
    const char *run_dir,
    RawAllStageState *out_state
)
{
    char scan_state_path[PATH_MAX_LEN];
    ScanState scan_state = {0};
    size_t i;

    if (out_state == NULL ||
        !has_nonempty_text(run_dir) ||
        snprintf(
            scan_state_path,
            sizeof(scan_state_path),
            "%s/%s/scan_state.txt",
            run_dir,
            APP_STATE_DIR_NAME) >= (int)sizeof(scan_state_path) ||
        !scan_state_load(scan_state_path, &scan_state)) {
        return 0;
    }

    if (scan_state.source_ntfs_serial != 0ULL) {
        raw_all_stage_set_backend_identity(
            out_state,
            FS_BACKEND_KIND_NTFS,
            "ntfs",
            "NTFS",
            1,
            1
        );
        return 1;
    }

    for (i = 0U; i < scan_state.accepted_ntfs_serial_count; i++) {
        if (scan_state.accepted_ntfs_serials[i] != 0ULL) {
            raw_all_stage_set_backend_identity(
                out_state,
                FS_BACKEND_KIND_NTFS,
                "ntfs",
                "NTFS",
                1,
                1
            );
            return 1;
        }
    }

    return 0;
}

static void raw_all_stage_restore_saved_backend_identity(
    const char *run_dir,
    RawAllStageState *state
)
{
    FsBackendArtifactState hfsplus_artifacts = {0};
    size_t ignored_recovered_files = 0U;
    size_t ignored_named_files = 0U;

    if (state == NULL) {
        return;
    }

    /* A child that actually configured the source has stronger evidence than
     * old compatibility fields in scan_state.txt.  In particular, the raw
     * supervisor process starts with the legacy default NTFS facade even when
     * its child proved HFS+; never overwrite that saved proof here. */
    if (raw_all_stage_state_has_backend_identity(state)) {
        return;
    }

    if (load_saved_ntfs_backend_identity_for_run(run_dir, state)) {
        return;
    }

    if (load_saved_hfsplus_artifact_state_for_run(
            run_dir,
            &hfsplus_artifacts,
            &ignored_recovered_files,
            &ignored_named_files)) {
        raw_all_stage_set_backend_identity(
            state,
            FS_BACKEND_KIND_HFSPLUS,
            "hfsplus",
            "HFS+",
            hfsplus_artifacts.metadata_snapshot_ready ||
                hfsplus_artifacts.finalize_state_ready,
            0
        );
        return;
    }
}

static int load_saved_artifact_state_for_run(
    const char *output_dir,
    FsBackendArtifactState *out_state,
    size_t *out_recovered_files,
    size_t *out_named_files
)
{
    if (get_backend_artifact_state_for_run(output_dir, out_state)) {
        if (out_recovered_files != NULL) {
            *out_recovered_files = fs_backend_recovered_output_count();
        }
        if (out_named_files != NULL) {
            *out_named_files = fs_backend_named_output_count();
        }
        return 1;
    }

    return load_saved_hfsplus_artifact_state_for_run(
        output_dir,
        out_state,
        out_recovered_files,
        out_named_files
    );
}

static int load_recovered_output_log_summary(
    const char *output_dir,
    RecoveredOutputLogSummary *out_summary
)
{
    char log_path[PATH_MAX_LEN];
    FILE *file = NULL;
    char line[4096];
    RecoveredOutputLogRow *rows = NULL;
    size_t row_count = 0U;
    size_t row_capacity = 0U;
    size_t i;

    if (out_summary == NULL) {
        return 0;
    }

    memset(out_summary, 0, sizeof(*out_summary));
    if (!has_nonempty_text(output_dir) ||
        snprintf(
            log_path,
            sizeof(log_path),
            "%s/%s/recovered_outputs.tsv",
            output_dir,
            APP_STATE_DIR_NAME) >= (int)sizeof(log_path)) {
        return 0;
    }

    file = fopen(log_path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char *tab;
        char *path;
        char *tab2;
        char *tab3 = NULL;
        long long abs_offset = -1;
        int reconciled = 0;
        RecoveredOutputLogRow *grown;

        if (strncmp(line, "offset\tpath", 11) == 0) {
            continue;
        }

        tab = strchr(line, '\t');
        if (tab == NULL) {
            continue;
        }
        *tab = '\0';
        path = tab + 1;
        tab2 = strchr(path, '\t');
        if (tab2 != NULL) {
            *tab2 = '\0';
            tab3 = strchr(tab2 + 1, '\t');
            if (tab3 != NULL) {
                *tab3 = '\0';
            }
            reconciled = atoi(tab2 + 1) != 0;
        }
        path[strcspn(path, "\r\n")] = '\0';
        if (!has_nonempty_text(path) ||
            sscanf(line, "%lld", &abs_offset) != 1 ||
            abs_offset < 0) {
            continue;
        }
        if (strstr(path, "/" APP_PHOTOREC_IMPORT_RELATIVE_DIR "/") != NULL) {
            reconciled = 0;
        }

        if (row_count == row_capacity) {
            size_t next_capacity = row_capacity == 0U ? 512U : row_capacity * 2U;

            grown = (RecoveredOutputLogRow *)realloc(
                rows,
                next_capacity * sizeof(*rows));
            if (grown == NULL) {
                fclose(file);
                free(rows);
                return 0;
            }
            rows = grown;
            row_capacity = next_capacity;
        }

        rows[row_count].abs_offset = abs_offset;
        rows[row_count].reconciled = reconciled ? 1 : 0;
        rows[row_count].embedded =
            tab2 != NULL && tab3 != NULL &&
            strncmp(tab3 + 1, "embedded", strlen("embedded")) == 0;
        rows[row_count].path = strdup(path);
        if (rows[row_count].path == NULL) {
            fclose(file);
            for (i = 0U; i < row_count; i++) {
                free(rows[i].path);
            }
            free(rows);
            return 0;
        }
        rows[row_count].path_hash = hash_text_local(path);
        rows[row_count].order = row_count;
        row_count++;
    }

    fclose(file);
    if (row_count > 1U) {
        size_t write_index = 0U;

        qsort(
            rows,
            row_count,
            sizeof(*rows),
            compare_recovered_output_log_rows_by_path);

        for (i = 0U; i < row_count; i++) {
            RecoveredOutputLogRow chosen = rows[i];

            while (i + 1U < row_count &&
                   rows[i + 1U].path_hash == chosen.path_hash &&
                   strcmp(rows[i + 1U].path, chosen.path) == 0) {
                if (rows[i + 1U].order > chosen.order) {
                    free(chosen.path);
                    chosen = rows[i + 1U];
                } else {
                    free(rows[i + 1U].path);
                }
                i++;
            }

            rows[write_index++] = chosen;
        }
        row_count = write_index;

        qsort(
            rows,
            row_count,
            sizeof(*rows),
            compare_recovered_output_log_rows);
    }

    for (i = 0U; i < row_count; i++) {
        while (i + 1U < row_count &&
               rows[i + 1U].abs_offset == rows[i].abs_offset) {
            i++;
        }
        out_summary->total_files++;
        if (rows[i].reconciled) {
            out_summary->reconciled_files++;
        } else if (rows[i].embedded) {
            out_summary->embedded_files++;
        } else {
            out_summary->unreconciled_files++;
        }
    }

    for (i = 0U; i < row_count; i++) {
        free(rows[i].path);
    }
    free(rows);
    out_summary->available = 1;
    return 1;
}

static int load_run_recovered_state_summary(
    const char *output_dir,
    RunRecoveredStateSummary *out_summary
)
{
    RecoveredOutputLogSummary tracked = {0};
    RecoveredOutputLogSummary live_tracked = {0};
    size_t recovered_from_artifacts = 0U;
    size_t named_from_artifacts = 0U;
    int have_backend_summary = 0;
    int have_live_summary = 0;

    if (out_summary == NULL) {
        return 0;
    }

    memset(out_summary, 0, sizeof(*out_summary));
    out_summary->artifact_state_available =
        load_saved_artifact_state_for_run(
            output_dir,
            &out_summary->artifact_state,
            &recovered_from_artifacts,
            &named_from_artifacts
        );

    have_live_summary =
        load_recovered_output_summary_from_live_stats(output_dir, &live_tracked) &&
        live_tracked.available &&
        live_tracked.total_files > 0U;
    have_backend_summary =
        load_recovered_output_summary_from_backend_artifacts(output_dir, &tracked) &&
        tracked.available;

    if (have_backend_summary) {
        int using_live_summary = 0;

        if (live_tracked.available &&
            live_tracked.total_files > 0U &&
            (tracked.total_files == 0U ||
             live_tracked.unreconciled_files < tracked.unreconciled_files ||
             live_tracked.reconciled_files > tracked.reconciled_files)) {
            tracked = live_tracked;
            using_live_summary = 1;
        }
        out_summary->recovered_files = tracked.total_files;
        out_summary->named_files = tracked.reconciled_files;
        out_summary->unident_files = tracked.unreconciled_files;
        out_summary->available = 1;
        out_summary->used_backend_artifacts = using_live_summary ? 0 : 1;
        return 1;
    }

    if (have_live_summary) {
        if (load_recovered_output_log_summary(output_dir, &tracked) &&
            tracked.available &&
            tracked.total_files >= live_tracked.total_files &&
            (tracked.unreconciled_files < live_tracked.unreconciled_files ||
             tracked.reconciled_files > live_tracked.reconciled_files)) {
            out_summary->recovered_files = tracked.total_files;
            out_summary->named_files = tracked.reconciled_files;
            out_summary->unident_files = tracked.unreconciled_files;
            out_summary->available = 1;
            out_summary->used_backend_artifacts = 1;
            return 1;
        }
        out_summary->recovered_files = live_tracked.total_files;
        out_summary->named_files = live_tracked.reconciled_files;
        out_summary->unident_files = live_tracked.unreconciled_files;
        out_summary->available = 1;
        return 1;
    }

    if (load_recovered_output_log_summary(output_dir, &tracked) &&
        tracked.available) {
        out_summary->recovered_files = tracked.total_files;
        out_summary->named_files = tracked.reconciled_files;
        out_summary->unident_files = tracked.unreconciled_files;
        out_summary->available = 1;
        return 1;
    }

    if (out_summary->artifact_state_available &&
        recovered_from_artifacts > 0U) {
        out_summary->recovered_files = recovered_from_artifacts;
        out_summary->named_files = named_from_artifacts;
        out_summary->unident_files =
            recovered_from_artifacts >= named_from_artifacts
                ? recovered_from_artifacts - named_from_artifacts
                : out_summary->artifact_state.pending_outputs;
        out_summary->available = 1;
        return 1;
    }

    out_summary->recovered_files = count_recovered_files_for_run(output_dir);
    out_summary->unident_files = count_unident_files_for_run(output_dir);
    out_summary->named_files =
        out_summary->recovered_files >= out_summary->unident_files
            ? out_summary->recovered_files - out_summary->unident_files
            : 0U;
    out_summary->available = 1;
    return 1;
}

static size_t saved_hfsplus_assembly_count_for_run(const char *output_dir)
{
    char measurement_path[PATH_MAX_LEN];
    FILE *measurement = NULL;
    size_t assembly_files = 0U;

    if (build_state_child_path_local(
            output_dir,
            "metadata/sequential_extent_measurement.txt",
            measurement_path,
            sizeof(measurement_path))) {
        measurement = fopen(measurement_path, "r");
    }
    if (measurement != NULL) {
        char line[256];

        while (fgets(line, sizeof(line), measurement) != NULL) {
            unsigned long long value = 0ULL;

            if (sscanf(line, "assembly_files_completed=%llu", &value) == 1) {
                assembly_files = value > SIZE_MAX ? SIZE_MAX : (size_t)value;
                break;
            }
        }
        fclose(measurement);
    }
    return assembly_files;
}

static size_t best_effort_recovered_count_for_run(const char *output_dir)
{
    RunRecoveredStateSummary summary = {0};
    size_t assembly_files = saved_hfsplus_assembly_count_for_run(output_dir);

    if (load_run_recovered_state_summary(output_dir, &summary) &&
        summary.available) {
        return summary.recovered_files > assembly_files
            ? summary.recovered_files
            : assembly_files;
    }

    return assembly_files;
}

size_t app_best_effort_recovered_count_for_run(const char *output_dir)
{
    return best_effort_recovered_count_for_run(output_dir);
}

size_t app_best_effort_named_count_for_run(const char *output_dir)
{
    RunRecoveredStateSummary summary = {0};
    size_t assembled = saved_hfsplus_assembly_count_for_run(output_dir);

    if (load_run_recovered_state_summary(output_dir, &summary) &&
        summary.available) {
        return summary.named_files > assembled
            ? summary.named_files
            : assembled;
    }

    return assembled;
}

static size_t best_effort_unident_count_for_run(const char *output_dir)
{
    RunRecoveredStateSummary summary = {0};

    if (load_run_recovered_state_summary(output_dir, &summary) &&
        summary.available) {
        return summary.unident_files;
    }

    return 0U;
}

size_t app_best_effort_unident_count_for_run(const char *output_dir)
{
    return best_effort_unident_count_for_run(output_dir);
}

static int report_should_skip_name(const char *name)
{
    return name == NULL ||
           name[0] == '\0' ||
           strcmp(name, ".") == 0 ||
           strcmp(name, "..") == 0 ||
           name[0] == '.';
}

static void lowercase_ascii_copy(char *out, size_t out_size, const char *input)
{
    size_t i = 0U;

    if (out == NULL || out_size == 0U) {
        return;
    }

    out[0] = '\0';
    if (input == NULL) {
        return;
    }

    while (input[i] != '\0' && i + 1U < out_size) {
        unsigned char ch = (unsigned char)input[i];
        out[i] = (char)tolower(ch);
        i++;
    }
    out[i] = '\0';
}

static void extract_report_extension(
    const char *name,
    char *out,
    size_t out_size
)
{
    const char *dot;

    if (out == NULL || out_size == 0U) {
        return;
    }

    out[0] = '\0';
    if (!has_nonempty_text(name)) {
        snprintf(out, out_size, "%s", "(none)");
        return;
    }

    dot = strrchr(name, '.');
    if (dot == NULL || dot == name || dot[1] == '\0') {
        snprintf(out, out_size, "%s", "(none)");
        return;
    }

    lowercase_ascii_copy(out, out_size, dot + 1);
    if (out[0] == '\0') {
        snprintf(out, out_size, "%s", "(none)");
    }
}

static int add_run_format_stat(
    RunRecoverySummary *summary,
    const char *label,
    uint64_t bytes
)
{
    size_t i;
    RunFormatStat *grown;

    if (summary == NULL || !has_nonempty_text(label)) {
        return 0;
    }

    for (i = 0; i < summary->format_count; i++) {
        if (strcmp(summary->formats[i].label, label) == 0) {
            summary->formats[i].files++;
            summary->formats[i].bytes += bytes;
            return 1;
        }
    }

    if (summary->format_count == summary->format_capacity) {
        size_t next_capacity =
            summary->format_capacity == 0U ? 16U : summary->format_capacity * 2U;
        grown = (RunFormatStat *)realloc(
            summary->formats,
            next_capacity * sizeof(*summary->formats)
        );
        if (grown == NULL) {
            return 0;
        }
        summary->formats = grown;
        summary->format_capacity = next_capacity;
    }

    snprintf(
        summary->formats[summary->format_count].label,
        sizeof(summary->formats[summary->format_count].label),
        "%s",
        label
    );
    summary->formats[summary->format_count].files = 1U;
    summary->formats[summary->format_count].bytes = bytes;
    summary->format_count++;
    return 1;
}

static int add_run_bucket_stat(
    RunRecoverySummary *summary,
    const char *label,
    uint64_t bytes
)
{
    size_t i;
    RunBucketStat *grown;

    if (summary == NULL || !has_nonempty_text(label)) {
        return 0;
    }

    for (i = 0; i < summary->bucket_count; i++) {
        if (strcmp(summary->buckets[i].label, label) == 0) {
            summary->buckets[i].files++;
            summary->buckets[i].bytes += bytes;
            return 1;
        }
    }

    if (summary->bucket_count == summary->bucket_capacity) {
        size_t next_capacity =
            summary->bucket_capacity == 0U ? 8U : summary->bucket_capacity * 2U;
        grown = (RunBucketStat *)realloc(
            summary->buckets,
            next_capacity * sizeof(*summary->buckets)
        );
        if (grown == NULL) {
            return 0;
        }
        summary->buckets = grown;
        summary->bucket_capacity = next_capacity;
    }

    snprintf(
        summary->buckets[summary->bucket_count].label,
        sizeof(summary->buckets[summary->bucket_count].label),
        "%s",
        label
    );
    summary->buckets[summary->bucket_count].files = 1U;
    summary->buckets[summary->bucket_count].bytes = bytes;
    summary->bucket_count++;
    return 1;
}

static int collect_recovered_summary_recursive(
    const char *path,
    const char *top_bucket,
    RunRecoverySummary *summary
)
{
    DIR *dir;
    struct dirent *entry;

    if (!has_nonempty_text(path) || summary == NULL) {
        return 0;
    }

    dir = opendir(path);
    if (dir == NULL) {
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        char child_path[2048];
        struct stat st;

        if (report_should_skip_name(entry->d_name)) {
            continue;
        }

        if (snprintf(
                child_path,
                sizeof(child_path),
                "%s/%s",
                path,
                entry->d_name) >= (int)sizeof(child_path)) {
            continue;
        }

        if (stat(child_path, &st) != 0) {
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            const char *child_bucket = top_bucket != NULL ? top_bucket : entry->d_name;
            if (!collect_recovered_summary_recursive(child_path, child_bucket, summary)) {
                closedir(dir);
                return 0;
            }
            continue;
        }

        if (S_ISREG(st.st_mode) &&
            !is_internal_output_artifact_name(entry->d_name)) {
            char ext[32];
            const char *bucket = top_bucket != NULL ? top_bucket : "(root)";

            summary->total_files++;
            summary->total_bytes += (uint64_t)st.st_size;
            extract_report_extension(entry->d_name, ext, sizeof(ext));
            if (!add_run_format_stat(summary, ext, (uint64_t)st.st_size) ||
                !add_run_bucket_stat(summary, bucket, (uint64_t)st.st_size)) {
                closedir(dir);
                return 0;
            }
        }
    }

    closedir(dir);
    return 1;
}

static int compare_run_format_stat_desc(const void *left, const void *right)
{
    const RunFormatStat *a = (const RunFormatStat *)left;
    const RunFormatStat *b = (const RunFormatStat *)right;

    if (a->files != b->files) {
        return a->files < b->files ? 1 : -1;
    }
    if (a->bytes != b->bytes) {
        return a->bytes < b->bytes ? 1 : -1;
    }
    return strcasecmp(a->label, b->label);
}

static int compare_run_bucket_stat_desc(const void *left, const void *right)
{
    const RunBucketStat *a = (const RunBucketStat *)left;
    const RunBucketStat *b = (const RunBucketStat *)right;

    if (a->files != b->files) {
        return a->files < b->files ? 1 : -1;
    }
    if (a->bytes != b->bytes) {
        return a->bytes < b->bytes ? 1 : -1;
    }
    return strcasecmp(a->label, b->label);
}

static int compare_read_error_offset_asc(const void *left, const void *right)
{
    const ReadErrorRange *a = (const ReadErrorRange *)left;
    const ReadErrorRange *b = (const ReadErrorRange *)right;

    if (a->offset < b->offset) {
        return -1;
    }
    if (a->offset > b->offset) {
        return 1;
    }
    return 0;
}

static int compare_read_error_cluster_desc(const void *left, const void *right)
{
    const ReadErrorCluster *a = (const ReadErrorCluster *)left;
    const ReadErrorCluster *b = (const ReadErrorCluster *)right;

    if (a->bytes != b->bytes) {
        return a->bytes < b->bytes ? 1 : -1;
    }
    if (a->ranges != b->ranges) {
        return a->ranges < b->ranges ? 1 : -1;
    }
    return a->start_offset < b->start_offset ? -1 : (a->start_offset > b->start_offset ? 1 : 0);
}

static int compare_read_error_cluster_start_asc(const void *left, const void *right)
{
    const ReadErrorCluster *a = (const ReadErrorCluster *)left;
    const ReadErrorCluster *b = (const ReadErrorCluster *)right;

    if (a->start_offset < b->start_offset) {
        return -1;
    }
    if (a->start_offset > b->start_offset) {
        return 1;
    }
    return 0;
}

