static int read_error_cluster_append_local(
    ReadErrorCluster **io_clusters,
    size_t *io_count,
    size_t *io_capacity,
    uint64_t start_offset,
    uint64_t end_offset,
    size_t ranges
)
{
    ReadErrorCluster *grown;

    if (io_clusters == NULL ||
        io_count == NULL ||
        io_capacity == NULL ||
        end_offset <= start_offset) {
        return 0;
    }

    if (*io_count == *io_capacity) {
        size_t next_capacity =
            *io_capacity == 0U ? 16U : *io_capacity * 2U;

        grown = (ReadErrorCluster *)realloc(
            *io_clusters,
            next_capacity * sizeof(**io_clusters)
        );
        if (grown == NULL) {
            return 0;
        }
        *io_clusters = grown;
        *io_capacity = next_capacity;
    }

    (*io_clusters)[*io_count].start_offset = start_offset;
    (*io_clusters)[*io_count].end_offset = end_offset;
    (*io_clusters)[*io_count].bytes = end_offset - start_offset;
    (*io_clusters)[*io_count].ranges = ranges > 0U ? ranges : 1U;
    (*io_count)++;
    return 1;
}

static int load_merged_gui_read_coverage_spans(
    const char *run_dir,
    ReadErrorCluster **out_spans,
    size_t *out_span_count,
    int *out_coverage_available,
    int include_selected_scan_ranges
)
{
    char path[PATH_MAX_LEN];
    FILE *file = NULL;
    ReadErrorCluster *spans = NULL;
    size_t span_count = 0U;
    size_t span_capacity = 0U;
    GuiCoveragePassFilter *filters = NULL;
    size_t filter_count = 0U;
    int filter_available = 0;
    char line[256];
    int ok = 0;
    size_t i;
    size_t merged_count = 0U;

    if (out_spans != NULL) {
        *out_spans = NULL;
    }
    if (out_span_count != NULL) {
        *out_span_count = 0U;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = 0;
    }
    if (run_dir == NULL ||
        out_spans == NULL ||
        out_span_count == NULL ||
        !build_state_child_path_local(run_dir, "gui_read_coverage.tsv", path, sizeof(path))) {
        return 0;
    }
    if (!load_gui_coverage_pass_filters_for_run_dir(
            run_dir,
            &filters,
            &filter_count,
            &filter_available)) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        free(filters);
        return 1;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        char pass_id[64];
        unsigned long long start = 0ULL;
        unsigned long long end = 0ULL;

        if (strncmp(line, "pass_id\t", 8U) == 0) {
            continue;
        }
        if (sscanf(line, "%63[^\t]\t%llu\t%llu", pass_id, &start, &end) != 3 ||
            end <= start) {
            continue;
        }
        if (!gui_coverage_pass_id_allowed(
                pass_id,
                filters,
                filter_count,
                filter_available)) {
            size_t filter_index;
            int selected_scan_allowed = 0;

            if (include_selected_scan_ranges && filter_available) {
                for (filter_index = 0U;
                     filter_index < filter_count;
                     filter_index++) {
                    if (strcmp(filters[filter_index].pass_id, pass_id) == 0) {
                        selected_scan_allowed =
                            filters[filter_index].selected_scan_range;
                        break;
                    }
                }
            }
            if (!selected_scan_allowed) {
                continue;
            }
        }
        if (!read_error_cluster_append_local(
                &spans,
                &span_count,
                &span_capacity,
                (uint64_t)start,
                (uint64_t)end,
                1U)) {
            goto cleanup;
        }
    }

    fclose(file);
    file = NULL;

    /* A zone which exhausted its hard wall-clock allowance remains a real
     * read problem (and is drawn red), but it is also terminally accounted for
     * so the next child cannot rediscover and enter the same gap forever. */
    if (build_terminal_coverage_ranges_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        file = fopen(path, "r");
        if (file != NULL) {
            while (fgets(line, sizeof(line), file) != NULL) {
                unsigned long long start = 0ULL;
                unsigned long long end = 0ULL;

                if (strncmp(line, "start_offset\t", 13U) == 0) {
                    continue;
                }
                if (sscanf(line, "%llu\t%llu", &start, &end) != 2 ||
                    end <= start) {
                    continue;
                }
                if (!read_error_cluster_append_local(
                        &spans,
                        &span_count,
                        &span_capacity,
                        (uint64_t)start,
                        (uint64_t)end,
                        1U)) {
                    goto cleanup;
                }
            }
        }
    }

    if (span_count > 1U) {
        qsort(
            spans,
            span_count,
            sizeof(*spans),
            compare_read_error_cluster_start_asc
        );
    }

    for (i = 0U; i < span_count; i++) {
        ReadErrorCluster *previous;

        if (spans[i].end_offset <= spans[i].start_offset) {
            continue;
        }
        if (merged_count == 0U) {
            spans[merged_count++] = spans[i];
            continue;
        }
        previous = &spans[merged_count - 1U];
        if (spans[i].start_offset <= previous->end_offset) {
            if (spans[i].end_offset > previous->end_offset) {
                previous->end_offset = spans[i].end_offset;
                previous->bytes = previous->end_offset - previous->start_offset;
            }
            previous->ranges += spans[i].ranges;
            continue;
        }
        spans[merged_count++] = spans[i];
    }

    span_count = merged_count;
    ok = 1;

cleanup:
    if (file != NULL) {
        fclose(file);
    }
    free(filters);
    if (!ok) {
        free(spans);
        return 0;
    }
    *out_spans = spans;
    *out_span_count = span_count;
    return 1;
}

static int discover_coverage_gaps_for_run_dir(
    const char *run_dir,
    uint64_t coverage_start,
    uint64_t coverage_end,
    uint64_t min_gap_bytes,
    ReadErrorCluster **out_gaps,
    size_t *out_gap_count,
    uint64_t *out_total_gap_bytes,
    int *out_coverage_available,
    int include_selected_scan_ranges
)
{
    ReadErrorCluster *coverage = NULL;
    size_t coverage_count = 0U;
    ReadErrorCluster *gaps = NULL;
    size_t gap_count = 0U;
    size_t gap_capacity = 0U;
    uint64_t cursor = coverage_start;
    uint64_t total_gap_bytes = 0ULL;
    size_t i;
    int coverage_available = 0;
    int ok = 0;

    if (out_gaps != NULL) {
        *out_gaps = NULL;
    }
    if (out_gap_count != NULL) {
        *out_gap_count = 0U;
    }
    if (out_total_gap_bytes != NULL) {
        *out_total_gap_bytes = 0ULL;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = 0;
    }
    if (!has_nonempty_text(run_dir) ||
        coverage_end <= coverage_start ||
        out_gaps == NULL ||
        out_gap_count == NULL) {
        return 0;
    }

    if (!load_merged_gui_read_coverage_spans(
            run_dir,
            &coverage,
            &coverage_count,
            &coverage_available,
            include_selected_scan_ranges)) {
        return 0;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = coverage_available;
    }
    if (!coverage_available || coverage_count == 0U) {
        if (coverage_count == 0U && out_coverage_available != NULL) {
            *out_coverage_available = 0;
        }
        free(coverage);
        return 1;
    }

    for (i = 0U; i < coverage_count; i++) {
        uint64_t start = coverage[i].start_offset;
        uint64_t end = coverage[i].end_offset;

        if (start < coverage_start) {
            start = coverage_start;
        }
        if (end < coverage_start) {
            end = coverage_start;
        }
        if (start > coverage_end) {
            start = coverage_end;
        }
        if (end > coverage_end) {
            end = coverage_end;
        }
        if (end <= start) {
            continue;
        }
        if (start > cursor && start - cursor >= min_gap_bytes) {
            if (!read_error_cluster_append_local(
                    &gaps,
                    &gap_count,
                    &gap_capacity,
                    cursor,
                    start,
                    1U)) {
                goto cleanup;
            }
            total_gap_bytes += start - cursor;
        }
        if (end > cursor) {
            cursor = end;
        }
    }

    if (coverage_end > cursor && coverage_end - cursor >= min_gap_bytes) {
        if (!read_error_cluster_append_local(
                &gaps,
                &gap_count,
                &gap_capacity,
                cursor,
                coverage_end,
                1U)) {
            goto cleanup;
        }
        total_gap_bytes += coverage_end - cursor;
    }

    ok = 1;

cleanup:
    free(coverage);
    if (!ok) {
        free(gaps);
        return 0;
    }
    *out_gaps = gaps;
    *out_gap_count = gap_count;
    if (out_total_gap_bytes != NULL) {
        *out_total_gap_bytes = total_gap_bytes;
    }
    return 1;
}

static int raw_all_repair_false_end_cursor_from_trailing_gap(
    const AppConfig *config,
    ScanState *state,
    int trusted_completed_scan_checkpoint
)
{
    ReadErrorCluster *gaps = NULL;
    size_t gap_count = 0U;
    uint64_t gap_bytes = 0ULL;
    uint64_t scope_start;
    uint64_t scope_end;
    uint64_t minimum_suspicious_tail;
    uint64_t repaired_offset = 0ULL;
    uint64_t trailing_start = 0ULL;
    uint64_t trailing_end = 0ULL;
    int coverage_available = 0;
    size_t i;

    if (config == NULL || state == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        config->manual_start_explicit || config->additive_requested ||
        trusted_completed_scan_checkpoint ||
        !has_nonempty_text(config->output_dir) ||
        state->source_size == 0ULL ||
        (state->scan_offset < state->source_size &&
         state->source_size - state->scan_offset >
             RAW_ALL_RESUME_ALIGNMENT)) {
        return 0;
    }

    scope_start = raw_all_effective_scan_start_offset_for_source(
        config, state->source_size);
    scope_end = raw_all_effective_scan_end_offset_for_source(
        config, state->source_size);
    if (scope_start != 0ULL || scope_end < state->source_size ||
        !discover_coverage_gaps_for_run_dir(
            config->output_dir,
            0ULL,
            state->source_size,
            RAW_ALL_COVERAGE_GAP_MIN_BYTES,
            &gaps,
            &gap_count,
            &gap_bytes,
            &coverage_available,
            1) ||
        !coverage_available) {
        free(gaps);
        return 0;
    }

    minimum_suspicious_tail = state->source_size / 8ULL;
    if (minimum_suspicious_tail < RAW_ALL_COVERAGE_GAP_RETRY_CHUNK_BYTES) {
        minimum_suspicious_tail = RAW_ALL_COVERAGE_GAP_RETRY_CHUNK_BYTES;
    }
    for (i = 0U; i < gap_count; i++) {
        uint64_t tail_slack;

        if (gaps[i].end_offset > state->source_size) {
            continue;
        }
        tail_slack = state->source_size - gaps[i].end_offset;
        if (gaps[i].bytes < minimum_suspicious_tail ||
            tail_slack > RAW_ALL_COVERAGE_GAP_MIN_BYTES) {
            continue;
        }
        trailing_start = gaps[i].start_offset;
        trailing_end = gaps[i].end_offset;
        break;
    }
    free(gaps);
    if (trailing_end <= trailing_start) {
        return 0;
    }

    repaired_offset = trailing_start;
    if (config->stall_retry_backtrack_bytes > 0ULL &&
        repaired_offset > config->stall_retry_backtrack_bytes) {
        repaired_offset -= config->stall_retry_backtrack_bytes;
    } else {
        repaired_offset = 0ULL;
    }
    repaired_offset -= repaired_offset % RAW_ALL_RESUME_ALIGNMENT;
    if (repaired_offset >= state->scan_offset) {
        return 0;
    }

    log_runtime_event_error(
        "Raw-all resume repaired a false full-source cursor: durable coverage ends at byte %llu and leaves the trailing range %llu..%llu unread; resuming the primary sequential scan at %llu instead of treating %llu as 100%%",
        (unsigned long long)trailing_start,
        (unsigned long long)trailing_start,
        (unsigned long long)trailing_end,
        (unsigned long long)repaired_offset,
        (unsigned long long)state->scan_offset
    );
    state->scan_offset = repaired_offset;
    state->scan_completed = 0;
    state->completed = 0;
    return 1;
}

static int write_coverage_gaps_file_for_run_dir(
    const char *run_dir,
    const ReadErrorCluster *gaps,
    size_t gap_count,
    uint64_t total_gap_bytes,
    uint64_t source_size,
    const char *phase,
    const char *status
)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32];
    FILE *file;
    size_t i;

    if (!has_nonempty_text(run_dir) ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_coverage_gaps_path_for_run_dir(run_dir, path, sizeof(path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", path) >=
            (int)sizeof(temp_path)) {
        return 0;
    }

    file = fopen(temp_path, "w");
    if (file == NULL) {
        return 0;
    }

    fprintf(
        file,
        "gap_index\tstart_offset\tend_offset\tbytes\tsource_size\tphase\tstatus\tupdated_unix\n"
    );
    for (i = 0U; i < gap_count; i++) {
        fprintf(
            file,
            "%zu\t%llu\t%llu\t%llu\t%llu\t",
            i + 1U,
            (unsigned long long)gaps[i].start_offset,
            (unsigned long long)gaps[i].end_offset,
            (unsigned long long)gaps[i].bytes,
            (unsigned long long)source_size
        );
        write_tsv_text_field_local(file, has_nonempty_text(phase) ? phase : "unknown");
        fputc('\t', file);
        write_tsv_text_field_local(file, has_nonempty_text(status) ? status : "unknown");
        fprintf(file, "\t%llu\n", (unsigned long long)time(NULL));
    }
    if (gap_count == 0U) {
        fprintf(
            file,
            "0\t0\t0\t%llu\t%llu\t",
            (unsigned long long)total_gap_bytes,
            (unsigned long long)source_size
        );
        write_tsv_text_field_local(file, has_nonempty_text(phase) ? phase : "unknown");
        fputc('\t', file);
        write_tsv_text_field_local(file, has_nonempty_text(status) ? status : "no_large_gaps");
        fprintf(file, "\t%llu\n", (unsigned long long)time(NULL));
    }

    if (fclose(file) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    if (rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return 0;
    }
    return 1;
}

static int write_coverage_gap_snapshot_for_run_dir(
    const char *run_dir,
    uint64_t source_size,
    const char *phase,
    const char *status,
    size_t *out_gap_count,
    uint64_t *out_total_gap_bytes,
    int *out_coverage_available
)
{
    ReadErrorCluster *gaps = NULL;
    size_t gap_count = 0U;
    uint64_t total_gap_bytes = 0ULL;
    int coverage_available = 0;
    int ok;

    if (out_gap_count != NULL) {
        *out_gap_count = 0U;
    }
    if (out_total_gap_bytes != NULL) {
        *out_total_gap_bytes = 0ULL;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = 0;
    }

    if (!has_nonempty_text(run_dir) || source_size == 0ULL) {
        return 0;
    }

    if (!discover_coverage_gaps_for_run_dir(
            run_dir,
            0ULL,
            source_size,
            RAW_ALL_COVERAGE_GAP_MIN_BYTES,
            &gaps,
            &gap_count,
            &total_gap_bytes,
            &coverage_available,
            0)) {
        return 0;
    }

    if (out_gap_count != NULL) {
        *out_gap_count = gap_count;
    }
    if (out_total_gap_bytes != NULL) {
        *out_total_gap_bytes = total_gap_bytes;
    }
    if (out_coverage_available != NULL) {
        *out_coverage_available = coverage_available;
    }

    if (!coverage_available) {
        ok = write_coverage_gaps_file_for_run_dir(
            run_dir,
            NULL,
            0U,
            0ULL,
            source_size,
            phase,
            "coverage_unavailable"
        );
        free(gaps);
        return ok;
    }

    ok = write_coverage_gaps_file_for_run_dir(
        run_dir,
        gaps,
        gap_count,
        total_gap_bytes,
        source_size,
        phase,
        has_nonempty_text(status)
            ? status
            : (gap_count > 0U ? "pending_retry" : "no_large_gaps")
    );
    free(gaps);
    return ok;
}

#define RAW_ALL_DEFERRED_PLAN_MAX_INPUTS 8192U
#define RAW_ALL_DEFERRED_PLAN_MAX_OUTPUTS 2048U

typedef struct {
    uint64_t start_offset;
    uint64_t end_offset;
    uint64_t bytes;
    uint64_t owner_offset;
    uint64_t owner_end_offset;
    uint64_t score;
    char source[32];
    char kind[48];
    char reason[96];
    char owner_label[128];
    char action[48];
} RawAllDeferredPlanEntry;

