static int deferred_plan_text_contains(
    const char *text,
    const char *needle
)
{
    char text_lower[256];
    char needle_lower[64];

    if (!has_nonempty_text(text) || !has_nonempty_text(needle)) {
        return 0;
    }

    lowercase_ascii_copy(text_lower, sizeof(text_lower), text);
    lowercase_ascii_copy(needle_lower, sizeof(needle_lower), needle);
    return strstr(text_lower, needle_lower) != NULL;
}

static uint64_t score_deferred_plan_entry(
    const char *source,
    const char *kind,
    const char *reason,
    uint64_t bytes
)
{
    int score = 200;

    (void)source;

    if (deferred_plan_text_contains(kind, "jpg") ||
        deferred_plan_text_contains(kind, "jpeg") ||
        deferred_plan_text_contains(reason, "jpg") ||
        deferred_plan_text_contains(reason, "jpeg")) {
        score = 1000;
    } else if (deferred_plan_text_contains(kind, "pdf") ||
               deferred_plan_text_contains(reason, "pdf")) {
        score = 950;
    } else if (deferred_plan_text_contains(kind, "mov") ||
               deferred_plan_text_contains(kind, "mp4") ||
               deferred_plan_text_contains(kind, "ftyp") ||
               deferred_plan_text_contains(kind, "avi") ||
               deferred_plan_text_contains(kind, "riff") ||
               deferred_plan_text_contains(kind, "mpeg") ||
               deferred_plan_text_contains(kind, "mpg") ||
               deferred_plan_text_contains(kind, "mkv") ||
               deferred_plan_text_contains(reason, "video")) {
        score = 900;
    } else if (deferred_plan_text_contains(kind, "dng") ||
               deferred_plan_text_contains(kind, "cr2") ||
               deferred_plan_text_contains(kind, "cr3") ||
               deferred_plan_text_contains(kind, "nef") ||
               deferred_plan_text_contains(kind, "arw") ||
               deferred_plan_text_contains(kind, "raw")) {
        score = 850;
    } else if (deferred_plan_text_contains(kind, "png")) {
        score = 500;
    } else if (deferred_plan_text_contains(kind, "picture") ||
               deferred_plan_text_contains(kind, "generic")) {
        score = 250;
    }

    if (deferred_plan_text_contains(reason, "jpeg_jump") ||
        deferred_plan_text_contains(reason, "child")) {
        score += 200;
    }
    if (deferred_plan_text_contains(reason, "dense") ||
        deferred_plan_text_contains(reason, "swallow")) {
        score += 120;
    }
    if (deferred_plan_text_contains(reason, "generic_picture_cap")) {
        score -= 150;
    }

    if (bytes > 0ULL && bytes <= 64ULL * 1024ULL * 1024ULL) {
        score += 150;
    } else if (bytes <= 512ULL * 1024ULL * 1024ULL) {
        score += 50;
    } else if (bytes > 4ULL * 1024ULL * 1024ULL * 1024ULL) {
        score -= 250;
    } else if (bytes > 1024ULL * 1024ULL * 1024ULL) {
        score -= 100;
    }

    return score > 0 ? (uint64_t)score : 1ULL;
}

static int append_deferred_plan_entry(
    RawAllDeferredPlanEntry **io_entries,
    size_t *io_count,
    size_t *io_capacity,
    uint64_t start_offset,
    uint64_t end_offset,
    uint64_t owner_offset,
    uint64_t owner_end_offset,
    const char *source,
    const char *kind,
    const char *reason,
    const char *owner_label,
    const char *action
)
{
    RawAllDeferredPlanEntry *grown;
    RawAllDeferredPlanEntry *entry;
    uint64_t bytes;

    if (io_entries == NULL ||
        io_count == NULL ||
        io_capacity == NULL ||
        end_offset <= start_offset ||
        *io_count >= RAW_ALL_DEFERRED_PLAN_MAX_INPUTS) {
        return 0;
    }

    if (*io_count == *io_capacity) {
        size_t next_capacity =
            *io_capacity == 0U ? 64U : *io_capacity * 2U;
        if (next_capacity > RAW_ALL_DEFERRED_PLAN_MAX_INPUTS) {
            next_capacity = RAW_ALL_DEFERRED_PLAN_MAX_INPUTS;
        }
        grown = (RawAllDeferredPlanEntry *)realloc(
            *io_entries,
            next_capacity * sizeof(**io_entries)
        );
        if (grown == NULL) {
            return 0;
        }
        *io_entries = grown;
        *io_capacity = next_capacity;
    }

    bytes = end_offset - start_offset;
    entry = &(*io_entries)[*io_count];
    memset(entry, 0, sizeof(*entry));
    entry->start_offset = start_offset;
    entry->end_offset = end_offset;
    entry->bytes = bytes;
    entry->owner_offset = owner_offset;
    entry->owner_end_offset = owner_end_offset;
    snprintf(entry->source, sizeof(entry->source), "%s", source != NULL ? source : "");
    snprintf(entry->kind, sizeof(entry->kind), "%s", kind != NULL ? kind : "");
    snprintf(entry->reason, sizeof(entry->reason), "%s", reason != NULL ? reason : "");
    snprintf(
        entry->owner_label,
        sizeof(entry->owner_label),
        "%s",
        owner_label != NULL ? owner_label : ""
    );
    snprintf(entry->action, sizeof(entry->action), "%s", action != NULL ? action : "");
    entry->score = score_deferred_plan_entry(
        entry->source,
        entry->kind,
        entry->reason,
        bytes
    );
    (*io_count)++;
    return 1;
}

static int load_deferred_plan_input_file(
    const char *path,
    const char *source,
    RawAllDeferredPlanEntry **io_entries,
    size_t *io_count,
    size_t *io_capacity
)
{
    FILE *file;
    char line[1024];

    if (!has_nonempty_text(path) || !has_nonempty_text(source)) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long a = 0ULL;
        unsigned long long b = 0ULL;
        unsigned long long c = 0ULL;
        unsigned long long d = 0ULL;
        unsigned long long e = 0ULL;
        unsigned long long f = 0ULL;
        char kind[96] = "";
        char reason[128] = "";
        char extra_reason[128] = "";
        char owner_label[160] = "";
        int parsed = 0;

        if (!isdigit((unsigned char)line[0])) {
            continue;
        }

        if (strcmp(source, "swallowed") == 0) {
            parsed = sscanf(
                line,
                "%llu\t%llu\t%llu\t%llu\t%95[^\t]\t%127[^\t]\t%159[^\t]\t%127[^\n]",
                &a,
                &b,
                &c,
                &d,
                kind,
                reason,
                owner_label,
                extra_reason
            );
            if (parsed >= 2) {
                (void)append_deferred_plan_entry(
                    io_entries,
                    io_count,
                    io_capacity,
                    (uint64_t)a,
                    (uint64_t)b,
                    parsed >= 4 ? (uint64_t)c : 0ULL,
                    parsed >= 4 ? (uint64_t)d : 0ULL,
                    source,
                    parsed >= 5 ? kind : "unknown",
                    parsed >= 6 ? reason : "swallowed_interval",
                    parsed >= 7 ? owner_label : "",
                    "revisit_child_range"
                );
            }
        } else if (strcmp(source, "safety_drop") == 0) {
            parsed = sscanf(
                line,
                "%llu\t%llu\t%llu\t%95[^\t]\t%127[^\t]\t%127[^\t]\t%llu\t%llu\t%159[^\n]",
                &a,
                &b,
                &c,
                kind,
                reason,
                extra_reason,
                &d,
                &e,
                owner_label
            );
            if (parsed >= 2) {
                if (parsed >= 6 && has_nonempty_text(extra_reason)) {
                    snprintf(reason, sizeof(reason), "%s", extra_reason);
                }
                (void)append_deferred_plan_entry(
                    io_entries,
                    io_count,
                    io_capacity,
                    (uint64_t)a,
                    (uint64_t)b,
                    parsed >= 8 ? (uint64_t)d : 0ULL,
                    parsed >= 8 ? (uint64_t)e : 0ULL,
                    source,
                    parsed >= 4 ? kind : "unknown",
                    parsed >= 5 ? reason : "safety_interval_dropped",
                    parsed >= 9 ? owner_label : "",
                    "revisit_dropped_interval"
                );
            }
            (void)c;
        } else if (strcmp(source, "coverage_gap") == 0) {
            parsed = sscanf(
                line,
                "%llu\t%llu\t%llu\t%llu\t%llu\t%95[^\t]\t%127[^\t]\t%llu",
                &a,
                &b,
                &c,
                &d,
                &e,
                kind,
                reason,
                &f
            );
            if (parsed >= 3) {
                (void)append_deferred_plan_entry(
                    io_entries,
                    io_count,
                    io_capacity,
                    (uint64_t)b,
                    (uint64_t)c,
                    0ULL,
                    0ULL,
                    source,
                    parsed >= 6 ? kind : "coverage",
                    parsed >= 7 ? reason : "coverage_gap",
                    "",
                    "retry_gap"
                );
            }
            (void)d;
            (void)e;
            (void)f;
        }
    }

    fclose(file);
    return 1;
}

static int compare_deferred_plan_entries_desc(
    const void *left,
    const void *right
)
{
    const RawAllDeferredPlanEntry *a =
        (const RawAllDeferredPlanEntry *)left;
    const RawAllDeferredPlanEntry *b =
        (const RawAllDeferredPlanEntry *)right;

    if (a->score != b->score) {
        return a->score < b->score ? 1 : -1;
    }
    if (a->start_offset != b->start_offset) {
        return a->start_offset > b->start_offset ? 1 : -1;
    }
    if (a->bytes != b->bytes) {
        return a->bytes < b->bytes ? 1 : -1;
    }
    return strcmp(a->source, b->source);
}

static int compare_deferred_plan_entries_by_range(
    const void *left,
    const void *right)
{
    const RawAllDeferredPlanEntry *a =
        (const RawAllDeferredPlanEntry *)left;
    const RawAllDeferredPlanEntry *b =
        (const RawAllDeferredPlanEntry *)right;

    if (a->start_offset != b->start_offset) {
        return a->start_offset < b->start_offset ? -1 : 1;
    }
    if (a->end_offset != b->end_offset) {
        return a->end_offset > b->end_offset ? -1 : 1;
    }
    return compare_deferred_plan_entries_desc(left, right);
}

static int deferred_plan_entries_same_class(
    const RawAllDeferredPlanEntry *a,
    const RawAllDeferredPlanEntry *b)
{
    return a != NULL && b != NULL &&
           strcmp(a->source, b->source) == 0 &&
           strcmp(a->kind, b->kind) == 0 &&
           strcmp(a->reason, b->reason) == 0 &&
           strcmp(a->action, b->action) == 0;
}

static size_t compact_deferred_plan_entries(
    RawAllDeferredPlanEntry *entries,
    size_t entry_count,
    size_t *out_metadata_suppressed,
    size_t *out_duplicates_merged)
{
    size_t read_index;
    size_t write_count = 0U;
    size_t metadata_suppressed = 0U;
    size_t duplicates_merged = 0U;

    if (out_metadata_suppressed != NULL) *out_metadata_suppressed = 0U;
    if (out_duplicates_merged != NULL) *out_duplicates_merged = 0U;
    if (entries == NULL || entry_count == 0U) return 0U;

    qsort(
        entries,
        entry_count,
        sizeof(*entries),
        compare_deferred_plan_entries_by_range
    );
    for (read_index = 0U; read_index < entry_count; ++read_index) {
        RawAllDeferredPlanEntry *entry = &entries[read_index];

        if (fs_backend_range_has_trusted_metadata_owner(
                entry->start_offset,
                entry->end_offset)) {
            metadata_suppressed++;
            continue;
        }
        if (write_count > 0U) {
            RawAllDeferredPlanEntry *previous = &entries[write_count - 1U];

            if (entry->start_offset <= previous->end_offset &&
                deferred_plan_entries_same_class(previous, entry)) {
                if (entry->end_offset > previous->end_offset) {
                    previous->end_offset = entry->end_offset;
                    previous->bytes =
                        previous->end_offset - previous->start_offset;
                }
                if (entry->score > previous->score) {
                    previous->score = entry->score;
                    previous->owner_offset = entry->owner_offset;
                    previous->owner_end_offset = entry->owner_end_offset;
                    snprintf(
                        previous->owner_label,
                        sizeof(previous->owner_label),
                        "%s",
                        entry->owner_label
                    );
                }
                duplicates_merged++;
                continue;
            }
        }
        if (write_count != read_index) entries[write_count] = *entry;
        write_count++;
    }
    if (out_metadata_suppressed != NULL) {
        *out_metadata_suppressed = metadata_suppressed;
    }
    if (out_duplicates_merged != NULL) {
        *out_duplicates_merged = duplicates_merged;
    }
    return write_count;
}

static int deferred_plan_inputs_newer_than_plan(
    const char *run_dir,
    const char *plan_path,
    int *out_any_input
)
{
    const char *leaves[] = {
        "swallowed_file_intervals.tsv",
        "safety_interval_dropped.tsv",
        "coverage_gaps.tsv"
    };
    struct stat plan_st;
    time_t newest_input = 0;
    int have_input = 0;
    size_t i;

    if (out_any_input != NULL) {
        *out_any_input = 0;
    }

    for (i = 0U; i < sizeof(leaves) / sizeof(leaves[0]); i++) {
        char path[PATH_MAX_LEN];
        struct stat st;

        if (!build_raw_all_state_named_path_for_run_dir(
                run_dir,
                leaves[i],
                path,
                sizeof(path))) {
            continue;
        }
        if (stat(path, &st) == 0 && S_ISREG(st.st_mode)) {
            have_input = 1;
            if (st.st_mtime > newest_input) {
                newest_input = st.st_mtime;
            }
        }
    }

    if (out_any_input != NULL) {
        *out_any_input = have_input;
    }
    if (!have_input) {
        return 0;
    }
    if (stat(plan_path, &plan_st) != 0 || !S_ISREG(plan_st.st_mode)) {
        return 1;
    }
    return newest_input > plan_st.st_mtime;
}

static int write_deferred_plan_for_run_dir(const char *run_dir)
{
    RawAllDeferredPlanEntry *entries = NULL;
    size_t entry_count = 0U;
    size_t loaded_entry_count = 0U;
    size_t entry_capacity = 0U;
    char plan_path[PATH_MAX_LEN];
    char plan_temp_path[PATH_MAX_LEN + 32];
    char state_path[PATH_MAX_LEN];
    char state_temp_path[PATH_MAX_LEN + 32];
    FILE *plan_file = NULL;
    FILE *state_file = NULL;
    int have_input = 0;
    uint64_t planned_bytes = 0ULL;
    size_t output_count;
    size_t metadata_suppressed = 0U;
    size_t duplicates_merged = 0U;
    size_t i;
    int ok = 0;

    if (!has_nonempty_text(run_dir) ||
        !build_deferred_plan_path_for_run_dir(run_dir, plan_path, sizeof(plan_path)) ||
        !build_deferred_plan_state_path_for_run_dir(run_dir, state_path, sizeof(state_path)) ||
        snprintf(plan_temp_path, sizeof(plan_temp_path), "%s.tmp", plan_path) >=
            (int)sizeof(plan_temp_path) ||
        snprintf(state_temp_path, sizeof(state_temp_path), "%s.tmp", state_path) >=
            (int)sizeof(state_temp_path)) {
        return 0;
    }

    if (!fs_backend_output_path_write_guard_allows(plan_temp_path) ||
        !fs_backend_output_path_write_guard_allows(state_temp_path) ||
        !ensure_raw_all_supervisor_state_dir(run_dir)) {
        return 0;
    }

    if (!deferred_plan_inputs_newer_than_plan(run_dir, plan_path, &have_input)) {
        return have_input ? 1 : 0;
    }

    {
        char path[PATH_MAX_LEN];

        if (build_raw_all_state_named_path_for_run_dir(
                run_dir,
                "swallowed_file_intervals.tsv",
                path,
                sizeof(path))) {
            (void)load_deferred_plan_input_file(
                path,
                "swallowed",
                &entries,
                &entry_count,
                &entry_capacity
            );
        }
        if (build_raw_all_state_named_path_for_run_dir(
                run_dir,
                "safety_interval_dropped.tsv",
                path,
                sizeof(path))) {
            (void)load_deferred_plan_input_file(
                path,
                "safety_drop",
                &entries,
                &entry_count,
                &entry_capacity
            );
        }
        if (build_raw_all_state_named_path_for_run_dir(
                run_dir,
                "coverage_gaps.tsv",
                path,
                sizeof(path))) {
            (void)load_deferred_plan_input_file(
                path,
                "coverage_gap",
                &entries,
                &entry_count,
                &entry_capacity
            );
        }
    }

    loaded_entry_count = entry_count;
    entry_count = compact_deferred_plan_entries(
        entries,
        entry_count,
        &metadata_suppressed,
        &duplicates_merged
    );
    if (entry_count > 1U) {
        qsort(
            entries,
            entry_count,
            sizeof(*entries),
            compare_deferred_plan_entries_desc
        );
    }

    output_count =
        entry_count < RAW_ALL_DEFERRED_PLAN_MAX_OUTPUTS
            ? entry_count
            : RAW_ALL_DEFERRED_PLAN_MAX_OUTPUTS;
    for (i = 0U; i < output_count; i++) {
        planned_bytes += entries[i].bytes;
    }

    if (output_count == 0U) {
        (void)unlink(plan_path);
        (void)unlink(state_path);
        ok = 1;
        goto cleanup;
    }

    plan_file = fopen(plan_temp_path, "w");
    if (plan_file == NULL) {
        goto cleanup;
    }
    fprintf(
        plan_file,
        "rank\tsource\tstart_offset\tend_offset\tbytes\tkind\treason\towner_offset\towner_end_offset\towner_label\tscore\taction\n"
    );
    for (i = 0U; i < output_count; i++) {
        fprintf(plan_file, "%zu\t", i + 1U);
        write_tsv_text_field_local(plan_file, entries[i].source);
        fprintf(
            plan_file,
            "\t%llu\t%llu\t%llu\t",
            (unsigned long long)entries[i].start_offset,
            (unsigned long long)entries[i].end_offset,
            (unsigned long long)entries[i].bytes
        );
        write_tsv_text_field_local(plan_file, entries[i].kind);
        fputc('\t', plan_file);
        write_tsv_text_field_local(plan_file, entries[i].reason);
        fprintf(
            plan_file,
            "\t%llu\t%llu\t",
            (unsigned long long)entries[i].owner_offset,
            (unsigned long long)entries[i].owner_end_offset
        );
        write_tsv_text_field_local(plan_file, entries[i].owner_label);
        fprintf(plan_file, "\t%llu\t", (unsigned long long)entries[i].score);
        write_tsv_text_field_local(plan_file, entries[i].action);
        fputc('\n', plan_file);
    }
    if (fclose(plan_file) != 0) {
        plan_file = NULL;
        goto cleanup;
    }
    plan_file = NULL;

    state_file = fopen(state_temp_path, "w");
    if (state_file == NULL) {
        goto cleanup;
    }
    fprintf(state_file, "version=1\n");
    fprintf(state_file, "updated_unix=%llu\n", (unsigned long long)time(NULL));
    fprintf(state_file, "input_entries=%zu\n", loaded_entry_count);
    fprintf(state_file, "compacted_entries=%zu\n", entry_count);
    fprintf(state_file, "metadata_owned_suppressed=%zu\n", metadata_suppressed);
    fprintf(state_file, "duplicate_or_overlapping_entries_merged=%zu\n",
            duplicates_merged);
    fprintf(state_file, "planned_entries=%zu\n", output_count);
    fprintf(state_file, "planned_bytes=%llu\n", (unsigned long long)planned_bytes);
    fprintf(
        state_file,
        "top_score=%llu\n",
        output_count > 0U ? (unsigned long long)entries[0].score : 0ULL
    );
    fprintf(
        state_file,
        "top_source=%s\n",
        output_count > 0U ? entries[0].source : ""
    );
    fprintf(
        state_file,
        "top_kind=%s\n",
        output_count > 0U ? entries[0].kind : ""
    );
    fprintf(
        state_file,
        "top_reason=%s\n",
        output_count > 0U ? entries[0].reason : ""
    );
    if (fclose(state_file) != 0) {
        state_file = NULL;
        goto cleanup;
    }
    state_file = NULL;

    if (rename(plan_temp_path, plan_path) != 0 ||
        rename(state_temp_path, state_path) != 0) {
        goto cleanup;
    }

    ok = 1;

cleanup:
    if (plan_file != NULL) {
        fclose(plan_file);
    }
    if (state_file != NULL) {
        fclose(state_file);
    }
    if (!ok) {
        (void)unlink(plan_temp_path);
        (void)unlink(state_temp_path);
    }
    free(entries);
    return ok;
}

static int raw_all_full_source_completion_is_safe(
    const AppConfig *config,
    uint64_t source_size,
    uint64_t final_offset,
    int scanner_reported_completed,
    const char *phase,
    size_t *out_gap_count,
    uint64_t *out_gap_bytes
)
{
    ReadErrorCluster *gaps = NULL;
    size_t gap_count = 0U;
    uint64_t total_gap_bytes = 0ULL;
    uint64_t active_start;
    uint64_t active_end;
    int coverage_available = 0;
    int safe = 0;

    if (out_gap_count != NULL) {
        *out_gap_count = 0U;
    }
    if (out_gap_bytes != NULL) {
        *out_gap_bytes = 0ULL;
    }
    if (config == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !scanner_reported_completed ||
        source_size == 0ULL) {
        return 0;
    }

    active_start = raw_all_effective_scan_start_offset_for_source(config, source_size);
    active_end = raw_all_effective_scan_end_offset_for_source(config, source_size);
    if (active_start != 0ULL || active_end < source_size) {
        return 0;
    }
    if (final_offset < source_size) {
        return 0;
    }

    if (!discover_coverage_gaps_for_run_dir(
            config->output_dir,
            0ULL,
            source_size,
            RAW_ALL_COVERAGE_GAP_MIN_BYTES,
            &gaps,
            &gap_count,
            &total_gap_bytes,
            &coverage_available,
            1)) {
        return 0;
    }
    if (out_gap_count != NULL) {
        *out_gap_count = gap_count;
    }
    if (out_gap_bytes != NULL) {
        *out_gap_bytes = total_gap_bytes;
    }

    if (coverage_available) {
        (void)write_coverage_gaps_file_for_run_dir(
            config->output_dir,
            gaps,
            gap_count,
            total_gap_bytes,
            source_size,
            has_nonempty_text(phase) ? phase : "completion_check",
            gap_count > 0U ? "pending_retry" : "no_large_gaps"
        );
        if (gap_count > 0U) {
            char gap_text[96];

            format_size_summary(total_gap_bytes, gap_text, sizeof(gap_text));
            if (g_raw_all_coverage_retry_exhausted) {
                (void)write_coverage_gaps_file_for_run_dir(
                    config->output_dir,
                    gaps,
                    gap_count,
                    total_gap_bytes,
                    source_size,
                    has_nonempty_text(phase) ? phase : "completion_check",
                    "unreadable_after_exhaustive_retry"
                );
                log_error(
                    "Raw-all finished after exhaustively retrying the source: %zu coverage gap%s (%s) could not be read and remain explicitly recorded as unreadable trouble areas",
                    gap_count,
                    gap_count == 1U ? "" : "s",
                    gap_text
                );
                free(gaps);
                return 0;
            }
            log_error(
                "Raw-all primary completion is waiting for post-scan coverage: %zu large gap%s remain (%s). This same run will retry them before it finishes.",
                gap_count,
                gap_count == 1U ? "" : "s",
                gap_text
            );
            free(gaps);
            return 0;
        }
    } else {
        log_error(
            "Raw-all completion blocked: no durable eligible read-coverage ranges are available for the full source"
        );
        free(gaps);
        return 0;
    }

    safe = 1;
    free(gaps);
    return safe;
}

static int raw_all_selected_scope_completion_is_safe(
    const AppConfig *config,
    uint64_t source_size,
    uint64_t final_offset,
    const char *phase,
    size_t *out_gap_count,
    uint64_t *out_gap_bytes
)
{
    ReadErrorCluster *gaps = NULL;
    uint64_t scope_start;
    uint64_t scope_end;
    uint64_t gap_bytes = 0ULL;
    size_t gap_count = 0U;
    int coverage_available = 0;

    if (out_gap_count != NULL) *out_gap_count = 0U;
    if (out_gap_bytes != NULL) *out_gap_bytes = 0ULL;
    if (config == NULL || config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        source_size == 0ULL || !has_nonempty_text(config->output_dir)) {
        return 0;
    }

    scope_start = raw_all_effective_scan_start_offset_for_source(
        config, source_size);
    scope_end = raw_all_effective_scan_end_offset_for_source(
        config, source_size);
    if (scope_end <= scope_start || final_offset < scope_end ||
        !discover_coverage_gaps_for_run_dir(
            config->output_dir,
            scope_start,
            scope_end,
            RAW_ALL_COVERAGE_GAP_MIN_BYTES,
            &gaps,
            &gap_count,
            &gap_bytes,
            &coverage_available,
            1)) {
        free(gaps);
        return 0;
    }
    if (out_gap_count != NULL) *out_gap_count = gap_count;
    if (out_gap_bytes != NULL) *out_gap_bytes = gap_bytes;

    (void)write_coverage_gaps_file_for_run_dir(
        config->output_dir,
        gaps,
        gap_count,
        gap_bytes,
        source_size,
        has_nonempty_text(phase) ? phase : "selected_scope_completion_check",
        !coverage_available
            ? "coverage_unavailable"
            : (gap_count > 0U ? "pending_retry" : "no_large_gaps")
    );
    if (!coverage_available) {
        log_error(
            "Raw-all selected-scope completion blocked: no durable read-coverage map is available for the requested byte range"
        );
        free(gaps);
        return 0;
    }
    if (gap_count > 0U || gap_bytes > 0ULL) {
        char gap_text[96];

        format_size_summary(gap_bytes, gap_text, sizeof(gap_text));
        if (g_raw_all_coverage_retry_exhausted) {
            (void)write_coverage_gaps_file_for_run_dir(
                config->output_dir,
                gaps,
                gap_count,
                gap_bytes,
                source_size,
                has_nonempty_text(phase)
                    ? phase
                    : "selected_scope_completion_check",
                "unreadable_after_exhaustive_retry"
            );
            log_error(
                "Raw-all selected scope finished after exhaustive retry with %zu explicitly unreadable coverage gap%s (%s)",
                gap_count,
                gap_count == 1U ? "" : "s",
                gap_text
            );
            free(gaps);
            return 0;
        }
        log_error(
            "Raw-all selected scope is waiting for its automatic post-scan coverage pass: %zu large gap%s remain inside the requested byte range (%s)",
            gap_count,
            gap_count == 1U ? "" : "s",
            gap_text
        );
        free(gaps);
        return 0;
    }

    free(gaps);
    return 1;
}

static int raw_all_saved_selected_scope_is_complete(
    const AppConfig *config,
    uint64_t source_size)
{
    RawAllStageState stage_state = {0};
    char stage_path[PATH_MAX_LEN];
    uint64_t expected_start;
    uint64_t expected_end;

    if (config == NULL || config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        source_size == 0ULL || !has_nonempty_text(config->output_dir) ||
        !build_raw_all_stage_path_for_run_dir(
            config->output_dir, stage_path, sizeof(stage_path)) ||
        !load_raw_all_stage_state(stage_path, &stage_state) ||
        !stage_state.selected_scope_complete) {
        return 0;
    }

    expected_start = raw_all_effective_scan_start_offset_for_source(
        config, source_size);
    expected_end = raw_all_effective_scan_end_offset_for_source(
        config, source_size);
    if (expected_end <= expected_start ||
        stage_state.selected_scope_start_bytes != expected_start ||
        stage_state.selected_scope_end_bytes != expected_end ||
        stage_state.selected_scope_progress_bytes <
            expected_end - expected_start) {
        return 0;
    }

    return raw_all_selected_scope_completion_is_safe(
        config,
        source_size,
        expected_end,
        "saved_selected_scope_check",
        NULL,
        NULL
    );
}

static void append_coverage_gap_retry_event_for_run_dir(
    const char *run_dir,
    size_t gap_index,
    const char *direction,
    uint64_t start_offset,
    uint64_t end_offset,
    size_t attempt_index,
    int scan_ok,
    size_t recovered_before,
    size_t recovered_after,
    const char *note
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    int write_header;

    if (!has_nonempty_text(run_dir) ||
        end_offset <= start_offset ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_coverage_gap_retry_path_for_run_dir(run_dir, path, sizeof(path))) {
        return;
    }

    write_header = stat(path, &st) != 0 || st.st_size == 0;
    file = fopen(path, "a");
    if (file == NULL) {
        return;
    }
    if (write_header) {
        fprintf(
            file,
            "updated_unix\tattempt\tgap_index\tdirection\tstart_offset\tend_offset\tbytes\tscan_ok\trecovered_before\trecovered_after\trecovered_delta\tnote\n"
        );
    }
    fprintf(
        file,
        "%llu\t%zu\t%zu\t",
        (unsigned long long)time(NULL),
        attempt_index,
        gap_index
    );
    write_tsv_text_field_local(file, has_nonempty_text(direction) ? direction : "unknown");
    fprintf(
        file,
        "\t%llu\t%llu\t%llu\t%d\t%zu\t%zu\t%zu\t",
        (unsigned long long)start_offset,
        (unsigned long long)end_offset,
        (unsigned long long)(end_offset - start_offset),
        scan_ok ? 1 : 0,
        recovered_before,
        recovered_after,
        recovered_after >= recovered_before ? recovered_after - recovered_before : 0U
    );
    write_tsv_text_field_local(file, note != NULL ? note : "");
    fputc('\n', file);
    fclose(file);
}

static void write_coverage_gap_retry_state_for_run_dir(
    const char *run_dir,
    const char *status,
    size_t gap_index,
    size_t gap_count,
    size_t attempt_index,
    const char *direction,
    uint64_t chunk_start,
    uint64_t chunk_end,
    uint64_t attempted_bytes,
    uint64_t retry_budget_bytes,
    size_t recovered_before,
    size_t recovered_current
)
{
    char path[PATH_MAX_LEN];
    char temp_path[PATH_MAX_LEN + 32U];
    FILE *file;
    CoverageGapRetryState previous = {0};
    time_t now;
    time_t zone_started_unix = 0;
    size_t zone_attempts = 0U;

    if (!has_nonempty_text(run_dir) ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_coverage_gap_retry_state_path_for_run_dir(
            run_dir, path, sizeof(path)) ||
        snprintf(temp_path, sizeof(temp_path), "%s.tmp", path) >=
            (int)sizeof(temp_path)) {
        return;
    }
    (void)load_coverage_gap_retry_state_for_run_dir(run_dir, &previous);
    if (strcmp(has_nonempty_text(status) ? status : "", "planned") == 0 &&
        previous.present &&
        previous.supervisor_pid == getppid() &&
        strcmp(previous.status, "scanning") == 0 &&
        previous.chunk_end > previous.chunk_start) {
        /* The supervisor may have restarted a child in the middle of this
         * exact coverage zone.  Do not erase its cross-process timer before
         * the new child has selected and republished the same chunk. */
        return;
    }
    now = time(NULL);
    if (chunk_end > chunk_start &&
        previous.present &&
        previous.supervisor_pid == getppid() &&
        previous.chunk_start == chunk_start &&
        previous.chunk_end == chunk_end &&
        previous.zone_started_unix > 0) {
        zone_started_unix = previous.zone_started_unix;
        zone_attempts = previous.zone_attempts;
    }
    if (chunk_end > chunk_start &&
        strcmp(has_nonempty_text(status) ? status : "", "scanning") == 0) {
        if (zone_started_unix <= 0) {
            zone_started_unix = now;
        }
        zone_attempts++;
    }
    file = fopen(temp_path, "w");
    if (file == NULL) {
        return;
    }
    (void)chmod(temp_path, 0644);
    fprintf(file, "version=1\n");
    fprintf(file, "updated_unix=%llu\n", (unsigned long long)now);
    fprintf(file, "supervisor_pid=%ld\n", (long)getppid());
    fprintf(file, "phase=coverage_gap_retry\n");
    fprintf(file, "status=%s\n", has_nonempty_text(status) ? status : "unknown");
    fprintf(file, "gap_index=%zu\n", gap_index);
    fprintf(file, "gap_count=%zu\n", gap_count);
    fprintf(file, "attempt_index=%zu\n", attempt_index);
    fprintf(file, "direction=%s\n", has_nonempty_text(direction) ? direction : "unknown");
    fprintf(file, "chunk_start=%llu\n", (unsigned long long)chunk_start);
    fprintf(file, "chunk_end=%llu\n", (unsigned long long)chunk_end);
    fprintf(
        file,
        "chunk_bytes=%llu\n",
        (unsigned long long)(chunk_end > chunk_start ? chunk_end - chunk_start : 0ULL));
    fprintf(file, "attempted_bytes=%llu\n", (unsigned long long)attempted_bytes);
    fprintf(file, "retry_budget_bytes=%llu\n", (unsigned long long)retry_budget_bytes);
    fprintf(file, "recovered_before=%zu\n", recovered_before);
    fprintf(file, "recovered_current=%zu\n", recovered_current);
    fprintf(
        file,
        "zone_started_unix=%llu\n",
        (unsigned long long)zone_started_unix);
    fprintf(file, "zone_attempts=%zu\n", zone_attempts);
    fprintf(
        file,
        "zone_elapsed_seconds=%llu\n",
        (unsigned long long)(zone_started_unix > 0 && now >= zone_started_unix
            ? now - zone_started_unix
            : 0));
    fprintf(
        file,
        "recovered_delta=%zu\n",
        recovered_current >= recovered_before
            ? recovered_current - recovered_before
            : 0U);
    if (fclose(file) != 0 || rename(temp_path, path) != 0) {
        (void)unlink(temp_path);
        return;
    }
    (void)mft_apply_output_owner_to_path(path);
}

static int load_coverage_gap_retry_state_for_run_dir(
    const char *run_dir,
    CoverageGapRetryState *out_state
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[256];
    CoverageGapRetryState state = {0};

    if (out_state != NULL) {
        memset(out_state, 0, sizeof(*out_state));
    }
    if (!has_nonempty_text(run_dir) ||
        out_state == NULL ||
        !build_coverage_gap_retry_state_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return 0;
    }
    file = fopen(path, "r");
    if (file == NULL) {
        return 0;
    }
    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long value = 0ULL;

        if (sscanf(line, "updated_unix=%llu", &value) == 1) {
            state.updated_unix = (time_t)value;
        } else if (sscanf(line, "supervisor_pid=%llu", &value) == 1) {
            state.supervisor_pid = (pid_t)value;
        } else if (sscanf(line, "zone_started_unix=%llu", &value) == 1) {
            state.zone_started_unix = (time_t)value;
        } else if (sscanf(line, "zone_attempts=%llu", &value) == 1) {
            state.zone_attempts = (size_t)value;
        } else if (sscanf(line, "gap_index=%llu", &value) == 1) {
            state.gap_index = (size_t)value;
        } else if (sscanf(line, "gap_count=%llu", &value) == 1) {
            state.gap_count = (size_t)value;
        } else if (sscanf(line, "attempt_index=%llu", &value) == 1) {
            state.attempt_index = (size_t)value;
        } else if (sscanf(line, "chunk_start=%llu", &value) == 1) {
            state.chunk_start = (uint64_t)value;
        } else if (sscanf(line, "chunk_end=%llu", &value) == 1) {
            state.chunk_end = (uint64_t)value;
        } else if (sscanf(line, "attempted_bytes=%llu", &value) == 1) {
            state.attempted_bytes = (uint64_t)value;
        } else if (sscanf(line, "retry_budget_bytes=%llu", &value) == 1) {
            state.retry_budget_bytes = (uint64_t)value;
        } else if (sscanf(line, "recovered_before=%llu", &value) == 1) {
            state.recovered_before = (size_t)value;
        } else if (sscanf(line, "recovered_current=%llu", &value) == 1) {
            state.recovered_current = (size_t)value;
        } else if (strncmp(line, "status=", 7U) == 0) {
            size_t length = strcspn(line + 7U, "\r\n");

            if (length >= sizeof(state.status)) {
                length = sizeof(state.status) - 1U;
            }
            memcpy(state.status, line + 7U, length);
            state.status[length] = '\0';
        } else if (strncmp(line, "direction=", 10U) == 0) {
            size_t length = strcspn(line + 10U, "\r\n");

            if (length >= sizeof(state.direction)) {
                length = sizeof(state.direction) - 1U;
            }
            memcpy(state.direction, line + 10U, length);
            state.direction[length] = '\0';
        }
    }
    fclose(file);
    state.present = state.updated_unix > 0;
    *out_state = state;
    return state.present;
}

static int append_terminal_coverage_range_for_run_dir(
    const char *run_dir,
    uint64_t start_offset,
    uint64_t end_offset,
    time_t zone_started_unix,
    size_t zone_attempts,
    const char *reason
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    char line[512];
    time_t now = time(NULL);
    unsigned long long elapsed = 0ULL;
    int write_header;

    if (!has_nonempty_text(run_dir) ||
        end_offset <= start_offset ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_terminal_coverage_ranges_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return 0;
    }
    file = fopen(path, "r");
    if (file != NULL) {
        while (fgets(line, sizeof(line), file) != NULL) {
            unsigned long long saved_start = 0ULL;
            unsigned long long saved_end = 0ULL;

            if (sscanf(line, "%llu\t%llu", &saved_start, &saved_end) == 2 &&
                saved_start == start_offset &&
                saved_end == end_offset) {
                fclose(file);
                return 1;
            }
        }
        fclose(file);
    }

    write_header = stat(path, &st) != 0 || st.st_size == 0;
    file = fopen(path, "a");
    if (file == NULL) {
        return 0;
    }
    if (write_header) {
        fprintf(
            file,
            "start_offset\tend_offset\tfirst_seen_unix\tterminal_unix\telapsed_seconds\tattempts\treason\n");
    }
    if (zone_started_unix > 0 && now >= zone_started_unix) {
        elapsed = (unsigned long long)(now - zone_started_unix);
    }
    fprintf(
        file,
        "%llu\t%llu\t%llu\t%llu\t%llu\t%zu\t",
        (unsigned long long)start_offset,
        (unsigned long long)end_offset,
        (unsigned long long)zone_started_unix,
        (unsigned long long)now,
        elapsed,
        zone_attempts);
    write_tsv_text_field_local(
        file,
        has_nonempty_text(reason) ? reason : "coverage_zone_timeout");
    fputc('\n', file);
    if (fclose(file) != 0) {
        return 0;
    }
    (void)mft_apply_output_owner_to_path(path);
    app_gui_note_trouble(start_offset, end_offset, "coverage_unreadable");
    return 1;
}

static int load_terminal_coverage_summary_for_run_dir(
    const char *run_dir,
    uint64_t scope_start,
    uint64_t scope_end,
    size_t *out_count,
    uint64_t *out_bytes
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    char line[512];
    size_t count = 0U;
    uint64_t bytes = 0ULL;

    if (out_count != NULL) {
        *out_count = 0U;
    }
    if (out_bytes != NULL) {
        *out_bytes = 0ULL;
    }
    if (!has_nonempty_text(run_dir) ||
        scope_end <= scope_start ||
        out_count == NULL ||
        out_bytes == NULL ||
        !build_terminal_coverage_ranges_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return 0;
    }
    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }
    while (fgets(line, sizeof(line), file) != NULL) {
        unsigned long long saved_start = 0ULL;
        unsigned long long saved_end = 0ULL;
        uint64_t clipped_start;
        uint64_t clipped_end;

        if (sscanf(line, "%llu\t%llu", &saved_start, &saved_end) != 2 ||
            saved_end <= saved_start) {
            continue;
        }
        clipped_start = (uint64_t)saved_start > scope_start
            ? (uint64_t)saved_start
            : scope_start;
        clipped_end = (uint64_t)saved_end < scope_end
            ? (uint64_t)saved_end
            : scope_end;
        if (clipped_end <= clipped_start) {
            continue;
        }
        count++;
        if (UINT64_MAX - bytes < clipped_end - clipped_start) {
            bytes = UINT64_MAX;
        } else {
            bytes += clipped_end - clipped_start;
        }
    }
    fclose(file);
    *out_count = count;
    *out_bytes = bytes;
    return 1;
}

static void refresh_saved_coverage_verdict_after_resume(
    const AppConfig *config,
    uint64_t source_size,
    const char *context
)
{
    ReadErrorCluster *gaps = NULL;
    size_t gap_count = 0U;
    uint64_t gap_bytes = 0ULL;
    uint64_t coverage_start;
    uint64_t coverage_end;
    size_t terminal_count = 0U;
    uint64_t terminal_bytes = 0ULL;
    int coverage_available = 0;
    CoverageGapRetryState previous = {0};

    if (config == NULL ||
        config->scan_mode != APP_SCAN_MODE_RAW_ALL ||
        !has_nonempty_text(config->output_dir) ||
        source_size == 0ULL) {
        return;
    }

    coverage_start = raw_all_effective_scan_start_offset_for_source(
        config, source_size);
    coverage_end = raw_all_effective_scan_end_offset_for_source(
        config, source_size);
    if (coverage_end <= coverage_start ||
        !discover_coverage_gaps_for_run_dir(
            config->output_dir,
            coverage_start,
            coverage_end,
            RAW_ALL_COVERAGE_GAP_MIN_BYTES,
            &gaps,
            &gap_count,
            &gap_bytes,
            &coverage_available,
            1)) {
        free(gaps);
        return;
    }

    (void)write_coverage_gaps_file_for_run_dir(
        config->output_dir,
        gaps,
        gap_count,
        gap_bytes,
        coverage_end,
        has_nonempty_text(context) ? context : "resume_verification",
        !coverage_available
            ? "coverage_unavailable"
            : (gap_count > 0U ? "pending_retry" : "no_large_gaps")
    );
    if (!coverage_available || gap_count > 0U) {
        free(gaps);
        return;
    }

    (void)load_terminal_coverage_summary_for_run_dir(
        config->output_dir,
        coverage_start,
        coverage_end,
        &terminal_count,
        &terminal_bytes
    );
    g_raw_all_coverage_retry_exhausted = terminal_count > 0U;
    g_raw_all_terminal_gap_count = terminal_count;
    g_raw_all_terminal_gap_bytes = terminal_bytes;

    (void)load_coverage_gap_retry_state_for_run_dir(
        config->output_dir, &previous);
    write_coverage_gap_retry_state_for_run_dir(
        config->output_dir,
        terminal_count > 0U
            ? "complete_with_terminal_ranges"
            : "complete",
        0U,
        0U,
        previous.attempt_index,
        "done",
        0ULL,
        0ULL,
        previous.attempted_bytes,
        previous.retry_budget_bytes,
        previous.recovered_before,
        fs_backend_recovered_output_count()
    );
    if (previous.present &&
        strcmp(previous.status,
               terminal_count > 0U
                   ? "complete_with_terminal_ranges"
                   : "complete") != 0) {
        log_info(
            "Saved coverage verdict refreshed after resume: no large unread gaps remain%s%s",
            has_nonempty_text(context) ? " context=" : "",
            has_nonempty_text(context) ? context : ""
        );
    }
    free(gaps);
}

static void append_coverage_gap_observation_for_run_dir(
    const char *run_dir,
    const char *pass_id,
    uint64_t gap_start,
    uint64_t gap_end,
    uint64_t read_start,
    uint64_t read_end,
    const char *status
)
{
    char path[PATH_MAX_LEN];
    FILE *file;
    struct stat st;
    int write_header;

    if (!has_nonempty_text(run_dir) ||
        !has_nonempty_text(pass_id) ||
        gap_end <= gap_start ||
        read_end <= read_start ||
        !ensure_raw_all_supervisor_state_dir(run_dir) ||
        !build_coverage_gap_observations_path_for_run_dir(
            run_dir,
            path,
            sizeof(path))) {
        return;
    }

    write_header = stat(path, &st) != 0 || st.st_size == 0;
    file = fopen(path, "a");
    if (file == NULL) {
        return;
    }
    if (write_header) {
        fprintf(
            file,
            "updated_unix\tpass_id\tgap_start\tgap_end\tbytes\tread_start\tread_end\tstatus\n"
        );
    }
    fprintf(
        file,
        "%llu\t",
        (unsigned long long)time(NULL)
    );
    write_tsv_text_field_local(file, pass_id);
    fprintf(
        file,
        "\t%llu\t%llu\t%llu\t%llu\t%llu\t",
        (unsigned long long)gap_start,
        (unsigned long long)gap_end,
        (unsigned long long)(gap_end - gap_start),
        (unsigned long long)read_start,
        (unsigned long long)read_end
    );
    write_tsv_text_field_local(file, has_nonempty_text(status) ? status : "observed_live");
    fputc('\n', file);
    fclose(file);
}

static int parse_read_error_range_line(char *line, ReadErrorRange *out_range)
{
    char *fields[8] = {0};
    char *cursor = line;
    char *token = NULL;
    char *saveptr = NULL;
    size_t field_count = 0U;

    if (line == NULL || out_range == NULL) {
        return 0;
    }
    if (strncmp(line, "offset\tend_offset\tbytes", 23) == 0) {
        return 0;
    }

    while ((token = strtok_r(cursor, "\t", &saveptr)) != NULL &&
           field_count < (sizeof(fields) / sizeof(fields[0]))) {
        fields[field_count++] = token;
        cursor = NULL;
    }
    if (field_count < 4U) {
        return 0;
    }

    memset(out_range, 0, sizeof(*out_range));
    out_range->offset = strtoull(fields[0], NULL, 10);
    out_range->end_offset = strtoull(fields[1], NULL, 10);
    out_range->bytes = strtoull(fields[2], NULL, 10);
    if (out_range->end_offset <= out_range->offset || out_range->bytes == 0U) {
        return 0;
    }

    if (field_count >= 8U) {
        fields[7][strcspn(fields[7], "\r\n")] = '\0';
        out_range->errno_code = (int)strtol(fields[3], NULL, 10);
        out_range->granularity_bytes = strtoull(fields[4], NULL, 10);
        snprintf(out_range->source_path, sizeof(out_range->source_path), "%s", fields[5]);
        snprintf(out_range->run_id, sizeof(out_range->run_id), "%s", fields[6]);
        snprintf(out_range->note, sizeof(out_range->note), "%s", fields[7]);
    } else {
        fields[3][strcspn(fields[3], "\r\n")] = '\0';
        snprintf(out_range->note, sizeof(out_range->note), "%s", fields[3]);
    }

    return 1;
}

static int load_read_error_ranges_from_path(
    const char *path,
    ReadErrorRange **out_ranges,
    size_t *out_count
)
{
    FILE *file = NULL;
    ReadErrorRange *ranges = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    char line[2048];
    int ok = 0;

    if (out_ranges == NULL || out_count == NULL) {
        return 0;
    }

    *out_ranges = NULL;
    *out_count = 0U;
    if (!has_nonempty_text(path)) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        ReadErrorRange parsed;
        ReadErrorRange *grown;

        if (!parse_read_error_range_line(line, &parsed)) {
            continue;
        }

        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 16U : capacity * 2U;
            grown = (ReadErrorRange *)realloc(ranges, next_capacity * sizeof(*ranges));
            if (grown == NULL) {
                goto cleanup;
            }
            ranges = grown;
            capacity = next_capacity;
        }

        ranges[count++] = parsed;
    }

    ok = 1;

cleanup:
    if (file != NULL) {
        fclose(file);
    }
    if (!ok) {
        free(ranges);
        return 0;
    }

    if (count > 1U) {
        qsort(ranges, count, sizeof(*ranges), compare_read_error_offset_asc);
    }

    *out_ranges = ranges;
    *out_count = count;
    return 1;
}

static int build_read_error_clusters_streaming_from_path(
    const char *path,
    ReadErrorCluster **out_clusters,
    size_t *out_cluster_count,
    size_t *out_range_count
)
{
    FILE *file = NULL;
    ReadErrorCluster *clusters = NULL;
    size_t cluster_count = 0U;
    size_t cluster_capacity = 0U;
    size_t range_count = 0U;
    char line[2048];
    uint64_t previous_offset = 0U;
    int have_previous = 0;
    int ok = 0;

    if (out_clusters == NULL || out_cluster_count == NULL || out_range_count == NULL) {
        return 0;
    }

    *out_clusters = NULL;
    *out_cluster_count = 0U;
    *out_range_count = 0U;
    if (!has_nonempty_text(path)) {
        return 0;
    }

    file = fopen(path, "r");
    if (file == NULL) {
        return 1;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        ReadErrorRange parsed;
        ReadErrorCluster *cluster = NULL;

        if (!parse_read_error_range_line(line, &parsed)) {
            continue;
        }
        if (have_previous && parsed.offset < previous_offset) {
            goto cleanup;
        }
        previous_offset = parsed.offset;
        have_previous = 1;
        range_count++;

        if (cluster_count > 0U) {
            cluster = &clusters[cluster_count - 1U];
        }

        if (cluster != NULL &&
            parsed.offset <= cluster->end_offset + RUN_LOG_READ_ERROR_CLUSTER_GAP_BYTES) {
            if (parsed.end_offset > cluster->end_offset) {
                cluster->end_offset = parsed.end_offset;
            }
            cluster->bytes += parsed.bytes;
            cluster->ranges++;
            continue;
        }

        if (cluster_count == cluster_capacity) {
            size_t next_capacity = cluster_capacity == 0U ? 8U : cluster_capacity * 2U;
            ReadErrorCluster *grown = (ReadErrorCluster *)realloc(
                clusters,
                next_capacity * sizeof(*clusters)
            );

            if (grown == NULL) {
                goto cleanup;
            }

            clusters = grown;
            cluster_capacity = next_capacity;
        }

        clusters[cluster_count].start_offset = parsed.offset;
        clusters[cluster_count].end_offset = parsed.end_offset;
        clusters[cluster_count].bytes = parsed.bytes;
        clusters[cluster_count].ranges = 1U;
        cluster_count++;
    }

    if (cluster_count > 1U) {
        qsort(clusters, cluster_count, sizeof(*clusters), compare_read_error_cluster_desc);
    }
    ok = 1;

cleanup:
    if (file != NULL) {
        fclose(file);
    }
    if (!ok) {
        free(clusters);
        return 0;
    }

    *out_clusters = clusters;
    *out_cluster_count = cluster_count;
    *out_range_count = range_count;
    return 1;
}

static int compare_read_error_kind_desc(const void *left, const void *right)
{
    const ReadErrorKindStat *a = (const ReadErrorKindStat *)left;
    const ReadErrorKindStat *b = (const ReadErrorKindStat *)right;

    if (a->bytes != b->bytes) {
        return a->bytes < b->bytes ? 1 : -1;
    }
    if (a->ranges != b->ranges) {
        return a->ranges < b->ranges ? 1 : -1;
    }
    if (a->errno_code != b->errno_code) {
        return a->errno_code < b->errno_code ? -1 : 1;
    }
    return strcasecmp(a->note, b->note);
}

static void format_lba_text(
    uint64_t offset,
    uint64_t block_size,
    char *out,
    size_t out_size
)
{
    char grouped[64];

    if (out == NULL || out_size == 0U || block_size == 0U) {
        return;
    }

    format_u64_grouped(offset / block_size, grouped, sizeof(grouped));
    snprintf(out, out_size, "%s", grouped);
}

static int build_read_error_kind_stats(
    const ReadErrorRange *ranges,
    size_t range_count,
    ReadErrorKindStat **out_stats,
    size_t *out_count
)
{
    ReadErrorKindStat *stats = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    size_t i;

    if (out_stats == NULL || out_count == NULL) {
        return 0;
    }
    *out_stats = NULL;
    *out_count = 0U;

    for (i = 0; i < range_count; i++) {
        size_t j;
        int found = 0;

        for (j = 0; j < count; j++) {
            if (stats[j].errno_code == ranges[i].errno_code &&
                strcmp(stats[j].note, ranges[i].note) == 0) {
                stats[j].ranges++;
                stats[j].bytes += ranges[i].bytes;
                found = 1;
                break;
            }
        }

        if (found) {
            continue;
        }

        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 8U : capacity * 2U;
            ReadErrorKindStat *grown =
                (ReadErrorKindStat *)realloc(stats, next_capacity * sizeof(*stats));
            if (grown == NULL) {
                free(stats);
                return 0;
            }
            stats = grown;
            capacity = next_capacity;
        }

        stats[count].errno_code = ranges[i].errno_code;
        snprintf(stats[count].note, sizeof(stats[count].note), "%s", ranges[i].note);
        stats[count].ranges = 1U;
        stats[count].bytes = ranges[i].bytes;
        count++;
    }

    if (count > 1U) {
        qsort(stats, count, sizeof(*stats), compare_read_error_kind_desc);
    }

    *out_stats = stats;
    *out_count = count;
    return 1;
}

static size_t summary_bucket_file_count(
    const RunRecoverySummary *summary,
    const char *label
)
{
    size_t i;

    if (summary == NULL || !has_nonempty_text(label)) {
        return 0U;
    }

    for (i = 0; i < summary->bucket_count; i++) {
        if (strcmp(summary->buckets[i].label, label) == 0) {
            return summary->buckets[i].files;
        }
    }

    return 0U;
}

